INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Au commencement Dieu créa les cieux et la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Et la terre était déserte et vide; les ténèbres couvraient l\'abîme et l\'Esprit de Dieu reposait sur les eaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Et Dieu dit: Que la lumière soit. Et la lumière fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Et Dieu vit que la lumière était bonne, et Dieu sépara la lumière et les ténèbres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Et Dieu appela la lumière jour, et il appela les ténèbres nuit. Et il y eut un soir et il y eut un matin; ce fut un jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Et Dieu dit: Qu\'il y ait une étendue entre les eaux, et qu\'elle sépare les eaux d\'avec les eaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Et Dieu fit l\'étendue et sépara les eaux qui sont au-dessous de l\'étendue et les eaux qui sont au-dessus de l\'étendue, et cela fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Et Dieu appela l\'étendue cieux. Et il y eut un soir et il y eut un matin; ce fut le second jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Et Dieu dit: Que les eaux de dessous les cieux s\'amoncellent en un seul lieu et que le sec paraisse. Et cela fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Et Dieu appela le sec terre et il appela l\'amas des eaux mers; et Dieu vit que cela était bon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Et Dieu dit: Que la terre fasse pousser du gazon, des herbes portant semence, des arbres à fruits produisant, selon leur espèce, du fruit ayant en soi sa semence, sur la terre. Et cela fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Et la terre fit sortir des plantes, des herbes portant semence selon leur espèce et des arbres produisant selon leur espèce du fruit ayant en soi sa semence; et Dieu vit que cela était bon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Et il y eut un soir et il y eut un matin; ce fut le troisième jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Et Dieu dit: Qu\'il y ait des luminaires dans l\'étendue des cieux pour séparer le jour et la nuit, et qu\'ils servent de signes et qu\'ils fassent les époques et les jours et années;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'et qu\'ils servent dans l\'étendue des cieux de luminaires pour luire sur la terre. Et cela fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Et Dieu fit les deux grands luminaires, le plus grand luminaire pour dominer sur le jour et le plus petit pour dominer sur la nuit, et les étoiles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Et Dieu les plaça dans l\'étendue des cieux pour luire sur la terre,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'et pour dominer sur le jour et sur la nuit, et pour séparer la lumière et les ténèbres. Et Dieu vit que cela était bon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Et il y eut un soir et il y eut un matin; ce fut le quatrième jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Et Dieu dit: Que les eaux foisonnent d\'une multitude d\'êtres animés, et que des volatiles volent sur la terre, sur la face de l\'étendue des cieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Et Dieu créa les grandes bêtes aquatiques et tout être animé qui se meut, dont les eaux fourmillent, selon leur espèce, et tout volatile ailé selon son espèce. Et Dieu vit que cela était bon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Et Dieu les bénit en disant: Fructifiez et multipliez et remplissez les eaux dans les mers, et que les oiseaux multiplient sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Et il y eut un soir et il y eut un matin; ce fut le cinquième jour');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Et Dieu dit: Que la terre fasse sortir des êtres animés selon leur espèce, le bétail, les reptiles et les animaux terrestres selon leur espèce. Et cela fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Et Dieu fit des animaux terrestres selon leur espèce. Et Dieu vit que cela était bon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Et Dieu dit: Faisons l\'homme à notre image, selon notre ressemblance, et qu\'ils dominent sur les poissons de la mer et sur les oiseaux du ciel et sur le bétail et sur toute la terre et sur tout reptile qui rampe sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Et Dieu créa l\'homme à son image. Il l\'a créé à l\'image de Dieu. Il les a créés mâle et femelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Et Dieu les bénit, et Dieu leur dit: Fructifiez et multipliez et remplissez la terre et soumettez-la, et assujettissez-vous les poissons de la mer et les oiseaux des cieux et tout animal qui se meut sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Et Dieu dit: Voici, je vous ai donné toute herbe portant semence qui est sur la face de toute la terre, et tous les arbres qui ont un fruit d\'arbre portant semence; cela vous servira de nourriture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Et à tout animal de la terre et à tout oiseau des cieux et à tout ce qui se meut sur la terre ayant en soi une âme vivante, j\'ai donné toute herbe pour nourriture. Et cela fut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Et Dieu vit tout ce qu\'il avait fait, et voici c\'était très bon. Et il y eut un soir et il y eut un matin; ce fut le sixième jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Et les cieux et la terre et toute leur armée furent achevés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Et Dieu acheva au septième jour toute l\'œuvre qu\'il avait faite. Et il cessa au septième jour de travailler à toute l\'œuvre qu\'il avait faite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Et Dieu bénit le septième jour et le sanctifia, parce qu\'en ce jour-là il avait cessé de travailler à toute l\'œuvre qu\'il avait créée pour la faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'C\'est là ce qui est procédé des cieux et de la terre quand ils furent créés, au jour où l\'Eternel Dieu fit une terre et des cieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Il n\'y avait encore sur la terre aucun arbrisseau des champs, et aucune herbe des champs n\'avait encore germé; car l\'Eternel Dieu n\'avait pas fait pleuvoir sur la terre et il n\'y avait pas d\'homme pour cultiver le sol;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'et une vapeur montait de la terre et arrosait toute la face du sol.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Et l\'Eternel Dieu forma l\'homme de la poussière du sol, et il souffla dans ses narines un souffle de vie, et l\'homme devint un être animé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Et l\'Eternel Dieu planta un jardin en Eden, à l\'orient, et il mit là l\'homme qu\'il avait formé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Et l\'Eternel Dieu fit pousser du sol tout arbre agréable à voir et bon à manger, et l\'arbre de vie au milieu du jardin et l\'arbre de la connaissance du bien et du mal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Et un fleuve sortait d\'Eden pour arroser le jardin, et de là il se partageait et devenait quatre fleuves.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Le nom de l\'un est Pischon; c\'est celui qui entoure toute la terre de Havila où est l\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Et l\'or de cette terre-là est bon; c\'est là qu\'est le bdellium et la pierre de Schoham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Et le nom du second fleuve est Guihon; c\'est celui qui entoure toute la terre de Cusch.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Et le nom du troisième fleuve est Hiddékel, qui coule à l\'orient d\'Assur. Et le quatrième fleuve est l\'Euphrate.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Et l\'Eternel Dieu prit l\'homme et le plaça dans le jardin d\'Eden pour le cultiver et pour le garder.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Et l\'Eternel Dieu donna à l\'homme cet ordre: Tu mangeras librement de tout arbre du jardin;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'mais de l\'arbre de la connaissance du bien et du mal, tu n\'en mangeras pas, car au jour où tu en mangeras, tu mourras certainement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Et l\'Eternel Dieu dit: Il n\'est pas bon que l\'homme soit seul; je lui ferai une aide qui soit sa pareille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Et l\'Eternel Dieu forma du sol tout animal des champs et tout oiseau des cieux, et les fit venir vers l\'homme pour voir comment il les appellerait, et pour que, selon que l\'homme appellerait un être vivant, ce fût son nom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Et l\'homme donna des noms à tous les bestiaux et aux oiseaux des cieux et à toutes les bêtes sauvages; et il ne trouva pas pour l\'homme une aide qui fût sa pareille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Et l\'Eternel Dieu fit tomber un profond assoupissement sur l\'homme, qui s\'endormit, et il prit une de ses côtes et referma la chair à sa place,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'et de la côte qu\'il avait prise de l\'homme, l\'Eternel Dieu forma une femme, et il l\'amena vers l\'homme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Et l\'homme dit: Celle-ci cette fois est os de mes os et chair de ma chair; celle-ci sera appelée femme parce qu\'elle a été prise de l\'homme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'C\'est pourquoi l\'homme laissera son père et sa mère et il s\'attachera à sa femme, et ils deviendront une seule chair.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Et l\'homme et sa femme étaient tous deux nus, sans en avoir honte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Or le serpent était le plus fin des animaux des champs que l\'Eternel Dieu avait faits. Et il dit à la femme: Est-ce que Dieu aurait dit: Vous ne mangerez pas de tout arbre du jardin?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Et la femme répondit au serpent: Nous mangeons du fruit des arbres du jardin;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mais du fruit de l\'arbre qui est au milieu du jardin, Dieu a dit: Vous n\'en mangerez pas et vous n\'y toucherez pas, de peur que vous ne mouriez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Et le serpent dit à la femme: Vous ne mourrez nullement;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'mais Dieu sait qu\'au jour où vous en mangerez, vos yeux s\'ouvriront et vous serez comme Dieu, connaissant le bien et le mal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Et la femme vit que l\'arbre était bon à manger et qu\'il était agréable aux yeux et que l\'arbre était désirable pour devenir intelligent; et elle prit de son fruit et en mangea, et elle en donna aussi à son mari qui était avec elle, et il en mangea.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Et les yeux de tous deux s\'ouvrirent et ils connurent qu\'ils étaient nus; et ils cousirent des feuilles de figuier et se firent des ceintures.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Et ils entendirent le bruit de l\'Eternel Dieu passant dans le jardin au vent du jour. Et l\'homme et sa femme se cachèrent de devant l\'Eternel Dieu parmi les arbres du jardin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Et l\'Eternel Dieu appela l\'homme et lui dit: Où es-tu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Et il dit: Je t\'ai entendu dans le jardin et j\'ai craint, car je suis nu; et je me suis caché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Et il dit: Qui t\'a montré que tu es nu? As-tu mangé de l\'arbre dont je t\'avais dit de ne pas manger?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Et l\'homme dit: C\'est la femme que tu as mise auprès de moi qui m\'a donné du fruit de l\'arbre, et j\'en ai mangé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Et l\'Eternel Dieu dit à la femme: Qu\'est-ce que tu as fait? Et la femme répondit: Le serpent m\'a trompée et j\'en ai mangé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Et l\'Eternel Dieu dit au serpent: Parce que tu as fait cela, tu es maudit d\'entre toutes les bêtes et d\'entre tous les animaux des champs; tu marcheras sur ton ventre et tu mangeras la poussière tous les jours de ta vie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Et je mettrai inimitié entre toi et la femme, entre ta postérité et sa postérité; cette postérité te meurtrira à la tête, et toi tu la meurtriras au talon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A la femme il dit: Je rendrai fort pénible ton travail et ta grossesse; tu enfanteras des fils avec peine; ton désir se portera vers ton mari, et il dominera sur toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Et à Adam il dit: Parce que tu as écouté la voix de ta femme et que tu as mangé de l\'arbre au sujet duquel je t\'avais donné cet ordre: Tu n\'en mangeras pas! Le sol est maudit à cause de toi. Tu en tireras ta nourriture avec travail tous les jours de ta vie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Et il te produira des épines et des chardons et tu mangeras les plantes des champs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Tu mangeras ton pain à la sueur de ton visage jusqu\'à ce que tu retournes à la terre, parce que c\'est d\'elle que tu as été tiré; car tu es poussière et tu redeviendras poussière.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Et l\'homme donna à sa femme le nom d\'Eve, parce qu\'elle a été la mère de tous les vivants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Et l\'Eternel Dieu fit à Adam et à sa femme des tuniques de peau et les vêtit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Et l\'Eternel Dieu dit: Voici, l\'homme est devenu comme l\'un de nous, pour la connaissance du bien et du mal; et maintenant il ne faut pas qu\'il avance sa main et qu\'il prenne aussi de l\'arbre de vie et qu\'il en mange, et vive à toujours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Et l\'Eternel Dieu le fit sortir du jardin d\'Eden pour cultiver la terre d\'où il avait été pris.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Et il chassa l\'homme, et il plaça à l\'orient du jardin d\'Eden les chérubins et la flamme de l\'épée tournoyante pour garder le chemin de l\'arbre de vie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Et l\'homme ayant connu Eve sa femme, elle conçut et enfanta Caïn; et elle dit: J\'ai donné l\'être à un homme avec l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Elle enfanta encore Abel son frère; et Abel fut berger, et Caïn était cultivateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Et après un certain temps, Caïn offrit des produits de la terre en oblation à l\'Eternel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'et Abel ayant offert, lui aussi, des premiers-nés de son troupeau et de leur graisse, l\'Eternel regarda Abel et son oblation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'et il n\'avait pas regardé Caïn et son oblation. Et Caïn fut fort irrité et son visage fut abattu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Et l\'Eternel dit à Caïn: Pourquoi es-tu irrité et pourquoi ton visage est-il abattu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Si tu fais bien, ne seras-tu pas agréé? Et si tu ne fais pas bien, le péché se tient à la porte; son désir tend vers toi, et toi tu dois dominer sur lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Et Caïn parla à Abel, son frère, et il arriva, comme ils étaient dans la campagne, que Caïn s\'éleva contre Abel son frère et le tua.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Et l\'Eternel dit à Caïn; Où est Abel, ton frère? Et il dit: Je ne sais pas; suis-je le gardien de mon frère?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Et il dit: Qu\'as-tu fait? J\'entends le sang de ton frère qui crie à moi de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Et maintenant tu es maudit par la terre qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Lorsque tu cultiveras la terre, elle ne te donnera plus son fruit; tu seras errant et fugitif sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Et Caïn dit à l\'Eternel: Ma peine est plus grande que je ne la puis supporter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Voici tu m\'as chassé aujourd\'hui de dessus la face du pays, et je serai caché de devant ta face, je serai errant et fugitif sur la terre, et il arrivera que quiconque me trouvera me tuera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Et l\'Eternel lui dit: C\'est pourquoi, si quelqu\'un tue Caïn, Caïn sera vengé sept fois. Et l\'Eternel mit un signe sur Caïn pour que quiconque le trouverait ne le frappât point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Et Caïn sortit de devant l\'Eternel, et il habita dans le pays de Nod, à l\'orient d\'Eden.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Et Caïn connut sa femme, et elle conçut et enfanta Hénoc; et il se mit à bâtir une ville, et il appela cette ville Hénoc, du nom de son fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Et Irad naquit à Hénoc; et Irad engendra Méhujaël, et Méhujaël engendra Méthusaël, et Méthusaël engendra Lémec.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Et Lémec prit deux femmes; le nom de l\'une était Ada et le nom de la seconde, Tsilla.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Et Ada enfanta Jabal; il a été le père de ceux qui habitent sous la tente et au milieu des troupeaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Et le nom de son frère était Jubal; il a été le père de tous ceux qui jouent de la harpe et du chalumeau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Et Tsilla eut aussi des enfants: Tubal-Caïn, qui forgeait toute espèce d\'instruments tranchants d\'airain et de fer, et la sœur de Tubal-Caïn, Naama.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Et Lémec dit à ses femmes: Ada et Tsilla, entendez ma voix! Femmes de Lémec, écoutez ma parole! J\'ai tué un homme pour m\'avoir blessé, Et un enfant pour m\'avoir meurtri.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Car Caïn sera vengé sept fois, Et Lémec soixante-dix-sept fois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Et Adam connut encore sa femme, et elle enfanta un fils et l\'appela Seth, car, dit-elle, Dieu m\'a donné une autre postérité à la place d\'Abel, parce que Caïn l\'a tué.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Et à Seth aussi naquit un fils, et il l\'appela Enosch. Ce fut alors que l\'on commença à invoquer le nom de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'C\'est ici le livre de la postérité d\'Adam. Au jour où Dieu créa Adam, il le fit à la ressemblance de Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Il les créa mâle et femelle et il les bénit et leur donna le nom d\'Homme au jour où ils furent créés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Et Adam vécut cent trente ans et engendra un fils à sa ressemblance, selon son image, et il lui donna le nom de Seth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Et les jours d\'Adam, après qu\'il eut engendré Seth, furent de huit cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Et tout le temps qu\'Adam vécut fut de neuf cent trente ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Et Seth vécut cent cinq ans, et il engendra Enosch.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Et après qu\'il eut engendré Enosch, Seth vécut huit cent sept ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Et tout le temps que Seth vécut fut de neuf cent douze ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Et Enosch vécut quatre-vingt-dix ans, et il engendra Kénan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Et après qu\'il eut engendré Kénan, Enosch vécut huit cent quinze ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Et tout le temps qu\'Enosch vécut fut de neuf cent cinq ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Et Kénan vécut soixante-dix ans, et il engendra Mahalaléel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Et après qu\'il eut engendré Mahalaléel, Kénan vécut huit cent quarante ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Et tout le temps que Kénan vécut fut de neuf cent dix ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Et Mahalaléel vécut soixante-cinq ans, et il engendra Jéred.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Et après qu\'il eut engendré Jéred, Mahalaléel vécut huit cent trente ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Et tout le temps que Mahalaléel vécut fut de huit cent quatre-vingt-quinze ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Et Jéred vécut cent soixante-deux ans, et il engendra Hénoc.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Et après qu\'il eut engendré Hénoc, Jéred vécut huit cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Et tout le temps que Jéred vécut fut de neuf cent soixante-deux ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Et Hénoc vécut soixante-cinq ans, et il engendra Méthusélah.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Et après qu\'il eut engendré Méthusélah, Hénoc marcha avec Dieu trois cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Et tout le temps qu\'Hénoc vécut fut de trois cent soixante-cinq ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Hénoc marcha donc avec Dieu, et on ne le vit plus, car Dieu l\'avait pris.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Et Méthusélah vécut cent quatre-vingt-sept ans, et il engendra Lémec.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Et après qu\'il eut engendré Lémec, Méthusélah vécut sept cent quatre-vingt-deux ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Et tout le temps que Méthusélah vécut fut de neuf cent soixante-neuf ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Et Lémec vécut cent quatre vingt-deux ans, et il engendra un fils;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'et il lui donna le nom de Noé en disant: Celui-ci nous soulagera du travail de nos mains et de la peine que nous donne ce sol que l\'Eternel a maudit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Et après qu\'il eut engendré Noé, Lémec vécut cinq cent quatre-vingt-quinze ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Et tout le temps que Lémec vécut fut de sept cent soixante-dix-sept ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Et Noé, âgé de cinq cents ans, engendra Sem, Cham et Japheth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Lorsque les hommes eurent commencé à être nombreux sur la face de la terre et que des filles leur furent nées,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'les fils de Dieu virent que les filles des hommes étaient belles, et ils prirent des femmes d\'entre toutes celles qui leur plurent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Et l\'Eternel dit: Mon Esprit ne contestera pas à toujours avec l\'homme, car aussi il n\'est que chair, et ses jours seront de cent vingt ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Les géants étaient sur la terre en ces jours-là, et cela après que les fils de Dieu étaient venus vers les filles des hommes et qu\'elles leur avaient donné des enfants; ce sont là ces héros qui sont dès les temps les plus anciens des hommes célèbres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Et l\'Eternel vit que la méchanceté de l\'homme était grande sur la terre et que tous les desseins des pensées de son cœur n\'étaient que mal continuellement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Et l\'Eternel se repentit d\'avoir fait l\'homme sur la terre, et il fut affligé dans son cœur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Et l\'Eternel dit: J\'effacerai de dessus la terre l\'homme que j\'ai créé, depuis l\'homme jusqu\'au bétail, aux reptiles et aux oiseaux des cieux, car je me repens de les avoir faits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Et Noé trouva grâce aux yeux de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'C\'est ici l\'histoire de Noé. Noé était un homme juste, intègre parmi les hommes de son temps; Noé marchait avec Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Et Noé eut trois fils, Sem, Cham et Japheth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Et la terre se corrompit devant Dieu, et la terre se remplit de violence.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Et Dieu vit la terre, et voici elle était corrompue, car toute chair suivait sur la terre une voie de corruption.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Et Dieu dit à Noé: La fin de toute chair est venue devant moi car par eux la terre est pleine de violence. Je vais les détruire, ainsi que la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Fais-toi une arche de bois résineux; tu la feras composée de cellules et tu l\'enduiras de poix en dedans et en dehors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Et voici comment tu la feras; la longueur de l\'arche sera de trois cents coudées, sa largeur de cinquante et sa hauteur de trente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tu feras une ouverture à l\'arche, et tu la feras d\'une coudée depuis le toit. Tu mettras la porte de l\'arche sur le côté. Tu feras un premier, un second et un troisième étage de cellules.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Et moi je vais faire venir le déluge, une inondation de la terre, pour détruire de dessous les cieux toute chair ayant en soi souffle de vie. Tout ce qui est sur la terre périra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mais j\'établirai mon alliance avec toi, et tu entreras dans l\'arche, toi, tes fils, ta femme et les femmes de tes fils avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Et de tout ce qui vit, de toutes les espèces d\'animaux, tu en feras entrer deux de chacune dans l\'arche, pour les conserver en vie ainsi que toi; ce sera un mâle et une femelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Des oiseaux des diverses espèces, des quadrupèdes des diverses espèces et de toutes les diverses espèces d\'animaux qui rampent sur le sol, il en viendra vers toi deux de chacune pour que tu les conserves en vie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Et toi, prends de tout ce qui peut se manger et fais-en provision; cela servira à ta nourriture et à la leur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Et Noé se mit à l\'œuvre; il fit tout ainsi que Dieu le lui avait ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Et l\'Eternel dit à Noé: Entre, toi et toute ta famille dans l\'arche, car je t\'ai vu juste devant moi au milieu de cette génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De tous les animaux purs tu en prendras sept paires, les mâles et leurs femelles, et de tous les animaux qui ne sont pas purs, tu en prendras deux, un mâle et sa femelle;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'et aussi des oiseaux des cieux sept paires, mâles et femelles, pour en conserver la race sur la face de toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Car sept jours encore, et je ferai pleuvoir sur la terre quarante jours et quarante nuits, et j\'effacerai de dessus le sol tous les êtres que j\'ai faits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Et Noé fit tout ce que l\'Eternel lui avait ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Et Noé avait six cents ans quand eut lieu le déluge, une inondation de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Et Noé entra dans l\'arche, et avec lui ses fils, sa femme et les femmes de ses fils, de devant les eaux du déluge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Des animaux purs et de ceux qui ne sont pas purs, des oiseaux et de tout ce qui rampe sur le sol,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'chaque paire, mâle et femelle, entra vers Noé dans l\'arche, comme Dieu l\'avait ordonné à Noé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Et au bout des sept jours les eaux du déluge furent sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'L\'an six cent de la vie de Noé, au deuxième mois, le dix-septième jour du mois, en ce jour-là toutes les fontaines du grand abîme jaillirent et les écluses des cieux s\'ouvrirent,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'et la pluie tomba sur la terre quarante jours et quarante nuits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En ce jour même, Noé entra dans l\'arche, ainsi que Sem, Cham et Japheth, fils de Noé, et la femme de Noé et les trois femmes de ses fils avec eux;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'eux et tous les animaux sauvages des diverses espèces et tous les bestiaux des diverses espèces et tous les reptiles des diverses espèces qui rampent sur la terre et tous les oiseaux des diverses espèces, tous les petits oiseaux, tout ce qui a des ailes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Il vint vers Noé, dans l\'arche deux de chaque sorte de créature ayant souffle de vie;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'ils arrivaient mâle et femelle, de toute chair, comme Dieu le lui avait ordonné. Et l\'Eternel ferma la porte sur lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Et le déluge fut quarante jours sur la terre, et les eaux grossirent et soulevèrent l\'arche, et elle s\'éleva de dessus la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Et les eaux crûrent et devinrent extrêmement grosses sur la terre, et l\'arche flotta sur les eaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Et les eaux ayant crû extraordinairement sur la terre, toutes les hautes montagnes qui sont sous tous les cieux furent couvertes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Les eaux s\'élevèrent de quinze coudées au-dessus, et les montagnes furent couvertes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Et toute créature qui se meut sur la terre périt, oiseaux, bétail, animaux sauvages et toutes les bêtes qui rampent sur la terre, ainsi que tous les hommes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'De tout ce qui existe sur la terre sèche, tout ce qui a souffle de vie dans les narines mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Tout être qui se trouve sur la face du sol disparut, de l\'homme jusqu\'au bétail, jusqu\'aux reptiles et jusqu\'aux oiseaux des cieux. Ils furent effacés de la terre, et il ne fut laissé de reste que Noé et ce qui était avec lui dans l\'arche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Et les eaux furent hautes sur la terre cent cinquante jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Et Dieu se souvint de Noé et de tous les animaux et de tout le bétail qui était avec lui dans l\'arche, et Dieu fit passer un vent sur la terre, et les eaux baissèrent,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'et les fontaines de l\'abîme et les écluses des cieux se fermèrent, et la pluie cessa de tomber des cieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Et les eaux se retirèrent de dessus la terre peu à peu; et les eaux diminuèrent au bout de cent cinquante jours,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'et l\'arche s\'arrêta au septième mois, le dix-septième jour du mois, sur les montagnes d\'Ararat.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Et les eaux allèrent en diminuant jusqu\'au dixième mois, le premier jour du mois, apparurent les sommets des montagnes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Et il arriva qu\'au bout de quarante jours, Noé ouvrit la fenêtre de l\'arche, qu\'il avait faite,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'et lâcha le corbeau; et le corbeau sortit, partant et revenant jusqu\'à ce que les eaux fussent séchées au-dessus de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Et il lâcha la colombe d\'auprès de lui pour voir si les eaux avaient diminué de dessus la face de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Et la colombe, n\'ayant pas trouvé où poser la plante de son pied, revint vers lui dans l\'arche, parce qu\'il y avait des eaux sur la face de toute la terre. Et il étendit la main, la prit et la fit rentrer auprès de lui dans l\'arche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Et il attendit encore sept autres jours et il lâcha de nouveau la colombe hors de l\'arche;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'et la colombe revint vers lui sur le soir, et voici elle avait dans son bec une feuille d\'olivier toute fraîche; et Noé reconnut que les eaux avaient diminué sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Et il attendit encore sept autres jours et lâcha la colombe; et elle ne revint plus vers lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Et l\'an six cent un, au premier mois, le premier du mois, les eaux avaient séché sur la terre. Noé ôta la couverture de l\'arche et aperçut que la face du sol avait séché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Et au second mois, le vingt-septième jour du mois, la terre fut sèche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Et Dieu parla à Noé en ces mots:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sors de l\'arche, toi, ta femme, tes fils et les femmes de tes fils avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Tous les animaux qui sont avec toi, de toute espèce, oiseaux, quadrupèdes et tous les reptiles qui rampent sur la terre, fais-les sortir avec toi, et qu\'ils abondent sur la terre; qu\'ils fructifient et deviennent nombreux sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Et Noé sortit, et ses fils, sa femme et les femmes de ses fils avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Tous les animaux, tous les reptiles et tous les oiseaux, tous les êtres qui se meuvent sur la terre selon leurs familles, sortirent de l\'arche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Et Noé construisit un autel à l\'Eternel et prit de toutes les bêtes pures et de tous les oiseaux purs, et offrit des holocaustes sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Et l\'Eternel sentit une odeur d\'apaisement, et l\'Eternel dit en son cœur: Je ne maudirai plus désormais la terre à cause de l\'homme parce que les pensées du cœur de l\'homme sont mauvaises dès l\'enfance, et désormais je ne frapperai plus tout être vivant, comme je l\'ai fait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Désormais, tant que la terre durera, les semailles, les moissons, le froid, le chaud, l\'été, l\'hiver, le jour et la nuit ne cesseront point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Et Dieu bénit Noé et ses fils, et leur dit: Fructifiez, multipliez-vous et remplissez la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Vous serez craints et redoutés de tout animal de la terre et de tout oiseau des cieux; toutes les bêtes qui rampent sur la terre et tous les poissons de la mer vous sont livrés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tout ce qui a mouvement et vie vous servira de nourriture; je vous ai donné tout cela comme la verdure des plantes;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'seulement vous ne mangerez pas de chair avec son âme, avec son sang,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'et votre sang à vous, j\'en demanderai compte à cause de vos âmes; j\'en demanderai compte à tout animal; et de la main de l\'homme, de la main de chaque frère je redemanderai l\'âme de l\'homme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Qui versera le sang de l\'homme, par l\'homme son sang sera versé, car Dieu a fait l\'homme à son image.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Et vous, fructifiez et multipliez-vous, abondez sur la terre et vous y multipliez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Et Dieu dit à Noé et à ses fils avec lui:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Et moi, je vais établir mon alliance avec vous et avec votre postérité après vous,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'avec tout être vivant qui est avec vous, oiseau, bétail, et tout animal de la terre qui est avec vous, depuis ceux qui sont sortis de l\'arche jusqu\'à tout animal de la terre;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'j\'établis avec vous cette alliance, que désormais nulle chair ne soit détruite par les eaux du déluge, et qu\'il n\'y ait plus de déluge pour ravager la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Et Dieu dit: Voici le signe de l\'alliance que je mets entre moi et vous et tout être vivant qui est avec vous, à perpétuité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'J\'ai mis mon arc dans la nuée, et il deviendra signe d\'alliance entre moi et la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Il arrivera que quand j\'amoncellerai des nuées sur la terre, l\'arc apparaîtra dans la nuée;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'et je me souviendrai de l\'alliance que j\'ai avec vous et avec tout être vivant, de quelque sorte qu\'il soit, pour que les eaux ne deviennent plus un déluge détruisant les créatures de toute sorte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Et l\'arc sera dans la nuée, et en le voyant je me souviendrai de l\'alliance perpétuelle qui existe entre Dieu et tout être, de quelque sorte que ce soit, qui vit sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Et Dieu dit à Noé: Tel est le signe de l\'alliance que j\'ai établie entre moi et toute chair qui est sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Et les fils de Noé qui sortirent de l\'arche étaient Sem, Cham et Japheth; et Cham était père de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ces trois sont les fils de Noé, et c\'est d\'eux que descendent les habitants de toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Et Noé, qui était cultivateur, commença à planter de la vigne,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'et il but du vin et fut ivre, et il se découvrit au milieu de sa tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Et Cham, père de Canaan, vit la nudité de son père et le rapporta à ses deux frères dehors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Et Sem avec Japheth prit le manteau, et ils le mirent sur leurs épaules à tous deux, et ils marchèrent en arrière et couvrirent la nudité de leur père. Leurs faces étant tournées en arrière, ils n\'avaient point vu la nudité de leur père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Et Noé se réveilla de son ivresse, et il sut ce que lui avait fait son plus jeune fils,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'et il dit: Maudit soit Canaan! Il sera pour ses frères le serviteur des serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Puis il dit: Béni soit l\'Eternel, Dieu de Sem, Et que Canaan soit son serviteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Que Dieu donne de l\'espace à Japheth, Et qu\'il habite dans les tentes de Sem; Et que Canaan soit son serviteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Et Noé vécut après le déluge trois cent cinquante ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Et tous les jours de Noé furent neuf cent cinquante ans, et il mourut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Voici la postérité des fils de Noé, Sem, Cham et Japheth. Il leur naquit des fils après le déluge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Fils de Japheth: Gomer, Magog, Madaï, Javan, Tubal, Mésec et Thiras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Fils de Gomer: Askénaz, Riphath et Thogarma.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Fils de Javan: Elisa et Tharsis, Kittim et Dodanim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'C\'est d\'eux que viennent les peuples dispersés, dans les îles des nations, dans leurs divers pays, chacun selon sa langue, selon leurs familles, en leurs nations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Fils de Cham: Cusch, Mitsraïm, Put et Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Fils de Cusch: Séba, Havila, Sabétha, Raama et Sabthéca. Fils de Raama: Schéba et Dédan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Et Cusch engendra Nimrod; celui-ci a commencé à être un homme puissant sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'C\'était un puissant chasseur devant l\'Eternel; c\'est pourquoi l\'on dit: Comme Nimrod, puissant chasseur devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Et le commencement de son empire fut Babel, Erec, Accad et Calné au pays de Sinéar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Etant allé de ce pays-là en Assur, il bâtit Ninive, Rehoboth-Ir et Calach,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'et Résen entre Ninive et Calach; c\'est la grande ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Et Mitsraïm engendra les Ludim, les Anamim, les Lehabim, les Naphthuchim,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'les Pathrusim, les Casluchim, c\'est de là que sont sortis les Philistins, et les Caphthorim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Et Canaan engendra Sidon, son premier-né, et Heth,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'et le Jébusien, l\'Amorrhéen, le Guirgasien,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'le Hévien, l\'Arkien, le Sinien,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'l\'Arvadien, le Tsémarien et le Hamathien. Ensuite les familles des Cananéens s\'étendirent;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'et le territoire des Cananéens alla de Sidon, dans la direction de Guérar, jusqu\'à Gaza; dans la direction de Sodome, Gomorrhe, Adma et Tséboïm, jusqu\'à Léscha.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Tels sont les fils de Cham selon leurs familles, selon leurs langues, dans leurs divers pays, dans leurs nations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Et des fils naquirent aussi à Sem, qui est le père de tous les fils d\'Héber et le frère aîné de Japheth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Fils de Sem: Elam, Assur, Arpacsad, Lud et Aram.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Fils d\'Aram: Uts, Hul, Guéther et Mas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Et Arpacsad engendra Sélah, et Sélah engendra Héber.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Et Héber eut deux fils; le nom de l\'un était Péleg, parce que de son temps la terre était partagée; et le nom de son frère était Joktan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Et Joktan engendra Almodad, Séleph, Hatsarmaveth, Jérach,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Uzal, Dikla,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimaël, Schéba,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Havila et Jobab. Tous ceux-là sont fils de Joktan;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'et le pays où ils habitèrent fut la montagne d\'Orient, à partir de Mésa, dans la direction de Séphar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Tels sont les fils de Sem selon leurs familles, selon leurs langues, dans leurs divers pays, selon leurs nations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Telles sont les familles des fils de Noé selon leurs générations, dans leurs nations. Et c\'est d\'eux que sont sorties les nations qui se sont dispersées sur la terre après le déluge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Or toute la terre avait la même langue et les mêmes mots.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Et étant allés du côté de l\'orient, ils trouvèrent une plaine dans le pays de Sinéar, et ils s\'y établirent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Et ils se dirent entre eux: Allons, faisons des briques et cuisons-les au feu. Et la brique leur servit de pierre, et le bitume leur servit de mortier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Et ils dirent: Allons, bâtissons-nous une ville et une tour dont le sommet soit dans les cieux, et faisons-nous un monument, de peur que nous ne soyons dispersés sur la face de toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Et l\'Eternel descendit pour voir, la ville et la tour que bâtissaient les fils des hommes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Et l\'Eternel dit: Voici, ils ne sont qu\'un peuple et ils ont tous une même langue, et ceci est le commencement de leurs entreprises; et maintenant, quoi qu\'ils veuillent entreprendre, rien ne les empêchera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Allons! descendons et confondons là leur langage, de sorte que l\'un ne comprenne plus le langage de l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Et l\'Eternel les dispersa de là sur la face de toute la terre, et ils cessèrent de bâtir la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'C\'est pourquoi elle fut appelée Babel, parce que c\'est là que l\'Eternel confondit le langage de toute la terre, et c\'est de là que l\'Eternel les a dispersés sur la face de toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Voici la postérité de Sem. Sem, âgé de cent ans, engendra Arpacsad, deux ans après le déluge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Et après qu\'il eut engendré Arpacsad, Sem vécut cinq cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Et Arpacsad vécut trente-cinq ans, et il engendra Sélah.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Et après qu\'il eut engendré Sélah, Arpacsad vécut quatre cent trois ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Et Sélah vécut trente ans, et il engendra Héber.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Et après qu\'il eut engendré Héber, Sélah vécut quatre cent trois ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Et Héber vécut trente-quatre ans, et il engendra Péleg.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Et après qu\'il eut engendré Péleg, Héber vécut quatre cent trente ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Et Péleg vécut trente ans, et il engendra Réhu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Et après qu\'il eut engendré Réhu, Péleg vécut deux cent neuf ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Et Réhu vécut trente-deux ans, et il engendra Sérug.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Et après qu\'il eut engendré Sérug, Réhu vécut deux cent sept ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Et Sérug vécut trente ans, et il engendra Nachor.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Et après qu\'il eut engendré Nachor, Sérug vécut deux cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Et Nachor vécut vingt-neuf ans, et il engendra Thérach.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Et après qu\'il eut engendré Thérach, Nachor vécut cent dix-neuf ans, et il engendra des fils et des filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Et Thérach vécut soixante-dix ans, et il engendra Abram, Nachor et Haran.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Voici la postérité de Thérach. Thérach avait engendré Abram, Nachor et Haran, et Haran avait engendré Lot.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Et Haran mourut en présence de Thérach son père, dans le pays de sa naissance, à Ur des Chaldéens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Et Abram et Nachor prirent des femmes; le nom de la femme d\'Abram fut Saraï, et le nom de la femme de Nachor, Milca, fille de Haran, père de Milca et de Jisca;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'et Saraï fut stérile, elle n\'avait pas d\'enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Et Thérach prit Abram, son fils, et Lot, fils d\'Haran, son petit-fils, et Saraï, sa belle-fille, femme d\'Abram son fils, et ils sortirent avec eux d\'Ur des Chaldéens pour aller au pays de Canaan, et ils vinrent jusqu\'à Charan et s\'y établirent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Et les jours de Thérach furent deux cent cinq ans, et Thérach mourut à Charan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Et l\'Eternel dit à Abram: Va-t-en de ton pays, de ta famille et de la maison de ton père, au pays que je te montrerai;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'et je ferai de toi une grande nation; je te bénirai et je rendrai grand ton nom. Tu seras une bénédiction:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'je bénirai ceux qui te béniront; et celui qui t\'injuriera, je le maudirai; et toutes les familles de la terre seront bénies en toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Et Abram s\'en alla comme l\'Eternel le lui avait dit, et Lot alla avec lui. Abram avait soixante-quinze ans quand il sortit de Charan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Et Abram prit Saraï sa femme et Lot, fils de son frère, et tous les biens dont ils s\'étaient enrichis et les gens qu\'ils avaient acquis à Charan, et ils sortirent pour aller au pays de Canaan. Et ils arrivèrent au pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Et Abram traversa le pays jusqu\'au lieu où est Sichem, jusqu\'au chêne de Moré. Or les Cananéens étaient alors dans le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Et l\'Eternel apparut à Abram et lui dit: Je donnerai ce pays à ta postérité. Et il éleva là un autel à l\'Eternel qui lui était apparu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Puis il se transporta de là à la montagne, à l\'orient de Béthel, et dressa sa tente, ayant Béthel à l\'occident et Aï à l\'orient, et il éleva là un autel à l\'Eternel et invoqua le nom de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Puis Abram partit, allant de campement en campement vers le Midi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Et il y eut une famine dans le pays, et Abram descendit en Egypte pour y séjourner, car la famine était grande dans le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Et lorsque il fut près d\'entrer en Egypte, il dit à Saraï sa femme: Ecoute; je sais que, comme tu es une belle femme,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'voici ce qui arrivera: Lorsque les Egyptiens te verront, ils diront: C\'est sa femme; ils me tueront et te laisseront vivre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dis donc que tu es ma sœur, afin qu\'il m\'arrive du bien à cause de toi et qu\'on me laisse la vie par égard pour toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Et comme Abram arrivait en Egypte, les Egyptiens virent que sa femme était fort belle,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'et les grands de Pharaon, l\'ayant vue, la vantèrent à Pharaon, et cette femme fut prise et emmenée dans la maison de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Et il fit du bien à Abram à cause d\'elle. Et il eut des moutons, des bœufs, des ânes, des serviteurs, des servantes, des ânesses et des chameaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Et l\'Eternel frappa Pharaon de grandes calamités, ainsi que sa maison, à cause de Saraï, femme d\'Abram.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Et Pharaon appela Abram et lui dit. Qu\'est-ce que tu m\'as fait? Pourquoi ne m\'as-tu pas déclaré qu\'elle était ta femme?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Pourquoi as-tu dit: C\'est ma sœur; de sorte que je l\'ai prise pour femme? Maintenant, voilà ta femme; prends-la et va-t-en.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Et Pharaon chargea des gens de le faire partir, lui, sa femme et tout ce qui lui appartenait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Et Abram partant d\'Egypte monta dans le Midi, lui, sa femme et tout ce qui lui appartenait, et Lot avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Or Abram était fort riche en troupeaux, en argent et en or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Puis il alla de campement en campement du Midi jusqu\'à Béthel, jusqu\'à l\'endroit où avait été dressée sa tente au commencement, entre Béthel et Aï,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'à l\'endroit où était l\'autel qu\'il avait fait la première fois. Et là Abram invoqua le nom de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Or Lot, qui marchait avec Abram, avait aussi des moutons, des bœufs et des tentes,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'et le pays ne leur suffisait pas pour habiter ensemble, car leurs biens étaient si grands qu\'ils ne pouvaient habiter ensemble.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Et il y eut un différend entre les bergers des troupeaux d\'Abram et ceux des troupeaux de Lot; les Cananéens et les Phéréziens étaient alors établis dans le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Et Abram dit à Lot: Qu\'il n\'y ait, n\'est-ce pas, point de débat entre moi et toi et entre mes bergers et les tiens, car nous sommes des frères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Tout le pays n\'est-il pas devant toi? Sépare-toi plutôt de moi. Si tu vas à gauche, je prendrai la droite, et si tu vas à droite, je prendrai la gauche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Et Lot, levant les yeux, vit toute la plaine du Jourdain jusqu\'à Tsoar: elle était, avant que l\'Eternel eût détruit Sodome et Gomorrhe, un pays entièrement arrosé comme le jardin de l\'Eternel, comme la terre d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Et Lot choisit pour soi toute la plaine du Jourdain, et Lot s\'en alla du côté de l\'orient; ils se séparèrent l\'un de l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram habitait dans le pays de Canaan, et Lot habitait au milieu des villes de la plaine, et il dressa ses tentes jusqu\'à Sodome.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Et les gens de Sodome étaient fort mauvais, grands pécheurs contre l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Et l\'Eternel dit à Abram après que Lot se fut séparé de lui: Lève les yeux et, du lieu où tu es, regarde au septentrion, au midi, à l\'orient et à l\'occident:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'tout le pays que tu vois, je le donnerai à toi et à tes descendants à perpétuité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Et je ferai que ta postérité soit comme la poussière de la terre; si l\'on peut compter la poussière de la terre, on comptera aussi ta postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Lève-toi, parcours le pays en long et en large, car je te le donnerai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Et Abram leva ses tentes et vint habiter aux chênes de Mamré, qui sont à Hébron, et il éleva là un autel à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Il arriva au temps d\'Amraphel, roi de Sinéar, d\'Arjoc, roi d\'Ellasar, de Kédorlaomer, roi d\'Elam, et de Thidéal, roi de Goïm,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'qu\'ils firent la guerre à Béra, roi de Sodome, à Birsa, roi de Gomorrhe, à Sinéab, roi d\'Adma, à Séméber, roi de Tséboïm, et au roi de Béla, qui est Tsoar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Tous ceux-ci se rassemblèrent dans la vallée de Siddim, qui est la mer Salée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Douze ans ils avaient été soumis à Kédorlaomer, mais la treizième année ils s\'étaient révoltés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Et la quatorzième année, Kédorlaomer vint avec les rois qui étaient avec lui, et ils battirent les Réphaïm à Astharoth-Karnaïm, les Zuzim à Ham, les Emim à Savé-Kiriathaïm');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'et les Horiens, dans leur montagne de Séir, jusqu\'à El-Paran, qui est près du désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Puis s\'en retournant, ils arrivèrent à la fontaine du Jugement, qui est Kadès, et ils battirent tout le pays des Amalékites, et aussi les Amorrhéens qui habitaient à Hatsatson-Thamar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Et le roi de Sodome sortit avec le roi de Gomorrhe, le roi d\'Adma, le roi de Tséboïm et le roi de Béla, qui est Tsoar, et ils se rangèrent en bataille contre eux dans la vallée de Siddim,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'contre Kédorlaomer, roi d\'Elam, Thidéal, roi de Goïm, Amraphel, roi de Sinéar, et Arjoc, roi d\'Ellasar, quatre rois contre les cinq.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Et il y avait dans la vallée de Siddim beaucoup de puits de bitume, et les rois de Sodome et de Gomorrhe s\'enfuirent, et ils y tombèrent, et ceux qui échappèrent s\'enfuirent dans la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Et [les ennemis] prirent tous les biens de Sodome et Gomorrhe et tous leurs vivres, et ils s\'en allèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ils prirent aussi Lot, fils du frère d\'Abram, et ses biens, et s\'en allèrent; or il demeurait à Sodome.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Et l\'un des fugitifs vint l\'annoncer à Abram l\'Hébreu; or il campait dans la chênaie de Mamré, l\'Amorrhéen, frère d\'Escol et frère d\'Aner; ils étaient des alliés d\'Abram.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Et quand Abram apprit que son frère avait été emmené captif, il mit sur pied ses gens nés dans sa maison, au nombre de trois cent dix-huit, et il poursuivit les rois jusqu\'à Dan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Et ayant partagé sa troupe pour les attaquer pendant la nuit avec ses serviteurs, il les battit et les poursuivit jusqu\'à Hoba, qui est au nord de Damas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Et il ramena tous les biens; il ramena aussi Lot, son frère, et ses biens, et aussi les femmes et les gens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Et comme Abram revenait après avoir battu Kédorlaomer et les rois qui étaient avec lui, le roi de Sodome alla au-devant de lui dans la vallée de Savé; c\'est la vallée du Roi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Et Melchisédek, roi de Salem, apporta du pain et du vin; il était sacrificateur du Dieu Très-Haut;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'et il bénit Abram et dit: Béni soit Abram par le Dieu Très-Haut qui a fondé les cieux et la terre,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'et béni soit le Dieu Très-Haut qui a livré tes ennemis entre tes mains! Et Abram lui donna la dîme de tout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Et le roi de Sodome dit à Abram: Donne-moi les personnes et prends pour toi les biens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram répondit au roi de Sodome: J\'ai levé ma main vers l\'Eternel, le Dieu Très-Haut, qui a fondé les cieux et la terre:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Si d\'un fil à une courroie de soulier je prends quoi que ce soit qui t\'appartienne!... Et tu ne diras pas: J\'ai enrichi Abram.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Je ne veux rien, si ce n\'est ce qu\'ont mangé les jeunes gens et la part des hommes qui sont venus avec moi, Aner, Escol et Mamré; eux prendront leur part.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Après ces choses, la parole de l\'Eternel fut adressée à Abram en vision, disant: Ne crains point, Abram; je suis ton bouclier; ta récompense sera très grande.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Et Abram dit: Seigneur Eternel, que me donneras-tu? Je passe ma vie sans enfants, et l\'héritier de ma maison est Dammések Eliézer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Et Abram dit: Vois, tu ne m\'as pas donné de postérité, et voici un homme attaché à ma maison sera mon héritier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Et voici, la parole de l\'Eternel lui fut adressée en ces termes: Celui-ci ne sera pas ton héritier, mais celui qui sortira de tes entrailles sera ton héritier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Et il le mena dehors et dit: Regarde vers le ciel et compte les étoiles, si tu peux les compter. Et il lui dit: Ainsi sera ta postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Et Abram eut foi en l\'Eternel, et l\'Eternel le lui imputa à justice.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Et il lui dit: Je suis l\'Eternel qui t\'ai fait sortir d\'Ur des Chaldéens afin de te donner ce pays pour le posséder.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Et il dit: Seigneur Eternel, à quoi connaîtrai-je que je le posséderai?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Et il lui dit: Va me prendre une génisse de trois ans, une chèvre de trois ans, un bélier de trois ans, une tourterelle et un jeune pigeon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Et il lui amena tous ces animaux et les partagea par le milieu, et il mit chaque moitié vis-à-vis de l\'autre; et il ne partagea pas les oiseaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Et les oiseaux de proie fondirent sur les bêtes mortes, et Abram les chassa.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Et comme le soleil allait se coucher, un profond sommeil tomba sur Abram, et voici une terreur, une obscurité profonde, tomba sur lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Et il dit à Abram: Sache bien que ta postérité sera étrangère dans un pays qui ne sera pas à eux; ils y seront en servitude et on les opprimera pendant quatre cents ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Et je jugerai à son tour la nation à laquelle ils auront été asservis, et ensuite ils sortiront avec de grands biens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Et toi, tu t\'en iras en paix vers tes pères; tu seras enseveli dans une heureuse vieillesse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Et à la quatrième génération ils reviendront ici, car jusqu\'à présent l\'iniquité de l\'Amorrhéen n\'est pas à son comble.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Et lorsque le soleil fut couché et que la nuit fut venue, voici une fournaise fumante et un brandon de feu passaient entre ces animaux partagés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En ce jour-là, l\'Eternel traita alliance avec Abram en ces termes: Je donne à ta postérité ce pays, depuis le fleuve d\'Egypte jusqu\'au grand fleuve, au fleuve d\'Euphrate:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'le pays du Kénien, du Kénizien, du Kadmonien,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'du Héthien, du Phérézien, des Réphaïm,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'de l\'Amorrhéen, du Cananéen, du Guirgasien et du Jébusien.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Et Saraï, femme d\'Abram, ne lui avait pas donné d\'enfants; et elle avait une esclave égyptienne nommée Hagar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Et Saraï dit à Abram: Voici, l\'Eternel m\'a rendue stérile; viens donc vers ma servante; peut-être aurai-je d\'elle des fils. Et Abram consentit à ce que disait sa femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Et Saraï, femme d\'Abram, prit Hagar, l\'Egyptienne, sa servante, au bout de dix ans de séjour d\'Abram dans le pays de Canaan, et elle la donna à Abram, son mari, pour qu\'il en fit sa femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Et il alla vers Hagar et elle conçut; et voyant qu\'elle avait conçu, elle n\'eut plus de respect pour sa maîtresse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Et Saraï dit à Abram: L\'outrage qui m\'est fait est sur toi. J\'ai mis ma servante dans ton sein, et quand elle a vu qu\'elle avait conçu, elle n\'a plus eu de respect pour moi. Que l\'Eternel juge entre moi et toi!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Et Abram dit à Saraï: Voici ta servante est en ton pouvoir; fais-lui ce que bon te semble. Et Saraï la maltraita, et elle s\'enfuit de devant elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Et l\'ange de l\'Eternel la trouva près de la source d\'eau dans le désert, près de la source qui est sur le chemin de Sur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'et il dit: Hagar, servante de Saraï, d\'où viens-tu et où vas-tu? Et elle dit: Je m\'enfuis loin de Saraï, ma maîtresse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Et l\'ange de l\'Eternel lui dit: Retourne vers ta maîtresse et laisse-toi maltraiter par elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Et l\'ange de l\'Eternel lui dit: Je te donnerai une postérité extrêmement nombreuse, si nombreuse qu\'on ne la comptera pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Et l\'ange de l\'Eternel lui dit: Voici tu es enceinte et tu enfanteras un fils; tu le nommeras Ismaël, parce que l\'Eternel a entendu ton affliction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Ce sera un âne sauvage que cet homme; sa main sera contre chacun, et la main de chacun sera contre lui, et il dressera ses tentes à la face de tous ses frères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Et elle appela l\'Eternel qui lui avait parlé du nom de Atta-El-Roï, parce qu\'elle avait dit: Ai-je donc ici même vu le Dieu qui me voyait?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'C\'est pourquoi on a appelé ce puits le puits de Lachaï-Roï. Il se trouve entre Kadès et Béred.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Et Hagar enfanta à Abram un fils. Et Abram donna au fils qu\'Hagar lui avait enfanté le nom d\'Ismaël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Et Abram avait quatre-vingt-six ans quand Hagar enfanta Ismaël à Abram.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Abram étant arrivé à l\'âge de quatre-vingt-dix-neuf ans, l\'Eternel apparut à Abram et lui dit: Je suis le Dieu puissant; marche devant ma face et sois intègre:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'je veux faire alliance avec toi, et je t\'accroîtrai extraordinairement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Et Abram tomba la face contre terre, et Dieu parla ainsi avec lui:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Voici mon alliance avec toi: tu deviendras père d\'une multitude de nations,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'et on ne te nommera plus Abram, mais ton nom sera Abraham; car je t\'ai fait le père d\'une multitude de nations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Et je te ferai croître extraordinairement, et je ferai de toi des nations; et des rois sortiront de toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Je ferai de mon alliance avec toi et avec tes descendants d\'âge en âge une alliance perpétuelle, pour être ton Dieu et le Dieu de tes descendants;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'et je donnerai à toi et à tes descendants le pays où tu séjournes comme étranger, tout le pays de Canaan, pour le posséder à perpétuité, et je serai leur Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Et Dieu dit à Abraham: Et toi, tu garderas mon alliance, toi et tes descendants d\'âge en âge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'L\'alliance que vous avez à garder, l\'alliance entre moi et vous et tes descendants, est que vous circoncisiez tous les mâles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Vous vous circoncirez dans votre chair, et cela sera le signe de l\'alliance entre moi et vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Quand il aura huit jours, tout mâle chez vous, d\'âge en âge, devra être circoncis, qu\'il soit né dans la maison ou acquis à prix d\'argent d\'un étranger quelconque qui n\'est pas de ta race.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Qu\'on ne manque pas de circoncire les mâles nés dans ta maison ou acquis pour de l\'argent, et que mon alliance soit dans votre chair comme alliance perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Un incirconcis, un mâle à qui la chair du prépuce n\'aura pas été coupée, cet homme-là sera retranché de son peuple: il aura enfreint mon alliance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Et Dieu dit à Abraham: Saraï ta femme, tu ne la nommeras plus Saraï, car son nom est Sara.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Je la bénirai, et même je te donnerai aussi d\'elle un fils; je la bénirai, et elle deviendra des nations; des rois de peuples sortiront d\'elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Et Abraham tomba la face contre terre, et il rit, et il dit en son cœur: Naîtra-t-il un enfant à un centenaire? Et Sara, une femme de quatre-vingt-dix ans, enfantera-t-elle?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Et Abraham dit à Dieu: Si seulement Ismaël vit devant toi!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Et Dieu dit: Mais Sara, ta femme, va t\'enfanter un fils. Tu le nommeras Isaac, et je ferai de mon alliance avec lui une alliance perpétuelle pour ses descendants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Et quant à Ismaël, je t\'ai entendu. Oui, je l\'ai béni! je le ferai fructifier et l\'accroîtrai extraordinairement. Il engendrera douze princes, et je ferai de lui une grande nation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Et je ferai alliance avec Isaac, que Sara t\'enfantera l\'année prochaine, à cette époque.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Et ayant achevé de parler avec lui, Dieu remonta d\'auprès d\'Abraham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Et Abraham prit Ismaël son fils, ainsi que tous ceux qui étaient nés chez lui et tous ceux qu\'il avait acquis à prix d\'argent, tout mâle d\'entre les gens de la maison d\'Abraham; et il circoncit leur chair en ce jour même, comme Dieu le lui avait commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Et Abraham avait quatre-vingt-dix-neuf ans lorsqu\'il fut circoncis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Et Ismaël, son fils, avait treize ans lorsqu\'il fut circoncis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Ce jour même, Abraham fut circoncis, ainsi qu\'Ismaël son fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Et tous les hommes de sa maison, ceux qui étaient nés chez lui et ceux qui avaient été acquis des étrangers à prix d\'argent, furent circoncis avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'L\'Eternel lui apparut dans la chênaie de Mamré. Comme il était assis à l\'entrée de la tente pendant la chaleur du jour,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'il leva les yeux et aperçut trois hommes se tenant devant lui; et dès qu\'il les vit, il courut à eux de l\'entrée de la tente, et il se prosterna en terre');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'et dit: Seigneur, si j\'ai trouvé grâce à tes yeux, ne passe pas devant ton serviteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Permets qu\'on aille chercher un peu d\'eau, et vous laverez vos pieds. Asseyez-vous sous l\'arbre;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'j\'apporterai un morceau de pain, vous prendrez des forces, puis vous continuerez votre chemin; car c\'est pour cela que vous avez passé devant votre serviteur. Ils répondirent: Fais comme tu l\'as dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Et Abraham s\'empressa d\'entrer dans la tente vers Sara, et il lui dit: Prends vite trois mesures de fleur de farine, pétris et fais des gâteaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Puis Abraham courut au bétail et prit une bête tendre et bonne et la donna au valet, qui se hâta de l\'apprêter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Et il prit du beurre et du lait et la bête qu\'il avait apprêtée, et il les mit devant eux; et lui se tenait debout auprès d\'eux sous l\'arbre, et ils mangèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Puis ils lui dirent: Où est Sara, ta femme? Il répondit: Elle est là dans la tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Et il dit: Certainement je reviendrai chez toi l\'an prochain, et voici Sara ta femme aura un fils. Et Sara entendait cela à l\'entrée de la tente, derrière lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Or Abraham et Sara étaient des vieillards, fort avancés dans la vie; Sara était hors d\'âge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Et Sara rit en elle-même en se disant: Vieille comme je suis, aurais-je encore du plaisir? Et mon seigneur est vieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Et l\'Eternel dit à Abraham: Pourquoi donc Sara a-t-elle ri en se disant: Est-ce que vraiment j\'enfanterai, vieille comme je suis?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Y a-t-il rien qui soit trop merveilleux pour l\'Eternel? A cette saison je reviendrai vers toi l\'an prochain, et Sara aura un fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Et Sara nia disant: Je n\'ai pas ri; car elle eut peur. Mais il lui dit: Non, car tu as ri.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Et ces hommes se levèrent de là et se tournèrent du côté de Sodome. Abraham allait avec eux pour les accompagner.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Or l\'Eternel dit: Cacherai-je à Abraham ce que je vais faire?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham doit devenir une nation grande et forte, et toutes les nations de la terre seront bénies en lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Car je l\'ai choisi afin qu\'il ordonne à ses fils et à sa maison après lui de garder la voie de l\'Eternel, en faisant ce qui est juste et droit, pour que l\'Eternel fasse venir sur Abraham ce qu\'il lui a promis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Et l\'Eternel dit: Le cri qui s\'élève de Sodome et Gomorrhe est bien fort et leur iniquité bien énorme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Je veux descendre et voir si, comme le bruit en est venu jusqu\'à moi, leur crime est arrivé au comble; ou si cela n\'est pas, je veux le savoir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Et ces hommes partirent et s\'en allèrent à Sodome; et Abraham se tenait encore devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Et Abraham s\'approcha et dit: Est-ce que vraiment tu ferais périr le juste avec le coupable?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Peut-être y a-t-il cinquante justes dans la ville; les ferais-tu donc périr et ne pardonnerais-tu pas à ce lieu à cause de ces cinquante justes qui s\'y trouveraient?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Loin de toi d\'agir de la sorte, de faire mourir le juste avec le coupable! Ainsi il en serait du juste comme du coupable! Loin de toi! Celui qui juge toute la terre ne rendrait-il pas justice?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Et l\'Eternel dit: Si je trouve à Sodome cinquante justes, au milieu de la ville, je pardonnerai à tout le lieu pour l\'amour d\'eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Et Abraham reprit: Voilà que j\'en suis venu à parler au Seigneur, moi qui suis poudre et cendre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Peut-être que des cinquante justes il en manquera cinq. Détruiras-tu pour cinq hommes toute la ville? Et il dit: Je ne la détruirai pas si j\'en trouve quarante-cinq.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Et Abraham continua encore à lui parler; il lui dit: Peut-être s\'en trouvera-t-il là quarante. Et il dit: Je ne le ferai pas pour l\'amour des quarante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Et Abraham dit: Que le Seigneur veuille ne pas s\'irriter si je parle! Peut-être s\'en trouvera-t-il trente. Et il dit: Je ne le ferai pas si j\'y en trouve trente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Et Abraham dit: Voilà que j\'en suis venu à parler au Seigneur. Peut-être s\'en trouvera-t-il vingt. Et il dit: Je ne la détruirai pas pour l\'amour des vingt.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Et Abraham dit: Que le Seigneur veuille ne pas s\'irriter, et je parlerai encore cette seule fois: Peut-être s\'en trouvera-t-il dix. Et il dit: Je ne la détruirai pas pour l\'amour des dix.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Et l\'Eternel s\'en alla quand il eut achevé de parler à Abraham, et Abraham retourna chez lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Et les deux anges arrivèrent à Sodome le soir. Et Lot était assis à la porte de Sodome. Et Lot, les voyant, se leva pour aller au-devant d\'eux, et il se prosterna le visage contre terre,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'et il dit: Je vous prie, mes seigneurs, veuillez entrer chez votre serviteur pour y passer la nuit; lavez vos pieds, et demain matin vous continuerez votre chemin. Et ils dirent: Non, nous passerons la nuit sur la place.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Et il les pressa tant qu\'ils allèrent chez lui et entrèrent dans sa maison. Et il leur fit un festin et cuisit des pains sans levain, et ils mangèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ils n\'étaient pas encore couchés que les hommes de la ville, les hommes de Sodome, entourèrent la maison, depuis les enfants jusqu\'aux vieillards, le peuple entier, de tous les bouts de la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Et ils appelèrent Lot et lui dirent: Où sont ces hommes qui sont entrés vers toi cette nuit? Fais-les sortir vers nous, que nous les connaissions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Et Lot s\'avança vers eux à l\'entrée de la maison, et ayant fermé la porte derrière lui,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'il leur dit: Non, mes frères, je vous en prie, ne faites pas le mal!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Voyez, j\'ai deux filles qui n\'ont pas connu d\'homme; laissez-moi vous les amener, et faites-leur ce qui vous plaira; mais à ces hommes, ne leur faites rien, car c\'est pour cela qu\'ils sont venus s\'abriter sous mon toit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Et ils dirent à Lot: Ote-toi de là! Et ils ajoutèrent: Cet individu est venu comme étranger, et il fait le juge! Eh bien! nous te ferons pis qu\'à eux. Et ils repoussèrent violemment cet homme, Lot, et ils s\'approchèrent pour enfoncer la porte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Et les deux hommes étendirent la main et retirèrent Lot vers eux dans la maison en fermant la porte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Et ils frappèrent d\'éblouissement les gens qui étaient à l\'entrée de la maison, depuis le plus petit jusqu\'au plus grand, et ceux-ci se lassèrent de chercher la porte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Et les hommes dirent à Lot: Qui as-tu ici? Gendres, fils, filles et qui que ce soit que tu aies dans la ville, fais-les sortir de ce lieu;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'car nous allons détruire ce lieu, parce qu\'un grand cri s\'est élevé contre eux devant l\'Eternel et que l\'Eternel nous a envoyés pour détruire la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Et Lot sortit et parla aux fiancés de ses filles et leur dit: Levez-vous, sortez de ce lieu, car l\'Eternel va détruire la ville. Et il sembla à ses gendres qu\'il plaisantait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Dès que l\'aube parut, les anges pressèrent Lot en disant: Lève-toi, prends ta femme et les deux filles qui sont ici, afin que tu ne périsses pas dans le châtiment de cette ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Et comme il tardait, ces hommes le prirent par la main, lui, sa femme et ses deux filles, parce que l\'Eternel voulait l\'épargner; et ils le firent sortir et le mirent hors de la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Et dès qu\'ils les eurent fait sortir, l\'un d\'eux dit: Sauve-toi! Il y va de ta vie. Ne regarde pas derrière toi et ne t\'arrête nulle part dans la Plaine; sauve-toi à la montagne, de peur que tu ne périsses.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Et Lot leur dit: Oh non! Seigneur:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'voici, ton serviteur a trouvé grâce à tes yeux, et tu as fait un grand acte de bonté à mon égard en me sauvant la vie; mais moi, je ne puis me sauver à la montagne; je risquerais d\'être atteint par la destruction et de périr.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Voilà cette ville qui est assez proche pour s\'y réfugier et qui n\'est que peu de chose; laisse-moi m\'y sauver, n\'est-elle pas petite, et que je vive.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Et il lui dit: Oui, je t\'accorde encore ceci, de ne pas détruire la ville dont tu m\'as parlé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Hâte-toi de t\'y sauver; car je ne puis rien faire que tu n\'y sois arrivé. C\'est pourquoi on a nommé la ville Tsoar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Le soleil se leva sur la terre, et Lot entra à Tsoar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Alors l\'Eternel fit pleuvoir sur Sodome et sur Gomorrhe du soufre et du feu d\'auprès de l\'Eternel, du ciel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Et il détruisit ces villes et toute la Plaine et tous les habitants des villes et les germes de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Et la femme de Lot regarda en arrière et devint une colonne de sel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Et Abraham se rendit le matin au lieu où il s\'était tenu devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Et il regarda à ses pieds du côté de Sodome et de Gomorrhe et sur toute l\'étendue de la Plaine, et voici la fumée de la terre montait comme la fumée d\'une fournaise.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Et il arriva que, lorsque Dieu détruisit les villes de la Plaine, Dieu se souvint d\'Abraham, et il fit échapper Lot au bouleversement, lorsqu\'il bouleversa les villes où Lot habitait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Et Lot monta de Tsoar et habita à la montagne, ayant avec lui ses deux filles, car il craignait d\'habiter à Tsoar; et il habitait dans une caverne, lui et ses deux filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Et l\'aînée dit à la cadette: Notre père est vieux, et il n\'y a pas d\'homme dans le pays pour venir vers nous selon l\'usage de tous les pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Allons! faisons boire du vin à notre père et couchons avec lui, et nous aurons de notre père une postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Elles firent donc boire du vin à leur père cette nuit-là, et l\'aînée vint et coucha avec son père, qui ne s\'aperçut ni de son coucher ni de son lever.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Le lendemain, l\'aînée dit à la cadette: Voici j\'ai couché hier avec mon père; faisons-lui boire du vin encore cette nuit et va coucher avec lui, et nous aurons de notre père une postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Elles firent donc encore boire du vin à leur père cette nuit-là, et la cadette se leva et se coucha auprès de lui, et il ne s\'aperçut ni de son coucher ni de son lever.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Les deux filles de Lot conçurent de leur père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'L\'aînée eut un fils, qu\'elle nomma Moab; c\'est le père des Moabites qui existent encore.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Et la cadette eut aussi un fils, qu\'elle nomma Ben-Ammi; c\'est le père des fils d\'Ammon qui existent encore.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Et Abraham partit de là pour la contrée du Midi, et s\'établit entre Kadès et Sur, et il séjourna à Guérar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Et Abraham dit de Sara sa femme: C\'est ma sœur. Et Abimélek, roi de Guérar, envoya prendre Sara.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Et Dieu vint vers Abimélek de nuit en songe et lui dit: Tu vas mourir à cause de la femme que tu as prise: elle a un mari.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Or Abimélek ne s\'était pas approché d\'elle; et il dit: Seigneur, feras-tu mourir des gens même innocents?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Ne m\'a-t-il pas dit: C\'est ma sœur? Et elle-même m\'a dit aussi: C\'est mon frère. C\'est avec un cœur intègre et des mains pures que j\'ai fait cela.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Et Dieu lui dit en songe: Moi aussi je sais que c\'est avec un cœur intègre que tu as fait cela; aussi t\'ai-je retenu de pécher contre moi; c\'est pourquoi je ne t\'ai pas permis de la toucher.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Et maintenant, rends la femme de cet homme, car il est prophète; il intercédera pour toi et tu vivras. Et si tu ne la rends pas, sache que tu mourras certainement, toi et tous ceux qui t\'appartiennent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Et dès le matin Abimélek appela ses serviteurs et leur rapporta toutes ces choses, et ces gens craignirent extrêmement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Et Abimélek appela Abraham et lui dit: Que nous as-tu fait? Et en quoi ai-je manqué à ton égard, que tu aies attiré sur moi et sur mon royaume une si grande culpabilité? Tu as fait avec moi des choses qui ne se font pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Et Abimélek dit à Abraham: A quoi as-tu pensé en agissant de la sorte?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Et Abraham dit: C\'est que je me disais: Sans doute qu\'il n\'y a pas de crainte de Dieu en ce lieu-ci et qu\'ils me tueront à cause de ma femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Et d\'ailleurs elle est réellement ma sœur; elle est fille de mon père, quoiqu\'elle ne soit pas fille de ma mère, et elle est devenue ma femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Et lorsque Dieu m\'a fait errer loin de la maison de mon père, je lui ai dit: Voici le service que tu me rendras; partout où nous arriverons, tu diras de moi: C\'est mon frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Alors Abimélek prit des brebis et des bœufs, des serviteurs et des servantes, qu\'il donna à Abraham, et il lui rendit Sara, sa femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Et Abimélek dit: Mon pays est à ta disposition; habite où bon te semblera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Et à Sara il dit: Voici, j\'ai donné mille pièces d\'argent à ton frère; c\'est un dédommagement en vue de ceux qui sont avec toi, mais sur le tout c\'est toi qui es blâmable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Alors Abraham intercéda auprès de Dieu, et Dieu guérit Abimélek et sa femme et ses esclaves, et ils eurent des enfants;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'car l\'Eternel avait rendu stériles toutes les femmes dans la maison d\'Abimélek à cause de Sara, femme d\'Abraham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Et l\'Eternel visita Sara, comme il l\'avait dit; et l\'Eternel accomplit pour Sara ce qu\'il avait promis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Et Sara conçut et enfanta à Abraham un fils dans sa vieillesse, au terme que Dieu lui avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Et Abraham nomma le fils qui lui était né, que Sara lui avait enfanté, Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Et Abraham circoncit Isaac, son fils, à l\'âge de huit jours, comme Dieu le lui avait ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham avait cent ans, quand Isaac, son fils, lui naquit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Et Sara dit: Dieu m\'a donné de quoi rire; quiconque l\'apprendra rira en pensant à moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Elle dit encore: Qui eût dit à Abraham: Sara a allaité des fils? Car j\'ai donné un fils à sa vieillesse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Et l\'enfant grandit, et on le sevra. Et Abraham fit un grand festin le jour où l\'on sevra Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Et Sara vit le fils d\'Hagar, l\'Egyptienne, qu\'elle avait enfanté à Abraham, qui riait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Et elle dit à Abraham: Chasse cette esclave et son fils, car le fils de cette esclave là n\'héritera pas avec mon fils, avec Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Et cela chagrina fort Abraham à cause de son fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Mais Dieu dit à Abraham: Ne te chagrine pas à cause de l\'enfant et de ta servante; quoi que Sara te dise, consens-y, car c\'est d\'Isaac que naîtra la postérité qui portera ton nom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Néanmoins du fils de l\'esclave je ferai aussi une nation, parce qu\'il est né de toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Le lendemain, dès le matin, Abraham prit du pain, une outre d\'eau qu\'il donna à Hagar et qu\'il lui mit sur l\'épaule, et l\'enfant, et il la renvoya. Et elle s\'en alla et s\'égara dans le désert de Béerséba.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Et l\'eau qui était dans l\'outre s\'épuisa; alors elle jeta l\'enfant sous l\'un des arbrisseaux,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'et elle s\'en alla s\'asseoir vis-à-vis, à une portée d\'arc, car elle disait: Que je ne voie pas mourir l\'enfant. Et elle s\'assit vis-à-vis, éleva la voix et pleura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Et Dieu entendit la voix du jeune garçon, et l\'ange de Dieu appela des cieux Hagar et lui dit: Qu\'as-tu, Hagar? Ne crains point, car Dieu a entendu la voix du jeune garçon là où il est.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Lève-toi, relève le jeune garçon et prends-le par la main, car je ferai de lui une grande nation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Et Dieu lui ouvrit les yeux, et elle vit un puits; elle alla remplir d\'eau son outre et donna à boire au jeune garçon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Et Dieu fut avec le jeune garçon, et il grandit; il habitait au désert et fut un tireur d\'arc.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Et il habitait dans le désert de Paran, et sa mère prit pour lui une femme au pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Et il arriva en ce temps-là qu\'Abimélek avec Picol, chef de son armée, parla ainsi à Abraham: Dieu est avec toi dans tout ce que tu fais.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Maintenant donc jure-moi ici par le nom de Dieu que tu ne tromperas ni moi ni mes enfants ou petits-enfants; comme j\'ai agi avec bonté envers toi, tu agiras de même envers moi et envers le pays où tu séjournes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Et Abraham répondit: Je le jurerai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Mais Abraham fit des reproches à Abimélek au sujet du puits dont les serviteurs d\'Abimélek s\'étaient emparés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Et Abimélek dit: Je ne sais qui a fait cela; toi-même tu ne m\'en avais pas informé, et moi je n\'en ai entendu parler qu\'aujourd\'hui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Et Abraham prit des brebis et des bœufs et les donna à Abimélek, et ils firent alliance eux deux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Et Abraham mit à part sept jeunes brebis du troupeau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Et Abimélek dit à Abraham: Qu\'est-ce que ces sept jeunes brebis que tu as mises à part?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Et il répondit: C\'est que tu accepteras de moi ces sept jeunes brebis, parce que ceci fera foi en ma faveur que j\'ai creusé ce puits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'C\'est pourquoi on a appelé ce lieu-là Béerséba, parce que c\'est là qu\'ils ont tous deux prêté serment.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Ainsi il firent alliance à Béerséba; puis Abimélek se leva avec Picol, chef de son armée, et ils retournèrent au pays des Philistins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Et Abraham planta un tamarisc à Béerséba, et il invoqua le nom de l\'Eternel, Dieu d\'éternité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Et Abraham séjourna longtemps au pays des Philistins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Il arriva après ces choses que Dieu mit à l\'épreuve Abraham, et il lui dit: Abraham! Et il répondit: Me voici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Et il dit: Prends ton fils, ton unique, celui que tu aimes, Isaac, et t\'en va au pays de Morija, et là offre-le en holocauste sur une montagne que je te dirai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Et Abraham se leva de bon matin, bâta son âne, prit deux de ses serviteurs avec lui et Isaac son fils; il fendit le bois de l\'holocauste, puis il partit et s\'en alla vers le lieu que Dieu lui avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Le troisième jour, Abraham, levant les yeux, vit le lieu de loin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Et Abraham dit à ses serviteurs: Tenez-vous ici avec l\'âne; moi et le jeune garçon, nous voulons aller jusque-là et adorer, puis revenir vers vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Et Abraham prit le bois de l\'holocauste et le mit sur Isaac son fils; et il prit dans sa main le feu et le couteau, et ils s\'en allèrent tous deux ensemble.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Et Isaac parla à Abraham son père, et dit: Mon père! Et Abraham dit: Me voici, mon fils. Et il dit: Voilà le feu et le bois, mais où est l\'agneau pour l\'holocauste?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Et Abraham dit: Dieu verra à trouver l\'agneau pour l\'holocauste, mon fils. Et ils allaient tous deux ensemble.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Et ils arrivèrent au lieu que Dieu lui avait dit; et Abraham y dressa l\'autel et arrangea le bois; et il lia Isaac son fils, et il le mit sur l\'autel, par-dessus le bois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Et Abraham étendit la main et prit le couteau pour égorger son fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Et l\'ange de l\'Eternel lui cria des cieux: Abraham! Abraham! Et il répondit: Me voici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Et l\'ange dit: Ne porte pas la main sur le jeune garçon et ne lui fais rien, car maintenant je sais que tu crains Dieu et que tu ne m\'as pas refusé ton fils, ton unique.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Et Abraham, levant les yeux, aperçut derrière lui un bélier, pris dans les buissons par les cornes. Et Abraham alla prendre le bélier et l\'offrit en holocauste à la place de son fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Et Abraham nomma ce lieu-là: L\'Eternel verra, comme on dit aujourd\'hui: Sur la montagne de l\'Eternel il sera vu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Et l\'ange de l\'Eternel appela des cieux Abraham une seconde fois');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'et dit: J\'ai juré par moi, dit l\'Eternel, que, puisque tu as fait cela et que tu n\'as pas refusé ton fils, ton unique,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'je te bénirai certainement et je te donnerai certainement une postérité qui égalera en nombre les étoiles du ciel et le sable qui est au bord de la mer; et ta postérité possédera la porte de ses ennemis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Et en ta postérité toutes les nations de la terre se béniront, parce que tu as obéi à ma voix.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Et Abraham retourna vers ses serviteurs; et ils se levèrent et s\'en allèrent ensemble à Béerséba. Et Abraham habita à Béerséba.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Et après ces choses, on apporta à Abraham cette nouvelle: Voilà Milca qui a aussi donné des fils à Nachor, ton frère:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uts, son premier-né, Buz, son frère, Kémuel, père d\'Aram,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Késed, Hazo, Pildas, Jidlaph et Béthuel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Et Béthuel fut père de Rébecca. Ces huit-là sont les fils que Milca enfanta à Nachor, frère d\'Abraham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Et sa concubine, nommée Réuma, eut aussi des enfants: Tébach, Gaham, Thahas et Maaca.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sara, ayant vécu cent vingt-sept ans, ce fut la durée de sa vie,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'mourut à Kirjath-Arba, c\'est-à-dire Hébron, dans le pays de Canaan. Et Abraham vint pour faire le deuil de Sara et pour la pleurer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Puis Abraham se leva d\'auprès du corps et parla ainsi aux fils de Heth:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Je suis chez vous un étranger et un hôte; accordez-moi de posséder parmi vous un lieu de sépulture, que je puisse enlever de devant moi mon mort pour l\'ensevelir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Et les fils de Heth répondirent à Abraham en lui disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Ecoute-nous, mon seigneur; tu es un prince de Dieu au milieu de nous; ensevelis ton mort dans le meilleur de nos sépulcres; aucun de nous ne te refusera son sépulcre pour ensevelir ton mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Alors Abraham se leva et se prosterna devant le peuple du pays, les fils de Heth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Et il leur dit: Si vous voulez que j\'enlève de devant moi mon mort pour l\'ensevelir, écoutez-moi et intercédez pour moi auprès d\'Ephron, fils de Tsohar,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'pour qu\'il me donne la caverne de Macpéla, qui est à lui et qui est au bout de son champ, qu\'il me la donne en votre présence pour l\'argent qu\'elle vaut, comme un sépulcre qui m\'appartienne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Or Ephron était assis au milieu des fils de Heth, et Ephron le Héthien répondit à Abraham en présence des fils de Heth, de tous ceux qui entraient par la porte de sa ville; il lui dit:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Non, mon seigneur, écoute-moi: je te donne le champ et je te donne la caverne qui y est; je te la donne aux yeux des fils de mon peuple; enterre ton mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Et Abraham se prosterna devant le peuple du pays');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'et parla à Ephron en ces termes en présence du peuple du pays: Qu\'il te plaise seulement de m\'écouter: je donne le prix du champ; reçois-le de moi, et j\'enterrerai là mon mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Et Ephron répondit à Abraham en lui disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mon seigneur, écoute: une terre de quatre cents sicles d\'argent, entre moi et toi qu\'est-ce que cela? Enterre ton mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Et Abraham, ayant entendu Ephron, lui pesa l\'argent qu\'il avait dit en présence des fils de Heth, quatre cents sicles d\'argent ayant cours chez le marchand.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Ainsi le champ d\'Ephron, qui est à Macpéla, vis-à-vis de Mamré, le champ, la caverne qui s\'y trouve et tous les arbres qui étaient dans le champ et dans ses confins tout autour,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'demeura acquis à Abraham aux yeux des fils de Heth, de tous ceux qui passaient par la porte de sa ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Après cela, Abraham ensevelit Sara sa femme dans la caverne du champ, de Macpéla, vis-à-vis de Mamré, c\'est-à-dire Hébron, dans le pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Et le champ, et la caverne qui s\'y trouve, demeura à Abraham comme propriété sépulcrale provenant des fils de Heth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Et Abraham était vieux, avancé en âge, et l\'Eternel avait béni Abraham en toutes choses.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Et Abraham dit à son serviteur, l\'intendant de sa maison, qui avait la direction de tout ce qui était à lui: Place ta main sous ma cuisse,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'et je te ferai jurer par l\'Eternel, Dieu des cieux et Dieu de la terre, que tu ne prendras pas pour mon fils une femme d\'entre les filles des Cananéens, au milieu desquels j\'habite;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'mais ce sera dans mon pays et dans le lieu de ma naissance que tu iras prendre une femme pour mon fils, pour Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Et le serviteur lui répondit: Peut-être que cette femme ne voudra pas me suivre dans ce pays-ci; faudra-t-il que je ramène ton fils dans le pays d\'où tu es sorti?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Et Abraham lui dit: Garde-toi bien de ramener là mon fils!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'L\'Eternel, le Dieu des cieux, qui m\'a pris de la maison de mon père et du pays de ma naissance, et qui m\'a dit et qui m\'a juré: Je donnerai ce pays à ta postérité, l\'Eternel enverra son ange devant toi, et tu prendras là une femme pour mon fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Que si la femme ne veut pas te suivre, tu seras dégagé du serment que je te fais faire; seulement tu ne ramèneras pas là mon fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Alors le serviteur plaça sa main sous la cuisse d\'Abraham son maître et lui jura ce qu\'il demandait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Le serviteur prit dix des chameaux de son maître et s\'en alla; or il disposait de tous les biens de son maître. Il partit et alla en Mésopotamie, à la ville de Nachor.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Et il fit ployer les genoux aux chameaux en dehors de la ville, près du puits, sur le soir, à l\'heure où les femmes sortent pour puiser l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Et il dit: Eternel, Dieu d\'Abraham mon maître, veuille me faire rencontrer aujourd\'hui ce que je désire, et use de bonté envers mon maître Abraham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Voici je me tiens près de la source, et les filles des gens de la ville vont sortir pour puiser de l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Que la jeune fille à qui je dirai: Penche ta cruche pour que je boive, et qui répondra: Bois, et je donnerai aussi à boire à tes chameaux, soit celle que tu as destinée à ton serviteur Isaac; et par là je connaîtrai que tu as usé de bonté envers mon maître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Il n\'avait pas encore fini de parler, et voici Rébecca, fille de Béthuel, fils de Milca, femme de Nachor, frère d\'Abraham, sortait avec sa cruche sur l\'épaule.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Et la jeune fille était fort belle; elle était vierge, nul homme ne l\'avait connue. Elle descendit à la source, remplit sa cruche et remonta.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Et le serviteur courut au-devant d\'elle et dit: Donne-moi, je te prie, un peu d\'eau de ta cruche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Et elle dit: Bois, mon seigneur; et elle se hâta d\'abaisser sa cruche sur sa main, et lui donna à boire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Quand elle eut achevé de lui donner à boire, elle dit: J\'en puiserai aussi pour tes chameaux, jusqu\'à ce qu\'ils aient fini de boire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Et elle se hâta de vider sa cruche dans l\'abreuvoir, courut encore au puits pour puiser, et puisa pour tous ses chameaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Et cet homme la considérait en silence pour savoir si l\'Eternel avait fait réussir son voyage ou non.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Quand les chameaux eurent fini de boire, il prit un anneau d\'or du poids d\'un demi-sicle et deux bracelets du poids de dix sicles d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Et il dit: De qui es-tu fille? Apprends-le moi, je te prie. Y a-t-il chez ton père une place pour nous où passer la nuit?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Et elle lui dit: Je suis fille de Béthuel, le fils de Milca, qu\'elle a enfanté à Nachor.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Et elle ajouta: Il y a chez nous paille et fourrage en quantité et aussi une place où passer la nuit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Et cet homme s\'inclina et se prosterna devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Et il dit: Béni soit l\'Eternel, le Dieu d\'Abraham mon maître, qui n\'a pas manqué à sa bonté et à sa fidélité envers mon maître. Et moi, l\'Eternel m\'a conduit par le chemin chez les frères de mon maître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Et la jeune fille courut et fit chez sa mère le récit de ce qui s\'était passé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Or Rébecca avait un frère nommé Laban. Et Laban courut dehors vers cet homme, près de la source.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Quand il vit l\'anneau et les bracelets aux mains de sa sœur et qu\'il entendit les paroles de Rébecca sa sœur, qui disait: Voilà ce que cet homme m\'a dit, il vint vers cet homme; et voici il se tenait près des chameaux, vers la source.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Et il dit: Entre, béni de l\'Eternel; pourquoi te tiens-tu dehors? J\'ai préparé la maison et une place pour les chameaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Et l\'homme entra dans la maison, et Laban débâta les chameaux et donna de la paille et du fourrage aux chameaux, et de l\'eau pour laver ses pieds et les pieds des gens qui étaient avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Puis il lui présenta à manger; mais il dit: Je ne mangerai point que je n\'aie dit ce que j\'ai à dire. Et Laban dit: Parle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Et il dit: Je suis serviteur d\'Abraham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'L\'Eternel a béni abondamment mon maître, et il est devenu grand; il lui a donné du menu et du gros bétail, de l\'argent et de l\'or, des serviteurs et des servantes, des chameaux et des ânes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Et Sara, femme de mon maître, a enfanté un fils à mon maître étant déjà vieille, et il lui a donné tout ce qu\'il possède.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Et mon maître m\'a fait jurer en disant: Tu ne prendras pas une femme pour mon fils parmi les filles des Cananéens dans le pays desquels j\'habite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Mais tu te rendras dans la maison de mon père et dans ma parenté et tu prendras une femme pour mon fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Et je dis à mon maître: Peut-être la femme ne voudra-t-elle pas me suivre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Et il me dit: L\'Eternel, devant lequel j\'ai marché, enverra son ange avec toi et fera réussir ton voyage, et tu prendras une femme pour mon fils, de ma parenté et de la maison de mon père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Tu seras dégagé du serment que je te fais faire une fois que tu te seras rendu dans ma parenté; si on ne te la donne pas, tu seras dégagé du serment que je te fais faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Et quand je suis arrivé aujourd\'hui à la source, j\'ai dit: Eternel, Dieu de mon maître Abraham, s\'il te plaît de faire réussir le voyage que je fais,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'voici je me tiens près de la source; qu\'il arrive que la jeune fille qui sortira pour puiser et à qui je dirai: Donne-moi à boire, je te prie, un peu d\'eau de ta cruche,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'et qui me répondra: Bois, et j\'en puiserai aussi pour tes chameaux, soit la femme que l\'Eternel a destinée au fils de mon maître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Je n\'avais pas encore achevé de parler en moi-même que voici Rébecca sortait avec sa cruche sur l\'épaule, et elle est descendue et a puisé, et je lui ai dit: Donne-moi à boire, je te prie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Et elle s\'est hâtée d\'abaisser sa cruche de dessus son épaule, et elle m\'a dit: Bois, et je donnerai aussi à boire à tes chameaux. J\'ai donc bu, et elle a aussi donné à boire aux chameaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Et je l\'ai interrogée, et j\'ai dit: De qui es-tu fille? Elle a répondu: Je suis fille de Béthuel, fils de Nachor, que Milca lui a enfanté. Alors j\'ai mis l\'anneau à ses narines et les bracelets à ses mains.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Puis je me suis incliné et je me suis prosterné devant l\'Eternel, et j\'ai béni l\'Eternel, le Dieu de mon maître Abraham, qui m\'a conduit dans le vrai chemin pour prendre la fille du frère de mon maître pour son fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Et maintenant, si vous voulez user de bonté et de fidélité envers mon maître, déclarez-le moi; si non, déclarez-le, et je me tournerai à droite ou à gauche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Et Laban et Béthuel répondirent et dirent: La chose vient de l\'Eternel; nous ne pouvons te dire ni mal ni bien.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Voici, Rébecca est devant toi; prends-la et t\'en va, et qu\'elle soit la femme du fils de ton maître, comme l\'Eternel l\'a dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Et lorsque le serviteur d\'Abraham eut entendu leurs paroles, il se prosterna en terre devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Et le serviteur sortit des objets d\'argent et des objets d\'or et des vêtements, et les donna à Rébecca; et il fit de riches présents à son frère et à sa mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Et ils mangèrent et burent, lui et les gens qui étaient avec lui, et ils passèrent là la nuit. Et au matin ils se levèrent, et il dit: Renvoyez-moi à mon maître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Et son frère et sa mère dirent: Que la jeune fille demeure avec nous quelques jours, une dizaine; puis tu partiras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Et il leur dit: Ne me retardez point, puisque l\'Eternel a fait réussir mon voyage; renvoyez-moi, que je m\'en retourne chez mon maître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Et ils dirent: Appelons la jeune fille et voyons ce qu\'elle dira.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Ils appelèrent donc Rébecca et lui dirent: Veux-tu partir avec cet homme? Et elle répondit: Je partirai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Alors ils congédièrent Rébecca leur sœur et sa nourrice, et le serviteur d\'Abraham et ses gens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Et ils bénirent Rébecca et lui dirent: Toi, notre sœur, puisses-tu devenir des milliers de myriades, et puisse ta postérité posséder la porte de ses ennemis!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Et Rébecca et ses servantes se levèrent et montèrent sur les chameaux et suivirent cet homme. Et le serviteur prit Rébecca et s\'en alla.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Et Isaac était revenu du puits de Lachaï-Roï, et il habitait dans le pays du Midi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Et Isaac était sorti pour méditer dans les champs à l\'approche du soir; et, levant les yeux, il vit des chameaux qui arrivaient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Et Rébecca leva aussi les yeux, et elle vit Isaac et sauta à bas du chameau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Et elle dit au serviteur: Qui est cet homme-là, qui vient dans les champs au-devant de nous? Et le serviteur répondit: C\'est mon maître. Et elle prit son voile et se couvrit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Et le serviteur raconta à Isaac toutes les choses qu\'il avait faites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Et Isaac mena Rébecca dans la tente de Sara sa mère; et il prit Rébecca, et elle fut sa femme, et il l\'aima. Et Isaac se consola de la mort de sa mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Et Abraham prit encore une femme nommée Kétura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Et elle lui enfanta Zimran, Jokschan, Médan, Madian, Jisbak et Suach.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Et Jokschan engendra Schéba et Dédan. Et les enfants de Dédan furent les Assurim, les Létusim et les Léummim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Et les enfants de Madian furent: Epha, Ephen, Hénoc, Abida et Eldaa. Tous ceux-là sont enfants de Kétura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Et Abraham donna tout ce qui lui appartenait à Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Et aux fils des concubines qu\'il avait eues, Abraham donna des présents, et il les envoya de son vivant loin de son fils Isaac, à l\'orient, au pays d\'Orient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Et voici les années que vécut Abraham: cent soixante-quinze ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Puis Abraham expira, et il mourut dans une bonne vieillesse, rassasié de jours, et il fut recueilli vers les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Et Isaac et Ismaël, ses fils, l\'ensevelirent dans la caverne de Macpéla, dans le champ d\'Ephron, fils de Tsohar, le Héthien, qui est en face de Mamré;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'le champ qu\'Abraham avait acheté des fils de Heth. C\'est là que fut enterré Abraham, avec Sara, sa femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Et après la mort d\'Abraham, Dieu bénit Isaac son fils. Et Isaac habita près du puits de Lachaï-Roï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Voici la postérité d\'Ismaël, fils d\'Abraham, qu\'avait enfanté à Abraham Hagar, l\'Egyptienne, servante de Sara.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Voici les noms des fils d\'Ismaël, selon les noms de leurs postérités: premier-né d\'Ismaël, Nébajoth, puis Kédar, Adbéel, Mibsam,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Massa,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Théma, Jétur, Naphis et Kedma.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ce sont là les fils d\'Ismaël et ce sont là leurs noms, selon leurs villages et leurs campements: ce furent les douze chefs de leurs tribus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Et voici les années que vécut Ismaël: cent trente-sept ans, puis il expira et il mourut et fut recueilli vers les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Et ses descendants habitèrent de Havila jusqu\'à Sur, qui est en face de l\'Egypte, dans la direction de l\'Assyrie. Il s\'est étendu en face de tous ses frères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Voici la postérité d\'Isaac, fils d\'Abraham. Abraham engendra Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Et Isaac avait quarante ans quand il prit pour femme Rébecca, fille de Béthuel, l\'Araméen, de Paddan-Aram, sœur de Laban, l\'Araméen.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Et Isaac implora l\'Eternel au sujet de sa femme, car elle était stérile. Et l\'Eternel accéda à sa prière, et Rébecca sa femme conçut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Et les enfants se heurtaient dans son sein, et elle dit: S\'il en est ainsi, pourquoi suis-je? Et elle alla consulter l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Et l\'Eternel lui dit: Deux nations sont dans ton sein, Et deux races se sépareront au sortir de tes entrailles. Une race l\'emportera sur une race, Et le grand servira le petit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Et son temps pour enfanter arriva, et elle avait deux jumeaux dans son sein.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Celui qui sortit le premier était roux, tout entier comme un manteau de poil; et ils l\'appelèrent Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Et ensuite, son frère étant sorti en tenant dans sa main le talon d\'Esaü, on le nomma Jacob. Et Isaac avait soixante ans quand ils naquirent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Et ces garçons grandirent. Et Esaü devint un habile chasseur, un homme sauvage, et Jacob, un homme de bien, habitant les tentes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Et Isaac prit en affection Esaü, car il aimait la venaison; et Rébecca était affectionnée à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Et Jacob fit un potage. Et Esaü arriva des champs, et il était fort las.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Et Esaü dit à Jacob: Laisse-moi avaler de ce roux, de ce roux-là! car je suis las. C\'est pourquoi on le nomma Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Et Jacob dit: Vends-moi d\'abord ton droit d\'aînesse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Et Esaü dit: Voici je m\'en vais mourir; que me sert mon droit d\'aînesse?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Et Jacob dit: Jure-moi d\'abord. Et il lui jura, et vendit son droit d\'aînesse à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Et Jacob ayant donné à Esaü du pain et du potage de lentilles, il mangea et but; puis il se leva et s\'en alla. Et Esaü méprisa le droit d\'aînesse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Et il y eut une famine au pays, outre la première famine qui avait eu lieu du temps d\'Abraham. Et Isaac alla à Guérar, vers Abimélek, roi des Philistins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Et l\'Eternel lui apparut et dit: Ne descends point en Egypte; demeure dans le pays que je te dis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Séjourne dans ce pays-ci, et je serai avec toi et je te bénirai. Car je donnerai à toi et à ta postérité tous ces pays-ci, et je tiendrai le serment que j\'ai fait à Abraham, ton père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Et je rendrai ta postérité nombreuse comme les étoiles des cieux, et je donnerai à ta postérité tous ces pays-ci; et toutes les nations de la terre se béniront en ta postérité,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'parce qu\'Abraham a obéi à ma voix et a gardé ce que je lui ai ordonné, mes commandements, mes statuts et mes lois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Et Isaac demeura à Guérar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Et les gens du lieu le questionnèrent sur sa femme, et il dit: C\'est ma sœur. Car il craignait de dire: Ma femme; de peur, se disait-il, que les gens du lieu ne me tuent à cause de Rébecca. Car elle était belle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Or il arriva, comme son séjour en ce lieu se prolongeait, qu\'Abimélek, roi des Philistins, regardant par la fenêtre, aperçut Isaac qui faisait des caresses à Rébecca sa femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Et Abimélek appela Isaac et dit: Ce ne peut être que ta femme; et comment as-tu dit: C\'est ma sœur? Et Isaac lui, dit: C\'est que je disais: Je crains de mourir à cause d\'elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Et Abimélek dit: Qu\'est-ce que tu nous as fait là? Il aurait bien pu arriver que quelqu\'un eût pris ta femme et que tu nous eusses rendus coupables.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Et Abimélek donna cet ordre à tout le peuple: Qui touchera cet homme ou sa femme, sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Et Isaac fit des semailles en ce pays-là, et il recueillit cette année le centuple. Et l\'Eternel le bénit;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'et cet homme s\'agrandit et alla grandissant jusqu\'à devenir extrêmement grand.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Il devint possesseur de menu et de gros bétail, et d\'un grand nombre de serviteurs, et les Philistins lui portèrent envie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Et tous les puits que les serviteurs de son père avaient creusés, du temps de son père Abraham, les Philistins les bouchèrent en les remplissant de terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Et Abimélek dit à Isaac: Va-t-en de chez nous, car tu es devenu beaucoup plus fort que nous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Et Isaac s\'en alla; il campa dans la vallée de Guérar et s\'y établit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Et Isaac creusa de nouveau les puits qu\'on avait creusés du temps d\'Abraham son père et que les Philistins avaient bouchés après la mort d\'Abraham, et il leur donna les noms que son père leur avait donnés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Et les serviteurs d\'Isaac creusèrent dans la vallée et y trouvèrent un puits d\'eau vive.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Et les bergers de Guérar se querellèrent avec les bergers d\'Isaac en disant: L\'eau est à nous. Et il appela le puits Esek, parce qu\'ils avaient eu un débat avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Ensuite ils creusèrent un autre puits, pour lequel ils se querellèrent encore; et il le nomma Sitna.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Alors il partit de là et creusa un autre puits, pour lequel il n\'y eut pas de querelle; et il le nomma Rehoboth, et il dit: C\'est que l\'Eternel nous a maintenant mis à l\'aise, et nous fructifierons dans le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Et il monta de là à Béerséba.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Et l\'Eternel lui apparut cette nuit-là et lui dit: Je suis le Dieu d\'Abraham ton père; ne crains point, car je suis avec toi; je te bénirai et je te donnerai une nombreuse postérité à cause d\'Abraham, mon serviteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Et il éleva là un autel et invoqua le nom de l\'Eternel, et il dressa là sa tente. Et les serviteurs d\'Isaac creusèrent là un puits;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'et Abimélek vint vers lui, de Guérar, avec Ahuzath, son ami, et Picol, chef de son armée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Et Isaac leur dit: Pourquoi êtes-vous venus vers moi, vous qui me haïssez et m\'avez renvoyé de chez vous?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Et ils répondirent: Nous avons vu clairement que l\'Eternel a été avec toi, et nous avons dit: Qu\'il y ait un serment entre nous, entre nous et toi! Nous voudrions donc faire alliance avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Jure de ne pas nous faire de mal, de même que nous ne t\'avons point touché et que nous ne t\'avons fait que du bien et t\'avons laissé aller en paix. Tu es maintenant le béni de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Et il leur fit un banquet, et ils mangèrent et burent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Et le lendemain matin, ils se prêtèrent serment l\'un à l\'autre; puis Isaac les congédia, et ils s\'en allèrent de chez lui en paix.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Il arriva en ce même jour que les serviteurs d\'Isaac vinrent lui faire rapport au sujet du puits qu\'ils creusaient, et ils lui dirent: Nous avons trouvé de l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Et il l\'appela Sibéa. C\'est pour cela que la ville se nomme Béerséba jusqu\'à ce jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Et Esaü, âgé de quarante ans, prit pour femmes Judith, fille de Bééri, le Héthien, et Basmath, fille d\'Elon, le Héthien.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Et elles furent un sujet d\'amertume pour Isaac et Rébecca.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Il arriva lorsqu\'Isaac fut devenu vieux et que ses yeux furent affaiblis au point de ne plus voir, qu\'il appela Esaü, son fils aîné, et lui dit: Mon fils! Et celui-ci dit: Me voici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Et Isaac dit: Tu vois que je suis vieux; je ne connais pas le jour de ma mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Maintenant donc, prends tes armes, ton carquois et ton arc, et va dans la campagne et tue-moi du gibier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Et fais-m\'en un bon plat, comme j\'aime, et apporte-le moi, que je le mange, afin que mon âme te bénisse avant que je meure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Et Rébecca entendait lorsqu\'Isaac parlait à Esaü, son fils. Et Esaü alla dans la campagne pour tuer du gibier et l\'apporter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Et Rébecca parla ainsi à Jacob, son fils: Ecoute, j\'ai entendu ton père qui disait ainsi à Esaü, ton frère:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Apporte-moi du gibier et fais-m\'en un bon plat, afin que je le mange et que je te bénisse devant l\'Eternel avant que je meure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Maintenant donc, mon fils, obéis-moi dans ce que je vais te commander.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Va au troupeau et prends-moi deux bons chevreaux, et j\'en ferai un bon plat pour ton père, comme il aime.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Et tu l\'apporteras à ton père, et il en mangera, afin qu\'il te bénisse avant de mourir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Et Jacob dit à Rébecca, sa mère: Voici Esaü, mon frère, est velu, et moi j\'ai la peau lisse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Peut-être que mon père me tâtera, et je passerai à ses yeux pour m\'être joué de lui, et j\'attirerai sur moi une malédiction et non une bénédiction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Et sa mère lui dit: Je prends sur moi ta malédiction, mon fils; obéis-moi seulement; va, prends-les moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Et il alla, les prit et les apporta à sa mère; et sa mère en fit un bon plat, comme son père aimait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Et Rébecca prit les beaux habits d\'Esaü, son fils aîné, qu\'elle avait dans la maison, et elle en vêtit Jacob, son fils cadet.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Et des peaux de chevreaux elle lui couvrit les mains et la partie rase du cou.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Et elle remit à Jacob, son fils, le bon plat et le pain qu\'elle avait faits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Et il vint vers son père, et dit: Mon père! Et celui-ci dit: Me voici; qui es-tu, mon fils?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Et Jacob dit à son père: Je suis Esaü, ton premier-né. J\'ai fait comme tu m\'as dit. Lève-toi, je te prie, assieds-toi et mange de ma chasse, afin que ton âme me bénisse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Et Isaac dit à son fils: Comment donc as-tu trouvé si vite, mon fils? Et Jacob dit: C\'est que l\'Eternel ton Dieu l\'a fait venir devant moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Et Isaac dit à Jacob: Approche un peu, que je te tâte, mon fils [pour savoir] si tu es bien mon fils Esaü ou non.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Et Jacob s\'approcha d\'Isaac, son père, qui le tâta et dit: La voix est la voix de Jacob, et les mains sont les mains d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Et comme il ne l\'avait pas reconnu, parce que ses mains étaient velues comme celles d\'Esaü, son frère, il le bénit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Et il dit: C\'est bien toi qui es mon fils Esaü? Et Jacob dit: C\'est moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Et Isaac dit: Sers-moi, que je mange de la chasse de mon fils, afin que mon âme te bénisse. Et il le servit, et Isaac mangea. Et il lui apporta du vin, et il but.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Et Isaac, son père, lui dit: Approche-toi et embrasse-moi, mon fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Et il s\'approcha et l\'embrassa. Et Isaac sentit l\'odeur de ses habits, et il le bénit et dit: Oui, le parfum de mon fils Est pareil au parfum de campagnes Qu\'a bénies l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Que Dieu te donne de la rosée des cieux Et des sucs de la terre, Et abondance de blé et de moût.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Que des peuples te servent Et que des nations se prosternent devant toi. Sois le maître de tes frères, Et que les fils de ta mère se prosternent devant toi! Maudit soit qui te maudira! Et béni soit qui te bénira!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Et il arriva que, quand Isaac eut achevé de bénir Jacob, et comme Jacob venait de sortir de devant Isaac, son père, Esaü, son frère, revint de la chasse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Et il fit, lui aussi, un bon plat, et il l\'apporta, et dit à son père: Que mon père se lève et mange de la chasse de son fils, afin que ton âme me bénisse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Et Isaac, son père, lui dit: Qui es-tu? Et il dit: Je suis ton fils, ton premier-né, Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Et Isaac fut saisi d\'une terreur extrême, et il dit: Qui est donc celui qui a tué du gibier et m\'en a apporté? Et j\'ai mangé de tout avant que tu vinsses, et je l\'ai béni; et aussi il sera béni.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Quand Esaü eut entendu les paroles de son père, il jeta un grand cri, un cri de douleur amère, et il dit à son père: Bénis-moi, moi aussi, mon père!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Et Isaac dit: Ton frère est venu en trompeur, et il a pris ta bénédiction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Et Esaü dit: Est-ce parce qu\'on l\'appelle Jacob qu\'il m\'a supplanté ces deux fois? Il a pris mon droit d\'aînesse, et voici maintenant il a pris ma bénédiction. Et il ajouta: N\'as-tu pas en réserve pour moi une bénédiction?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Et Isaac répondit et dit à Esaü: Voici, je l\'ai établi ton maître et je lui ai donné tous ses frères pour serviteurs et je l\'ai fourni de froment et de moût. Pour toi donc, que ferais-je, mon fils?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Et Esaü dit à son père: N\'as-tu que cette seule bénédiction, mon père? Bénis-moi, moi aussi, mon père! Et Esaü éleva la voix et pleura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Et Isaac son père répondit et lui dit: Voici, ta demeure sera privée des sucs de la terre Et de la rosée qui descend des cieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Tu vivras de ton épée, Et tu seras asservi à ton frère. Et il arrivera que, en faisant effort, Tu briseras son joug de dessus ton cou.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Et Esaü devint ennemi de Jacob à cause de la bénédiction que son père lui avait donnée; et Esaü dit en son cœur: Vienne le temps du deuil de mon père, alors je tuerai Jacob, mon frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'On rapporta à Rébecca les paroles d\'Esaü, son fils aîné; et elle envoya appeler Jacob, son fils cadet, et lui dit: Voici Esaü, ton frère, va se venger de toi en te tuant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Maintenant donc, mon fils, écoute-moi: lève-toi, fuis vers Laban, mon frère, à Charan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Et tu demeureras avec lui quelque temps, jusqu\'à ce que la fureur de ton frère soit passée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Une fois que la colère de ton frère se sera détournée de toi et qu\'il aura oublié ce que tu lui as fait, je t\'enverrai chercher de là. Pourquoi serais-je privée de vous deux en un même jour?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Et Rébecca dit à Isaac: Je suis dégoûtée de la vie à cause des filles de Heth. Si Jacob prend d\'entre les filles de Heth une femme comme celles-là, d\'entre les filles de ce pays, à quoi me sert la vie?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Et Isaac appela Jacob et le bénit, et il lui donna cet ordre: Tu ne prendras pas pour femme une des filles de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Lève-toi, va en Paddan-Aram chez Béthuel, père de ta mère, et prends-toi une femme de là, d\'entre les filles de Laban, frère de ta mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Et le Dieu puissant te bénira, te fera fructifier et t\'accroîtra, et tu deviendras une assemblée de peuples;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'et il te donnera la bénédiction d\'Abraham, à toi et à ta postérité avec toi, afin que tu possèdes la terre où tu séjournes et que Dieu a donnée à Abraham.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Et Isaac fit partir Jacob, et il s\'en alla en Paddan-Aram, vers Laban, fils de Béthuel, l\'Araméen, frère de Rébecca, mère de Jacob et d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Et Esaü vit qu\'Isaac avait béni Jacob et qu\'il l\'avait fait partir pour Paddan-Aram afin de prendre de là une femme, et qu\'en le bénissant il lui avait donné cet ordre: Tu ne prendras pas pour femme une des filles de Canaan;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'et que Jacob avait obéi à son père et à sa mère et s\'en était allé en Paddan-Aram,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Esaü, voyant donc que les filles de Canaan déplaisaient à Isaac, son père,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 's\'en alla vers Ismaël, et prit pour femme, outre celles qu\'il avait déjà, Mahalath, fille d\'Ismaël, fils d\'Abraham, sœur de Nébajoth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Et Jacob partit de Béerséba et s\'en alla à Charan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Et étant arrivé, dans le lieu où il passa la nuit parce que le soleil était couché, il prit des pierres de ce lieu, en fit son chevet et se coucha dans ce lieu-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Et il eut un songe; et voici, une échelle posée sur la terre, dont le sommet touchait au ciel; et voici des anges de Dieu montaient et descendaient par cette échelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Et voici l\'Eternel se tenait au haut, et il dit: Je suis l\'Eternel, le Dieu d\'Abraham, ton père, et le Dieu d\'Isaac. Cette terre sur laquelle tu es couché, je te la donnerai, à toi et à ta postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Et ta postérité sera comme la poussière de la terre; et tu t\'étendras à l\'occident et à l\'orient, au septentrion et au midi; et toutes les familles de la terre seront bénies en toi et en ta postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Et voici, je suis avec toi, et je te garderai partout où tu iras; et je te ramènerai en ce pays car je ne t\'abandonnerai point que je n\'aie fait ce que je t\'ai dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Et Jacob s\'éveilla de son sommeil et dit: Certainement l\'Eternel est en ce lieu-ci, et moi je ne le savais pas!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Et il fut saisi de crainte, et il dit: Que ce lieu est auguste! Ce ne peut être que la maison de Dieu; c\'est ici la porte des cieux!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Et dès le matin, Jacob prit la pierre dont il avait fait son chevet et la dressa pour monument, et il versa de l\'huile sur son sommet.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Et il nomma ce lieu-là Béthel; mais primitivement le nom de la ville était Luz.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Et Jacob fit un vœu en ces termes: Si Dieu est avec moi et qu\'il me garde dans ce voyage que je fais et qu\'il me donne du pain à manger et des habits pour me vêtir,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'et que je retourne heureusement à la maison de mon père, l\'Eternel sera mon Dieu;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'et cette pierre, que j\'ai dressée pour monument, sera une maison de Dieu; et tout ce que tu me donneras, je t\'en paierai certainement la dîme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Et Jacob reprit sa marche et s\'en alla au pays des Fils de l\'Orient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Et il aperçut un puits dans la campagne; et il y avait là trois troupeaux de brebis couchés auprès, car c\'était de ce puits qu\'on faisait boire les troupeaux; et la pierre sur l\'ouverture du puits était grosse;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'tous les troupeaux se réunissaient là, on roulait la pierre de dessus l\'ouverture du puits, on abreuvait les brebis, et on remettait la pierre à sa place sur l\'ouverture du puits;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'et Jacob dit aux bergers: Mes frères, d\'où êtes-vous? Et ils répondirent: Nous sommes de Charan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Et il leur dit: Connaissez-vous Laban, fils de Nachor? Ils dirent: Nous le connaissons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Il leur dit: Se porte-t-il bien? Ils lui répondirent: Il se porte bien, et voici Rachel, sa fille, qui vient avec les brebis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Et il dit: Mais il est encore grand jour! Ce n\'est pas le moment de rassembler le bétail; abreuvez les brebis et retournez les faire paître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Ils dirent: Nous ne le pouvons pas jusqu\'à ce que tous les troupeaux soient rassemblés et qu\'on roule la pierre de dessus l\'ouverture du puits; alors nous abreuverons les brebis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Il parlait encore avec eux, quand Rachel arriva avec les brebis de son père, car elle était bergère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Alors, quand Jacob vit Rachel, fille de Laban, frère de sa mère, et les brebis de Laban, frère de sa mère, il s\'approcha, roula la pierre de dessus l\'ouverture du puits, et abreuva les brebis de Laban, frère de sa mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Et Jacob embrassa Rachel, et il éleva la voix et pleura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Et Jacob apprit à Rachel qu\'il était frère de son père, et qu\'il était fils de Rébecca; et elle courut l\'annoncer à son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Et en entendant parler de Jacob, fils de sa sœur, Laban courut au-devant de lui, l\'embrassa et lui donna des baisers, et il le conduisit dans sa maison. Et Jacob raconta à Laban toutes ces choses.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Et Laban lui dit: Tu es bien mes os et ma chair. Et Jacob demeura avec lui un mois entier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Et Laban dit à Jacob: Est-ce que, parce que tu es mon frère, tu me serviras pour rien? Déclare-moi quel salaire tu veux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Laban avait deux filles; le nom de l\'aînée était Léa, et le nom de la cadette, Rachel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Léa avait une mine chétive, et Rachel était belle de taille et belle de visage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Et Jacob aima Rachel et il dit: Je te servirai sept ans pour Rachel, ta fille cadette.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Et Laban répondit: Mieux vaut te la donner que de la donner à un autre; reste seulement avec moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Et Jacob servit pour Rachel sept ans, qui ne lui parurent que quelques jours, parce qu\'il l\'aimait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Et Jacob dit à Laban: Donne-moi ma femme, car mon temps est accompli, et j\'irai vers elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Et Laban réunit tous les gens du lieu et fit un festin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Et le soir venu, il prit Léa, sa fille, et l\'amena à Jacob, qui alla vers elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Et Laban donna sa servante Zilpa à Léa, sa fille, pour servante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Et le matin venu, voici c\'était Léa. Et Jacob dit à Laban: Que m\'as-tu fait? N\'est-ce pas pour Rachel que j\'ai servi chez toi? Et pourquoi m\'as-tu trompé?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Et Laban dit: Cela ne se fait pas chez nous, de donner la cadette avant l\'aînée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Achève la semaine de celle-ci, et nous te donnerons aussi l\'autre pour le service que tu feras encore chez moi sept autres années.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacob fit ainsi, il acheva la semaine de Léa, et Laban lui donna Rachel, sa fille, pour femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Et Laban donna sa servante Bilha à Rachel, sa fille, pour servante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Et Jacob alla aussi vers Rachel, et il aima aussi Rachel, plus que Léa; et il servit encore chez Laban sept autres années.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Et l\'Eternel vit que Léa était haïe, et il la rendit féconde; mais Rachel était stérile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Et Léa conçut et enfanta un fils, et elle le nomma Ruben, car elle dit: L\'Eternel a regardé à mon affliction, et maintenant mon mari m\'aimera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Elle conçut encore et enfanta un fils, et elle dit: L\'Eternel a entendu que j\'étais haïe, et il m\'a encore donné celui-ci. Et elle le nomma Siméon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Elle conçut encore et enfanta un fils, et elle dit: Cette fois, mon mari s\'attachera à moi, puisque je lui ai enfanté trois fils. C\'est pourquoi on le nomma Lévi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Elle conçut encore et enfanta un fils, et elle dit: Cette fois je louerai l\'Eternel. C\'est pourquoi elle le nomma Juda. Et elle cessa d\'avoir des enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Et Rachel vit qu\'elle ne donnait point d\'enfant à Jacob, et Rachel fut jalouse de sa sœur et dit à Jacob: Donne-moi des fils, sinon je suis morte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Et Jacob se fâcha contre Rachel, et dit: Suis-je à la place de Dieu qui t\'a rendue stérile?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Et elle dit: Voici ma servante Bilha; va vers elle, qu\'elle enfante sur mes genoux, et par elle j\'aurai, moi aussi, une famille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Et elle lui donna Bilha, sa servante, pour femme, et Jacob alla vers elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Et Bilha conçut et enfanta un fils à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Et Rachel dit: Dieu m\'a rendu justice, et même il a entendu ma voix et m\'a donné un fils. C\'est pourquoi elle l\'appela Dan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Et Bilha, servante de Rachel, conçut encore et enfanta un second fils, à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Et Rachel dit: C\'étaient des luttes de Dieu que mes luttes avec ma sœur; aussi je l\'ai emporté. Et elle le nomma Nephthali.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Et Léa, voyant qu\'elle avait cessé d\'avoir des enfants, prit Zilpa, sa servante, et la donna pour femme à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Et Zilpa, servante de Léa, enfanta un fils à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Et Léa dit: Quelle bonne fortune! Et elle le nomma Gad.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Et Zilpa, servante de Léa, enfanta un second fils à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Et Léa dit: Pour mon bonheur! car les filles me diront bienheureuse. Et elle le nomma Asser.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben sortit au temps de la moisson des blés, et trouva des mandragores dans les champs, et il les apporta à Léa, sa mère. Et Rachel dit à Léa: Donne-moi, s\'il te plaît, des mandragores de ton fils?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Et Léa lui dit: Est-ce peu que tu prennes mon mari? Tu prendrais encore les mandragores de mon fils? Et Rachel dit: Eh bien! il sera avec toi cette nuit en échange des mandragores de ton fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Et Jacob revint des champs le soir, et Léa sortit au-devant de lui et lui dit: Tu viendras chez moi, car je t\'ai loué pour les mandragores de mon fils. Et il fut avec elle cette nuit-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Et Dieu exauça Léa, et elle conçut et enfanta à Jacob un cinquième fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Et Léa dit: Dieu m\'a donné mon salaire pour avoir donné ma servante à mon mari. Et elle le nomma Issacar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Et Léa conçut encore et enfanta un sixième fils à Jacob;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'et Léa dit: Dieu m\'a richement dotée; cette fois mon mari habitera avec moi, puisque je lui ai enfanté six fils. Et elle le nomma Zabulon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Ensuite elle enfanta une fille, et elle la nomma Dina.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Et Dieu se souvint de Rachel, et Dieu l\'exauça et la rendit féconde.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Et elle conçut et enfanta un fils, et elle dit: Dieu a ôté mon opprobre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Et elle le nomma Joseph, en disant: Que l\'Eternel m\'ajoute encore un autre fils!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Et il arriva, lorsque Rachel eut enfanté Joseph, que Jacob dit à Laban: Donne-moi mon congé, que je m\'en aille chez moi, dans mon pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Donne-moi mes femmes, pour lesquelles je t\'ai servi, et mes enfants, et que je m\'en aille, car tu sais toi-même le service que j\'ai fait pour toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Et Laban lui dit: Si j\'ai trouvé grâce à tes yeux... J\'ai bien observé: l\'Eternel m\'a béni à cause de toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Et il dit: Fixe-moi ton salaire, et je te le donnerai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Jacob lui dit: Tu sais toi-même comment je t\'ai servi, et ce qu\'est devenu ton bétail avec moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Car c\'était peu de chose que ton bien, avant moi, et il s\'est extrêmement accru; et l\'Eternel a mis pour toi la bénédiction sur mes pas; et maintenant, quand travaillerai-je aussi pour ma maison?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Laban lui dit: Que te donnerai-je? Et Jacob dit: Tu ne me donneras rien du tout. Si tu m\'accordes ce que je vais dire, je recommencerai à paître tes troupeaux et à les garder.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Je passerai aujourd\'hui à travers tout ton troupeau, en mettant à part toute bête picotée et rayée et toute bête noire parmi les agneaux, et tout ce qui est rayé et picoté parmi les chèvres; ce sera là mon salaire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Et à l\'avenir ma justice témoignera pour moi quand tu viendras reconnaître mon salaire. Tout ce qui ne sera pas picoté et rayé, parmi les chèvres et noir parmi les agneaux sera un vol, s\'il est chez moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Et Laban dit: Eh bien! qu\'il en soit comme tu dis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Et le jour même, il sépara les boucs tachetés et rayés et toutes les chèvres picotées et rayées, tout ce qui avait du blanc, et tout ce qui était noir parmi les agneaux; et il les confia à ses fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Et il mit l\'espace de trois journées de chemin entre lui et Jacob. Et Jacob paissait le reste des troupeaux de Laban.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Et Jacob prit des baguettes vertes de peuplier, d\'amandier et de platane; il y pela des places blanches, mettant à nu le blanc des baguettes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Et il mit les baguettes qu\'il avait pelées en regard des brebis dans les auges, dans les abreuvoirs où les brebis venaient boire; et elles entraient en chaleur quand elles venaient boire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Et les brebis s\'accouplaient à la vue des baguettes, et elles faisaient des agneaux tachetés, picotés et rayés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Et ces agneaux, Jacob les mettait à part, et il tournait la face du troupeau vers ce qui était tacheté et tout ce qui était noir dans le troupeau de Laban. Il se fit ainsi des troupeaux à lui, qu\'il ne joignait pas au troupeau de Laban.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Et il arrivait que, toutes les fois que les brebis vigoureuses entraient en chaleur, Jacob mettait les baguettes dans les auges sous les yeux des brebis, afin qu\'elles s\'accouplassent quand les baguettes y étaient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mais quand les brebis étaient chétives, il ne les mettait point, en sorte que les agneaux chétifs, étaient pour Laban, et les vigoureux pour Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Et cet homme s\'accrut extraordinairement, et il eut de nombreux troupeaux, des servantes et des serviteurs, des chameaux et des ânes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Et Jacob entendit les propos des fils de Laban, qui disaient: Jacob a pris tout ce qui appartient à notre père, et c\'est de ce qui appartient à notre père qu\'il s\'est fait toute cette richesse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Et Jacob s\'aperçut que le visage de Laban n\'était plus à son égard comme auparavant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Et l\'Eternel dit à Jacob: Retourne au pays de tes pères et vers ta parenté, et je serai avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Et Jacob fit dire à Rachel et à Léa de venir le trouver aux champs, vers son troupeau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Et il leur dit: Je vois que le visage de votre père n\'est plus le même envers moi qu\'auparavant; or le Dieu de mon père a été avec moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Et vous savez vous-mêmes que j\'ai servi votre père de tout mon pouvoir;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'et votre père s\'est joué de moi et a changé dix fois mon salaire; mais Dieu ne lui a pas permis de me faire du tort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Quand il disait ainsi: Les picotés seront ton salaire, toutes les brebis faisaient des agneaux picotés. Et s\'il disait ainsi: Les tachetés seront ton salaire, toutes les brebis faisaient des agneaux tachetés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Dieu a donc pris le bétail de votre père, et il me l\'a donné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Car il arriva, au temps où les brebis entrent en chaleur, que je levai les yeux et vis en songe que les béliers qui couvraient les brebis étaient tachetés, picotés et rayés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Et l\'ange de Dieu me dit en songe: Jacob! Et je dis: Me voici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Et il dit: Lève les yeux et regarde; tous les béliers qui couvrent les brebis sont tachetés, picotés et rayés; car j\'ai vu tout ce que te fait Laban.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Je suis le Dieu de Béthel, où tu oignis un monument, où tu me fis un vœu. Pars maintenant, sors de ce pays et retourne au pays de ta naissance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Et Rachel et Léa répondirent et lui dirent: Y a-t-il encore pour nous une part ou un héritage dans la maison de notre père?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Ne nous a-t-il pas tenues pour des étrangères, puisqu\'il nous a vendues? Et il a de plus mangé notre argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Car tout le bien que Dieu a enlevé à notre père, nous l\'avons, nous et nos fils. Maintenant donc, tout ce que Dieu t\'a dit, fais-le.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Et Jacob se leva et fit monter ses enfants et ses femmes sur les chameaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Et il emmena tout son bétail et tout le bien qu\'il avait acquis, le troupeau particulier qu\'il avait acquis à Paddan-Aram, pour s\'en aller vers Isaac, son père, au pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Or Laban était allé tondre ses brebis; et Rachel déroba les théraphim de son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Et Jacob se déroba à Laban l\'Araméen, en ne lui disant pas qu\'il s\'enfuyait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Et il s\'enfuit, lui et tout ce qui était à lui; il se mit en route et traversa le fleuve, et il se dirigea vers la montagne de Galaad.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Le troisième jour, on rapporta à Laban que Jacob s\'était enfui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Et il prit ses frères avec lui, et le poursuivit pendant sept journées de chemin, et il se trouva près de lui à la montagne de Galaad.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Et Dieu vint vers Laban l\'Araméen dans un songe, de nuit, et il lui dit: Garde-toi de rien dire à Jacob ni en bien ni en mal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Laban atteignit Jacob; Jacob avait dressé sa tente sur la montagne; et Laban avait dressé la sienne avec ses frères sur la montagne de Galaad.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Et Laban dit à Jacob: Qu\'as-tu fait, de te dérober et d\'emmener mes filles comme des prisonnières de guerre?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Pourquoi t\'es-tu enfui secrètement et m\'as-tu trompé? Tu ne m\'as point averti, moi qui t\'aurais accompagné joyeusement, avec des chants, au son du tambourin et de la harpe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Et tu ne m\'as pas laissé embrasser mes fils et mes filles! Maintenant tu as agi follement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Il ne tient qu\'à moi de vous faire du mal; mais le Dieu de votre père m\'a parlé la nuit passée en disant: Garde-toi de rien dire à Jacob ni en bien ni en mal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Et maintenant tu es parti parce que tu languissais après la maison de ton père; [mais] pourquoi as-tu dérobé mes dieux?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Et Jacob répondit et dit à Laban: C\'est que j\'ai craint parce que je me suis dit que tu pouvais m\'enlever tes filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Quant à celui chez qui tu trouveras tes dieux, il ne vivra point; en présence de nos frères, reconnais ce qui chez moi t\'appartient et prends-le. Or Jacob ignorait que Rachel les eût dérobés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Et Laban entra dans la tente de Jacob et dans la tente de Léa et dans la tente des deux servantes, et ne trouva rien. Puis il sortit de la tente de Léa et entra dans la tente de Rachel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Et Rachel avait pris les théraphim, les avait mis dans la selle à chameau, et s\'était assise dessus. Et Laban fouilla toute la tente, sans trouver.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Et elle dit à son père: Que mon seigneur ne s\'irrite pas de ce que je ne puis pas me lever devant toi; car j\'ai ce qui est ordinaire aux femmes. Et il chercha, mais il ne trouva pas les théraphim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Et Jacob se mit en colère et querella Laban; et Jacob répondit et dit: Quel est mon crime, quelle est ma faute, que tu t\'acharnes après moi?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'En fouillant tout mon bagage, qu\'as-tu trouvé de tous les effets de ta maison? Mets-le ici devant mes frères et tes frères, et qu\'ils soient juges entre nous deux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Ces vingt ans que j\'ai été avec toi, tes brebis et tes chèvres n\'ont pas avorté, et je n\'ai pas mangé les béliers de ton troupeau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Ce qui était déchiré, je ne te l\'ai pas fait voir; c\'est moi qui en supportais la perte. Tu me réclamais ce qui avait été dérobé de jour et ce qui avait été dérobé de nuit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Je vivais consumé le jour par la chaleur, la nuit par le froid; et mon sommeil fuyait de mes yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Voici vingt ans que je suis dans ta maison; je t\'ai servi quatorze ans pour tes deux filles et six ans pour ton bétail, et tu as changé mon salaire dix fois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si le Dieu de mon père, le Dieu d\'Abraham et la Frayeur d\'Isaac, n\'eût été pour moi, certes tu m\'aurais maintenant laissé partir à vide. Dieu a vu ma souffrance et le travail de mes mains; et cette nuit il a prononcé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban répondit et dit à Jacob: Ces filles sont mes filles, ces fils mes fils, ces troupeaux mes troupeaux, et tout ce que tu vois est à moi. Et mes filles, que leur ferais-je aujourd\'hui à elles et aux fils qu\'elles ont enfantés?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Maintenant donc, viens, faisons alliance toi et moi, et qu\'il y ait un témoin entre moi et toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Et Jacob prit une pierre et la dressa pour monument.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Et Jacob dit à ses frères: Amassez des pierres. Et ils prirent des pierres et en firent un monceau, et ils mangèrent là sur le monceau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Et Laban l\'appela Jégar-Sahadutha; et Jacob l\'appela Galed.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Et Laban dit: Ce monceau est témoin entre moi et toi aujourd\'hui. C\'est pourquoi on le nomma Galed,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'et aussi Mitspa, parce que [Laban] avait dit: Que l\'Eternel nous surveille l\'un et l\'autre quand nous serons cachés l\'un à l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si tu maltraites mes filles et si tu prends des femmes à côté de mes filles, personne ne sera avec nous; mais vois, c\'est Dieu qui sera témoin entre moi et toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Laban dit encore à Jacob: Voici ce monceau, et voici le monument que j\'ai dressé entre moi et toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Ce monceau est témoin, et ce monument est témoin que moi je n\'avancerai pas vers toi au-delà de ce monceau, et que toi tu n\'avanceras pas vers moi au-delà de ce monceau et de ce monument, pour nuire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Le Dieu d\'Abraham et le Dieu de Nachor, les dieux de leur père, jugeront entre nous. Et Jacob jura par la Frayeur de son père Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Et Jacob fit un sacrifice sur la montagne; et il invita ses frères à un repas. Ils mangèrent donc et passèrent la nuit sur la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Et dès le lendemain matin, Laban embrassa ses fils et ses filles, et les bénit; puis Laban partit et s\'en retourna chez lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jacob continua son chemin, et des anges de Dieu le rencontrèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Et quand il les eut vus, Jacob dit: C\'est le camp de Dieu! Et il nomma ce lieu là Mahanaïm.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Et Jacob envoya des messagers devant lui, vers Esaü, son frère, au pays de Séir, dans la campagne d\'Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Et il leur donna cet ordre: Vous parlerez ainsi à mon seigneur, à Esaü: Ainsi a dit ton serviteur Jacob: J\'ai séjourné chez Laban et j\'y suis resté jusqu\'à présent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'J\'ai des bœufs et des ânes, des brebis, des serviteurs et des servantes; et j\'en fais informer mon seigneur, pour trouver grâce à tes yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Et les messagers revinrent vers Jacob en disant: Nous nous sommes rendus auprès de ton frère, auprès d\'Esaü; et de plus, il vient à ta rencontre, et il a quatre cents hommes avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Et Jacob fut tout effrayé et en angoisse. Et il partagea les gens qui étaient avec lui, et le menu et le gros bétail et les chameaux, en deux troupes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Et il dit: Si Esaü rencontre l\'une des troupes et la frappe, l\'autre, qui restera, sera une réserve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Et Jacob dit: Dieu de mon père Abraham et Dieu de mon père Isaac, Eternel, qui m\'as dit: Retourne en ton pays et au lieu de ta naissance, et je te ferai du bien;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'je suis trop petit pour toutes les grâces et pour toute la fidélité dont tu as usé envers ton serviteur, car j\'ai passé ce Jourdain avec mon bâton, et maintenant je suis devenu deux troupes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Délivre-moi, je te prie, de la main de mon frère, de la main d\'Esaü; car je crains qu\'il ne vienne et qu\'il ne me frappe, la mère avec les enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Et toi, tu as dit: Certainement je te ferai du bien, et je rendrai ta postérité pareille au sable de la mer, qu\'on ne peut compter, tant il y en a.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Et il passa là cette nuit. Et des biens qu\'il avait avec lui il prit de quoi faire une offrande à Esaü, son frère:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'deux cents chèvres et vingt boucs, deux cents brebis et vingt béliers,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'trente chamelles qui allaitaient, avec leurs petits, quarante vaches et dix taureaux, vingt ânesses et dix ânons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Et il remit à ses serviteurs chaque troupeau à part, et il dit à ses serviteurs: Passez devant moi et laissez une distance entre chaque troupeau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Et il donna cet ordre au premier: Quand Esaü, mon frère, te rencontrera et te demandera: A qui es-tu, où vas-tu, et à qui appartient ce troupeau qui va devant toi?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Tu diras: A ton serviteur Jacob: c\'est une offrande qu\'il envoie à mon seigneur, à Esaü; et le voici lui-même qui nous suit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Il donna le même ordre au second et au troisième et à tous ceux qui suivaient les troupeaux: Vous parlerez ainsi à Esaü quand vous le rencontrerez,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'et vous direz: Voici aussi ton serviteur Jacob qui nous suit. Car il s\'était dit: Je l\'apaiserai par ce présent qui va devant moi, et après cela je verrai sa face; peut-être me fera-t-il bon accueil.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Et le présent passa avant lui; et lui, il passa cette nuit-là dans le camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Et il se leva cette nuit-là, prit ses deux femmes et ses deux servantes et ses onze enfants, et passa le gué du Jabbok.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Et il les prit et leur fit passer le torrent, et il fit aussi passer ce qui lui appartenait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Et Jacob resta seul. Et un homme lutta avec lui jusqu\'au lever de l\'aurore.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Et voyant qu\'il ne pouvait le vaincre, il le toucha à l\'emboîture de la hanche, et l\'emboîture de la hanche de Jacob se démit pendant qu\'il luttait avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Et il dit à Jacob: Laisse-moi aller, car l\'aurore est levée. Et il dit: Je ne te laisserai point aller que tu ne m\'aies béni.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Et il lui dit: Quel est ton nom? Et il dit: Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Et il dit: Ton nom ne sera plus Jacob, mais Israël, car tu as combattu avec Dieu et les hommes, et tu as vaincu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Et Jacob l\'interrogea et dit: Fais-moi, je te prie, connaître ton nom. Et il dit: Pourquoi t\'enquérir de mon nom? Et il le bénit là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Et Jacob nomma ce lieu Péniel; car, dit-il, j\'ai vu Dieu face à face et ma vie a été épargnée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Et il vit le soleil se lever quand il eut passé Pénuel; et il boitait de la hanche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'C\'est pourquoi les enfants d\'Israël ne mangent point jusqu\'à aujourd\'hui le grand nerf qui est à l\'emboîture de la hanche, parce qu\'il avait touché l\'emboîture de la hanche de Jacob, au grand nerf.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Et Jacob leva les yeux et aperçut Esaü qui venait, ayant avec lui quatre cents hommes. Et il partagea les enfants entre Léa, Rachel et les deux servantes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Et il plaça les servantes et leurs enfants en tête, ensuite Léa et ses enfants, et ensuite Rachel et Joseph.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Et lui-même passa devant eux et se prosterna en terre sept fois, jusqu\'à ce qu\'il fût proche de son frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Et Esaü courut à sa rencontre, l\'embrassa, se jeta à son cou et lui donna un baiser, et ils pleurèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Puis il leva les yeux et vit les femmes et les enfants, et il dit: Qui sont ceux que tu as là? Et il dit: Ce sont les enfants que Dieu a accordés à ton serviteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Et les servantes s\'approchèrent, elles et leurs enfants, et se prosternèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Léa aussi s\'approcha, elle et ses enfants, et ils se prosternèrent. Et ensuite s\'approchèrent Joseph et Rachel, et ils se prosternèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Et Esaü dit: Que veux-tu faire avec toute cette troupe que j\'ai rencontrée? Et il dit: C\'est pour trouver grâce aux yeux de mon seigneur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Et Esaü dit: J\'ai bien assez, mon frère; que ce qui est à toi soit à toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Et Jacob dit: Non, je te prie; si j\'ai trouvé grâce à tes yeux, tu accepteras, je te prie, mon offrande de ma main, car c\'est pour cela que j\'ai vu ta face comme on voit la face de Dieu et que tu m\'as accueilli favorablement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Accepte, je te prie, mon présent qui t\'a été amené, car Dieu a été, bon pour moi, et j\'ai de tout. Et il le pressa, et Esaü accepta.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Et il dit: Partons et marchons, et j\'irai devant toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Et Jacob dit: Mon seigneur sait que les enfants sont délicats; et je suis chargé de brebis et de vaches qui allaitent; si on les presse un seul jour, tout le troupeau périra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Que mon seigneur passe, je te prie, devant son serviteur; et moi je cheminerai tout doucement, sur les pas du convoi qui est devant moi et sur les pas des enfants, jusqu\'à ce que j\'arrive chez mon seigneur, à Séir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Et Esaü dit: Que je laisse auprès de toi quelques uns des gens qui sont avec moi. Et il dit: Pourquoi cela? Que je trouve grâce aux yeux de mon seigneur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Et Esaü retourna ce jour-là sur ses pas à Séir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Et Jacob partit pour Succoth, et il se construisit une maison; et, comme il avait fait des cabanes pour son bétail, on a nommé ce lieu-là Succoth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Et Jacob, à son retour de Paddan-Aram, arriva sain et sauf à la ville de Sichem, qui est au pays de Canaan, et il campa devant la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Et il acheta des fils de Hémor, père de Sichem, pour cent késitas, la pièce de terre où il avait dressé sa tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Et il éleva là un autel, et il l\'appela Dieu fort, le Dieu d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Et Dina, la fille de Léa, qu\'elle avait enfantée à Jacob, sortit pour voir les filles du pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Et Sichem, fils de Hémor, le Hévien, prince du pays, la vit, l\'enleva, coucha avec elle et lui fit violence.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Et son âme s\'attacha à Dina, fille de Jacob, et il aima la jeune fille et chercha à gagner le cœur de la jeune fille par ses paroles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Et Sichem dit à Hémor, son père: Prends-moi cette jeune fille pour femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Or Jacob avait appris qu\'on avait outragé Dina, sa fille; mais ses fils étaient aux champs avec son bétail, et Jacob avait gardé le silence jusqu\'à leur retour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Et Hémor, père de Sichem, sortit pour parler à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Et les fils de Jacob étaient de retour des champs quand ils apprirent la chose; et ces hommes en furent outrés et se mirent dans une grande colère parce qu\'il avait commis une infamie contre Israël, en couchant avec la fille de Jacob, chose qui ne devait point se faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Et Hémor leur parla ainsi Sichem, mon fils... son âme s\'est attachée à votre fille; donnez-la lui, je vous prie, pour femme;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'et alliez-vous avec nous: vous nous donnerez vos filles, et vous prendrez nos filles;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'vous vous établirez chez nous; et le pays sera à votre disposition; demeurez-y et y trafiquez, et ayez-y des possessions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Et Sichem dit au père et aux frères de la jeune fille: Que je trouve grâce à vos yeux, et ce que vous me direz, je le donnerai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Imposez-moi un fort prix d\'achat et de grands présents, et je les donnerai comme vous me direz; et donnez-moi la jeune fille pour femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Les fils de Jacob répondirent à Sichem et à Hémor, son père, avec ruse et leur donnèrent des paroles, parce qu\'il avait déshonoré Dina, leur sœur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Et ils leur dirent: C\'est une chose que nous ne pouvons pas faire que de donner notre sœur à un homme non circoncis; car c\'est pour nous un opprobre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nous ne consentirons à votre demande qu\'à la condition que vous deveniez comme nous, en faisant circoncire tout mâle parmi vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Ainsi nous vous donnerons nos filles et nous prendrons vos filles; et nous nous établirons chez vous, et nous deviendrons un seul peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mais si vous ne consentez pas à vous circoncire, nous prendrons notre fille et nous nous en irons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Et leurs paroles furent agréées de Hémor et de Sichem, fils de Hémor.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Et le jeune homme ne tarda pas à faire la chose, car il était épris de la fille de Jacob, et il était l\'homme le plus honoré de toute la maison de son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Et Hémor et Sichem, son fils, se rendirent à la porte de leur ville et parlèrent aux hommes de leur ville en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ces gens-là sont des hommes paisibles au milieu de nous; qu\'ils s\'établissent dans le pays et qu\'ils y trafiquent; voici le pays est assez vaste pour eux en long et en large. Nous prendrons leurs filles pour femmes et nous leur donnerons nos filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mais ces hommes ne consentiront à habiter avec nous pour devenir un même peuple qu\'à la condition que tout mâle parmi nous soit circoncis, comme ils le sont eux-mêmes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Leurs troupeaux et leurs biens et toutes leurs bêtes de somme ne seront-ils pas à nous? Il faut seulement que nous consentions à ce qu\'ils demandent, et qu\'ils s\'établissent chez nous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Et tous ceux qui sortaient par la porte de la ville écoutèrent Hémor et Sichem, son fils, et tout mâle fut circoncis, tout homme sortant par la porte de la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Et il arriva au troisième jour, lorsqu\'ils étaient souffrants, que deux des fils de Jacob, Siméon et Lévi, frères de Dina, prirent chacun son épée, se jetèrent sur la ville sans crainte, et tuèrent tous les mâles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Ils firent passer au fil de l\'épée Hémor et Sichem, son fils, et ils prirent Dina de la maison de Sichem et sortirent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Les fils de Jacob se jetèrent sur les tués et pillèrent la ville, parce qu\'on avait déshonoré leur sœur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Et ils prirent leur petit et leur gros bétail et leurs ânes, ce qui était dans la ville et aux champs;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'ils emmenèrent et pillèrent tous leurs biens et tous leurs petits enfants et leurs femmes, et tout ce qui était dans les maisons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Et Jacob dit à Siméon et à Lévi: Vous avez troublé ma vie en me mettant en mauvaise odeur parmi les habitants du pays, parmi les Cananéens et les Phéréziens. Et moi je n\'ai que peu de gens; ils s\'assembleront contre moi et me frapperont, et je serai détruit, moi et ma maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Ils répondirent: Traiterait-on notre sœur comme une prostituée?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Et Dieu dit à Jacob: Lève-toi, monte à Béthel et demeures-y, et fais-y un autel au Dieu qui t\'est apparu quand tu fuyais de devant Esaü, ton frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Et Jacob dit à sa famille et à tous ceux qui étaient avec lui: Otez les dieux de l\'étranger qui sont au milieu de vous, purifiez-vous et changez de vêtements;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'et nous nous lèverons et monterons à Béthel, et j\'y ferai un autel au Dieu qui m\'a répondu au jour de ma détresse et qui a été avec moi dans le chemin où j\'ai marché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Et ils donnèrent à Jacob tous les dieux de l\'étranger qui étaient entre leurs mains et les boucles qu\'ils avaient aux oreilles; et Jacob les enfouit sous le chêne qui est à Sichem.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Et ils partirent. Et la terreur de Dieu fut sur les villes environnantes, et on ne poursuivit pas les fils de Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Et Jacob arriva à Luz, qui est au pays de Canaan, c\'est Béthel, lui et tous les gens qui étaient avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Il bâtit là un autel, et il appela ce lieu Dieu fort de Béthel, car c\'est là que les êtres divins lui étaient apparus lorsqu\'il fuyait de devant son frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Et Débora, nourrice de Rébecca, mourut, et elle fut enterrée au-dessous de Béthel, au pied du chêne que l\'on nomma le chêne des pleurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Et Dieu apparut encore à Jacob à son retour de Paddan-Aram, et il le bénit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Et Dieu lui dit: Ton nom est Jacob; tu ne seras plus appelé Jacob, mais Israël sera ton nom. Et il le nomma Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Et Dieu lui dit: Je suis le Dieu puissant. Fructifie et multiplie: une nation, une assemblée de nations naîtra de toi, et de tes reins sortiront des rois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Et le pays que j\'ai donné à Abraham et à Isaac, je te le donnerai, et je donnerai ce pays à ta postérité après toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Et Dieu remonta d\'auprès de lui, du lieu où il lui avait parlé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Et Jacob dressa un monument dans le lieu où il lui avait parlé, un monument de pierre, et il y fit une libation et y versa de l\'huile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Et Jacob donna au lieu où Dieu lui avait parlé le nom de Béthel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Et ils partirent de Béthel, et il y avait encore un espace de chemin jusqu\'à Ephrath, lorsque Rachel enfanta, et son accouchement fut pénible.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Et pendant ce pénible enfantement, la femme qui l\'accouchait lui dit: Ne crains point, car c\'est encore un fils que tu as là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Et en rendant l\'âme, car elle se mourait, elle le nomma Bénoni; mais son père l\'appela Benjamin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Et Rachel mourut, et elle fut ensevelie au chemin d\'Ephrath, qui est Bethléem.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Et Jacob dressa un monument sur sa tombe; c\'est le monument de la tombe de Rachel qui subsiste encore aujourd\'hui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Et Israël partit, et il dressa sa tente au-delà de Migdal-Eder.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Et il arriva, pendant qu\'Israël demeurait dans cette contrée, que Ruben vint et coucha avec Bilha, concubine de son père; et Israël l\'apprit. Et les fils de Jacob étaient au nombre de douze.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Fils de Léa: Ruben, premier-né de Jacob, Siméon, Lévi, Juda, Issacar et Zabulon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Fils de Rachel: Joseph et Benjamin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Fils de Bilha, servante de Rachel: Dan et Nephthali.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Fils de Zilpa, servante de Léa: Gad et Asser. Ce sont là les fils de Jacob, qui lui naquirent à Paddan-Aram.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Et Jacob arriva vers Isaac, son père, à Mamré, à la ville d\'Arba, qui est Hébron, où avaient séjourné Abraham et Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Et les jours d\'Isaac furent de cent quatre-vingts ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Et Isaac expira et mourut et fut recueilli vers les siens, vieux et rassasié de jours; et Esaü et Jacob, ses fils, l\'ensevelirent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Et voici la postérité d\'Esaü, qui est Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaü prit ses femmes parmi les filles de Canaan: Ada, fille d\'Elon, le Héthien, Oholibama, fille d\'Ana, fille de Tsibéon, le Hévien,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'et Basmath, fille d\'Ismaël, sœur de Nébajoth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada enfanta à Esaü Eliphaz, et Basmath enfanta Réuel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'et Oholibama enfanta Jéusch, Jaélam et Korach. Ce sont là les fils d\'Esaü, qui lui naquirent au pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Et Esaü prit ses femmes et ses fils et ses filles, et toutes les personnes de sa maison, et ses troupeaux, et tous ses bestiaux, et tous les biens dont il s\'était enrichi dans le pays de Canaan; et il s\'en alla dans un pays, loin de Jacob, son frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Car leurs biens étaient trop grands pour qu\'ils pussent demeurer ensemble, et le pays où ils séjournaient ne pouvait leur suffire, à cause de leurs troupeaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Et Esaü s\'établit dans la montagne de Séir. Esaü est Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Et voici la postérité d\'Esaü, père d\'Edom, dans la montagne de Séir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Voici les noms des fils d\'Esaü: Eliphaz, fils d\'Ada, femme d\'Esaü; Réuel, fils de Basmath, femme d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Et les fils d\'Eliphaz furent Théman, Omar, Tsépho et Gaétham et Kénaz.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Et Thimna fut concubine d\'Eliphaz, fils d\'Esaü, et enfanta Amalek à Eliphaz. Ce sont là les fils d\'Ada, femme d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Et voici les fils de Réuel: Nahath et Zérach, Schamma et Mizza. Ce furent là les fils, de Basmath, femme d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Et ceux-ci furent les fils d\'Oholibama, fille d\'Ana, fille de Tsibéon et femme d\'Esaü: elle enfanta à Esaü Jéusch, Jaélam et Korach.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Voici les chefs des fils d\'Esaü: Fils d\'Eliphaz, premier-né d\'Esaü: le chef Théman, le chef Omar, le chef Zépho, le chef Kénaz,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, '[le chef Korach], le chef Gaétham, le chef Amalek. Ce sont là les chefs d\'Eliphaz, au pays d\'Edom; ce sont là les fils d\'Ada.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Et voici les fils de Réuel, fils d\'Esaü: le chef Nahath, le chef Zérach, le chef Schamma, le chef Mizza. Ce sont là les chefs de Réuel, au pays d\'Edom; ce sont là les fils de Basmath, femme d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Et voici les fils d\'Oholibama, femme d\'Esaü: le chef Jéusch, le chef Jaélam, le chef Korach. Ce sont là les chefs d\'Oholibama, fille d\'Ana et femme d\'Esaü.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ce sont là les fils d\'Esaü et ce sont là leurs chefs; c\'est Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Voici les fils de Séir, le Horien, qui habitaient le pays: Lotan, Schobal, Tsibéon, Ana,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dischon, Etser et Dischan. Ce sont là les chefs des Horiens, fils de Séir, au pays d\'Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Et les fils de Lotan furent Hori et Hémam; et Thimna était sœur de Lotan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Et voici les fils de Schobal: Alvan, Mânahath et Ebal, Schépho et Onam.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Et voici les fils de Tsibéon: Ajja et Ana. C\'est cet Ana qui trouva les sources chaudes dans le désert, en paissant les ânes de Tsibéon, son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Et voici les enfants d\'Ana: Dischon et Oholibama, fille d\'Ana.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Et voici les fils de Dischon: Hemdan, Eschban, Jithran et Kéran.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Voici les fils d\'Etser: Bilhan, Zaavan et Akan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Voici les fils de Dischan: Uts et Aran.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Voici les chefs des Horiens: le chef Lotan, le chef Schobal, le chef Tsibéon, le chef Ana,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'le chef Dischon, le chef Etser, le chef Dischan. Ce sont là les chefs des Horiens, selon les chefs qu\'ils eurent au pays de Séir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Et voici les rois qui régnèrent au pays d\'Edom avant qu\'un roi régnât sur les enfants d\'Israël:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Béla, fils de Béor, régna en Edom, et le nom de sa ville était Dinhaba.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Et Béla mourut, et Jobab, fils de Zérach, de Botsra, régna à sa place.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Et Jobab mourut, et Huscham, du pays des Thémanites, régna à sa place.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Et Huscham mourut; et Hadad, fils de Bédad, régna à sa place; il défit Madian aux champs de Moab; et le nom de sa ville était Avith.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Et Hadad mourut, et Samla, de Masréka, régna à sa place.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Et Samla mourut, et Saül, de Rehoboth sur le fleuve, régna à sa place.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Et Saül mourut, et Baal-Hanan, fils d\'Acbor, régna à sa place.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Et Baal-Hanan, fils d\'Acbor, mourut, et Hadar règna à sa place; et le nom de sa ville était Paü, et le nom de sa femme Méhétabéel, fille de Matred, fille de Mézahab.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Et voici les noms des chefs d\'Esaü, selon leurs familles, selon leurs lieux, par leurs noms: le chef Thimna, le chef Alva, le chef Jétheth,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'le chef Oholibama, le chef Ela, le chef Pinon,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'le chef Kénaz, le chef Théman, le chef Mibtsar,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'le chef Magdiel, le chef Iram. Ce sont là les chefs d\'Edom selon leurs demeures au pays au\'ils occupent. C\'est là Esaü le Père d\'Edom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Et Jacob s\'établit dans le pays où son père avait séjourné, dans le pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Voici la postérité de Jacob. Joseph, âgé de dix-sept ans, paissait les brebis avec ses frères; et, jeune garçon, il se trouvait avec les fils de Bilha et avec les fils de Zilpa, femmes de son père. Et Joseph fit à leur père de mauvais rapports sur leur compte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Et Israël aimait Joseph plus que tous ses autres fils, car c\'était un fils de sa vieillesse, et il lui fit une robe longue.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Et ses frères virent que leur père l\'aimait plus que tous ses frères, et ils le prirent en haine, et ils ne pouvaient lui parler amicalement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Et Joseph eut un songe, et il le raconta à ses frères, et ils le haïrent encore plus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Il leur dit: Ecoutez, je vous prie, ce songe que j\'ai eu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Voici, nous étions à lier des gerbes au milieu des champs. Et voici ma gerbe s\'est levée et s\'est tenue debout; et voici vos gerbes l\'ont entourée et se sont prosternées devant ma gerbe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Et ses frères lui dirent: Règnerais-tu donc sur nous, ou nous gouvernerais-tu? Et ils le haïrent encore plus pour ses songes et pour ses paroles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Et il eut encore un autre songe, et il le raconta à ses frères, et il dit: Voici, j\'ai eu encore un songe; et voici le soleil, la lune et onze étoiles se prosternaient devant moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Et il le raconta à son père et à ses frères; et son père le réprimanda et lui dit: Qu\'est-ce que ce songe que tu as eu? Faudra-t-il que nous venions, moi, ta mère et tes frères, nous prosterner en terre devant toi?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Et ses frères furent jaloux de lui; mais son père retint la chose.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Et ses frères allèrent paître les troupeaux de leur père à Sichem.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Et Israël dit à Joseph: Tes frères ne paissent-ils pas [les troupeaux] à Sichem? Viens, que je t\'envoie vers eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Et il répondit: Me voici. Et il lui dit: Va donc voir si tes frères vont bien et si les troupeaux vont bien, et apporte-m\'en des nouvelles. Ainsi il l\'envoya de la vallée d\'Hébron, et Joseph arriva à Sichem.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Et un homme le trouva comme il errait dans la campagne. Et cet homme l\'interrogea, disant: Que cherches-tu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Et il dit: Je cherche mes frères; indique-moi, je te prie, où ils font paître.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Et l\'homme dit: Ils sont partis d\'ici, car je les ai entendus dire: Allons à Dothan. Et Joseph alla à la recherche de ses frères, et il les trouva à Dothan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Ils le virent de loin; et avant qu\'il fût près d\'eux, ils complotèrent contre lui pour le faire mourir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Et ils se dirent l\'un à l\'autre: Voici l\'homme aux songes; c\'est bien lui qui vient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Maintenant donc venez, tuons-le et jetons-le dans une de ces fosses, et nous dirons qu\'une bête féroce l\'a dévoré; et nous verrons ce qui en sera de ses songes!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Et Ruben entendit cela, et pour le délivrer de leurs mains, il dit: Ne le frappons pas à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Et Ruben leur dit: Ne versez pas de sang; jetez-le dans cette fosse qui est au pâturage, et ne portez pas la main sur lui. C\'était afin de le délivrer de leurs mains pour le rendre à son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Et quand Joseph arriva vers ses frères, ils dépouillèrent Joseph de sa robe, de la robe longue qu\'il avait mise.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Et ils le prirent et le jetèrent dans la fosse. Et la fosse était vide; elle n\'avait pas d\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Et ils s\'assirent pour manger. Et, levant les yeux, ils aperçurent une caravane d\'Ismaélites venant de Galaad; et leurs chameaux étaient chargés d\'astragale, de baume et de ladanum, qu\'ils allaient porter en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Et Juda dit à ses frères: Que gagnerons-nous à tuer notre frère et à cacher son sang?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Allons le vendre aux Ismaélites, et que notre main ne soit point sur lui, car c\'est notre frère, notre chair. Et ses frères l\'écoutèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Et quand [les] marchands madianites passèrent, ils tirèrent Joseph et le firent remonter de la fosse, et ils vendirent Joseph aux Ismaélites pour vingt pièces d\'argent; ceux-ci l\'emmenèrent en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Et Ruben retourna à la fosse, et voici Joseph n\'était plus dans la fosse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Alors il déchira ses vêtements, et il retourna vers ses frères et dit: L\'enfant n\'y est plus, et moi, où irai-je?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Et ils prirent la robe de Joseph, égorgèrent un bouc et trempèrent la robe dans le sang.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Et ils envoyèrent la robe longue et la firent parvenir à leur père et dirent: Voici ce que nous avons trouvé; reconnais si c\'est la robe de ton fils ou non.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Et il la reconnut et dit: La robe de mon fils! Une bête féroce l\'a dévoré! Joseph a été mis en pièces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Et Jacob déchira ses vêtements et mit un sac sur ses reins, et il mena deuil sur son fils pendant longtemps.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Et tous ses fils et toutes ses filles vinrent pour le consoler; mais il refusa d\'être consolé, et il dit: Je descendrai vers mon fils au sépulcre en menant deuil. Et son père le pleura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Et les Madianites le vendirent en Egypte à Potiphar, officier de Pharaon, chef des gardes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Il arriva dans ce temps-là que Juda descendit d\'auprès de ses frères et arriva jusque près d\'un homme d\'Adullam nommé Hira.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Et là Juda vit la fille d\'un Cananéen nommé Schua; et il la prit [pour femme] et alla vers elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Et elle conçut et enfanta un fils, et il le nomma Er.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Et elle conçut encore et enfanta un fils, et elle le nomma Onan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Elle enfanta encore un fils, et elle le nomma Schéla. Et Juda était à Kézib quand elle l\'enfanta.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Et Juda prit pour Er, son premier-né, une femme nommée Thamar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Et Er, premier-né de Juda, fut méchant aux yeux de l\'Eternel, et l\'Eternel le fit mourir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Et Juda dit à Onan: Va vers la femme de ton frère en ta qualité de beau-frère et suscite une postérité à ton frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mais Onan savait que cette postérité ne serait pas à lui, et quand il allait vers la femme de son frère, il faisait en sorte de ne point donner de postérité à son frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Et ce qu\'il faisait déplut à l\'Eternel, et il le fit mourir aussi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Et Juda dit à Thamar, sa belle-fille: Demeure comme veuve dans la maison de ton père jusqu\'à ce que Schéla, mon fils, soit devenu grand. Car il disait: Il ne faut pas qu\'il meure, lui aussi, comme ses frères. Et Thamar s\'en alla et demeura dans la maison de son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Et bien des jours s\'écoulèrent, et la fille de Schua, femme de Juda, mourut. Et Juda, après avoir fini son deuil, monta vers ceux qui tondaient ses brebis à Thimna, lui et Hira, son ami, l\'Adullamite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Et on en informa Thamar, en lui disant: Voici, ton beau-père monte à Thimna pour tondre ses brebis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Et elle ôta ses habits de veuve, se couvrit d\'un voile et s\'en enveloppa, et elle s\'assit à l\'entrée d\'Enaïm, qui est sur le chemin de Thimna; car elle avait vu que Schéla était devenu grand et qu\'elle ne lui avait pas été donnée pour femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Et Juda la vit et la prit pour une femme de mauvaise vie; car elle avait couvert son visage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Et il se détourna vers elle, vers le chemin, et il dit: Permets que j\'aille vers toi. Car il ne savait pas que ce fût sa belle-fille. Elle répondit: Que me donneras-tu pour venir vers moi?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Il dit: J\'enverrai un chevreau du troupeau. Et elle dit: A condition que tu me donnes un gage jusqu\'à ce que tu l\'envoies.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Il dit: Quel est le gage que je te donnerai? Et elle répondit: Ton cachet et ton cordon, et ton bâton que tu as à la main. Et il les lui donna, et il alla vers elle, et elle devint enceinte de lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Et elle se leva et s\'en alla; et elle ôta son voile et remit ses habits de veuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Et Juda envoya le chevreau par son ami, l\'Adullamite, pour retirer le gage des mains de cette femme; mais il ne la trouva point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Et il interrogea les hommes du lieu, en disant: Où est cette prostituée qui était à Enaïm, au bord du chemin? Ils lui dirent: Il n\'y a point eu ici de prostituée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Et il retourna vers Juda et dit: Je ne l\'ai point trouvée, et même les gens du lieu ont dit: Il n\'y a point eu ici de prostituée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Et Juda dit: Qu\'elle garde cela! Il ne faut pas qu\'on se moque de nous. C\'est un fait que j\'ai envoyé ce chevreau, et tu ne l\'as point trouvée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Et il arriva qu\'environ trois mois après on alla dire à Juda: Thamar, ta belle-fille, s\'est prostituée, et même la voilà enceinte de ses prostitutions. Et Juda dit: Faites-la sortir, et qu\'elle soit brûlée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Comme on la faisait sortir, elle envoya dire à son beau-père: C\'est d\'un homme à qui ceci appartient que je suis enceinte. Elle dit encore: Examine, je te prie, à qui sont ce cachet et ces cordons, et ce bâton.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Et Juda les reconnut et dit: Elle est plus juste que moi; [c\'est arrivé] parce que je ne l\'ai point donnée à Schéla, mon fils. Et il ne la connut plus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Et à l\'époque où elle devait accoucher, voici il y avait des jumeaux dans son sein.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Et pendant qu\'elle enfantait, l\'un d\'eux étendit une main; et l\'accoucheuse la prit et y lia un fil écarlate en disant: C\'est celui-ci qui est sorti le premier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Mais il retira sa main, et voici son frère sortit. Et elle dit: Quelle brèche tu as faite! La brèche soit sur toi! Et on le nomma Pérets.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Ensuite sortit son frère, qui avait à sa main le fil écarlate, et on le nomma Zérach.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Joseph fut emmené en Egypte, et Potiphar, officier de Pharaon, chef des gardes, homme égyptien, l\'acheta des Ismaélites qui l\'y avaient amené.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Et l\'Eternel fut avec Joseph, et Joseph menait toutes choses à bien et son maître, l\'Egyptien, le plaça dans sa maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Et son maître vit que l\'Eternel était avec lui, et que l\'Eternel faisait réussir entre ses mains tout ce qu\'il faisait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Et Joseph trouva grâce à ses yeux, et il fut employé à son service, et son maître l\'établit sur sa maison et lui remit tout ce qui lui appartenait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Et dès qu\'il l\'eut établi sur sa maison et sur tout ce qui lui appartenait, l\'Eternel bénit la maison de l\'Egyptien à cause de Joseph. Et la bénédiction de l\'Eternel fut sur tout ce qui lui appartenait, dans la maison et aux champs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Et il abandonna aux soins de Joseph tout ce qui lui appartenait, et avec lui il ne s\'informa plus de rien, si ce n\'est des aliments qu\'il prenait. Et Joseph était beau de taille et beau de visage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Et il arriva après ces choses que la femme de son maître jeta les yeux sur Joseph et dit: Couche avec moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Et il refusa et dit à la femme de son maître: Voici mon maître ne s\'informe avec moi de rien dans la maison, et il a remis entre mes mains tout ce qui lui appartient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Il n\'est pas plus grand que moi dans cette maison, et il ne m\'a rien interdit que toi, parce que tu es sa femme. Comment ferais-je ce grand mal et pécherais-je contre Dieu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Et comme elle en parlait tous les jours à Joseph et qu\'il ne consentait point à coucher auprès d\'elle ni à être avec elle,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'il arriva un certain jour que Joseph, étant entré dans la maison pour faire ses affaires, sans qu\'il y eût là au logis aucun des gens de la maison,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'elle le saisit par son vêtement en disant: Couche avec moi. Et il lui laissa son vêtement dans la main, et il s\'enfuit et sortit de la maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Et quand elle vit qu\'il lui avait laissé son vêtement dans la main et qu\'il s\'était enfui dehors,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'elle appela les gens de sa maison et leur parla disant: Voyez, on nous a amené un homme hébreu pour s\'amuser de nous. Il est entré vers moi pour coucher avec moi; et j\'ai appelé à grands cris;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'et quand il a entendu que j\'élevais la voix et que je criais, il a laissé son vêtement à côté de moi et s\'est enfui et est sorti de la maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Et elle garda près d\'elle le vêtement de Joseph jusqu\'à ce que son maître rentrât.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Et elle lui parla de cette manière, disant: Le serviteur hébreu que tu nous as amené est venu vers moi pour s\'amuser de moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Et quand j\'ai élevé la voix et que j\'ai appelé, il a laissé son vêtement à côté de moi et s\'est enfui dehors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Et quand le maître de Joseph eut entendu les paroles de sa femme, qui lui disait: Voilà ce que m\'a fait ton serviteur, sa colère s\'enflamma.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Et le maître de Joseph le prit et le mit dans la prison; c\'était le lieu où étaient détenus les prisonniers du roi. Il fut là dans la prison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Et l\'Eternel fut avec Joseph, et il étendit sur lui sa bonté et lui concilia la faveur du gouverneur de la prison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Et le gouverneur de la prison confia à Joseph tous les prisonniers qui étaient dans la prison; et tout ce qui s\'y faisait, c\'était lui qui le faisait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Le gouverneur de la prison ne prenait connaissance de rien de tout ce que Joseph avait en mains, parce que l\'Eternel était avec lui et que l\'Eternel faisait réussir ce qu\'il faisait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Il arriva après ces choses que l\'échanson du roi d\'Egypte et le panetier commirent une faute envers leur seigneur, envers le roi d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Et Pharaon fut irrité contre ses deux officiers, contre le chef des échansons et le chef des panetiers;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'et il les fit enfermer chez le chef des gardes, dans la prison, dans le lieu où Joseph était enfermé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Et le chef des gardes établit Joseph auprès d\'eux, et il les servait; et ils furent quelque temps en prison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Et l\'échanson et le panetier du roi d\'Egypte, qui étaient enfermés dans la prison, eurent tous deux un songe dans la même nuit, chacun un songe différent, chacun un songe ayant sa signification particulière.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Et Joseph vint chez eux au matin, et il vit qu\'ils étaient tristes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Et il questionna les officiers de Pharaon, qui étaient avec lui en prison dans la maison de son maître, et leur dit: D\'où vient que vous avez aujourd\'hui mauvais visage?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Et ils lui dirent: Nous avons fait un songe, et il n\'y a personne pour l\'interpréter. Et Joseph dit: Les interprétations ne sont-elles pas à Dieu? Racontez-moi, je vous prie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Et le chef des échansons raconta à Joseph le songe qu\'il avait eu et lui dit: Dans mon songe, voici un cep était devant moi;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'et à ce cep il y avait trois sarments. Et à peine eut-il poussé que sa fleur sortit et que ses grappes donnèrent des raisins mûrs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Et la coupe de Pharaon était dans ma main, et je pris des raisins, et je pressai le jus dans la coupe de Pharaon, et je mis la coupe dans la main de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Et Joseph lui dit: Voici l\'interprétation. Les trois sarments sont trois jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Encore trois jours, et Pharaon élèvera ta tête et te rétablira dans ta charge, et tu mettras la coupe de Pharaon dans sa main, selon l\'office que tu remplissais auparavant quand tu étais son échanson.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Si tu te souviens de moi quand tout ira bien pour toi, et si tu daignes user de bonté envers moi, parle de moi à Pharaon et fais-moi sortir de cette maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Car c\'est par un vol que j\'ai été enlevé du pays des Hébreux, et ici même je n\'ai rien fait pour qu\'on me mît dans cette fosse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Et le chef des panetiers, voyant que Joseph avait donné une interprétation favorable, lui dit: Moi aussi, dans mon songe, voici j\'avais trois corbeilles de pain blanc sur la tête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Et dans la corbeille de dessus, il y avait toutes sortes de pâtisseries faites pour Pharaon; et les oiseaux les mangeaient de la corbeille qui était sur ma tête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Et Joseph répondit et dit: Voici l\'interprétation. Les trois corbeilles sont trois jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Encore trois jours, et Pharaon enlèvera ta tête de dessus toi et te pendra à un bois, et les oiseaux mangeront ta chair de dessus toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Et il arriva le troisième jour, jour de naissance de Pharaon, qu\'il fit un festin à tous ses serviteurs, et il éleva la tête du chef des échansons et la tête du chef des panetiers au milieu de ses serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Il rétablit dans son office d\'échanson le chef des échansons, qui mit la coupe dans la main de Pharaon,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'et il fit pendre le chef des panetiers, selon l\'interprétation que Joseph leur avait donnée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Et le chef des échansons ne parla pas de Joseph, et l\'oublia.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Et il arriva, après deux ans entiers, que Pharaon eut un songe. Voici il se tenait près du fleuve;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'et voici que du fleuve montaient sept vaches belles à voir et fort grasses, et elles se mirent à paître dans la prairie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Et voici sept autres vaches montaient du fleuve après elles, laides à voir et fort maigres, et elles vinrent se placer à côté des vaches qui étaient sur le bord du fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Et les vaches laides et maigres dévorèrent les sept vaches belles et grasses. Et Pharaon s\'éveilla.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Et il se rendormit et songea une seconde fois. Et voici sept épis montaient d\'une même tige, gras et beaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Et voici sept épis maigres et brûlés par le vent d\'orient germaient après ceux-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Et les épis maigres engloutirent les sept épis gras et pleins. Et Pharaon s\'éveilla; et voici c\'était un songe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Et au matin, étant frappé dans son esprit, il envoya appeler tous les scribes et tous les sages d\'Egypte. Et Pharaon leur raconta son songe; et pas un ne l\'interpréta à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Et le chef des échansons parla à Pharaon disant: Je vais rappeler aujourd\'hui mes fautes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Pharaon s\'était irrité contre ses, serviteurs et m\'avait mis en prison dans la maison du chef des gardes, moi et le chef des panetiers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Et nous eûmes un songe dans une même nuit, moi et lui; nous eûmes chacun un songe ayant sa propre signification.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Et il y avait là avec nous un jeune homme hébreu, serviteur du chef des gardes, et nous lui racontâmes nos songes, et il nous en donna l\'interprétation; il donna à chacun l\'interprétation de son songe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Et il arriva que les choses se passèrent comme il avait interprété; moi, on me rétablit dans mon poste, et lui, on le pendit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Et Pharaon envoya appeler Joseph, et on le fit sortir en hâte de la fosse. On le rasa, on lui mit d\'autres habits, et il vint vers Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Et Pharaon dit à Joseph: J\'ai eu un songe et il n\'y a personne qui l\'interprète. Et j\'ai entendu dire de toi que, quand tu entends, un songe, tu l\'interprètes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Et Joseph répondit à Pharaon en disant: Ce n\'est pas moi, c\'est Dieu qui donnera la réponse favorable à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Et Pharaon dit à Joseph: Dans mon songe, voici je me tenais sur le bord du fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Et voici que du fleuve montaient sept vaches grasses et de belle apparence, et elles se mirent à paître dans la prairie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Et voici sept autres vaches montaient après elles, chétives, de très laide apparence et fort maigres; je n\'en ai point vu de pareilles en laideur dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Et les vaches chétives et laides dévorèrent les sept premières, les vaches grasses;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'et elles entrèrent dans leur ventre sans qu\'il parût qu\'elles y fussent entrées: elles étaient aussi laides à voir qu\'auparavant. Et je m\'éveillai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Et je vis en songeant, et voici sept épis montaient sur une même tige, pleins et beaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Et voici sept épis stériles, maigres et brûlés par le vent d\'orient, germaient après ceux-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Et les épis maigres engloutirent les sept beaux épis. J\'ai raconté cela aux scribes, et aucun ne me l\'explique.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Et Joseph dit à Pharaon: Ce que Pharaon a songé, est un seul songe. Dieu a fait connaître à Pharaon ce qu\'il va faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Les sept belles vaches sont sept années; et les sept beaux épis sont sept années; c\'est un seul et même songe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Et les sept vaches chétives et laides qui montaient après elles sont sept années; et les sept épis vides, brûlés par le vent d\'orient, seront sept années de famine.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'C\'est ce que j\'ai dit à Pharaon: Dieu a fait voir à Pharaon ce qu\'il va faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Voici il va venir sept années de grande abondance dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Et sept années de famine leur succéderont, et toute cette abondance sera oubliée au pays d\'Egypte, et la famine consumera le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Et l\'on ne s\'apercevra plus de l\'abondance qui aura été dans le pays, à cause de la famine qui suivra; car elle sera très grande.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Et si le songe a été réitéré pour Pharaon, c\'est que la chose est décidée de la part de Dieu et que Dieu se hâte de l\'exécuter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Or maintenant, que Pharaon trouve un homme entendu et sage, et qu\'il l\'établisse sur le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Que Pharaon fasse ceci: qu\'il établisse des commissaires sur le pays, et qu\'il impose du cinquième le pays d\'Egypte durant les sept années d\'abondance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Et qu\'on rassemble tous les vivres que donneront les bonnes années qui viennent et qu\'on fasse des amas de blé à la disposition de Pharaon, comme provision dans les villes, et qu\'on les conserve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Et ces vivres serviront de réserve pour le pays en vue des sept années de famine qui seront au pays d\'Egypte, et le pays ne périra pas par la famine.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'La chose plut à Pharaon et à tous ses serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Et Pharaon dit à ses serviteurs: Trouverions-nous un homme pareil à celui-ci, ayant en lui l\'Esprit de Dieu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Et Pharaon dit à Joseph: Puisque Dieu t\'a fait connaître tout cela, nul n\'est entendu et sage comme toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'C\'est toi qui gouverneras ma maison, et tout mon peuple obéira à ta bouche; par le trône seulement je serai plus grand que toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Et Pharaon dit à Joseph: Vois, je t\'ai établi sur tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Et Pharaon ôta son anneau de sa main et le mit à la main de Joseph, et il le fit revêtir d\'habits de fin lin et lui mit un collier d\'or au cou.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Et il le fit monter sur le second de ses chars et l\'on cria devant lui: A genoux! Et il fut établi sur tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Et Pharaon dit à Joseph: Je suis Pharaon! Et sans toi nul ne lèvera la main ni le pied dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Et Pharaon nomma Joseph Tsaphnath-Panéach, et il lui donna pour femme Asnath, fille de Potiphéra, sacrificateur d\'On. Et Joseph sortit pour visiter le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Joseph était âgé de trente ans, quand il se présenta devant Pharaon, roi d\'Egypte. Et Joseph sortit de devant Pharaon, et parcourut tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Et la terre rapporta à pleines mains pendant les sept années d\'abondance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Et Joseph amassa tous les vivres des sept années qu\'il y eut au pays d\'Egypte, et il mit les vivres dans les villes; il mit dans l\'intérieur de chaque ville les vivres du territoire d\'alentour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Et Joseph amassa du blé comme le sable de la mer, en si grande quantité qu\'on cessa de compter, parce qu\'il était sans nombre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Et avant qu\'arrivât l\'année de famine, il naquit à Joseph deux fils que lui enfanta Asnath, fille de Potiphéra, sacrificateur d\'On.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Et Joseph donna au premier-né le nom de Manassé, car Dieu, dit-il, m\'a fait oublier toute ma peine et toute la maison de mon père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Et il donna au second le nom d\'Ephraïm, car Dieu, dit-il, m\'a fait fructifier dans le pays de mon affliction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Les sept années où l\'abondance avait régné en Egypte s\'achevèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Et les sept années de famine commencèrent à venir, comme Joseph l\'avait dit. Et il y eut famine dans tous les pays; mais dans tout le pays d\'Egypte il y avait du pain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Puis tout le pays d\'Egypte fut affamé; et le peuple cria à Pharaon pour avoir du pain. Et Pharaon dit à tous les Egyptiens: Allez vers, Joseph; faites ce qu\'il vous dira.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Et la famine était sur toute la face du pays, et Joseph ouvrit tous les greniers qu\'on y avait établis et vendit du blé aux Egyptiens. Et la famine s\'accrut au pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Et toute la terre venait au pays d\'Egypte pour acheter du blé auprès de Joseph; car la famine s\'était renforcée sur toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Et Jacob, voyant qu\'il y avait du blé à vendre en Egypte, dit à ses fils: Pourquoi êtes-vous à vous regarder?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Et il dit: Voici, j\'ai appris qu\'il y a du blé à vendre en Egypte; descendez-y et rapportez-nous-en du blé, afin que nous vivions et ne mourions point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Et les frères de Joseph descendirent au nombre de dix pour acheter du grain en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mais quant à Benjamin, frère de Joseph, Jacob ne l\'avait pas envoyé avec ses frères, car il s\'était dit: Il est à craindre qu\'il ne lui arrive malheur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Et les fils d\'Israël vinrent pour acheter du blé parmi les autres arrivants, car la famine était au pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Or Joseph était celui qui commandait dans le pays, et c\'était lui qui faisait la vente du blé à tout le monde. Et les frères de Joseph vinrent et se prosternèrent devant lui, la face contre terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Et Joseph vit ses frères, et il les reconnut; mais il fit l\'étranger avec eux, et leur parla avec rudesse et leur dit: D\'où venez-vous? Et ils répondirent: Du pays de Canaan, pour acheter des vivres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Joseph reconnut donc ses frères et eux ne le reconnurent pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Et Joseph se souvint des songes qu\'il avait eus à leur sujet. Et il leur dit: Vous êtes des espions; c\'est pour voir les points faibles du pays que vous êtes venus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Et ils lui dirent: Non, mon seigneur; tes serviteurs sont venus pour acheter des vivres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Tous tant que nous sommes, nous sommes fils d\'un même père; nous sommes honnêtes gens; tes serviteurs n\'ont jamais été des espions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Et il leur dit: Non, vous êtes, venus pour voir les points faibles du pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Et ils dirent: Nous, tes serviteurs, sommes douze frères, fils d\'un même père au pays de Canaan. Et voici le plus jeune est maintenant avec notre père, et il y en a un qui n\'est plus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Et Joseph leur dit: J\'en reste à ce que je vous ai dit: vous êtes des espions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Voici comment vous serez mis à l\'épreuve. Par la vie de Pharaon! Si vous sortez d\'ici que votre jeune frère n\'y soit venu!...');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Envoyez l\'un de vous chercher votre frère, et vous, restez prisonniers; et que vos paroles soient mises à l\'épreuve, et l\'on verra si vous dites vrai; sinon, par la vie de Pharaon! c\'est que vous êtes des espions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Et il les mit tous ensemble en prison pour trois jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Et au troisième jour Joseph leur dit: Faites ceci et vous vivrez. Je crains Dieu!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si vous êtes honnêtes gens, que l\'un de vous, votre frère, reste ici lié dans votre prison; et vous, allez, emportez du blé pour les besoins de vos familles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Et amenez-moi votre frère cadet; et vos paroles seront vérifiées, et vous ne mourrez point. Et ils firent ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Et ils se dirent l\'un à l\'autre: Certainement nous sommes punis à cause de notre frère; car nous avons vu la détresse de son âme, quand il nous demandait grâce, et nous ne l\'avons point écouté; voilà pourquoi nous nous trouvons dans cette détresse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Et Ruben leur répondit: Ne vous disais-je pas bien: Ne commettez pas de péché contre l\'enfant? Et vous n\'avez pas écouté; c\'est pourquoi voici son sang est redemandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Et eux ne savaient pas que Joseph comprenait; car ils se parlaient par interprète.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Et il s\'éloigna d\'eux et pleura. Puis il revint vers eux et leur parla; et il prit d\'entre eux Siméon et le fit lier sous leurs yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Et Joseph commanda qu\'on remplit de blé leurs vaisseaux et qu\'on remit l\'argent de chacun dans son sac, et qu\'on leur donnât des provisions pour la route; ce qu\'on fit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Et ils chargèrent leur blé sur leurs ânes et partirent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Et l\'un d\'eux ouvrit son sac pour donner du fourrage à son âne, à l\'endroit où l\'on passait la nuit, et il vit son argent; voici il était à l\'entrée de son sac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Et il dit à ses frères: On a remis mon argent; le voici dans mon sac! Et le cœur leur manqua et ils se dirent en tremblant l\'un à l\'autre Qu\'est-ce que Dieu nous a fait?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Et ils vinrent vers Jacob, leur père, au pays de Canaan, et lui racontèrent toutes les choses qui leur étaient arrivées, en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'L\'homme qui est le maître du pays nous a parlé avec rudesse et nous a pris pour des gens espionnant le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Et nous lui avons dit: Nous sommes honnêtes gens, nous n\'avons jamais été des espions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Nous sommes douze frères, fils d\'un même père; l\'un n\'est plus, et le plus jeune est maintenant avec notre père au pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Et l\'homme qui est le maître du pays nous a dit: A ceci je connaîtrai que vous êtes honnêtes gens: laissez avec moi l\'un de vos frères, prenez de quoi subvenir aux besoins de vos familles, et partez;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'et amenez-moi votre jeune frère, afin que je connaisse que vous n\'êtes point des espions, mais que vous êtes honnêtes gens; je vous rendrai votre frère, et vous trafiquerez dans le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Et comme ils vidaient leurs sacs, voici le paquet d\'argent de chacun était dans son sac; et ils virent, eux et leur père, leur paquet d\'argent, et ils eurent peur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Et Jacob, leur père, leur dit: Vous m\'avez privé d\'enfants: Joseph n\'est plus; Siméon n\'est plus, et vous allez prendre Benjamin: De tout ceci... c\'est moi qui en souffre!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Et Ruben parla à son père et lui dit: Tu feras mourir mes deux fils si je ne te le ramène; remets-le moi, et moi je te le rendrai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Et il répondit: Mon fils ne descendra point avec vous, car son frère est mort, et celui-ci est resté seul. Et s\'il lui arrivait du mal dans le voyage que vous allez faire, vous feriez descendre mes cheveux blancs avec douleur au sépulcre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Et la famine s\'appesantissait sur le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Et quand ils eurent achevé de manger le blé qu\'ils avaient apporté d\'Egypte, leur père leur dit: Retournez nous acheter un peu de vivres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Et Juda lui dit: Cet homme nous l\'a positivement déclaré: Vous ne verrez point ma face que votre frère ne soit avec vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si tu laisses venir notre frère avec nous, nous descendrons et nous t\'achèterons des vivres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Mais si tu ne le laisses pas venir, nous ne descendrons pas, car cet homme nous a dit: Vous ne verrez pas ma face que votre frère ne soit avec vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Et Israël dit: Pourquoi m\'avez-vous fait ce tort, de dire à cet homme que vous avez encore un frère?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Et ils dirent: Cet homme nous a interrogés en détail sur nous et sur notre parenté, en disant: Votre père vit-il encore? Avez-vous un frère? Et nous avons répondu d\'après ces questions. Pouvions-nous savoir qu\'il dirait: Faites descendre votre frère?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Et Juda dit à Israël son père: Laisse venir le jeune homme avec moi, et nous nous lèverons et partirons; et nous vivrons et ne mourrons point, ni nous, ni toi, ni nos petits enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'C\'est moi qui réponds de lui; c\'est de ma main que tu le redemanderas. Si je ne te le ramène, si je ne le mets pas là devant toi, je serai coupable envers toi à tout jamais.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Car si nous n\'avions pas tant tardé, nous serions déjà deux fois de retour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Et Israël, leur père, leur dit: S\'il en est ainsi faites donc ceci: Prenez dans vos vaisseaux des produits de choix du pays et portez à cet homme un présent: un peu de baume et un peu de miel, de l\'astragale, du ladanum, des pistaches et des amandes;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'et emportez de l\'argent à double, et vous reporterez l\'argent qui a été remis à l\'entrée de vos sacs. Peut-être était-ce une erreur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Et prenez votre frère, et levez-vous, retournez vers cet homme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Que le Dieu puissant fasse que cet homme ait compassion de vous quand vous vous présenterez devant lui, et qu\'il vous relâche votre autre frère et Benjamin. Et si je dois perdre mes enfants, que je les perde!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Et ces hommes prirent ce présent, et ayant pris de l\'argent à double avec eux, et Benjamin, ils se levèrent et descendirent en Egypte, et ils se présentèrent devant Joseph.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Et Joseph vit avec eux Benjamin, et il dit à celui qui avait l\'intendance de sa maison: Mène ces hommes à la maison, tue et apprête de quoi manger; car ces hommes mangeront avec moi à midi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Et cet homme fit comme Joseph avait dit, et il amena ces gens à la maison de Joseph,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'et ces gens eurent peur, de ce qu\'on les menait à la maison de Joseph et ils dirent: C\'est à cause de l\'argent qui s\'est retrouvé la première fois dans nos sacs, qu\'on nous conduit ici; c\'est pour nous assaillir et se jeter sur nous et nous prendre pour esclaves avec nos ânes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Et ils s\'approchèrent de l\'intendant de la maison de Joseph et lui parlèrent à la porte de la maison,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'et ils dirent: Permets, mon seigneur: nous sommes descendus une première fois pour acheter des vivres;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'et lorsque nous arrivâmes à l\'endroit où nous devions passer la nuit et que nous ouvrîmes nos sacs, voici, l\'argent de chacun était à l\'entrée de son sac, notre argent au complet, et nous l\'avons rapporté avec nous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Et nous avons pris avec nous d\'autre argent pour acheter des vivres. Nous ne savons pas qui a mis notre argent dans nos sacs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Et il dit: Tout va bien pour vous; ne craignez rien. Votre Dieu, le Dieu de votre père, vous a mis un trésor dans vos sacs; votre argent m\'a été remis. Et il leur fit amener Siméon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Et cet homme les fit entrer dans la maison de Joseph; il leur donna de l\'eau et ils lavèrent leurs pieds; et il donna du fourrage à leurs ânes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Et ils préparèrent le présent en attendant que Joseph vint à midi; car ils avaient appris qu\'ils prendraient là leur repas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Et Joseph rentra chez lui. Et ils lui apportèrent dans la maison le présent qu\'ils avaient pris avec eux; et ils se prosternèrent devant lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Il leur demanda comment ils se portaient, et il leur dit: Votre père, ce vieillard dont vous m\'avez parlé, se porte-t-il bien? Vit-il encore?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Et ils répondirent: Ton serviteur, notre père, se porte bien; il vit encore. Et ils s\'inclinèrent et se prosternèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Et il leva les yeux, et vit Benjamin, son frère, fils de sa mère, et il dit: Est-ce là votre frère cadet dont vous m\'avez parlé? Et il dit: Dieu te soit favorable, mon fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Et en toute hâte, car ses entrailles étaient émues pour son frère, Joseph chercha un endroit pour pleurer; et il entra dans sa chambre, et il y pleura.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Et il se lava le visage et sortit; et, se contenant, il dit: Servez le repas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Et on le servit à part, et eux à part, et les Egyptiens qui mangeaient avec lui aussi à part, parce que les Egyptiens ne peuvent prendre leurs repas avec les Hébreux, car c\'est pour les Egyptiens une chose abominable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Et ils s\'assirent devant lui, étant placés l\'aîné selon son rang d\'aîné, et le plus jeune selon son rang de cadet. Et ces hommes se regardaient l\'un l\'autre stupéfaits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Et il leur fit porter des portions de devant lui, et la portion de Benjamin était cinq fois plus grosse que les portions de tous les autres; et ils burent et s\'égayèrent avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Et il donna cet ordre à l\'intendant de sa maison: Remplis de blé les sacs de ces hommes, autant qu\'ils en peuvent porter, et mets l\'argent de chacun à l\'entrée de son sac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Et ma coupe, la coupe d\'argent, tu la mettras à l\'entrée du sac du plus jeune, avec l\'argent de son blé. Et il fit comme Joseph lui avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Le matin, dès qu\'il fit jour, ces hommes furent congédiés avec leurs ânes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Ils étaient sortis de la ville et ils n\'étaient pas encore éloignés, quand Joseph dit à l\'intendant de sa maison: Lève-toi, poursuis ces hommes et atteins-les, et dis-leur: Pourquoi avez-vous rendu le mal pour le bien?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'N\'est-ce pas la coupe dont mon maître se sert pour boire et pour deviner? Vous avez mal fait d\'agir ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Et il les atteignit et leur dit ces paroles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Et ils lui répondirent: Pourquoi mon seigneur parle-t-il de la sorte? Loin de tes serviteurs de commettre une telle action!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Voici, l\'argent que nous avons trouvé à l\'entrée de nos sacs, nous te l\'avons rapporté du pays de Canaan; et comment aurions-nous dérobé de la maison de ton maître de l\'argent ou de l\'or?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Celui de tes serviteurs chez qui on la trouvera, qu\'il meure, et nous-mêmes, nous deviendrons esclaves de mon seigneur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Et il dit: Soit! qu\'il en soit maintenant comme vous avez dit; que celui chez qui on la trouvera soit mon esclave, et vous, vous serez quittes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Et ils se hâtèrent de déposer chacun son sac à terre, et ils ouvrirent chacun son sac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Et il fouilla, en commençant par l\'aîné et finissant par le plus jeune. Et la coupe se trouva dans le sac de Benjamin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Et ils déchirèrent leurs vêtements, et chacun rechargea son âne, et ils retournèrent à la ville.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Et Juda avec ses frères vint à la maison de Joseph, qui s\'y trouvait encore, et ils se jetèrent à terre devant lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Et Joseph leur dit: Quelle est cette action que vous avez faite? Ne saviez-vous pas qu\'un homme tel que moi ne manque pas de deviner?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Et Juda dit: Que dirons-nous à mon seigneur? Comment parlerons-nous, et comment nous justifierons-nous? Dieu a trouvé l\'iniquité de tes serviteurs. Nous voici esclaves de mon seigneur, nous aussi bien que celui entre les mains de qui la coupe s\'est trouvée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Et il dit: Loin de moi d\'agir ainsi! L\'homme entre les mains duquel la coupe a été trouvée, lui, deviendra mon esclave; et vous, remontez en paix vers votre père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Et Juda s\'approcha de lui et dit: De grâce, mon seigneur! qu\'il soit permis à ton serviteur de dire une parole aux oreilles de mon seigneur, et que ta colère ne s\'enflamme point contre ton serviteur; car tu es l\'égal de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mon seigneur a interrogé ses serviteurs en disant: Avez-vous père ou frère?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Et nous avons dit à mon seigneur: Nous avons un père âgé et un jeune garçon qui lui est né en sa vieillesse; et son frère est mort, et celui-ci est resté seul de sa mère, et son père l\'aime.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Et tu as dit à tes serviteurs: Faites-le descendre vers moi, et que je le voie de mes yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Et nous avons dit à mon seigneur: Le jeune garçon ne peut quitter son père; et s\'il le quitte, son père mourra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Et tu as dit à tes serviteurs: Si votre jeune frère ne descend avec vous, vous ne reverrez pas ma face.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Et lorsque nous sommes remontés vers ton serviteur mon père, nous lui avons rapporté les paroles de mon seigneur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Et notre père dit: Retournez nous acheter un peu de vivres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Et nous avons dit: Nous ne pouvons descendre; si notre jeune frère est avec nous, nous descendrons; car nous ne pouvons pas voir la face de cet homme, que notre jeune frère ne soit avec nous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Et ton serviteur mon père nous a dit: Vous savez vous-mêmes que ma femme m\'a enfanté deux fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'L\'un s\'en est allé d\'avec moi, et j\'ai dit: Il faut qu\'il ait été dévoré; et je ne l\'ai pas revu jusqu\'à présent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Si vous emmenez encore celui-ci de devant moi et qu\'il lui arrive malheur, vous ferez descendre mes cheveux blancs avec douleur au sépulcre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Et maintenant, quand je viendrai vers ton serviteur mon père, si le jeune homme n\'est pas avec nous, lui dont l\'âme est étroitement liée à son âme,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'il arrivera, dès qu\'il verra que le jeune homme n\'y est pas, qu\'il mourra, et tes serviteurs auront fait descendre les cheveux blancs de ton serviteur notre père avec douleur dans le sépulcre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Car ton serviteur a répondu du jeune homme en le prenant à mon père; et il a dit: Si je ne te le ramène, je serai coupable envers mon père à tout jamais.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Maintenant donc, que ton serviteur demeure, je te prie, esclave de mon seigneur au lieu du jeune garçon, et que le jeune garçon remonte avec ses frères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Car comment remonterais-je vers mon père, si le jeune garçon n\'est avec moi? Que je ne voie pas la douleur qui atteindrait mon père!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Alors Joseph ne put se contenir devant tous ceux qui étaient présents, et il cria: Faites sortir chacun d\'auprès de moi! Et il ne resta personne avec lui quand Joseph se fit connaître à ses frères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Et il éleva la voix en pleurant, et les Egyptiens l\'entendirent, et la maison de Pharaon l\'entendit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Et Joseph dit à ses frères: Je suis Joseph! Mon père vit-il encore? Et ses frères ne pouvaient lui répondre, car ils étaient troublés de sa présence.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Et Joseph dit à ses frères: Approchez-vous de moi. Et ils s\'approchèrent, et il dit: Je suis Joseph, votre frère, moi que vous avez vendu pour être mené en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Et maintenant, ne vous affligez pas et ne soyez pas fâchés contre vous-mêmes de ce que vous m\'avez vendu pour être amené ici. Car c\'est pour vous conserver la vie que Dieu m\'a envoyé devant vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Car voici deux ans que la famine est dans le pays, et pendant cinq ans encore il n\'y aura ni labour ni moisson.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Et Dieu m\'a envoyé devant vous pour vous conserver un reste sur la terre et pour vous faire subsister comme de nombreux réchappés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Et maintenant ce n\'est pas vous qui m\'avez envoyé ici, c\'est Dieu. Et il m\'a établi comme père pour Pharaon, comme seigneur sur toute sa maison et gouverneur sur tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Hâtez-vous de monter vers mon père, et dites-lui: Ainsi a dit ton fils Joseph: Dieu m\'a établi seigneur sur toute l\'Egypte; descends vers moi, ne tarde pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Tu habiteras dans le pays de Gossen et tu seras près de moi, toi, tes enfants et les enfants de tes enfants, tes brebis et tes bœufs, et tout ce qui est à toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Et je t\'y nourrirai, car il y aura encore cinq ans de famine, afin que tu ne sois pas réduit à rien, toi et ta maison et tout ce qui est à toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Et voici, vous voyez de vos yeux, et Benjamin mon frère voit aussi de ses yeux que c\'est moi-même qui vous parle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Racontez à mon père toute ma gloire en Egypte et tout ce que vous avez vu, et hâtez-vous de faire descendre ici mon père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Et il se jeta au cou de Benjamin, son frère, et pleura; et Benjamin pleura sur, son cou.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Et il embrassa tous ses frères et pleura en les tenant embrassés. Et après cela, ses frères parlèrent avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Et la nouvelle se répandit dans la maison de Pharaon: Les frères de Joseph sont venus. Cela fut agréable à Pharaon et à ses serviteurs;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'et Pharaon dit à Joseph: Dis à tes frères: Faites ceci: Chargez vos bêtes et allez, retournez au pays de Canaan;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'et prenez votre père et vos familles, et venez vers moi: je veux vous donner les bonnes choses du pays d\'Egypte, et vous mangerez de ce que le pays a de meilleur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Et toi, je te charge de leur dire: Faites ceci: Emmenez du pays d\'Egypte des chariots pour vos petits enfants et pour vos femmes, et amenez votre père et venez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Et abandonnez sans regret les objets que vous possédez, car ce qu\'il y a de meilleur dans tout le pays d\'Egypte est à votre disposition.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Les fils d\'Israël firent ainsi. Et Joseph leur donna des chariots, selon l\'ordre de Pharaon, et il leur donna des provisions pour la route.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Il leur donna à chacun une robe de fête, et à Benjamin il donna trois cents pièces d\'argent et cinq robes de fête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Et à son père également il envoya dix ânes chargés des meilleurs produits de l\'Egypte, et dix ânesses chargées de blé, de pain et de vivres pour son père, pour la route.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Il congédia ses frères et ils partirent. Et il leur dit: Ne vous faites pas de reproches en chemin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Et ils montèrent d\'Egypte et vinrent au pays de Canaan vers Jacob, leur père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Et ils lui annoncèrent et lui dirent: Joseph vit encore, et même c\'est lui qui domine sur tout le pays d\'Egypte. Et son cœur se glaça, parce qu\'il ne les crut pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Et ils lui rapportèrent toutes les paroles que Joseph leur avait dites. Et il vit les chariots que Joseph avait envoyés pour le transporter. Et l\'esprit de Jacob, leur père, se ranima;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'et Israël dit: C\'est assez! Joseph, mon fils, vit encore; je veux aller et je le verrai avant que je meure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Et Israël partit avec tout ce qui lui appartenait, et il vint à Béerséba et offrit des sacrifices au Dieu de son père Isaac.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Et Dieu parla à Israël dans des visions de nuit, et il dit: Jacob, Jacob! Et il répondit: Me voici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Et il dit: Je suis le Dieu fort, le Dieu de ton père. Ne crains point de descendre en Egypte, car je t\'y ferai devenir une grande nation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Moi-même je descendrai avec toi en Egypte, et moi-même aussi je t\'en ferai sûrement remonter; et Joseph te fermera les yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Et Jacob partit de Béerséba, et les fils, d\'Israël transportèrent Jacob, leur père, et leurs petits enfants et leurs femmes, sur les chariots que Pharaon avait envoyés pour le transporter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Et ils prirent leur bétail et leurs biens, qu\'ils avaient acquis au pays de Canaan. Et Jacob et toute sa famille avec lui vinrent en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Il amena avec lui en Egypte ses fils et les fils de ses fils, ses filles et les filles de ses fils, et toute sa famille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Et voici les noms des fils d\'Israël venus en Egypte: Jacob et ses fils. Le premier-né de Jacob, Ruben.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Et les fils de Ruben: Hénoc, Pallu, Hetsron et Carmi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Et les fils de Siméon: Jémuel, Jamin, Ohad, Jakin, Tsohar, et Saül, fils de la Cananéenne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Et les fils de Lévi: Guerson, Kéhath et Mérari.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Et les fils de Juda: Er, Onan, Schéla, Pérets et Zérach. Mais Er et Onan moururent au pays de Canaan. Et les fils de Pérets furent Hetsron et Hamul.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Et les fils d\'Issacar: Thola, Puva, Job et Schimron.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Et les fils de Zabulon: Séred, Elon et Jachléel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Ce sont là, avec Dina sa fille, les fils de Léa, qu\'elle enfanta à Jacob en Paddan-Aram. Ses fils et ses filles étaient en tout trente-trois personnes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Et les fils de Gad: Tsiphion et Haggi, Schuni et Etsbon, Eri, Arodi, et Arêli.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Et les fils d\'Asser: Jinina, Jischva, Jischvi, Béria et Sérach leur sœur. Et les fils de Béria: Héber et Malkiel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Ce sont là les fils de Zilpa, que Laban avait donnée à Léa, sa fille; et elle les enfanta à Jacob: seize personnes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Les fils de Rachel, femme de Jacob: Joseph et Benjamin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Et Joseph eut au pays d\'Egypte des fils que lui enfanta Asnath, fille de Potiphéra, sacrificateur d\'On: Manassé et Ephraïm.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Et les fils de Benjamin: Béla, Béker et Aschbel; Guéra et Naaman; Echi et Rosch; Muppim, Huppim et Ard.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Ce sont là les fils, de Rachel, qui naquirent à Jacob; en tout, quatorze personnes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Et les fils de Dan: Huschim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Et les fils de Nephthali: Jachtséel, Guni, Jétser et Schillem.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ce sont là les fils de Bilha, que Laban avait donnée à Rachel, sa fille; et elle les enfanta à Jacob: en tout, sept personnes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Toutes les personnes venues avec Jacob en Egypte, issues de lui, sans compter les femmes des fils de Jacob, toutes ces personnes étaient au nombre de soixante-six.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Et les fils de Joseph, qui lui étaient nés en Egypte, étaient deux. Toutes les personnes de la maison de Jacob, venues en Egypte, étaient soixante-et-dix.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Et Jacob avait envoyé Juda devant lui vers Joseph, afin que celui-ci l\'introduisit dans le pays de Gossen. Et ils arrivèrent au pays de Gossen.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Et Joseph attela son chariot et monta à la rencontre d\'Israël, son père, en Gossen; et il se montra à lui et se jeta à son cou, et il pleura longtemps à son cou.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Et Israël dit à Joseph: Que je meure maintenant, puisque j\'ai vu ton visage, puisque tu vis encore!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Et Joseph dit à ses frères et à la famille de son père: Je monterai pour informer Pharaon, et je lui dirai: Mes frères et la famille de mon père, qui étaient au pays de Canaan, sont venus vers moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Et ces hommes font paître des brebis, car ce sont des propriétaires de bétail, et ils ont amené avec eux leurs brebis et leurs bœufs et tout ce qui est à eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Et quand Pharaon vous fera appeler, il vous dira: Quelle est votre occupation?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Et vous répondrez: Tes serviteurs sont propriétaires de bétail depuis leur jeunesse jusqu\'à ce jour, nous comme nos pères. Afin que vous demeuriez dans le pays de Gossen; car les Egyptiens ont en aversion tous ceux qui paissent des brebis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Et Joseph vint informer Pharaon et lui dit: Mon père et mes frères, avec leurs brebis et leurs bœufs et tout ce qui est à eux, sont venus du pays de Canaan, et voici ils sont dans le pays de Gossen.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Et d\'entre ses frères il prit cinq hommes et les présenta à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Et Pharaon dit à ses frères: Quelle est votre occupation? Et ils dirent à Pharaon: Tes serviteurs sont bergers, nous comme nos pères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Et ils dirent à Pharaon: C\'est pour séjourner dans le pays que nous sommes venus; car il n\'y a plus de pâture pour les troupeaux de tes serviteurs, car la famine s\'est appesantie sur le pays de Canaan. Permets donc à tes serviteurs d\'habiter au pays de Gossen.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Et Pharaon parla ainsi à Joseph: Ton père et tes frères sont venus vers toi;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'le pays d\'Egypte est à ta disposition; fais habiter ton père et tes frères dans la meilleure partie du pays; qu\'ils demeurent dans le pays de Gossen. Et si tu sais qu\'il y ait parmi eux des hommes habiles, tu les établiras sur les troupeaux qui m\'appartiennent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Et Joseph amena Jacob son père, et le présenta à Pharaon. Et Jacob bénit Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Et Pharaon dit à Jacob: Quel est le nombre des années de ta vie?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Et Jacob dit à Pharaon: La durée de ma vie errante a été de cent trente ans. Le temps des années de ma vie a été court et mauvais, et elles n\'ont point atteint les années de la vie errante de mes pères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Et Jacob bénit Pharaon, et il sortit de devant Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Et Joseph établit son père et ses frères, et il leur assigna une propriété au pays d\'Egypte, dans la meilleure partie du pays, dans le pays de Ramsès, comme l\'avait ordonné Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Et Joseph fournit de pain son père, ses frères et toute la famille de son père, selon le nombre des enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Et il n\'y avait point de pain dans tout le pays, car la famine était très grande, et le pays d\'Egypte et le pays de Canaan étaient épuisés par la famine.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Et Joseph amassa tout l\'argent qui se trouvait dans le pays d\'Egypte et dans le pays de Canaan, comme prix du blé qu\'on achetait; et Joseph fit porter cet argent dans la maison de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Et l\'argent manqua au pays d\'Egypte et au pays de Canaan, et tous les Egyptiens vinrent à Joseph en disant: Donne-nous du pain. Pourquoi mourrions-nous devant toi? Car nous sommes à bout d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Et Joseph répondit: Donnez votre bétail, et je vous donnerai du pain en échange de votre bétail, si vous êtes à bout d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Et ils amenèrent leur bétail à Joseph, et Joseph leur donna du pain en échange des chevaux, des troupeaux de brebis, des troupeaux de bœufs et des ânes. Il leur fournit du pain en échange de tous leurs troupeaux cette année-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Quand l\'année fut finie, ils vinrent à lui l\'année suivante, et lui dirent: Nous ne cacherons point à mon seigneur que, maintenant que l\'argent est épuisé et que les troupeaux ont achevé de passer à mon seigneur, il ne reste rien à la disposition de mon seigneur que nos corps et nos terres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Pourquoi péririons-nous sous tes yeux, nous et nos terres? Achète-nous, nous et nos terres, pour du pain, et nous serons, avec nos terres, esclaves de Pharaon. Et donne-nous de quoi semer, afin que nous vivions et ne mourions pas, et que le sol ne devienne pas un désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Et Joseph acquit tout le sol d\'Egypte à Pharaon; car les Egyptiens vendirent chacun son champ, parce que la famine les pressait; et la terre fut à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Et quant aux gens, il les fit passer dans les villes, depuis une extrémité du territoire de l\'Egypte jusqu\'à l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Il n\'y eut que les terres des prêtres qu\'il n\'acquit pas, car les prêtres recevaient de Pharaon une portion fixée, et ils mangeaient la portion que Pharaon leur avait donnée; c\'est pourquoi ils ne vendirent point leurs terres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Et Joseph dit au peuple: Voici, je vous ai acquis aujourd\'hui, vous et vos terres, à Pharaon. Voici pour vous de la semence, afin que vous ensemenciez le sol.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Et au temps des récoltes, vous donnerez le cinquième à Pharaon, et les quatre autres parties seront à vous, pour ensemencer les champs et pour votre nourriture, et pour celle des gens qui sont dans vos maisons, et pour la nourriture de vos petits enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Et ils dirent: Tu nous as sauvé la vie! Que nous trouvions grâce aux yeux de mon seigneur, et nous serons esclaves de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Et Joseph imposa au sol de l\'Egypte une contribution d\'un cinquième pour Pharaon, ce qui existe encore aujourd\'hui. Il n\'y a que les terres des prêtres qui ne soient point à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Et Israël habita au pays d\'Egypte, au pays de Gossen; et ils y eurent des possessions, et ils furent féconds et multiplièrent beaucoup.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Et Jacob vécut au pays d\'Egypte dix-sept ans. Et les jours de Jacob, les années de sa vie furent de cent quarante-sept ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Et quand les jours d\'Israël approchèrent de leur fin, il appela son fils Joseph et lui dit: Si j\'ai trouvé grâce à tes yeux, mets, je te prie, ta main sous ma cuisse, et use envers moi de bonté et de fidélité: ne m\'enterre point en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Quand je serai couché avec mes pères, tu m\'emporteras hors d\'Egypte et tu m\'enterreras dans leur tombeau. Et il dit: Je ferai selon ta parole.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Il dit: Jure-le moi. Et il le lui jura. Et Israël se prosterna sur le chevet du lit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Et il arriva, après ces choses, qu\'on dit à Joseph: Voici, ton père est malade. Et il prit avec lui ses deux fils, Manassé et Ephraïm.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Et on l\'annonça à Jacob, et on lui dit: Voici ton fils Joseph qui vient vers toi. Et Israël rassembla ses forces et s\'assit sur le lit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Et Jacob dit à Joseph: Le Dieu puissant m\'est apparu à Luz, au pays de Canaan, et m\'a béni;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'et il m\'a dit: Voici je te ferai fructifier et multiplier; je te ferai devenir une assemblée de peuples, et je donnerai ce pays à ta postérité après toi, en possession perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Et maintenant, tes deux fils qui te sont nés au pays d\'Egypte, avant que je vinsse vers toi en Egypte, ils seront miens; Ephraïm et Manassé seront miens, comme Ruben et Siméon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mais les enfants que tu as engendrés après eux seront tiens; ils seront rangés sous le nom de leurs frères quant à leur héritage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Et moi, quand je revenais de Paddan, je perdis Rachel, qui mourut au pays de Canaan, en route, lorsqu\'il y avait encore un espace de chemin jusqu\'à Ephrath; et je l\'enterrai là, sur le chemin d\'Ephrath, qui est Bethléem.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Et Israël vit les fils de Joseph, et dit: Qui sont ceux-ci?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Et Joseph dit à son père: Ce sont mes fils, que Dieu m\'a donnés ici. Et il dit: Amène-les moi, je te prie, afin que je les bénisse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Et les yeux d\'Israël étaient appesantis par la vieillesse, et il ne pouvait plus voir. Et il les fit approcher de lui, et il leur donna un baiser et les étreignit dans ses bras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Et Israël dit à Joseph: Je ne pensais plus voir ton visage, et voici Dieu m\'a fait voir aussi ta postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Et Joseph les retira d\'entre les genoux de son père et se prosterna le visage contre terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Et Joseph les prit tous les deux, Ephraïm à sa droite, à la gauche d\'Israël, et Manassé à sa gauche, à la droite d\'Israël, et il les fit approcher de lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Et Israël avança sa main droite et la mit sur la tête d\'Ephraïm, qui était le cadet, et sa main gauche sur la tête de Manassé. Il croisa ses mains, car Manassé était l\'aîné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Et il bénit Joseph, et dit: Que le Dieu devant la face duquel ont marché mes pères Abraham et Isaac, le Dieu qui a été mon berger depuis que je suis jusqu\'à ce jour,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'que l\'ange qui m\'a délivré de tout mal bénisse ces enfants, et qu\'ils soient appelés de mon nom et du nom de mes pères Abraham et Isaac, et qu\'ils multiplient très abondamment sur la terre!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Et Joseph, voyant que son père avait mis sa main droite sur la tête d\'Ephraïm, en eut du déplaisir; et il prit la main de son père pour l\'ôter de dessus la tête d\'Ephraïm et la porter sur celle de Manassé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Et Joseph dit à son père: Pas ainsi, mon père; car celui-ci est l\'aîné; mets ta main droite sur sa tête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Et son père refusa et dit: je le sais, mon fils, je le sais. Lui aussi deviendra un peuple! lui aussi sera grand; mais son frère cadet sera plus grand que lui, et sa postérité sera une multitude de nations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Et en ce jour-là, il les bénit et dit: Qu\'Israël bénisse par toi en disant: Que Dieu te rende tel qu\'Ephraïm et Manassé! Ainsi il mit Ephraïm avant Manassé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Et Israël dit à Joseph: Voici je vais mourir, et Dieu sera avec vous et vous fera retourner au pays de vos pères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Et moi je te donne une portion de plus qu\'à tes frères, que j\'ai prise de la main de l\'Amorrhéen avec mon épée et mon arc.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Et Jacob appela ses fils, et dit: Assemblez-vous, et je vous annoncerai ce qui vous arrivera dans la suite des jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Rassemblez-vous et écoutez, fils de Jacob! Ecoutez Israël, votre père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, tu es mon premier-né, Ma force et les prémices de ma vigueur, Eminent en dignité et éminent en force.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Tu as bouillonné comme l\'eau! Tu n\'auras point la prééminence; Car tu es monté sur la couche de ton père; Tu as profané...! Il est monté sur mon lit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Siméon et Lévi sont frères; Leurs glaives sont des instruments de violence.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Que mon âme n\'entre point dans leur conseil! Que ma gloire ne se joigne point à leur assemblée! Car dans leur colère ils ont tué des hommes; Dans leur caprice ils ont coupé les jarrets des taureaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maudite soit leur colère, car elle a été forte, Et leur fureur, car elle a été implacable! Je les diviserai en Jacob Et je les disperserai en Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Toi, Juda, tes frères te loueront; Ta main sera sur la nuque de tes ennemis; Les fils de ton père se prosterneront devant toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda est un jeune lion. Tu es remonté du carnage, mon fils! Il s\'est accroupi, il s\'est couché comme un lion, Comme une lionne; qui le provoquera?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Le sceptre ne se retirera point de Juda, Ni le bâton du commandement d\'entre ses pieds, Jusqu\'à ce que vienne Schilo, Et c\'est à lui qu\'appartient l\'obéissance des peuples.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Il attache au cep son ânon Et au cep de choix le petit de son ânesse; Il lave son vêtement dans le vin Et dans le sang des raisins son manteau;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Il a les yeux troubles de vin Et les dents blanches de lait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon habitera sur la côte des mers; Il sera sur la côte des navires Et il s\'adossera à Sidon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issacar est un âne osseux Couché entre les barres du bercail.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Il a vu que le repos est bon Et que le pays est agréable, Et il a tendu son épaule pour porter, Et il est devenu homme de corvée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan jugera son peuple Comme toute autre tribu d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Que Dan soit un serpent sur le chemin, Une vipère sur le sentier, Mordant les pâturons du cheval, Et celui qui le monte tombe à la renverse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Je me suis attendu à ton salut, ô Eternel!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, une troupe le presse, Et lui la presse en la poursuivant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'D\'Asser viendra le pain savoureux; Il fournira des mets délicieux de roi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nephthali est une biche lâchée; Il prononce des paroles gracieuses.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Le rameau d\'un arbre fertile, tel est Joseph, Le rameau d\'un arbre fertile au bord d\'une source; Ses branches s\'élancent au-dessus de la muraille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Des archers le provoquent, Lui lancent des flèches et l\'attaquent:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Son arc reste ferme; Ses bras et ses mains sont rendus agiles Par les mains du Puissant de Jacob, Par celui qui est le berger, le rocher d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Que du Dieu fort de ton père (il t\'aidera), Et du Tout-Puissant (il te bénira), [Te viennent] les bénédictions des cieux en haut Et les bénédictions de l\'abîme étendu en bas, Les bénédictions des mamelles et du sein maternel!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Les bénédictions de ton père ont surpassé les bénédictions des montagnes antiques, La beauté des collines éternelles. Qu\'elles soient sur la tête de Joseph, Sur le front du prince de ses frères!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin est un loup qui déchire. Le matin, il dévore la proie, Et sur le soir, il partage le butin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Tous ceux-là sont les douze tribus d\'Israël, et c\'est ainsi que leur parla leur père et qu\'il les bénit; il bénit chacun selon sa bénédiction particulière.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Ensuite il donna ses ordres et leur dit: Je vais être recueilli auprès de mon peuple; enterrez-moi avec mes pères dans la caverne qui est dans le champ d\'Ephron le Héthien,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'dans la caverne du champ de Macpéla, vis-à-vis de Mamré, au pays de Canaan, la caverne qu\'Abraham a acquise d\'Ephron le Héthien, avec le champ, comme un sépulcre qui lui appartint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'C\'est là qu\'on a enterré Abraham et Sara, sa femme; c\'est là qu\'on a enterré, Isaac et Rébecca, sa femme;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'et c\'est là que j\'ai enterré Léa. Le champ et la caverne qui s\'y trouve ont été acquis des fils de Heth.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Et quand Jacob eut achevé de donner ses ordres à ses fils, il retira ses pieds dans le lit et expira, et fut recueilli vers les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Et Joseph se jeta sur le visage de son père et pleura sur lui et l\'embrassa.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Et Joseph commanda aux médecins qui étaient à son service d\'embaumer son père; et les médecins embaumèrent Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Et ils y employèrent quarante jours, car c\'est le temps que l\'on met à embaumer. Et les Egyptiens le pleurèrent soixante et dix jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Quand les jours de son deuil furent passés, Joseph parla aux gens de la maison de Pharaon en disant: Si j\'ai trouvé grâce à vos yeux, faites entendre, je vous prie, à Pharaon ces paroles:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mon père m\'a fait jurer en disant: Voici je vais mourir; tu m\'enterreras dans mon sépulcre, que je me suis creusé au pays de Canaan. Maintenant donc, que j\'y monte, je te prie, et que j\'enterre là mon père, et je reviendrai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Et Pharaon répondit: Monte et enterre ton père, comme il te l\'a fait jurer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Et Joseph monta pour enterrer son père; et avec lui montèrent tous les serviteurs de Pharaon, les Anciens de sa maison, et tous les Anciens du pays d\'Egypte,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'et toute la maison de Joseph, ses frères et la maison de son père. Il n\'y eut que leurs petits enfants, leurs brebis et leurs bœufs qu\'ils laissèrent dans le pays de Gossen.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Avec lui montèrent aussi des chars et des cavaliers; c\'était une caravane très nombreuse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Ils vinrent jusqu\'à l\'aire d\'Atad, qui est au-delà du Jourdain, et ils y célébrèrent des cérémonies funèbres grandes et solennelles, et Joseph fit à son père un deuil de sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Les Cananéens, habitants du pays, voyant ce deuil dans l\'aire d\'Atad, dirent: Voilà un grand deuil chez les Egyptiens. C\'est pourquoi on a nommé cet endroit Abel-Mitsraïm; il est au-delà du Jourdain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Les fils de Jacob firent donc à son égard comme il leur avait commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Ses fils le transportèrent au pays de Canaan et l\'enterrèrent dans la caverne du champ de Macpéla qu\'Abraham avait acquise, avec le champ, d\'Ephron le Héthien, comme un sépulcre qui lui appartint, vis-à-vis de Mamré.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Et après qu\'il eut enterré son père, Joseph s\'en retourna en Egypte, lui et ses frères, et tous ceux qui étaient montés avec lui pour enterrer son père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Et les frères de Joseph, voyant que leur père était mort, dirent: Peut-être que Joseph se tournera contre nous et nous rendra tout le mal que nous lui avons fait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Et ils firent dire à Joseph: Ton père a donné cet ordre avant de mourir:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Vous parlerez ainsi à Joseph: Oh! veuille pardonner, je te prie, le crime de tes frères et leur péché; car ils t\'ont fait du mal; mais maintenant, pardonne, je te prie, le crime des serviteurs du Dieu de ton père. Et Joseph pleura quand ils lui parlèrent ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Et ses frères vinrent eux-mêmes et se jetèrent à ses pieds, et dirent: Voici, nous sommes tes serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Et Joseph leur dit: Ne craignez point, car suis-je à la place de Dieu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ce que vous avez pensé en mal contre moi, Dieu l\'a pensé en bien, afin de faire ce qui arrive aujourd\'hui, de conserver la vie à un peuple nombreux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Et maintenant, soyez sans crainte: je vous entretiendrai, vous et vos enfants. Et il les consola et parla à leur cœur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Joseph demeura en Egypte, lui et la maison de son père, et Joseph vécut cent dix ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Il vit les fils d\'Ephraïm jusqu\'à la troisième génération; des fils de Makir, fils de Manassé, naquirent aussi sur ses genoux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Et Joseph dit à ses frères: Pour moi, je vais mourir; mais Dieu vous visitera certainement et vous fera remonter de ce pays au pays qu\'il a promis par serment à Abraham, à Isaac et à Jacob.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Et Joseph fit jurer les fils d\'Israël en disant: Certainement Dieu vous visitera, et vous transporterez mes os d\'ici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Et Joseph mourut âgé de cent dix ans; et on l\'embauma, et on le mit dans un cercueil en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Et ce sont ici les noms des fils d\'Israël venus en Egypte. Ils y entrèrent avec Jacob, chacun d\'eux avec sa famille:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Siméon, Lévi et Juda;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issacar, Zabulon et Benjamin;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan et Nephthali, Gad et Asser.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Toutes les personnes issues de Jacob étaient au nombre de soixante-dix, et Joseph était déjà en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Et Joseph mourut, ainsi que tous ses frères et toute cette génération-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Et les fils d\'Israël s\'étaient accrus; ils multiplièrent et devinrent nombreux et extrêmement forts, et le pays en fut rempli.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Et il s\'éleva sur l\'Egypte un nouveau roi qui n\'avait point connu Joseph,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'et il dit à son peuple: Voilà que le peuple des fils d\'Israël est trop nombreux et trop fort pour nous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Voyons! prenons des précautions contre lui, de peur qu\'il ne s\'augmente et que, lorsque viendra une guerre, il ne se joigne, lui aussi, à ceux qui nous veulent du mal, et qu\'il ne combatte contre nous et ne sorte du pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Alors on établit sur Israël des chefs de corvée pour l\'écraser par leurs réquisitions, et il bâtit pour Pharaon des villes de greniers, Pithom et Ramsès.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mais plus on l\'opprimait, plus il devenait nombreux et s\'étendait. Et les fils d\'Israël devinrent odieux aux Egyptiens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Alors les Egyptiens firent travailler les fils d\'Israël par force;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'ils leur rendirent la vie amère par des travaux pénibles, mortier, briques et travaux de campagne de toute sorte; tout le travail qu\'on tirait d\'eux était travail forcé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Et le roi d\'Egypte parla aux sages-femmes des Hébreues; le nom de l\'une était Siphra et le nom de l\'autre Pua;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'et il leur dit: Quand vous accoucherez les femmes des Hébreux et que vous les verrez sur les sièges, si c\'est un fils, vous le ferez mourir; si c\'est une fille, elle peut vivre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mais les sages-femmes craignirent Dieu: elles ne firent point comme leur avait dit le roi d\'Egypte, mais laissèrent vivre les garçons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Et le roi d\'Egypte fit appeler les sages-femmes et leur dit: Pourquoi avez-vous agi de la sorte et laissé vivre les garçons?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Et les sages-femmes dirent à Pharaon: C\'est que les femmes des Hébreux ne sont pas comme les Egyptiennes. Elles sont vigoureuses; avant que leur arrive la sage-femme, elles sont accouchées!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Et Dieu fit du bien aux sages-femmes, et le peuple devint nombreux et extrêmement fort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Alors, comme les sages-femmes avaient craint Dieu et que Dieu avait accru les familles des Israélites,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Pharaon donna cet ordre à tout son peuple: Tous les fils qui naîtront, jetez-les dans le fleuve; mais toutes les filles, laissez-les vivre!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Et un homme de la maison de Lévi alla prendre pour femme une fille de Lévi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Et cette femme conçut et enfanta un fils, et elle vit qu\'il était beau et le cacha trois mois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Quand elle ne put plus le tenir caché, elle prit une arche en roseau, l\'enduisit de bitume et de poix et y mit le petit garçon. Puis elle mit l\'arche dans les joncs sur la rive du fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Et la sœur de l\'enfant se tenait à distance pour savoir ce qui lui arriverait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Or la fille de Pharaon vint faire ses ablutions sur le bord du fleuve et ses femmes marchaient le long du fleuve. Elle vit l\'arche au milieu des joncs et envoya sa servante pour le prendre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Et elle l\'ouvrit et vit l\'enfant: c\'était un petit garçon qui pleurait. Et elle eut pitié de lui et dit: C\'est un des enfants des Hébreux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Et la sœur de l\'enfant dit à la fille de Pharaon: Dois-je aller te chercher une nourrice d\'entre les femmes des Hébreux pour qu\'elle t\'allaite ce petit garçon?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Et la fille de Pharaon lui dit: Va. Et la jeune fille alla chercher la mère de l\'enfant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Et la fille de Pharaon lui dit: Emporte cet enfant-là et allaite-le moi; c\'est moi qui te donnerai ton salaire. Et la femme prit l\'enfant et l\'allaita.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Quand l\'enfant eut grandi, elle l\'amena à la fille de Pharaon et il devint son fils, et elle lui donna le nom de Moïse. Car, dit-elle, je l\'ai tiré de l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Et il arriva, en ce temps-là, que Moïse, étant devenu grand, sortit pour aller vers ses frères et vit leur lourd travail, et il vit un Egyptien frapper un Hébreu, un de ses frères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Alors, s\'étant tourné de côté et d\'autre et voyant qu\'il n\'y avait personne, il tua l\'Egyptien et le cacha dans le sable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Il sortit encore le lendemain et, voyant deux Hébreux qui se battaient, il dit à celui qui avait tort: Pourquoi frappes-tu ton camarade?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Mais celui-ci lui dit: Qui t\'a établi pour être notre chef et notre juge? Est-ce que tu veux me tuer, comme tu as tué l\'Egyptien? Alors Moïse eut peur et dit: Certainement l\'affaire s\'est ébruitée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Et Pharaon apprit cette affaire et chercha à faire mourir Moïse, et Moïse s\'enfuit loin de Pharaon. Il s\'arrêta dans la terre de Madian et s\'assit près du puits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Or le sacrificateur de Madian avait sept filles, et elles vinrent puiser de l\'eau et remplirent les auges pour abreuver les brebis de leur père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mais les bergers étant venus les chasser, Moïse se leva, prit leur défense et abreuva leurs brebis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Quand elles retournèrent vers Réuël leur père, celui-ci leur dit: Pourquoi revenez-vous si tôt aujourd\'hui?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Et elles dirent: C\'est qu\'un homme égyptien nous a débarrassées des bergers et que même il a puisé pour nous toute l\'eau qu\'il fallait et a abreuvé les brebis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Alors il dit à ses filles: Et où est-il? Pourquoi avez-vous laissé là cet homme? Appelez-le et qu\'il mange du pain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Et Moïse consentit à demeurer avec cet homme. Et celui-ci donna à Moïse sa fille Séphora,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'et elle enfanta un fils auquel il donna le nom de Guersom, parce que, dit-il, j\'ai été habitant d\'une terre étrangère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Dans ce temps, qui fut long, il arriva que le roi d\'Egypte mourut, et les fils d\'Israël gémirent de leur servitude et crièrent, et leur appel monta à Dieu du sein de la servitude.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Et Dieu entendit leur sanglot et Dieu se souvint de son alliance avec Abraham, avec Isaac et avec Jacob,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'et Dieu vit les fils d\'Israël et Dieu connut leur état.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Or Moïse était berger des brebis de Jéthro, son beau-père, sacrificateur de Madian, et il conduisit le troupeau au-delà du désert et arriva à la montagne de Dieu, à Horeb.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Et l\'ange de l\'Eternel lui apparut en flamme de feu du milieu des buissons et Moïse s\'aperçut que le buisson était en feu et que le buisson ne se consumait point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Et Moïse dit: Je veux faire un détour pour voir ce grand phénomène, comment il se fait que le buisson ne brûle pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Et l\'Eternel vit que Moïse s\'était détourné pour regarder et Dieu l\'appela du milieu des buissons et dit: Moïse, Moïse! Et il dit: Me voici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Et Dieu dit: N\'approche point d\'ici, ôte tes sandales de tes pieds, car le lieu où tu es est une terre sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Puis il dit: Je suis le Dieu de ton père, le Dieu d\'Abraham, le Dieu d\'Isaac et le Dieu de Jacob. Et Moïse cacha sa face parce qu\'il craignait de regarder Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Et l\'Eternel dit: J\'ai fort bien vu l\'affliction de mon peuple qui est en Egypte et j\'ai entendu le cri que lui font pousser ses exacteurs, car je connais ses peines,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'et je suis descendu pour l\'arracher à la puissance de l\'Egypte et pour le faire monter de ce pays-là dans une terre fertile et spacieuse, dans une terre découlant de lait et de miel, au lieu où se trouvent le Cananéen, le Héthien, l\'Amorrhéen, le Phérézien, le Hévien et le Jébusien.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Et maintenant, voici, le cri des fils d\'Israël est arrivé à moi et j\'ai vu en effet l\'oppression que les Egyptiens font peser sur eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Va donc maintenant: je t\'envoie vers Pharaon, et fais sortir d\'Egypte mon peuple, les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Et Moïse dit à Dieu: Qui suis-je pour aller vers Pharaon et pour faire sortir d\'Egypte les fils d\'Israël?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Et Dieu dit: C\'est que je serai avec toi. Et ceci sera pour toi le signe que c\'est moi qui t\'ai envoyé: quand tu auras fait sortir le peuple hors d\'Egypte, vous servirez Dieu sur cette montagne-ci.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Et Moïse dit à Dieu: Si je vais vers les fils d\'Israël et que je leur dise: Le Dieu de vos pères m\'a envoyé vers vous, et qu\'ils me disent: Quel est son nom? que leur dirai-je?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Et Dieu dit à Moïse: Je suis Celui qui suis. Puis il dit: Tu parleras ainsi aux fils d\'Israël: JE SUIS m\'a envoyé vers vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Et Dieu dit encore à Moïse: Tu parleras ainsi aux fils d\'Israël: L\'Eternel, Dieu de vos pères, Dieu d\'Abraham, Dieu d\'Isaac et Dieu de Jacob, m\'a envoyé vers vous. C\'est là mon nom pour toujours, c\'est là mon titre d\'âge en âge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Va, réunis les Anciens d\'Israël et dis-leur: L\'Eternel, Dieu de vos pères, m\'est apparu, le Dieu d\'Abraham, d\'Isaac et de Jacob, et il a dit: Je vous ai visités et j\'ai vu ce qu\'on vous fait en Egypte,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'et j\'ai résolu de vous tirer de l\'affliction dont vous souffrez en Egypte pour vous faire monter dans le pays du Cananéen, du Héthien, de l\'Amorrhéen, du Phérézien, du Hévien et du Jébusien, dans un pays découlant de lait et de miel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Et ils écouteront ta voix et tu iras, toi et les Anciens d\'Israël, vers le roi d\'Egypte et vous lui direz: L\'Eternel, Dieu des Hébreux, est venu à nous, et maintenant nous voudrions aller à trois journées de marche dans le désert pour offrir un sacrifice à l\'Eternel notre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Et moi je sais que le roi d\'Egypte ne vous permettra pas d\'aller, pas même si vous employiez la force.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Mais j\'étendrai ma main et je frapperai l\'Egypte par tous mes prodiges que je ferai au milieu d\'elle. Après cela, il vous renverra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Et je ferai trouver grâce à ce peuple aux yeux des Egyptiens, et il arrivera que, quand vous partirez, vous ne partirez point les mains vides.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Mais chaque femme demandera à sa voisine et à celle qui habitera chez elle des objets d\'argent, des objets d\'or et des habits, et vous les mettrez sur vos fils et sur vos filles, et ainsi vous emporterez les dépouilles de l\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Et Moïse répondit: Mais s\'ils ne me croient pas et n\'obéissent pas à ma voix parce qu\'ils diront: L\'Eternel ne t\'est point apparu?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Et l\'Eternel lui dit: Qu\'as-tu là à la main? Il dit: Un bâton.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Et l\'Eternel dit: Jette-le à terre. Et il le jeta à terre, et ce bâton devint un serpent, et Moïse s\'enfuit devant lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Et l\'Eternel dit à Moïse: Etends la main et saisis-le par la queue (et Moïse étendit la main et le saisit, et dans sa main le serpent redevint bâton),');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'afin qu\'ils croient que l\'Eternel, Dieu de leurs pères, Dieu d\'Abraham, Dieu d\'Isaac et Dieu de Jacob, t\'est apparu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Et l\'Eternel lui dit encore: Mets ta main dans ton sein. Et il mit la main dans son sein, puis l\'en sortit, et voici, sa main était couverte de lèpre, blanche comme la neige.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Et Dieu dit: Remets ta main dans ton sein (et il remit la main dans son sein, puis la sortit de son sein, et voici elle était redevenue semblable à sa chair).');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Ainsi, s\'ils ne te croient pas et s\'ils n\'écoutent pas la voix du premier signe, ils croiront à la voix du second;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'et s\'ils ne croient pas même à ces deux signes-là et n\'écoutent pas ta voix, alors tu prendras de l\'eau du fleuve et tu la répandras sur le sol, et l\'eau que tu auras prise du fleuve deviendra du sang sur le sol.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Et Moïse dit à l\'Eternel: Ah! Seigneur, je ne suis pas un homme qui ait la parole facile; il y a longtemps que je ne le suis pas, et je ne le suis pas non plus depuis que tu parles à ton serviteur, mais j\'ai la bouche pesante et la langue pesante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Et l\'Eternel lui dit: Qui a donné la bouche à l\'homme, ou qui est-ce qui rend muet ou sourd ou voyant ou aveugle? N\'est-ce pas moi, l\'Eternel?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Et maintenant va, et moi, je serai avec ta bouche et je t\'enseignerai ce que tu devras dire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Et Moïse dit: Ah! Seigneur! Envoie ton message par qui tu voudras l\'envoyer!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Alors la colère de l\'Eternel s\'enflamma contre Moïse et il dit: Et Aaron, ton frère, le Lévite? Ne sais-je pas qu\'il parle très bien, lui? Et même, il va venir à ta rencontre; il te verra et se réjouira dans son cœur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Et tu lui parleras et tu mettras dans sa bouche ce qu\'il devra dire, et moi je serai avec ta bouche et avec sa bouche, et je vous montrerai ce que vous aurez à faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Et c\'est lui qui parlera pour toi au peuple; il te servira de bouche et tu lui seras dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Et tu prendras en main ce bâton-là avec lequel tu feras les prodiges.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Et Moïse s\'en alla et retourna vers Jéthro son beau-père et lui dit: Je voudrais partir et retourner vers mes frères qui sont en Egypte pour voir s\'ils sont encore en vie. Et Jéthro dit à Moïse: Va en paix.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Et l\'Eternel dit à Moïse en Madian: Va, retourne en Egypte, car tous les hommes qui en voulaient à ta vie sont morts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Alors Moïse prit sa femme et ses fils et les fit monter sur l\'âne et retourner au pays d\'Egypte. Et Moïse prit en main le bâton de Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Et l\'Eternel dit à Moïse: En t\'en retournant en Egypte, considère tous les prodiges que j\'ai mis en ta main: tu les feras devant Pharaon, et moi, j\'endurcirai son cœur, et il ne laissera pas aller le peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Et tu diras à Pharaon: Ainsi a dit l\'Eternel: Israël est mon fils, mon premier-né,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'et je t\'ai dit: Laisse aller mon fils pour qu\'il me serve; et tu as refusé de le laisser aller. Je vais tuer ton fils, ton premier-né.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Et il arriva qu\'en route, à l\'endroit où ils passaient la nuit, l\'Eternel vint à Moïse et chercha à le faire mourir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Alors Séphora prit une pierre tranchante et coupa le prépuce de son fils et en toucha les pieds de Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Et elle dit: Tu es pour moi un époux de sang. Et il le laissa; c\'est alors qu\'elle dit: Epoux de sang! en parlant des circoncisions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Et l\'Eternel dit à Aaron: Va au-devant de Moïse dans le désert. Et il alla et le rencontra à la montagne de Dieu et il l\'embrassa.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Et Moïse fit connaître à Aaron toutes les paroles que l\'Eternel l\'avait chargé de dire et tous les prodiges qu\'il lui avait ordonné de faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Et Moïse alla avec Aaron et ils assemblèrent tous les Anciens des fils d\'Israël,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'et Aaron dit toutes les paroles que l\'Eternel avait dites à Moïse et il fit les prodiges aux yeux du peuple,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'et le peuple crut. Et ils apprirent que l\'Eternel avait visité les fils d\'Israël et qu\'il avait vu leur affliction, et ils s\'inclinèrent et se prosternèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Après cela, Moïse et Aaron étant venus vers Pharaon lui dirent: Ainsi a dit l\'Eternel, Dieu d\'Israël: Laisse aller mon peuple pour qu\'il célèbre une fête en mon honneur dans le désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Et Pharaon dit: Qui est l\'Eternel, que j\'obéisse à sa voix en laissant aller Israël? Je ne connais pas l\'Eternel, aussi ne laisserai-je pas aller Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Et ils dirent: Le Dieu des Hébreux s\'est manifesté à nous. Nous voudrions aller à trois journées de marche dans le désert pour sacrifier à l\'Eternel notre Dieu, de peur qu\'il ne nous frappe par la peste ou par l\'épée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Et le roi d\'Egypte leur dit: Pourquoi, Moïse et Aaron, faites-vous quitter au peuple son ouvrage? Allez à vos corvées!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Et Pharaon dit: Voici le bas peuple est maintenant nombreux et vous lui faites cesser ses corvées!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Et en ce jour-là Pharaon donna aux exacteurs du peuple et à ses contremaîtres l\'ordre suivant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Vous ne donnerez plus de paille aux gens pour faire les briques, comme on l\'a fait jusqu\'ici; ils iront eux-mêmes ramasser la paille qu\'il leur faut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Mais vous leur imposerez la tâche de briques qu\'ils ont toujours faite; vous n\'en retrancherez rien, car ce sont des paresseux; c\'est pourquoi ils crient: Nous voudrions aller faire un sacrifice à notre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Que les gens soient chargés d\'ouvrage et s\'y occupent, et qu\'ils ne fassent plus attention aux mensonges qu\'on leur dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Et les exacteurs du peuple et ses contremaîtres allèrent parler ainsi au peuple: Ainsi a dit Pharaon: Je ne vous donne plus de paille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Allez donc vous-mêmes prendre de la paille où vous en trouverez, car rien ne sera retranché de votre tâche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Et le peuple se répandit dans tout le pays d\'Egypte afin de ramasser du chaume pour en faire de la paille hachée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Et les exacteurs les pressaient disant: Faites tout votre ouvrage, jour par jour, comme quand on avait la paille!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Et l\'on battit les contremaîtres des fils d\'Israël, qu\'avaient établis sur eux les exacteurs de Pharaon, en leur disant: Pourquoi n\'avez-vous pas fait ces jours-ci toute votre tâche de briques comme précédemment?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Et les contremaîtres des fils d\'Israël allèrent réclamer à Pharaon et lui dirent: Pourquoi traiterais-tu ainsi tes serviteurs?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'On ne fournit pas de paille à tes serviteurs et on nous dit: Faites des briques! Et comme cela tes serviteurs sont battus et ton peuple se trouve en faute!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Et Pharaon dit: Vous êtes des paresseux, des paresseux! c\'est pourquoi vous dites: Nous voudrions aller faire un sacrifice à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Et maintenant allez travailler, on ne vous donnera pas de paille et vous ferez votre tâche de briques.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Et les contremaîtres des fils d\'Israël se virent dans une position fâcheuse, puisqu\'on leur disait: Vous ne retrancherez rien de vos briques; à chaque jour sa tâche!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Ils trouvèrent Moïse et Aaron qui se tenaient là pour les attendre quand ils sortiraient de chez Pharaon,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'et ils leur dirent: Que l\'Eternel vous voie et qu\'il juge, vous qui nous avez mis en mauvaise odeur auprès de Pharaon et auprès de ses serviteurs et qui leur avez mis l\'épée à la main pour nous tuer!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Alors Moïse retourna vers l\'Eternel et dit: Seigneur! Pourquoi as-tu fait du mal à ce peuple? Pourquoi donc m\'as-tu envoyé?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Depuis que je me suis présenté à Pharaon pour lui parler en ton nom, il a fait du mal à ce peuple et tu n\'as pas du tout délivré ton peuple!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Et l\'Eternel dit à Moïse: Maintenant tu verras ce que je ferai à Pharaon! Contraint par une main forte il les laissera aller. Contraint par une main forte il les chassera de son pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Et Dieu parla à Moïse et lui dit: Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Je suis apparu à Abraham, à Isaac et à Jacob comme Dieu puissant, mais sous mon nom d\'ETERNEL je ne me suis pas fait connaître à eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Non seulement j\'ai établi mon alliance avec eux pour leur donner le pays de Canaan, le pays où ils ont séjourné en étrangers,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'mais encore j\'ai entendu le gémissement des fils d\'Israël que les Egyptiens asservissent, et je me suis souvenu de mon alliance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'C\'est pourquoi dis aux fils d\'Israël: Je suis l\'Eternel, et je vous soustrairai aux corvées des Egyptiens et vous tirerai de leur service, et je vous libérerai à bras étendu et par de grands jugements.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Et je vous prendrai pour mon peuple, et je vous serai Dieu et vous saurez que je suis l\'Eternel votre Dieu qui vous soustrais aux corvées des Egyptiens;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'et je vous ferai entrer dans le pays que j\'ai juré de donner à Abraham, à Isaac et à Jacob, et je vous le donnerai en possession. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Et Moïse parla ainsi aux fils d\'Israël, et ils n\'écoutèrent pas Moïse parce qu\'ils avaient perdu patience et que leur service était dur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Va parler à Pharaon, roi d\'Egypte, pour qu\'il laisse partir de son pays les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Et Moïse parla devant l\'Eternel et dit: Si les fils d\'Israël ne m\'ont pas écouté, comment Pharaon m\'écoutera-t-il, moi qui suis incirconcis de lèvres!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'L\'Eternel parla à Moïse et à Aaron et les envoya aux fils d\'Israël et à Pharaon, roi d\'Egypte, avec l\'ordre de tirer les fils d\'Israël hors du pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ce sont ici leurs patriarches: Fils de Ruben, premier-né d\'Israël: Hénoc et Pallu, Hetsron et Carmi. Telles sont les branches de la tribu de Ruben.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Fils de Siméon: Jémuel, Jamin, Ohad, Jakin, Tsohar et Saül, fils de la Cananéenne. Telles sont les branches de la tribu de Siméon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Et ce sont ici les noms des fils de Lévi, avec leurs postérités: Guersom, Kéhath et Mérari. Et la vie de Lévi fut de cent trente-sept ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Fils de Guersom: Libni et Siméi, avec leurs diverses branches.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Fils de Kéhath: Amram, Jitsébar, Hébron et Uzziel. Et la vie de Kéhath fut de cent trente-trois ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Fils de Mérari: Machli et Muschi. Telles sont les branches de la tribu de Lévi, avec leurs postérités.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Et Amram prit pour femme Jokébed, sa tante, et elle lui enfanta Aaron et Moïse. Et la vie d\'Amram fut de cent trente-sept ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Fils de Jitsébar: Koré, Népheg et Zicri.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Fils d\'Uzziel: Misaël, Eltsaphan et Sitri.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Et Aaron prit pour femme Eliséba, fille d\'Amminadab et sœur de Nahason, et elle lui enfanta Nadab, Abihu, Eléazar et Ithamar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Fils de Koré: Assir, Elkana, Abiasaph. Telles sont les branches, des Koréites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Et Eléazar, fils d\'Aaron, prit pour femme une des filles de Putiel, et elle lui enfanta Phinées. Tels sont les patriarches des Lévites dans leurs différentes branches.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Ce sont là l\'Aaron et le Moïse auxquels l\'Eternel dit: Faites sortir du pays d\'Egypte les fils d\'Israël, selon leurs armées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ce sont ceux qui parlèrent à Pharaon, roi d\'Egypte, pour tirer d\'Egypte les fils d\'Israël. C\'est ce Moïse-là et cet Aaron-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Et il arriva, le jour où l\'Eternel parla à Moïse au pays d\'Egypte,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'que l\'Eternel parla à Moïse disant: Je suis l\'Eternel. Dis à Pharaon, roi d\'Egypte, tout ce que je te dis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Et Moïse dit en présence de l\'Eternel: Voici, je suis incirconcis de lèvres; comment Pharaon m\'écoutera-t-il?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Et l\'Eternel dit à Moïse: Vois, j\'ai fait de toi un dieu pour Pharaon, et Aaron ton frère sera ton prophète.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Toi, tu diras tout ce dont je te chargerai, et Aaron ton frère parlera à Pharaon pour qu\'il laisse sortir de son pays les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Et moi, j\'endurcirai le cœur de Pharaon et je multiplierai mes signes et mes miracles dans le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Et Pharaon ne vous écoutera pas, et je mettrai ma main sur l\'Egypte et je ferai sortir du pays d\'Egypte par de grands jugements mes armées, mon peuple, les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Et les Egyptiens sauront que je suis l\'Eternel, quand j\'étendrai ma main sur l\'Egypte et que je ferai sortir les fils d\'Israël du milieu d\'eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Ainsi firent Moïse et Aaron. Ils firent tout ce que l\'Eternel leur avait commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Or Moïse avait quatre-vingts ans et Aaron quatre-vingt-trois, lorsqu\'ils parlèrent à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Et l\'Eternel dit à Moïse et à Aaron:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Quand Pharaon vous dira: Faites un miracle, tu diras à Aaron: Prends ton bâton et jette-le devant Pharaon; qu\'il devienne un serpent!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Et Moïse et Aaron se rendirent vers Pharaon et firent selon que l\'Eternel l\'avait ordonné. Aaron jeta son bâton devant Pharaon et devant ses serviteurs, et il devint un dragon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Et Pharaon aussi appela ses sages et ses magiciens, et eux aussi, les enchanteurs d\'Egypte, firent la même chose par leurs arts occultes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'ils jetèrent chacun son bâton et ces bâtons devinrent des dragons. Et le bâton d\'Aaron engloutit leurs bâtons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Et le cœur de Pharaon s\'endurcit, et il ne les écouta pas, selon que l\'Eternel l\'avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Et l\'Eternel dit à Moïse: Le cœur de Pharaon est appesanti. Il a refusé de laisser aller le peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Va vers Pharaon demain matin. Il sortira pour aller au bord de l\'eau et tu te tiendras, pour l\'attendre, sur le bord du fleuve. Tu prendras en main le bâton qui a été changé en serpent');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'et tu lui diras: L\'Eternel, Dieu des Hébreux, m\'a envoyé vers toi pour te dire: Laisse aller mon peuple afin qu\'il me serve dans le désert. Et voici, tu n\'as jusqu\'à présent pas obéi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Ainsi a dit l\'Eternel: A ceci tu connaîtras que je suis l\'Eternel: je vais frapper, du bâton que j\'ai à la main, les eaux qui sont dans le fleuve et elles se changeront en sang,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'et le poisson qui est dans le fleuve périra et le fleuve deviendra infect et les Egyptiens répugneront à boire de l\'eau du fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Et l\'Eternel dit à Moïse: Dis à Aaron: Prends ton bâton et étends la main sur l\'eau de l\'Egypte, sur ses fleuves, sur ses canaux, sur ses étangs et sur tous ses réservoirs, et elle sera du sang, et il y aura du sang dans tout le pays d\'Egypte jusque dans les vases de bois et de pierre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Et Moïse et Aaron firent comme l\'Eternel l\'avait commandé: Aaron leva le bâton et frappa l\'eau qui était dans le fleuve, aux yeux de Pharaon et aux yeux de ses serviteurs, et toute l\'eau qui était dans le fleuve se changea en sang,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'et les poissons qui étaient dans le fleuve périrent et le fleuve devint infect et les Egyptiens ne purent boire de l\'eau du fleuve, et il y eut du sang dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Et les enchanteurs d\'Egypte firent la même chose par leurs arts occultes. Et le cœur de Pharaon s\'endurcit, et il ne les écouta pas, selon que l\'Eternel l\'avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Et Pharaon se détourna et entra en sa maison et ne fit point attention même à cela.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Et tous les Egyptiens creusèrent aux environs du fleuve pour trouver de l\'eau potable puisqu\'ils ne pouvaient boire de l\'eau du fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Et il s\'écoula sept jours après que l\'Eternel eut frappé le fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Et l\'Eternel dit à Moïse: Rends-toi vers Pharaon et dis-lui: Ainsi a dit l\'Eternel: Laisse aller mon peuple, et qu\'il me serve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Et si tu refuses de le laisser aller, je vais frapper tout ton territoire du fléau des grenouilles:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'le fleuve pullulera de grenouilles, elles monteront et entreront dans ta maison, dans ta chambre à coucher, sur ton lit, et dans la maison de tes serviteurs et au milieu de ton peuple, dans tes fours et dans tes pétrins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Les grenouilles monteront sur toi, sur ton peuple et sur tous tes serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Et l\'Eternel dit à Moïse: Dis à Aaron: Etends ta main et ton bâton sur les fleuves, sur les canaux et sur les étangs, et fais monter les grenouilles sur le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Et Aaron étendit sa main sur l\'eau d\'Egypte, et les grenouilles montèrent et couvrirent le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Et les enchanteurs firent la même chose par leurs arts, occultes: ils firent monter les grenouilles sur le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Et Pharaon appela Moïse et Aaron et leur dit: Faites des prières à l\'Eternel pour qu\'il éloigne les grenouilles de moi et de mon peuple, et je laisserai aller le peuple pour qu\'il sacrifie à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Et Moïse dit à Pharaon: Donne-moi tes ordres! Pour quand ferai-je des prières en faveur de toi, de tes serviteurs et de ton peuple, pour que l\'Eternel éloigne les grenouilles de toi et de tes maisons? Il n\'en restera que dans le fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Et Pharaon dit: Pour demain. Moïse dit: Il en sera comme tu le demandes, afin que tu saches que nul n\'est pareil à l\'Eternel notre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Les grenouilles se retireront de toi, de tes maisons, de tes serviteurs et de ton peuple; il n\'en restera que dans le fleuve.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Et Moïse et Aaron sortirent d\'auprès de Pharaon. Et Moïse cria à l\'Eternel au sujet des grenouilles qu\'il avait infligées à Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Et l\'Eternel fit ce que Moïse demandait: les grenouilles périrent dans les maisons, dans les cours et dans les champs,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'et on les enfouit par grandes masses et le pays en fut infecté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Et Pharaon, se voyant tranquille, appesantit son cœur et ne les écouta pas, selon que l\'Eternel l\'avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Et l\'Eternel dit à Moïse: Dis à Aaron: Etends ton bâton et frappe la poussière de la terre, et elle deviendra des moustiques dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Et ils firent ainsi; Aaron étendit sa main et son bâton et frappa la poussière de la terre, et les moustiques furent sur les hommes et sur le bétail: toute la poussière de la terre était moustiques dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Et les enchanteurs firent la même chose par leurs arts occultes, en vue de produire les moustiques, et ils ne le purent pas. Les moustiques furent sur les hommes et sur le bétail.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Et les enchanteurs dirent à Pharaon: C\'est le doigt d\'un dieu! Et le cœur de Pharaon s\'endurcit, et il ne les écouta pas, selon que l\'Eternel l\'avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Et l\'Eternel dit à Moïse: Va de bon matin te placer devant Pharaon, au moment où il sort pour aller au bord de l\'eau, et dis lui: Ainsi a dit l\'Eternel: Laisse aller mon peuple, et qu\'il me serve!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Car, si tu ne laisses pas aller mon peuple, je vais envoyer les scarabées sur toi, sur tes serviteurs, sur ton peuple et sur tes maisons; les scarabées rempliront les maisons des Egyptiens et le pays où ils sont,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'et je distinguerai en ce jour-là la terre de Gossen où habite mon peuple en ce qu\'il n\'y aura point là de scarabées, afin que tu saches que moi l\'Eternel je suis au milieu du pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ainsi je ferai une exemption qui distinguera mon peuple et ton peuple. C\'est demain que ce signe aura lieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Et l\'Eternel fit ainsi. Il vint une quantité de scarabées chez Pharaon et chez ses serviteurs, et dans toute la terre d\'Egypte le pays fut ravagé par les scarabées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Et Pharaon appela Moïse et Aaron et leur dit: Allez, sacrifiez à votre Dieu dans ce pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Et Moïse dit: Il ne convient pas de faire ainsi, car c\'est un sacrilège pour les Egyptiens que les sacrifices que nous faisons à l\'Eternel notre Dieu. Pourrions-nous faire sous les yeux des Egyptiens des sacrifices qui sont pour eux des sacrilèges sans qu\'ils nous lapidassent?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Nous irons à trois jours de marche dans le désert et nous sacrifierons à l\'Eternel notre Dieu, selon qu\'il nous le dira.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Et Pharaon dit: Pour moi, je vous permettrai d\'aller sacrifier à l\'Eternel votre Dieu dans le désert; seulement, ne vous éloignez pas. Faites des prières pour moi!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Et Moïse dit: Je vais sortir, de chez toi et faire des prières à l\'Eternel, et demain les scarabées se retireront de Pharaon, de ses serviteurs et de son peuple. Seulement, que Pharaon ne recommence pas à se moquer en ne permettant pas au peuple d\'aller sacrifier à l\'Eternel!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Et Moïse sortit de chez Pharaon et fit des prières à l\'Eternel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'et l\'Eternel fit ce que demandait Moïse et les scarabées se retirèrent de Pharaon, de ses serviteurs et de son peuple; il n\'en resta pas un seul.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Et Pharaon appesantit son cœur cette fois encore et ne laissa pas aller le peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Et l\'Eternel dit à Moïse: Rends-toi vers Pharaon et parle-lui ainsi: Ainsi a dit l\'Eternel, Dieu des Hébreux: Laisse aller mon peuple, et qu\'il me serve!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Car, si tu refuses de le laisser aller et que tu le retiennes encore,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'la main de l\'Eternel va être sur ton bétail qui est dans les champs, sur les chevaux, sur les ânes, sur les chameaux, sur les bœufs et les moutons: ce sera une peste terrible.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Et l\'Eternel fera une distinction entre le bétail d\'Israël et le bétail des Egyptiens: il ne périra rien de ce qui appartient aux fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Et l\'Eternel fixa le moment en disant: Demain l\'Eternel fera cela dans le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Et l\'Eternel fit cela dès le lendemain; tout bétail des Egyptiens périt, mais des bestiaux des fils d\'Israël il n\'en périt pas un seul.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Et Pharaon envoya voir et il se trouva que des bestiaux des fils d\'Israël il n\'en avait pas même péri un seul. Et le cœur de Pharaon s\'appesantit, et il ne laissa pas aller le peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Et l\'Eternel dit à Moïse et à Aaron: Prenez plein vos mains de cendre de forge, et que Moïse jette cette cendre vers le ciel, sous les yeux de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Et qu\'elle devienne une fine poussière sur tout le pays d\'Egypte, et qu\'elle forme sur les gens et sur les bêtes des tumeurs bourgeonnant en pustules, dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Et ils prirent la cendre de forge et se tinrent devant Pharaon, et Moïse la jeta vers le ciel. Et il y eut des tumeurs bourgeonnant en pustules sur les gens et sur les bêtes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Et les enchanteurs ne purent se tenir devant Moïse à cause des tumeurs, car les tumeurs étaient sur les enchanteurs et sur tous les Egyptiens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Et l\'Eternel endurcit le cœur de Pharaon, et il ne les écouta point, selon que l\'Eternel l\'avait dit à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Et l\'Eternel dit à Moïse: Va de bon matin te placer devant Pharaon et dis-lui: Ainsi a dit l\'Eternel, Dieu des Hébreux: Laisse aller mon peuple, et qu\'il me serve!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Car cette fois-ci je déchaînerai tous mes fléaux contre ton cœur et sur tes serviteurs et sur ton peuple, afin que tu saches que nul n\'est pareil à moi par toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Que maintenant j\'étende la main et que je te frappe de la peste, toi et ton peuple: tu seras effacé de la terre!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Mais non; voici pourquoi je te laisse subsister: c\'est pour que tu fasses éclater ma puissance et que l\'on célèbre mon nom par toute la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Tu te mets encore comme une barrière devant mon peuple pour ne pas le laisser aller!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Je vais demain, à cette heure même, faire tomber une grêle très forte, telle qu\'il n\'y en a pas eu en Egypte depuis qu\'elle existe jusqu\'à ce jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Maintenant fais mettre à l\'abri ton bétail et tout ce que tu as aux champs. Tout ce qui, hommes ou bêtes, se trouvera aux champs et ne rentrera pas, sera frappé de la grêle et périra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Ceux des serviteurs de Pharaon qui craignirent la parole de l\'Eternel firent retirer dans leurs maisons leurs serviteurs et leur bétail.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Et ceux qui ne firent pas attention à la parole de l\'Eternel laissèrent leurs serviteurs et leur bétail dans les champs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Et l\'Eternel dit à Moïse: Etends ta main vers le ciel et qu\'il grêle, dans tout le pays d\'Egypte, sur les hommes, sur le bétail et sur toutes les plantes de la campagne, dans le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Et Moïse étendit son bâton vers le ciel et l\'Eternel fit tonner et grêler et il tomba du feu sur la terre. L\'Eternel fit tomber de la grêle sur le pays d\'Egypte,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'et il y eut de la grêle et du feu mêlé à la grêle, et elle fut si forte qu\'il n\'y en avait jamais eu comme celle-là dans tout le pays d\'Egypte depuis que la nation y existait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Et la grêle frappa dans tout le pays d\'Egypte tout ce qui était aux champs, tant hommes que bestiaux. La grêle avait frappé toutes les plantes des champs;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'il n\'y avait que la terre de Gossen, qu\'habitaient les fils d\'Israël, où il n\'y eût pas eu de grêle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Alors Pharaon fit appeler Moïse et Aaron et leur dit: Cette fois-ci, j\'ai péché. C\'est l\'Eternel qui a raison, et moi et mon peuple qui avons tort!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Faites des prières à l\'Eternel, et qu\'il n\'y ait plus de tonnerre et de grêle, et je vous laisserai aller, sans que vous ayez à attendre davantage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Et Moïse lui dit: En sortant de la ville, j\'étendrai mes mains vers l\'Eternel, et le tonnerre cessera, et il n\'y aura plus de grêle, afin que tu saches que la terre est à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Quant à toi et à tes serviteurs, je sais que vous n\'aurez pas encore de crainte devant l\'Eternel Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Or le lin et l\'orge avaient été frappés, car l\'orge était en épis et le lin en fleurs;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'mais le froment et l\'épeautre n\'avaient pas été frappés, parce qu\'ils sont tardifs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Et Moïse, quittant Pharaon, sortit de la ville et étendit ses mains vers l\'Eternel, et le tonnerre et la grêle cessèrent et la pluie ne tomba plus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Et Pharaon vit que la pluie, la grêle et le tonnerre avaient cessé, et il recommença à pécher et il appesantit son cœur, tant lui que ses serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Et le cœur de Pharaon s\'endurcit, et il ne laissa pas aller les fils d\'Israël, selon que l\'Eternel l\'avait annoncé par Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Et l\'Eternel dit à Moïse: Rends-toi vers Pharaon, car j\'ai moi-même appesanti son cœur et le cœur de ses serviteurs, afin de faire au milieu d\'eux les signes que tu vas voir,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'et afin que tu racontes à ton fils et au fils de ton fils mes exploits au milieu des Egyptiens et mes signes opérés au milieu d\'eux, et que vous sachiez que je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Et Moïse et Aaron se rendirent vers Pharaon et lui dirent: Ainsi a dit l\'Eternel, Dieu des Hébreux: Jusques à quand refuseras-tu te t\'humilier devant moi? Laisse aller mon peuple, et qu\'il me serve!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Car, si tu refuses de laisser aller mon peuple, je vais demain faire venir les sauterelles dans tes Etats,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'et elles couvriront la face de la terre et l\'on ne pourra pas voir la terre; elles dévoreront ce qui est demeuré de reste, ce qui vous a été laissé par la grêle, et elles dévoreront tous les arbres qui vous croissent dans les champs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Et elles rempliront tes maisons, les maisons de tous tes serviteurs et les maisons de tous les Egyptiens, comme ne l\'ont jamais vu tes pères, ni les pères de tes pères, depuis le temps où ils étaient sur la terre jusqu\'à ce jour-ci. Et Moïse se retira et sortit de chez Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Et les serviteurs de Pharaon lui dirent: Jusques à quand cet homme-là nous portera-t-il malheur? Laisse aller ces gens et qu\'ils servent l\'Eternel leur Dieu. Ne vois-tu pas encore que l\'Egypte est perdue?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'On fit revenir Moïse et Aaron auprès de Pharaon, et il leur dit: Allez, servez l\'Eternel votre Dieu. Qui sont ceux qui iront?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Et Moïse dit: Nous irons avec nos jeunes gens et nos vieillards, nous irons avec nos fils et nos filles, avec nos brebis et nos bœufs; car nous avons une fête de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Et Pharaon leur dit: Que l\'Eternel soit avec vous aussi vrai que je vous laisserai aller avec vos petits enfants! Voyez! vous avez de mauvais desseins!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Non, non; allez, si vous voulez, vous autres hommes, et servez l\'Eternel puisque c\'est là ce que vous demandez. Et on les chassa de devant Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Et l\'Eternel dit à Moïse: Etends ta main sur le pays d\'Egypte pour y faire venir les sauterelles: qu\'elles montent sur le pays d\'Egypte, qu\'elles dévorent toutes les plantes du pays et tout ce qu\'a laissé la grêle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Et Moïse étendit son bâton sur le pays d\'Egypte et l\'Eternel fit souffler sur le pays un vent d\'orient tout ce jour-là et toute la nuit. Quand le matin fut là, le vent d\'orient avait apporté les sauterelles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Et les sauterelles montèrent sur tout le pays d\'Egypte et se posèrent sur tout le territoire de l\'Egypte, en quantité si considérable que jamais il n\'y avait eu auparavant une si grande quantité de sauterelles et que jamais il n\'y en aura autant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Et elles couvrirent la face de toute la terre et la terre en fut assombrie, et elles dévorèrent toutes les plantes du pays et tous les fruits d\'arbres que la grêle avait épargnés, et il ne resta rien de vert aux arbres ni aux plantes des champs dans tout le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Aussitôt Pharaon appela Moïse et Aaron et leur dit: J\'ai péché contre l\'Eternel votre Dieu et contre vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Maintenant pardonne, je te prie, mon péché, cette fois seulement, et faites des prières à l\'Eternel et votre Dieu pour qu\'il éloigne de moi au moins ce mortel fléau!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Et Moïse sortit de chez Pharaon et adressa des prières à l\'Eternel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'et l\'Eternel fit lever un vent contraire, un vent d\'occident très fort, qui emporta les sauterelles et les précipita dans la mer Rouge. Il ne resta pas une sauterelle dans tout le territoire d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Et l\'Eternel endurcit le cœur de Pharaon, et il ne laissa pas aller les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Et l\'Eternel dit à Moïse: Etends ta main vers le ciel et qu\'il y ait des ténèbres sur le pays d\'Egypte et qu\'on tâtonne dans les ténèbres!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Et Moïse étendit la main vers le ciel et il y eut d\'épaisses ténèbres dans tout le pays d\'Egypte pendant trois jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'On ne se voyait plus les uns les autres, et nul ne se leva de la place où il était pendant trois jours. Mais tous les fils d\'Israël avaient de la lumière dans les lieux qu\'ils habitaient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Et Pharaon appela Moïse et lui dit: Allez, servez l\'Eternel. On ne retiendra que vos brebis et vos bœufs; vos petits enfants même iront avec vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Et Moïse dit: Non seulement tu nous remettras de quoi faire des sacrifices et des holocaustes à l\'Eternel notre Dieu,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'mais encore nos troupeaux viendront avec nous, sans qu\'il en reste un ongle! Car c\'est d\'eux que nous prendrons de quoi servir l\'Eternel notre Dieu, et jusqu\'à ce que nous soyons arrivés là, nous ne saurons pas nous-mêmes ce que nous offrirons à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Et l\'Eternel endurcit le cœur de Pharaon, et il ne consentit pas à les laisser aller.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Et Pharaon dit à Moïse: Eloigne-toi de moi, prends garde à toi, ne parais plus devant moi! car le jour où tu paraîtras devant moi, tu mourras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Et Moïse dit: Tu l\'as dit, je ne reparaîtrai plus devant toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Et l\'Eternel avait dit à Moïse: Je frapperai encore d\'un coup Pharaon et l\'Egypte: après cela il vous laissera partir d\'ici. Quand il vous laissera partir tout à fait, il vous chassera même d\'ici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Parle donc au peuple et dis-lui que chaque homme doit demander à son voisin et chaque femme à sa voisine des objets d\'argent et des objets d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Et l\'Eternel fit trouver grâce au peuple aux yeux des Egyptiens, et Moïse était personnellement en très haute estime auprès des serviteurs de Pharaon et auprès du peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Et Moïse dit: Ainsi a dit l\'Eternel: Au milieu de la nuit je passerai au travers de l\'Egypte,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'et tout premier-né dans le pays d\'Egypte mourra, depuis le premier-né de Pharaon sur son trône, jusqu\'au premier-né de la servante qui est derrière la meule, et tout premier-né du bétail.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Et il s\'élèvera un grand cri dans tout le pays d\'Egypte, un cri tel qu\'il n\'y en a pas eu et tel qu\'il n\'y en aura pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mais chez tous les fils d\'Israël, personne, depuis les gens jusqu\'aux bêtes, pas même un chien, ne remuera sa langue, afin que vous sachiez que l\'Eternel distingue entre l\'Egypte et Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Et tous tes serviteurs que voilà descendront vers moi et se prosterneront devant moi, en disant: Sors, toi et tout le peuple à la tête duquel tu es. Après cela, je sortirai. Et Moïse sortit de chez Pharaon en grande colère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Et l\'Eternel avait dit à Moïse: Pharaon ne vous écoutera pas, afin que mes signes soient en grand nombre dans le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Et Moïse et Aaron firent tous ces signes-là devant Pharaon. Et l\'Eternel endurcit le cœur de Pharaon, et il ne laissa point aller les fils d\'Israël hors de son pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Et l\'Eternel parla à Moïse et à Aaron dans le pays d\'Egypte, en ces termes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Que ce mois-ci soit pour vous le commencement des mois: il sera pour vous le premier des mois de l\'année.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Parlez à toute l\'assemblée d\'Israël en ces termes: Le dix de ce mois, que chacun prenne un agneau par famille, un agneau par maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Et si la maison est trop peu nombreuse pour un agneau, qu\'il le prenne en commun avec son plus proche voisin, en tenant compte du nombre des personnes: vous compterez chaque personne selon ce qu\'elle peut manger de l\'agneau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Votre agneau doit être sans défaut, mâle, âgé d\'un an; vous prendrez soit un agneau, soit un chevreau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Et vous le mettrez en réserve jusqu\'au quatorze de ce mois; la totalité de l\'assemblée de la communauté d\'Israël l\'immolera dans la soirée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Et l\'on prendra de son sang et l\'on en mettra sur les deux montants, et sur le linteau de la porte, dans les maisons où on le mangera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Et l\'on en mangera la chair cette nuit-là; on la mangera rôtie au feu avec des pains sans levain et des herbes amères.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Vous n\'en mangerez rien cru ou bouilli, mais tout sera rôti au feu, tête, jambes et entrailles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Et vous n\'en laisserez rien jusqu\'au lendemain, et ce qui en sera resté jusqu\'au lendemain, vous le brûlerez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Et c\'est ainsi que vous le mangerez: les reins ceints, les sandales aux pieds et le bâton à la main, et vous le mangerez à la hâte. C\'est la Pâque de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Et je traverserai le pays d\'Egypte cette nuit-là et je frapperai tout premier-né dans le pays d\'Egypte, des hommes, jusqu\'aux bestiaux, et j\'exécuterai des jugements sur tous les dieux de l\'Egypte. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Et le sang sera un signe sur les maisons où vous êtes: je verrai le sang et je passerai outre et il n\'y aura pas de plaie sur vous pour vous détruire quand je frapperai le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Et vous ferez commémoration de ce jour et vous le célébrerez comme une fête à l\'Eternel, vous le célébrerez de génération en génération: c\'est une institution à perpétuité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Pendant sept jours vous mangerez des pains sans levain. Dès le premier jour, vous ferez disparaître de vos maisons le levain; car toute personne qui mangera du pain levé, du premier jour au septième, sera retranchée d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Et vous aurez une sainte assemblée le premier jour et une sainte assemblée le septième jour; on ne fera aucune œuvre pendant ces jours-là; vous ne ferez que ce qui sera nécessaire à la nourriture de chacun.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Et vous observerez l\'ordonnance des pains sans levain; car c\'est en ce même jour-là que j\'ai fait sortir vos armées du pays d\'Egypte, et vous observerez ce jour-là de génération en génération comme une institution perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Dans le premier mois, le quatorzième jour du mois, au soir, vous mangerez des pains sans levain, et cela jusqu\'au vingt-et-unième jour du mois au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sept jours durant il ne doit pas se trouver de levain dans vos maisons, car toute personne qui mangera de quelque levain sera retranchée de l\'assemblée d\'Israël, qu\'elle soit étrangère ou indigène.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Vous ne mangerez d\'aucun levain: dans tous les lieux où vous habiterez, vous mangerez des pains sans levain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Et Moïse appela tous les Anciens d\'Israël et leur dit: Choisissez et prenez du menu bétail pour vos familles et immolez la Pâque.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Puis vous prendrez un bouquet d\'hysope et vous le tremperez dans le sang qui sera dans le bassin et vous toucherez le linteau et les deux poteaux des portes avec le sang qui sera dans le bassin, et aucun de vous ne sortira de sa maison jusqu\'au matin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Et l\'Eternel traversera l\'Egypte pour la frapper, et quand il verra le sang sur le linteau et les deux poteaux de vos portes, il passera vos maisons et ne permettra pas au Destructeur d\'y entrer pour frapper.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Vous observerez ceci comme une institution pour vous et pour vos enfants, à perpétuité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Et lorsque vous serez entrés dans le pays que l\'Eternel vous donnera comme il l\'a promis, vous observerez ce rite,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'et quand vos enfants vous diront: Quelle signification ce rite a-t-il pour vous?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Vous répondrez: C\'est un sacrifice de Pâque à l\'Eternel, qui passa les maisons des fils d\'Israël en Egypte lorsqu\'il frappa l\'Egypte et qu\'il préserva nos maisons. Le peuple s\'inclina et se prosterna.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Et les fils d\'Israël allèrent et firent ainsi. Ils se conformèrent à tout ce que l\'Eternel avait commandé à Moïse et à Aaron.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Et à minuit, l\'Eternel frappa tous les premiers-nés dans le pays d\'Egypte, depuis le premier-né de Pharaon sur son trône jusqu\'aux premiers-nés des captifs qui étaient dans les prisons, et les premiers-nés des bestiaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Et Pharaon se leva dans la nuit, lui et tous ses serviteurs et toute l\'Egypte, et il y eut un grand cri en Egypte, car il n\'y avait pas de maison où il n\'y eût un mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Et il appela Moïse et Aaron pendant la nuit et leur dit: Levez-vous, sortez du milieu de mon peuple, et vous et les fils d\'Israël, et allez servir l\'Eternel comme vous l\'avez dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Prenez votre bétail, gros et petit, comme vous l\'avez dit, et allez; et vous, bénissez-moi!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Et les Egyptiens pressaient le peuple, se hâtant de le renvoyer du pays, car ils disaient: Nous sommes tous morts!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Et le peuple emporta sa pâte avant qu\'elle fût levée, leurs maies serrées dans leurs manteaux, sur leurs épaules.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Et les fils d\'Israël avaient fait ce que leur avait dit Moïse: ils avaient demandé aux Egyptiens des objets d\'argent, des objets d\'or et des habits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Et l\'Eternel leur avait concilié la faveur des Egyptiens, qui leur donnèrent ce qu\'ils demandaient. Ils emportèrent donc les dépouilles de l\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Et les fils d\'Israël partirent de Ramsès pour Succoth, au nombre d\'environ six cent mille piétons: les hommes, sans compter les enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Et ils avaient aussi avec eux une foule de gens de toute sorte et des brebis et des bœufs en troupeaux très considérables.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Et ils cuisirent en galettes non levées la pâte qu\'ils avaient emportée d\'Egypte: car elle était sans levain parce qu\'ils avaient été chassés d\'Egypte et n\'avaient pu tarder; et ils n\'avaient d\'ailleurs pas pris de provisions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Or le séjour que les fils d\'Israël avaient fait en Egypte était de quatre cent trente ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Et au bout de quatre cent trente ans, en ce même jour-là, toutes les armées de l\'Eternel sortirent du pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'C\'est là une nuit à célébrer à l\'honneur de l\'Eternel parce qu\'il les a fait sortir de la terre d\'Egypte. Cette nuit-là appartient à l\'Eternel, pour être célébrée par tous les fils d\'Israël de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Et l\'Eternel dit à Moïse et à Aaron: Voici la règle de la Pâque: Aucun étranger n\'en mangera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Mais tout serviteur acquis à prix d\'argent, tu le circonciras, et alors il en mangera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ni domicilié, ni mercenaire n\'en mangera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'On mangera chaque agneau dans une seule maison: tu ne porteras rien de sa chair hors de la maison et vous ne romprez aucun de ses os.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toute l\'assemblée d\'Israël fera la Pâque.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Quand un étranger séjournant avec toi voudra faire la Pâque à l\'Eternel, que tout mâle chez lui soit circoncis, et alors il s\'approchera pour faire la Pâque et sera comme l\'indigène; nul incirconcis n\'en mangera;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'il y aura une même loi pour l\'indigène et pour l\'étranger séjournant au milieu de vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Tous les fils d\'Israël firent ainsi. Ils se conformèrent à tout ce que l\'Eternel avait commandé à Moïse et à Aaron.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Et il arriva que dans ce même jour l\'Eternel fit sortir les fils d\'Israël de la terre d\'Egypte selon l\'ordre de leurs armées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'L\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Consacre-moi tout premier-né, le premier-né de toute mère parmi les fils d\'Israël, tant des hommes que du bétail. Il m\'appartient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Et Moïse dit au peuple: Vous vous souviendrez de ce jour où vous êtes sortis d\'Egypte, de la maison de servitude, car l\'Eternel vous en a fait sortir à main forte, et vous ne mangerez pas de pain levé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'C\'est aujourd\'hui que vous en sortez, au mois d\'Abib.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Et lorsque l\'Eternel t\'aura fait entrer dans la terre du Cananéen, du Héthien, de l\'Amorrhéen, du Hévien et du Jébusien, qu\'il a juré à tes pères de te donner, terre découlant de lait et de miel, alors tu pratiqueras ce rite en ce mois-ci.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Pendant sept jours tu mangeras des pains sans levain, et le septième jour il y aura fête à l\'honneur de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'On mangera des pains sans levain pendant ces sept jours et l\'on ne verra chez toi point de pain levé, et l\'on ne verra chez toi point de levain, dans tout ton territoire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Et en ce jour-là tu donneras à ton fils cette explication: C\'est à cause de ce que l\'Eternel a fait pour moi à ma sortie d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Et cela sera pour toi un signe sur ta main et un mémorial entre tes yeux, afin que la loi de l\'Eternel soit en ta bouche: car l\'Eternel t\'a fait sortir d\'Egypte à main forte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Tu observeras cette prescription au temps marqué d\'année en année.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Et quand l\'Eternel t\'aura fait entrer dans la terre du Cananéen, comme il l\'a juré à toi et à tes pères, et qu\'il te l\'aura donnée,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'tu remettras à l\'Eternel le premier-né de toute mère, et dans les premiers fruits du bétail qui t\'appartiendra, les mâles seront à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Tout premier-né de l\'âne, tu le rachèteras par un agneau, et si tu ne veux pas le racheter, tu l\'abattras. Et tout premier-né de l\'homme parmi tes fils, tu le rachèteras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Et lorsque ton fils t\'interrogera un jour en disant: Que signifie cela? tu lui diras: C\'est à main forte que l\'Eternel nous a fait sortir d\'Egypte, de la maison de servitude.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Quand Pharaon persista à refuser de nous laisser partir, l\'Eternel tua tout premier-né dans la terre d\'Egypte, depuis les premiers-nés des hommes jusqu\'aux premiers-nés des bestiaux. C\'est à cause de cela que je sacrifie à l\'Eternel tous les mâles premiers-nés, et que tout premier-né de mes fils, je dois le racheter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Et cela sera pour toi un signe sur ta main et un fronteau entre tes yeux, car c\'est à main forte que l\'Eternel nous a fait sortir d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Or, quand Pharaon eut laissé aller le peuple, Dieu ne les conduisit pas par le chemin de la terre des Philistins, parce qu\'elle était trop proche; car Dieu dit: Il ne faut pas qu\'en présence d\'une guerre le peuple se repente et s\'en retourne en Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Dieu fit donc faire au peuple un détour, dans la direction du désert, vers la mer Rouge. Et les fils d\'Israël étaient forts et valides en sortant d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Et Moïse emporta les os de Joseph, parce que celui-ci l\'avait fait expressément jurer aux fils d\'Israël, en leur disant: Dieu ne manquera pas de vous visiter, et alors vous emporterez d\'ici mes os.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Et ils partirent de Succoth et campèrent à Etham, au bord du désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Et l\'Eternel marchait devant eux de jour en colonne de nuée pour les guider dans leur chemin, et la nuit en colonne de feu pour les éclairer, afin qu\'ils pussent marcher de jour et de nuit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'La colonne de nuée ne cessait pas d\'être devant le peuple pendant le jour, ni la colonne de feu pendant la nuit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Parle aux fils d\'Israël et dis-leur de retourner et de camper devant Pi-Hahiroth, entre Migdol et la mer; vous camperez devant Baal-Tséphon, en face de ce lieu-là, au bord de la mer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Et Pharaon dira des fils d\'Israël: Ils sont égarés dans le pays; le désert les tient enfermés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Et j\'endurcirai le cœur de Pharaon et il les poursuivra, et je triompherai de Pharaon et de toute son armée, et l\'Egypte saura que je suis l\'Eternel. Et les fils d\'Israël firent ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'On annonça au roi d\'Egypte que le peuple s\'était enfui, et Pharaon et ses serviteurs changèrent de sentiment à l\'égard du peuple et ils dirent: Qu\'avons-nous fait de laisser aller Israël pour ne plus nous servir?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Et Pharaon attela son char et prit ses troupes avec lui:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'il prit six cents chars d\'élite et tous les chars d\'Egypte; sur chacun étaient des officiers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Et l\'Eternel endurcit le cœur de Pharaon, roi d\'Egypte, et il alla à la poursuite des fils d\'Israël; car les fils d\'Israël partaient tête levée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Les Egyptiens les poursuivirent donc et les atteignirent comme ils étaient campés au bord de la mer; tous les attelages de Pharaon, ses cavaliers et son armée les atteignirent près de Pi-Hahiroth, devant Baal-Tséphon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Et Pharaon s\'était approché. Et les fils d\'Israël levèrent les yeux et aperçurent les Egyptiens en marche derrière eux, et ils eurent une grande crainte. Et les fils d\'Israël crièrent à l\'Eternel');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'et ils dirent à Moïse: Est-ce faute de sépulcres en Egypte que tu nous as pris pour que nous mourions dans le désert? Que nous as-tu fait en nous tirant d\'Egypte?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'N\'est-ce pas ce que nous te disions en Egypte quand nous disions: Laisse-nous, nous voulons servir les Egyptiens! Car mieux valait pour nous servir les Egyptiens que mourir dans le désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Et Moïse dit au peuple: Ne craignez pas. Tenez-vous là et voyez la délivrance de l\'Eternel qu\'il opérera pour vous aujourd\'hui; car si aujourd\'hui vous avez vu les Egyptiens, vous ne les reverrez plus jamais.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'L\'Eternel combattra pour vous, et vous, vous vous tiendrez tranquilles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Et l\'Eternel dit à Moïse: Que cries-tu à moi? Dis aux fils d\'Israël de se mettre en marche;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'et toi, lève ton bâton, étends ta main sur la mer, fends-la, et que les fils d\'Israël entrent au milieu de la mer, sur le sec.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Et moi, je vais endurcir le cœur des Egyptiens et ils entreront à leur suite, et je triompherai de Pharaon, de toute son armée, de ses chars et de ses cavaliers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Et les Egyptiens sauront que je suis l\'Eternel, quand j\'aurai triomphé de Pharaon, de ses chars et de ses cavaliers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Or l\'ange de Dieu qui marchait devant le camp d\'Israël passa derrière eux et la colonne de nuée partit de devant eux et se tint derrière eux:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'elle vint entre le camp des Egyptiens et le camp d\'Israël; elle était nuée et obscurité, et la nuit elle éclairait. Et ils n\'approchèrent point les uns des autres de toute la nuit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Et Moïse étendit sa main sur la mer, et l\'Eternel fit refluer la mer par un violent vent d\'orient qui souffla toute la nuit, et il mit la mer à sec; les eaux se fendirent,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'et les fils d\'Israël entrèrent au milieu de la mer, sur le sec, et les eaux étaient pour eux une muraille à droite et à gauche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Les Egyptiens les poursuivirent et tous les chevaux de Pharaon, ses chars et ceux qui les montaient entrèrent après eux au milieu de la mer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Et pendant la veille du matin, l\'Eternel, dans la colonne de nuée et de feu, regarda vers le camp des Egyptiens. Il épouvanta le camp des Egyptiens;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'ils firent reculer leurs chars et ne les conduisirent qu\'à grand-peine. Et les Egyptiens dirent: Fuyons devant Israël, car l\'Eternel combat pour eux contre l\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Et l\'Eternel dit à Moïse: Etends ta main sur la mer, et que les eaux rebroussent sur les Egyptiens, sur leurs chars et sur leurs cavaliers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Et Moïse étendit la main sur la mer, et au point du jour la mer reprit sa place, et les Egyptiens, en fuyant, la rencontrèrent, et l\'Eternel culbuta les Egyptiens au milieu de la mer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Les eaux, en revenant, couvrirent les chars et ceux qui les montaient, de toute l\'armée de Pharaon, qui étaient entrés dans la mer après Israël. Il n\'en demeura pas un.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Or les fils d\'Israël avaient traversé la mer à sec, et les eaux leur avaient servi de muraille à droite et à gauche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Et l\'Eternel sauva en ce jour-là Israël de la main des Egyptiens, et Israël vit les Egyptiens morts sur le rivage de la mer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Et Israël vit la grande puissance que l\'Eternel avait déployée contre les Egyptiens, et le peuple craignit l\'Eternel et il crut à l\'Eternel et à Moïse son serviteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Alors Moïse et les fils d\'Israël chantèrent ce cantique à l\'Eternel. Ils dirent: Je veux chanter à l\'Eternel, car il a été souverainement grand, Il a précipité dans la mer cheval et cavalier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'L\'Eternel est ma force et mon chant de louange, il a été mon salut. C\'est lui qui est mon Dieu, je le célébrerai, Le Dieu de mon père, je l\'exalterai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'L\'Eternel est un guerrier, L\'Eternel est son nom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Il a jeté dans la mer, les chars de Pharaon et son armée, L\'élite de ses capitaines a été engloutie dans la mer Rouge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Les flots les couvrent, Ils sont descendus dans l\'abîme comme une pierre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Ta droite, Eternel, a montré sa force immense, Ta droite, Eternel, brise l\'ennemi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Par la grandeur de ta majesté, tu renverses tes adversaires, Tu déchaînes ton courroux, il les consume comme du chaume.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Au souffle de tes narines, les eaux se sont amoncelées, Les ondes se sont dressées comme une digue, Les flots se sont figés au sein de la mer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'L\'ennemi disait: Je poursuivrai, j\'atteindrai, Je partagerai les dépouilles, ma vengeance se repaîtra d\'eux, Je tirerai l\'épée, ma main les exterminera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Ton haleine a soufflé, la mer les a couverts! Ils se sont enfoncés comme du plomb dans les vastes eaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Qui est comme toi entre les dieux, Eternel? Qui est comme toi, auguste en sainteté, Redoutable à louer, opérant des merveilles?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Tu as étendu ta droite, la terre les engloutit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Tu as conduit par ta grâce ce peuple que tu as affranchi, Tu l\'as dirigé par ta puissance vers ta résidence sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'En l\'apprenant, les peuples frémiront: L\'angoisse s\'empare des habitants de la Philistie,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Déjà les chefs d\'Edom sont épouvantés, Un tremblement saisit les vaillants hommes de Moab, Tous les habitants de Canaan tombent en défaillance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'La terreur et la détresse fondront sur eux; Par la force de ton bras ils seront comme pétrifiés, Jusqu\'à ce qu\'ait passé ton peuple, ô Eternel! Jusqu\'à ce qu\'ait passé ce peuple que tu t\'es acquis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu les amèneras et les implanteras sur la montagne qui t\'appartient, Au lieu dont tu as fait ta demeure, ô Eternel, Au sanctuaire, Seigneur, que tes mains ont érigé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'L\'Eternel régnera pour toujours et à jamais!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Car les chevaux de Pharaon avec ses chars et ceux qui les montaient étaient entrés dans la mer, et l\'Eternel avait ramené sur eux les eaux de la mer et les fils d\'Israël avaient traversé la mer à sec.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Et Marie la prophétesse, sœur d\'Aaron, prit en main le tambourin, et toutes les femmes s\'avancèrent à sa suite avec des tambourins et avec des danses,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'et Marie répondait aux fils d\'Israël: Chantez à l\'Eternel, car il a été souverainement grand, Il a précipité dans la mer cheval et cavalier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Moïse fit partir Israël de la mer Rouge et ils s\'avancèrent vers le désert de Sur et marchèrent trois jours dans le désert sans trouver d\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Et ils arrivèrent à Mara, et ils ne purent boire de l\'eau de Mara, parce qu\'elle est amère (c\'est à cause de cela qu\'on appelle ce lieu Mara).');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Alors le peuple murmura contre Moïse en disant: Que boirons-nous?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Et Moïse cria à l\'Eternel, et l\'Eternel lui indiqua un bois qu\'il jeta dans l\'eau, et l\'eau devint douce. Ce fut là qu\'il lui donna une prescription et une ordonnance, et ce fut là qu\'il l\'éprouva');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'et dit: Si tu écoutes attentivement la voix de l\'Eternel ton Dieu et que tu fasses ce qui est droit à ses yeux et que tu prêtes l\'oreille à ses commandements et que tu observes toutes ses prescriptions, je ne mettrai sur toi aucune des maladies que j\'ai mises sur les Egyptiens; car c\'est moi, l\'Eternel, qui te guérit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Puis ils arrivèrent à Elim, et il y avait là douze sources d\'eau et soixante-dix palmiers, et ils y campèrent près des eaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Et toute l\'assemblée des fils d\'Israël partit d\'Elim et ils arrivèrent au désert de Sin, qui est entre Elim et Sinaï, le quinzième jour du second mois après leur sortie du pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Et toute l\'assemblée des fils d\'Israël murmura contre Moïse et contre Aaron dans le désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Et les fils d\'Israël leur dirent: Que ne sommes-nous morts de la main de l\'Eternel dans la terre d\'Egypte, quand nous étions assis devant les pots de viande, quand nous mangions du pain tout notre soûl! Car vous nous avez poussés dans ce désert pour faire mourir de faim toute cette multitude.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Alors l\'Eternel dit à Moïse: Je vais vous faire pleuvoir du pain du haut des cieux, et le peuple sortira et en recueillera jour par jour ce qu\'il lui faut, afin que je l\'éprouve [pour voir] s\'il marchera en ma loi ou non.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Mais le sixième jour ils prépareront ce qu\'ils en apporteront et il y en aura le double de ce qu\'ils en recueillent chaque jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Et Moïse et Aaron dirent à tous les fils d\'Israël: Ce soir vous saurez que c\'est l\'Eternel qui vous a fait sortir du pays d\'Egypte,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'et demain matin vous verrez la gloire de l\'Eternel, car il entend vos murmures qui sont contre l\'Eternel. Nous, que sommes-nous, que vous murmuriez contre nous?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Et Moïse dit: Ce sera quand l\'Eternel vous donnera ce soir de la viande à manger, et demain du pain tout votre soûl; car l\'Eternel entend ce que vous murmurez contre lui. Nous, que sommes-nous? Ce n\'est pas contre nous que vous murmurez, c\'est contre l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Et Moïse dit à Aaron: Dis à toute l\'assemblée des fils d\'Israël: Présentez-vous devant l\'Eternel, car il a entendu vos murmures.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Et comme Aaron parlait à toute l\'assemblée des fils d\'Israël et que ceux-ci se tournaient vers le désert, voilà que la gloire de l\'Eternel apparut dans la nuée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Et l\'Eternel parla à Moïse et lui dit:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'J\'ai entendu les murmures des fils d\'Israël. Parle-leur ainsi: Dans la soirée vous mangerez de la viande et demain matin vous vous rassasierez de pain, et vous saurez que moi, l\'Eternel, je suis votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Et le soir on vit monter les cailles et le camp en fut couvert. Et le matin il y avait une couche de rosée autour du camp,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'et lorsque la couche de rosée se fut dissipée, on aperçut à la surface du désert de petits grains floconneux, de petits grains pareils à du givre sur le sol.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Et les fils d\'Israël les virent et se dirent les uns aux autres: C\'est de la manne! car ils ne savaient ce que c\'était. Et Moïse leur dit: C\'est le pain que l\'Eternel vous a donné pour nourriture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Voici ce qu\'a ordonné l\'Eternel: Recueillez-en chacun ce qu\'il en faut pour sa nourriture: un omer par tête, selon le nombre des personnes; chacun en prendra pour ceux qui sont dans sa tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Les fils d\'Israël firent ainsi et recueillirent de la manne, les uns beaucoup, les autres peu;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'puis ils la mesurèrent à l\'omer, et celui qui en avait beaucoup n\'avait rien de trop et celui qui en avait peu n\'en manquait point: chacun en avait recueilli ce qu\'il lui en fallait pour manger.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Et Moïse leur dit: Que personne n\'en laisse jusqu\'à demain!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mais on n\'écouta pas Moïse et il y eut des gens qui en gardèrent jusqu\'au lendemain; les vers s\'y mirent et elle sentit mauvais. Et Moïse s\'irrita contre eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Ils recueillirent donc la manne chaque matin, chacun selon sa consommation, et quand le soleil devenait ardent, elle fondait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Mais le sixième jour ils en recueillirent le double, deux omers par personne, et tous les princes de l\'assemblée vinrent le rapporter à Moïse,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'qui leur dit: C\'est ce qu\'a dit l\'Eternel. Demain est un sabbat, un jour de repos saint à l\'Eternel. Ce que vous avez à cuire au four, cuisez-le; ce que vous avez à faire bouillir, faites-le bouillir; et tout le surplus, mettez-le en réserve pour demain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Ils le serrèrent donc jusqu\'au lendemain, comme Moïse l\'avait ordonné, et cela ne sentit point mauvais et les vers ne s\'y mirent point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Et Moïse dit: Mangez-la aujourd\'hui, car aujourd\'hui est sabbat en l\'honneur de l\'Eternel; aujourd\'hui vous n\'en trouveriez point dans la campagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Pendant six jours vous en recueillerez; mais le septième jour, jour de sabbat, il n\'y en aura pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Or le septième jour, il y eut des gens qui sortirent pour en recueillir, mais ils n\'en trouvèrent point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Et l\'Eternel dit à Moïse: Jusques à quand refuserez-vous de garder mes commandements et mes lois?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Voyez! C\'est parce que l\'Eternel vous a donné le sabbat qu\'il vous donne le sixième jour du pain pour deux jours. Que chacun reste où il est; que nul ne sorte de chez soi le septième jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Ainsi le peuple se reposa le septième jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Et la maison d\'Israël donna à ce pain le nom de manne. Cette manne était comme de la graine de coriandre, blanche et ayant le goût de galette au miel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Et Moïse dit: Voici ce que l\'Eternel a ordonné: Conservez-en le contenu d\'un omer pour vos descendants, afin qu\'ils voient le pain que je vous ai fait manger dans le désert, quand je vous ai tirés de la terre d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Moïse donc dit à Aaron: Prends une cruche et mets-y de la manne plein un omer, et place-la devant l\'Eternel afin de la conserver pour vos descendants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Et selon que l\'Eternel l\'avait ordonné à Moïse, Aaron la plaça devant le Témoignage pour la conserver.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Les fils d\'Israël ont mangé la manne pendant quarante ans, jusqu\'à ce qu\'ils arrivassent en pays habité: ils ont mangé la manne jusqu\'à ce qu\'ils arrivassent aux confins du pays de Canaan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'L\'omer est le dixième de l\'épha.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Toute l\'assemblée des fils d\'Israël partit du désert de Sin, marchant d\'étape en étape à l\'ordre de l\'Eternel. Et ils campèrent à Réphidim, et l\'on n\'y trouva pas d\'eau à boire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Alors le peuple querella Moïse et lui dit: Donnez-nous de l\'eau à boire. Et Moïse leur dit: Que faites-vous de me quereller? que faites-vous de tenter l\'Eternel?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Et le peuple eut soif dans ce lieu et murmura contre Moïse et dit: Pourquoi nous as-tu fait sortir d\'Egypte pour nous faire mourir de soif, nous, nos fils et nos troupeaux?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Et Moïse cria à l\'Eternel en disant: Que ferai-je pour ce peuple? Peu s\'en faut qu\'ils ne me lapident!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Et l\'Eternel dit à Moïse: Passe devant le peuple et prends avec toi des Anciens d\'Israël. Prends en main le bâton avec lequel tu as frappé le fleuve, et va!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Je vais me tenir là devant toi sur le rocher qui est en Horeb, et tu frapperas le rocher: il en sortira de l\'eau, et le peuple boira. Et Moïse fit ainsi, aux yeux des Anciens d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Et il nomma ce lieu-là Massa et Mériba, à cause de la querelle que lui avaient faite les fils d\'Israël et parce qu\'ils avaient tenté l\'Eternel en disant: L\'Eternel est-il au milieu de nous ou non?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Et Amalek vint attaquer Israël à Réphidim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Et Moïse dit à Josué: Choisis des hommes, avance et combats contre Amalek. Pour moi, je me tiendrai demain au sommet de la colline, le bâton de Dieu en ma main.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Et Josué fit comme Moïse le lui avait dit: il combattit contre Amalek. Or Moïse, Aaron et Hur étaient montés au sommet de la colline.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Et il arriva que, lorsque Moïse tenait la main levée, Israël avait le dessus, et lorsqu\'il laissait tomber sa main, Amalek avait le dessus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Et les mains de Moïse s\'étant fatiguées, ils prirent une pierre qu\'ils mirent sous lui et sur laquelle il s\'assit, et Aaron et Hur soutenaient ses mains, l\'un d\'un côté, l\'autre de l\'autre; ainsi ses mains furent fermes jusqu\'au coucher du soleil,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'et Josué défit Amalek et son peuple à la pointe de l\'épée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Et l\'Eternel dit à Moïse: Ecris ceci dans le livre pour que le souvenir s\'en perpétue et déclare à Josué que j\'effacerai entièrement la mémoire d\'Amalek de dessous les cieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Et Moïse construisit un autel qu\'il appela Jéhova-Nissi,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'et il dit: Puisqu\'on a levé la main contre le trône de l\'Eternel, l\'Eternel est en guerre contre Amalek d\'âge en âge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Jéthro, sacrificateur de Madian, beau-père de Moïse, apprit tout ce que Dieu avait fait pour Moïse et pour Israël son peuple: que l\'Eternel avait fait sortir Israël d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Alors Jéthro, beau-père de Moïse, prit Séphora, femme de Moïse, qu\'il avait renvoyée,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'et les deux fils de celle-ci, dont l\'un se nommait Guersom, parce que Moïse avait dit: J\'ai été habitant d\'une terre étrangère,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'et dont l\'autre se nommait Eliézer, parce que, avait-il dit, le Dieu de mon père est venu à mon secours et m\'a arraché à l\'épée de Pharaon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Et Jéthro, beau-père de Moïse, avec les fils et la femme de celui-ci, alla vers lui au désert où il campait, en la montagne de Dieu,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'et il fit dire à Moïse: Moi, ton beau-père, Jéthro, je viens vers toi, ainsi que ta femme et ses deux fils avec elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Et Moïse sortit au-devant de son beau-père, se prosterna et l\'embrassa; ils se demandèrent l\'un à l\'autre comment ils allaient, puis ils entrèrent dans la tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Alors Moïse raconta à son beau-père tout ce que l\'Eternel avait fait à Pharaon et aux Egyptiens à cause d\'Israël, et toutes les peines qui leur étaient survenues en chemin et comment l\'Eternel les en avait tirés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Et Jéthro se réjouit de tout le bien que l\'Eternel avait fait à Israël, qu\'il avait tiré de la main des Egyptiens,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'et il dit: Béni soit l\'Eternel, qui vous a tirés de la main des Egyptiens et de la main de Pharaon! qui a soustrait le peuple à la domination des Egyptiens!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Maintenant je sais que l\'Eternel est plus grand que tous les dieux, car il a été grand alors que les Egyptiens se sont élevés tyranniquement contre Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Et Jéthro, beau-père de Moïse, offrit à Dieu un holocauste et des sacrifices, et Aaron et tous les Anciens d\'Israël vinrent manger avec le beau-père de Moïse en présence de Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Le lendemain, Moïse s\'assit pour juger le peuple, et le peuple se tint devant lui du matin au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Et le beau-père de Moïse, voyant tout ce qu\'il faisait pour le peuple, lui dit: Qu\'est-ce que tu fais là pour ces gens? Pourquoi sièges-tu seul et pourquoi tout ce monde se tient-il là devant toi du matin au soir?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Et Moïse dit à son beau-père: C\'est que l\'on vient à moi pour consulter Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Lorsqu\'ils ont quelque affaire, elle vient à moi, et je juge entre eux, et je leur fais connaître les ordres de Dieu et ses lois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Et le beau-père de Moïse lui dit: Ce que tu fais n\'est pas bien:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'tu succomberas infailliblement, et toi et le peuple qui est avec toi; car la tâche est trop lourde pour toi; tu ne saurais la remplir seul.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Ecoute maintenant le conseil que je vais te donner, et que Dieu soit avec toi! Sois, toi, le représentant du peuple auprès de Dieu et porte les affaires devant Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Instruis-les de ses ordres et de ses lois et enseigne-leur la voie qu\'ils auront à suivre et ce qu\'ils auront à faire;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'mais choisis d\'entre tout le peuple des hommes de mérite, craignant Dieu, des hommes de vérité, haïssant le lucre, et établis-les sur le peuple comme chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'et qu\'ils jugent le peuple en tout temps; ils te rapporteront toutes les grandes affaires et jugeront eux-mêmes toutes les petites. Soulage-toi de ton fardeau et qu\'ils le portent avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si tu fais cela et que Dieu te donne des ordres, tu y pourras tenir, et tout ce peuple aussi viendra en paix en son lieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Et Moïse écouta son beau-père et fit tout ce que celui-ci lui avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Moïse choisit dans tout Israël des hommes de mérite et les préposa au peuple comme chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'ils jugeaient le peuple en tout temps et rapportaient à Moise les affaires graves et jugeaient eux-mêmes toutes les petites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Et Moïse prit congé de son beau-père, qui s\'en retourna dans son pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Ce fut le premier jour du troisième mois après leur sortie du pays d\'Egypte que les fils d\'Israël arrivèrent au désert de Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Et ils partirent de Réphidim, arrivèrent au désert de Sinaï et campèrent dans le désert. Israël y campa en face de la montagne,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'et Moïse monta vers Dieu, et l\'Eternel du haut de la montagne lui cria ces mots: Voici ce que tu diras à la maison de Jacob et ce que tu annonceras aux fils d\'Israël:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vous avez vu vous-mêmes ce que j\'ai fait aux Egyptiens et que je vous ai portés sur des ailes d\'aigle et vous ai amenés vers moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Et maintenant, si vous obéissez fidèlement à ma voix et que vous gardiez mon alliance, vous serez mon peuple particulier d\'entre tous les peuples; car toute la terre est à moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Mais vous, vous me serez un royaume de sacrificateurs et une nation sainte. Telles sont les paroles que tu diras aux fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Et Moïse vint et appela les Anciens du peuple et leur exposa tout ce que l\'Eternel l\'avait chargé de dire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Et tout le peuple répondit d\'une voix unanime: Tout ce qu\'a dit l\'Eternel, nous le ferons. Et Moïse alla porter à l\'Eternel la réponse du peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Et l\'Eternel dit à Moïse: Je vais venir à toi dans le sein de la nuée, afin que le peuple entende quand je parlerai avec toi, et qu\'ils aient foi en toi aussi à jamais. Et Moïse rapporta à l\'Eternel les paroles du peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Et l\'Eternel dit à Moïse: Va vers le peuple et sanctifie-les aujourd\'hui et demain, et qu\'ils lavent leurs vêtements,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'et qu\'ils se tiennent prêts pour le troisième jour, car le troisième jour l\'Eternel descendra, aux yeux de tout le peuple, sur la montagne de Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Fixe au peuple une limite alentour en leur disant: Gardez-vous de monter sur la montagne ou d\'en toucher le bord! Quiconque la touchera sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'On ne mettra pas la main sur lui, mais on le lapidera ou on le percera de flèches, que ce soit une bête ou un homme, il ne doit pas vivre! Quand la trompette sonnera, ils monteront sur la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Et Moïse descendit de la montagne vers le peuple, et il sanctifia le peuple et ils lavèrent leurs vêtements.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Et il dit au peuple: Soyez prêts dans trois jours. Ne vous approchez d\'aucune femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Au troisième jour, quand le matin fut venu, il y eut des coups de tonnerre, des éclairs, un lourd nuage sur la montagne et un son de trompe très fort, et tout le monde dans le camp trembla.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Et Moïse fit sortir le peuple du camp pour aller au-devant de Dieu. Et ils se tinrent au bas de la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Et le mont Sinaï était tout fumant, parce que l\'Eternel y était descendu au milieu du feu, et la fumée montait comme la fumée d\'une fournaise et toute la montagne trembla fort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Et le son de la trompe se renforçait toujours plus. Moïse parla, et Dieu lui répondit par une voix.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Et l\'Eternel descendit sur le mont Sinaï, sur le sommet de la montagne, et l\'Eternel appela Moïse au sommet de la montagne, et Moïse monta.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Et l\'Eternel dit à Moïse: Descends, fais une sommation au peuple, de peur qu\'il ne fasse irruption vers l\'Eternel pour regarder et qu\'il n\'en périsse beaucoup.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Et que même les sacrificateurs qui s\'approchent de l\'Eternel se sanctifient, de peur que l\'Eternel ne les frappe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Et Moïse dit à l\'Eternel: Il ne sera pas possible au peuple de monter sur le mont Sinaï puisque tu nous as toi-même adressé cette sommation: Pose des limites à la montagne et qu\'elle te soit sacrée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Et l\'Eternel lui dit: Va, descends, et tu remonteras ayant Aaron avec toi. Mais quant aux sacrificateurs et au peuple, qu\'ils ne fassent point irruption pour monter vers l\'Eternel, de peur qu\'il ne les frappe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Et Moïse descendit vers le peuple et le leur dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Et Dieu prononça toutes ces paroles:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Je suis l\'Eternel ton Dieu qui t\'ai tiré de la terre d\'Egypte, d\'une maison de servitude.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Tu n\'auras pas d\'autres dieux devant ma face.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Tu ne te feras pas d\'image taillée, ni aucune figure de ce qui est dans les cieux en haut, ou de ce qui est sur la terre en bas, ou de ce qui est dans les eaux au-dessous de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Tu ne te prosterneras point devant elles et tu ne les serviras point; car je suis l\'Eternel ton Dieu, un Dieu jaloux, punissant les crimes des pères sur les fils, sur la troisième et sur la quatrième génération, pour ceux qui me haïssent,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'et traitant avec bonté jusqu\'à mille générations ceux qui m\'aiment et qui gardent mes commandements.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Tu ne prendras pas le nom de l\'Eternel ton Dieu en vain, car l\'Eternel n\'absoudra point celui qui prendra son nom en vain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Souviens-toi du jour du sabbat pour le sanctifier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Pendant six jours tu travailleras et tu feras tout ce que tu as à faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mais le septième jour est un sabbat consacré à l\'Eternel ton Dieu; tu ne feras aucun ouvrage, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ta bête, ni l\'étranger qui est dans tes portes;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'car pendant six jours l\'Eternel a fait les cieux, la terre, la mer, et tout ce qu\'ils contiennent, et il s\'est reposé le septième jour; c\'est pourquoi l\'Eternel a béni le jour du sabbat et l\'a sanctifié.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honore ton père et ta mère afin que tes jours soient prolongés sur la terre que l\'Eternel ton Dieu te donne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Tu ne commettras pas de meurtre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Tu ne commettras pas d\'adultère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Tu ne déroberas pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Tu ne déposeras pas comme faux témoin contre ton prochain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Tu ne convoiteras pas la maison de ton prochain. Tu ne convoiteras pas la femme de ton prochain, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni rien de ce qui est à ton prochain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Et tout le peuple voyait et entendait le tonnerre, les éclairs, le son du cor, la montagne fumante. Et le peuple, à cette vue, trembla et se tint à distance,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'et il dit à Moïse: Parle, toi, avec nous, et que nous écoutions; et que Dieu ne parle pas avec nous, de peur que nous ne mourions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Et Moïse dit au peuple: Ne craignez pas, car c\'est pour vous mettre à l\'épreuve que Dieu est venu, et c\'est pour que sa crainte vous soit présente, afin que vous ne péchiez pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Et le peuple resta à distance. Mais Moïse s\'approcha de la nuée épaisse où était Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Et l\'Eternel dit à Moïse: Tu parleras ainsi aux fils d\'Israël: Vous avez vu vous-mêmes que je vous ai parlé du haut des cieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Vous ne ferez point de dieux à côté de moi, vous ne vous ferez point de dieux d\'argent et vous ne vous ferez point de dieux d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tu me feras un autel de terre, sur lequel tu immoleras tes holocaustes et tes sacrifices de reconnaissance, ton menu bétail et ton gros bétail; en quelque lieu que je fasse souvenir de mon nom, je viendrai à toi et te bénirai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Et si tu me fais un autel de pierres, tu ne le construiras point en pierres de taille; car, en levant le fer sur elles, tu les aurais rendues profanes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Et tu ne monteras point à mon autel par des degrés, afin que ta nudité ne soit pas découverte sur lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Et voici les lois que tu leur donneras:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Lorsque tu achèteras un serviteur hébreu, il servira six années, et la septième il sortira, affranchi gratuitement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'S\'il est entré seul, il sortira seul. S\'il avait une femme, sa femme sortira avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si son maître lui donne une femme et qu\'elle enfante des fils et des filles, la femme avec ses enfants appartiendra à son maître et il sortira seul.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Et si le serviteur fait la déclaration suivante: J\'aime mon maître, ma femme et mes enfants; je ne veux pas être affranchi;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'alors son maître l\'amènera devant Dieu et le fera approcher de la porte ou du poteau, et son maître lui percera l\'oreille d\'un poinçon, et il le servira à perpétuité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Et lorsque quelqu\'un aura vendu sa fille pour être servante, elle ne sortira point comme sortent les serviteurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si elle a déplu à son maître, qui n\'en a pas disposé, et qu\'il s\'en défasse, il n\'aura pas la faculté de la vendre à des gens étrangers après lui avoir été infidèle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'S\'il l\'avait mariée à son fils, il la traitera comme il est de règle de traiter ses filles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'S\'il en prend une autre, il ne lui retranchera pas le vivre, le vêtement et le couvert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'S\'il ne lui fournit pas ces trois choses, elle sortira gratuitement, sans rançon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Celui qui frappe un homme de sorte qu\'il en meure, doit être mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mais pour le cas où il n\'aurait point eu cet homme en vue et où ce serait Dieu qui l\'aurait fait se trouver devant sa main, je te fixerai un lieu où il puisse se réfugier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Lorsque, de propos délibéré, un homme tue son prochain avec ruse, tu le tireras même d\'auprès de mon autel pour qu\'il meure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Qui frappe son père ou sa mère doit être mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Celui qui dérobe un homme, soit qu\'il l\'ait vendu, soit qu\'on l\'ait retrouvé en sa possession, doit être mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Celui qui injurie son père ou sa mère doit être mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Lorsque des hommes se querellent et que l\'un en frappe un autre avec une pierre ou avec le poing, et que celui-ci n\'en meurt pas, mais est forcé de se mettre au lit,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 's\'il en relève et qu\'il puisse marcher dehors en s\'appuyant sur un bâton, celui qui l\'aura frappé sera quitte, sauf qu\'il indemnisera l\'autre pour ce qu\'il a chômé et se chargera de le faire guérir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Lorsqu\'un homme frappe son serviteur ou sa servante du bâton et que celui-ci meurt sous les coups, il doit être vengé;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'toutefois, s\'il survit un jour ou deux jours, il ne sera pas vengé, car il est sa propriété.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Et lorsque des hommes se battent, et qu\'ils heurtent une femme enceinte et qu\'elle accouche, sans qu\'il y ait de mal, le coupable sera passible d\'une amende que le mari de la femme lui imposera et qu\'il payera après décision d\'arbitres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mais s\'il y a du mal, tu donneras vie pour vie,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'œil pour œil, dent pour dent, main pour main, pied pour pied,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'brûlure pour brûlure, blessure pour blessure, meurtrissure pour meurtrissure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Et lorsqu\'un homme donnera un coup dans l\'œil à son serviteur ou à sa servante et lui fera perdre l\'œil, il le renverra libre, en compensation de l\'œil qu\'il a perdu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Et s\'il fait tomber une dent à son serviteur ou à sa servante, il le renverra libre, en compensation de la dent qu\'il a perdue.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Lorsqu\'un bœuf heurtera de sa corne un homme ou une femme et que cette personne en mourra, le bœuf devra être lapidé et l\'on n\'en mangera pas la chair, mais le maître du bœuf sera quitte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Mais si c\'est depuis longtemps que ce bœuf heurte de sa corne et qu\'on en ait averti formellement son maître et qu\'il ne l\'ait pas surveillé, et qu\'il ait causé la mort d\'un homme ou d\'une femme, le bœuf sera lapidé et son maître aussi sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Si on lui impose un prix pour se racheter, il payera pour rançon de sa vie tout ce qu\'on lui réclamera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'S\'il heurte un fils ou s\'il heurte une fille, on lui appliquera cette règle-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si le bœuf heurte un serviteur ou une servante, on payera en argent trente sicles au maître de l\'esclave, et le bœuf sera lapidé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Lorsque quelqu\'un ouvrira une citerne ou lorsque quelqu\'un creusera une citerne et ne la couvrira pas, et qu\'un bœuf ou qu\'un âne y tombera,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'le maître de la citerne indemnisera: il rendra au maître de la bête l\'argent qu\'elle valait, et la bête tuée lui appartiendra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Lorsque le bœuf d\'un homme blessera le bœuf d\'un autre et qu\'il en mourra, ils vendront le bœuf vivant et en partageront l\'argent, et ils partageront aussi le bœuf tué.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ou bien, s\'il est notoire que c\'était depuis longtemps un bœuf heurtant de la corne et que son maître ne l\'ait pas surveillé, il devra indemniser en donnant bœuf pour bœuf, et la bête tuée lui appartiendra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Si quelqu\'un vole un bœuf ou un mouton et qu\'il le tue ou le vende, il rendra cinq bœufs pour le bœuf et quatre moutons pour le mouton.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si on prend un voleur par effraction, qu\'on le frappe et qu\'il meure, on n\'est pas coupable de meurtre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Si le soleil est levé, on est coupable de meurtre. Le voleur doit indemniser; s\'il n\'a pas de quoi, on le vendra pour ce qu\'il a volé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si ce qu\'il a volé, que ce soit un bœuf, un âne ou un mouton, se retrouve vivant en sa possession, il indemnisera en donnant le double.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Lorsque quelqu\'un, en faisant pâturer dans un champ ou un verger, laissera aller ses bêtes pâturer dans le champ d\'autrui, il indemnisera en donnant ce qu\'il a de mieux dans son champ et dans son verger.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Lorsqu\'un feu éclatera et gagnera des épines et dévorera du blé en meule ou du blé sur pied ou un champ, celui qui aura allumé ce feu sera tenu d\'indemniser.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Lorsqu\'un homme donnera en garde à un autre de l\'argent ou des meubles, et qu\'ils se trouveront avoir été volés de la maison de celui-ci, si l\'on découvre le voleur, il indemnisera en rendant le double;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Si on ne découvre pas le voleur, le maître de la maison comparaîtra devant Dieu pour [qu\'on sache] s\'il n\'a pas mis la main sur le bien de son prochain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Quel que soit le corps d\'un délit, bœuf, âne, mouton, manteau ou tout objet perdu dont quelqu\'un dira: C\'est bien celui-là! l\'affaire des deux parties sera portée devant Dieu; celui que Dieu condamnera, rendra le double à son prochain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Lorsqu\'un homme donnera en garde à un autre un âne, ou un bœuf, ou un mouton, ou une pièce de bétail quelconque, et qu\'elle périra ou aura un membre cassé ou sera emmenée sans qu\'il y ait de témoin,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'le serment de l\'Eternel interviendra entre les deux parties pour qu\'on sache si le dépositaire n\'a pas mis la main sur le bien de l\'autre; et le propriétaire de la bête acceptera [ce serment] et l\'autre n\'aura point à indemniser.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Si on la lui a volée, il en indemnisera le propriétaire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Si elle a été mise en pièces [par une bête féroce], il en produira les restes comme preuve; il n\'indemnisera point de la bête déchirée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Lorsqu\'un homme empruntera d\'un autre une bête et qu\'elle se cassera un membre ou périra, sans que le propriétaire soit avec elle, l\'emprunteur aura à indemniser;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'si son propriétaire est avec elle, on n\'indemnisera point. Si c\'est une bête louée, elle était là pour son prix de louage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Lorsqu\'un homme séduit une vierge qui n\'est pas fiancée et a commerce avec elle, il doit payer un douaire en la prenant pour femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Si le père refuse positivement de la lui donner, il payera l\'argent qu\'on donne pour douaire des vierges.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Tu ne laisseras pas vivre de magicienne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Quiconque a commerce avec une bête devra être mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Qui sacrifie aux dieux, si ce n\'est à l\'Eternel, à lui seul, sera détruit comme anathème.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Tu ne feras pas de tort à l\'étranger et tu ne l\'opprimeras pas, car vous avez été des étrangers dans le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Vous ne chagrinerez jamais ni veuve, ni orphelin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Si tu les chagrines en quelque manière, car, s\'ils viennent à crier à moi, j\'entendrai certainement leur cri,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'ma colère s\'enflammera, et je vous tuerai par l\'épée, et vos femmes seront des veuves et vos fils des orphelins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si tu prêtes de l\'argent à quelqu\'un de mon peuple, au pauvre qui est avec toi, n\'agis pas à son égard comme celui qui fait métier de prêter; vous ne lui imposerez point d\'intérêt.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tu prends en gage le manteau de ton prochain, tu le lui rendras avant que le soleil se couche;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'car c\'est tout ce qu\'il a pour se couvrir, c\'est le vêtement de sa peau; sur quoi coucherait-il? Et s\'il crie à moi, j\'entendrai, car je suis compatissant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Tu ne blasphémeras pas contre Dieu et tu ne maudiras pas celui qui est un prince dans ton peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Tu ne différeras pas [le tribut] de ce qui remplit [tes champs] et de ce qui découle [de tes vignes]; tu me donneras le premier-né de tes fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Tu feras de même de celui de tes bœufs et de tes moutons: il sera sept jours avec sa mère, le huitième jour tu me le donneras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Vous me serez des hommes saints: vous ne mangerez point la chair qui se trouvera dans les champs, les animaux déchirés; vous jetterez cela aux chiens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Tu n\'accueilleras pas de vain bruit. Ne prête pas ton concours à un méchant en lui servant de témoin à charge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Tu ne te mettras pas à la suite du grand nombre pour mal faire, et tu ne déposeras pas dans un procès en te conformant au grand nombre pour faire fléchir [le droit].');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Et tu ne favoriseras point un faible dans son procès.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Lorsque tu rencontreras le bœuf de ton adversaire ou son âne égaré, tu ne manqueras pas de le lui ramener.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Lorsque tu verras l\'âne de celui qui te hait abattu sous sa charge, tu te garderas bien de l\'abandonner, tu le déchargeras avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Tu ne feras point fléchir le droit de l\'indigent dans son procès,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Eloigne-toi d\'une cause mensongère et ne mets pas à mort celui qui est innocent et juste, car je n\'absoudrai point un coupable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Tu n\'accepteras pas de présents, car les présents aveuglent les clairvoyants et ruinent les bonnes causes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Tu n\'opprimeras pas l\'étranger: vous savez vous-mêmes ce que c\'est que d\'être étranger, puisque vous avez été des étrangers dans le pays d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Pendant six années tu ensemenceras ta terre et en récolteras les produits;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'mais la septième tu les laisseras et les abandonneras, et les indigents de ton peuple les mangeront, et ce qu\'ils laisseront sera mangé par les bêtes sauvages. C\'est aussi ce que tu feras pour tes vignes et tes oliviers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Pendant six jours tu feras ce que tu as à faire, mais le septième jour tu cesseras, afin que ton bœuf et ton âne aient du repos et que le fils de ta servante et l\'étranger reprennent haleine.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Vous vous tiendrez sur vos gardes dans toutes les choses que je vous ai prescrites; vous ne mentionnerez pas de nom de dieux étrangers et on n\'en entendra pas dans ta bouche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trois fois dans l\'année tu me célébreras une fête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Tu observeras la fête des pains sans levain. Pendant sept jours tu mangeras des pains sans levain selon que je te l\'ai ordonné, au temps fixé du mois d\'Abib, car c\'est alors que tu es sorti d\'Egypte. Et l\'on ne paraîtra pas devant moi les mains vides.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Et la fête de la moisson, fête des prémices de tes produits, de ce que tu sèmeras dans les champs. Et la fête de la récolte, à la fin de l\'année, quand tu rentreras des champs tes produits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trois fois l\'année toute ta population mâle paraîtra devant le Souverain, l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Tu n\'associeras pas à du pain levé le sang de mon sacrifice. Et la graisse de ma victime de fête ne demeurera pas jusqu\'au matin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Tu apporteras à la maison de l\'Eternel ton Dieu les premières prémices de ton sol. Tu ne feras pas bouillir un chevreau dans le lait de sa mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Voici, j\'envoie un ange devant toi pour te garder dans le chemin et te faire entrer dans le lieu que j\'ai préparé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Prends garde à lui et obéis à sa voix. Ne lui résiste pas, car il ne vous pardonnerait pas votre rébellion, parce que mon nom est en lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Mais si tu obéis fidèlement à sa voix et que tu fasses tout ce que je dis, je serai un ennemi pour tes ennemis et un adversaire pour tes adversaires.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Car mon ange marchera devant toi et te fera entrer dans le pays des Amorrhéens, des Héthiens, des Phéréziens, des Cananéens, des Héviens et des Jébusiens, et je les détruirai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Tu ne te prosterneras pas devant leurs dieux et ne les serviras pas; et tu n\'imiteras pas leurs pratiques, mais tu devras renverser leurs statues et mettre en pièces leurs monuments.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Et vous servirez l\'Eternel votre Dieu. Et il bénira ton pain et ton eau, et j\'éloignerai de toi les maladies.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Il n\'y aura dans ton pays ni femme dont les enfants meurent avant de naître, ni femme stérile. Je n\'abrégerai pas tes jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Je déchaînerai devant toi ma terreur et j\'épouvanterai tous ceux chez qui tu arriveras, et je mettrai en fuite devant toi tous tes ennemis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Et j\'enverrai les frelons devant toi, et ils chasseront de devant toi les Héviens, les Cananéens et les Héthiens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Je ne les chasserai pas de devant toi en une seule année, de peur que le pays ne devienne un désert et que les bêtes sauvages ne soient en force contre toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'C\'est peu à peu que je les chasserai de devant toi, jusqu\'à ce que tu sois en nombre et que tu occupes le pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Et je te donnerai pour frontières la mer Rouge et la mer des Philistins, le désert et le fleuve; car je te livrerai les habitants du pays et tu les chasseras de devant toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Tu ne feras pas alliance avec eux et leurs dieux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ils n\'habiteront pas dans ton pays, de peur qu\'ils ne te fassent pécher contre moi: tu servirais leurs dieux, ce qui te serait funeste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Et à Moïse, il lui dit: Monte vers l\'Eternel, toi et Aaron, Nadab, Abihu et soixante-dix des Anciens d\'Israël, et prosternez-vous de loin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Et Moïse seul s\'approchera de l\'Eternel, mais eux n\'approcheront pas, et le peuple ne montera pas avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Et Moïse alla rapporter au peuple toutes les paroles de l\'Eternel et toutes les lois. Et tout le peuple répondit d\'une voix: Tout ce qu\'a dit l\'Eternel, nous le ferons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Et Moïse écrivit toutes les paroles de l\'Eternel, et, le lendemain, dès le matin, il érigea un autel au pied de la montagne et douze pierres pour les douze tribus d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Et il envoya les jeunes gens d\'Israël, et ils offrirent à l\'Eternel des holocaustes et sacrifièrent des taureaux en sacrifices d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Et Moïse prit la moitié du sang et la mit dans des bassins; et l\'autre moitié du sang, il l\'avait répandue sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Et il prit le Livre de l\'alliance et le lut au peuple. Et ils dirent: Tout ce qu\'a dit l\'Eternel, nous le ferons et y obéirons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Alors Moïse prit le sang et le répandit sur le peuple, et il dit: Voici le sang de l\'alliance que l\'Eternel a conclue avec vous, sur la base de toutes ces paroles-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Et Moïse monta avec Aaron, Nadab, Abihu et soixante-dix des Anciens d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Et ils virent le Dieu d\'Israël. Sous ses pieds c\'était comme un pavement de saphirs et comme le ciel même pour la pureté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Et l\'Eternel ne toucha pas les élus des fils d\'Israël; ils virent Dieu et mangèrent et burent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Et l\'Eternel dit à Moïse: Monte vers moi sur la montagne et restes-y, et je te donnerai les tables de pierre, la loi et les préceptes que j\'ai écrits pour leur enseignement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Et Moïse, avec Josué, son serviteur, se leva, et Moïse monta à la montagne de Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Il avait dit aux Anciens d\'Israël: Attendez-nous ici jusqu\'à ce que nous revenions vers vous. Vous avez avec vous Aaron et Hur. Qui aura quelque affaire pourra s\'adresser à eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Et Moïse monta à la montagne, et la nuée couvrit la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Et la gloire de l\'Eternel reposa sur le mont Sinaï, et la nuée le couvrit pendant six jours. Et il appela Moïse le septième jour, du milieu de la nuée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Et la gloire de l\'Eternel apparaissait aux fils d\'Israël comme un feu dévorant au sommet de la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Et Moïse entra dans la nuée et monta à la montagne. Et Moïse fut sur la montagne quarante jours et quarante nuits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Et l\'Eternel parla ainsi à Moïse:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Dis aux fils d\'Israël de me faire des offrandes. De tout homme qui y sera disposé vous accepterez l\'offrande qu\'il me fera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Et voici les offrandes que vous accepterez d\'eux: de l\'or, de l\'argent et de l\'airain;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'de la pourpre violette, de la pourpre écarlate, du cramoisi, du lin blanc et du poil de chèvre;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'des peaux de bélier teintes en rouge, des peaux de dauphin et du bois d\'acacia;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'de l\'huile pour le candélabre et des aromates pour l\'huile d\'onction et pour l\'encensement;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'des pierres d\'onyx et des pierres à enchâsser pour l\'éphod et pour le pectoral.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Et ils me feront un sanctuaire pour que j\'habite au milieu d\'eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Vous vous conformerez de tout point au modèle que je te montre de la Demeure et de tous ses meubles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'On fera une arche de bois d\'acacia, de deux coudées et demie de longueur, d\'une coudée et demie de largeur et d\'une coudée et demie de hauteur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'tu la revêtiras d\'or pur; tu l\'en revêtiras en dedans et en dehors et tu la garniras d\'une guirlande d\'or tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Tu fondras quatre boucles d\'or et les mettras à ses quatre pieds, deux boucles d\'un côté et deux de l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Tu feras des barres de bois d\'acacia, et les revêtiras d\'or,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'et tu passeras ces barres dans les boucles le long des côtés de l\'arche pour la porter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Les barres devront rester dans les boucles de l\'arche, on ne les en retirera pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Et tu placeras dans l\'arche le témoignage que je te donnerai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Et tu feras un propitiatoire d\'or pur, de deux coudées et demie de longueur et d\'une coudée et demie de largeur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'et tu feras deux chérubins d\'or, d\'or battu, faisant corps avec les deux bouts du propitiatoire:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'fais un chérubin à un bout et un à l\'autre; c\'est du propitiatoire même que l\'on fera sortir les chérubins, à ses deux bouts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Et les chérubins auront leurs ailes déployées vers le haut, couvrant de leurs ailes le propitiatoire et en face l\'un de l\'autre; les faces des chérubins seront tournées vers le propitiatoire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Et tu mettras le propitiatoire au-dessus de l\'arche et dans l\'arche tu mettras le témoignage, que je te donnerai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'C\'est là que je t\'assignerai et que je te communiquerai de dessus le propitiatoire, d\'entre les deux chérubins placés sur l\'arche du témoignage, tous les ordres que je te donnerai pour les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Tu feras une table de bois d\'acacia de deux coudées de longueur, d\'une coudée de largeur et d\'une coudée et demie de hauteur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'tu la revêtiras d\'or pur et tu l\'entoureras d\'une guirlande d\'or;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'et tu y feras un châssis d\'or, d\'une palme, et tu feras autour du châssis une bordure d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Et tu feras quatre boucles d\'or et tu mettras ces boucles aux quatre coins, aux quatre pieds de la table;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'les boucles seront tout près du châssis et recevront les barres à porter la table.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Tu feras ces barres de bois d\'acacia et tu les revêtiras d\'or; elles serviront à porter la table.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Et tu feras les plats, les godets, les burettes et les patères, avec lesquelles on fera les libations; tu les feras d\'or pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Et tu placeras sur la table le pain de proposition, qui sera devant moi continuellement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Tu feras un candélabre d\'or pur; le candélabre, son pied et sa tige, sera d\'or battu; ses calices, ses boutons et ses fleurs feront corps avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Et six branches partiront de ses côtés, trois branches de candélabre d\'un côté et trois branches de candélabre de l\'autre côté;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'il y aura sur la première branche trois coupes en fleurs d\'amandier, figurant un bouton qui s\'ouvre, et sur la seconde branche trois coupes en fleurs d\'amandier, figurant un bouton qui s\'ouvre, et ainsi pour les six branches partant du candélabre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Et au candélabre même il y aura quatre coupes en fleurs d\'amandier, figurant des boutons qui s\'ouvrent:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'un bouton sous les deux premières branches, un bouton sous les deux suivantes et un bouton sous les deux dernières, ce qui correspondra aux six branches sortant du candélabre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ces boutons et ces tiges feront corps avec lui; le tout sera une seule masse d\'or pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Et tu y feras des lampes au nombre de sept; on les placera dessus et l\'on tournera la lumière vers le devant du chandelier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Tu en feras les mouchettes et les cendriers en or pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'On emploiera un talent d\'or pur pour le faire, avec tous ces objets-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Aie soin de le faire sur le modèle qui t\'en est indiqué sur la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Quant à la Demeure, tu la feras de dix tentures; tu les feras de lin retors, de pourpre violette, de pourpre écarlate et de cramoisi, damassés de chérubins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longueur d\'une tenture sera de vingt-huit coudées, et la largeur de quatre coudées par tenture: la même dimension pour chaque tenture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinq des tentures seront jointes les unes aux autres, et les cinq autres seront aussi jointes les unes aux autres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Et tu mettras des ganses de pourpre violette sur le bord de la dernière tenture de l\'un de ces assemblages, et tu en mettras de même au bord de la dernière tenture du second assemblage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tu en feras cinquante à une tenture et cinquante au bout de la dernière tenture du second assemblage; les ganses seront en face l\'une de l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Et tu feras cinquante agrafes d\'or et tu joindras les tentures l\'une à l\'autre au moyen de ces agrafes, et la Demeure formera un tout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Tu feras aussi des tentures de poil de chèvre, pour servir de tente sur la Demeure: tu les feras au nombre de onze.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'La longueur d\'une tenture sera de trente coudées, et la largeur de quatre coudées par tenture: la même dimension pour chaque tenture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Et tu joindras cinq de ces tentures d\'une part et les six autres d\'autre part, et tu rendoubleras la sixième sur le devant de la Tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Et tu mettras cinquante ganses sur le bord de la dernière tenture d\'un assemblage et cinquante sur le bord de la dernière tenture du second assemblage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Et tu feras cinquante agrafes d\'airain et tu feras entrer les agrafes dans les ganses et tu joindras ainsi la Tente, et elle formera un tout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Et le pan qui sera de surplus dans les tentures de la Tente, savoir la moitié de la tenture de surplus, dépassera sur le derrière de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Et le surplus, en longueur, des tentures de la Tente, une coudée d\'un côté et une coudée de l\'autre, dépassera sur les côtés de la Demeure, de chaque côté, pour la couvrir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Tu feras pour la Tente une couverture en peaux de bélier, teinte en rouge, et une couverture en peaux de dauphin, par dessus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Tu feras aussi les planches de la Demeure, des planches d\'acacia posées debout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Chaque planche aura dix coudées de longueur et une coudée et demie de largeur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Chaque planche aura deux tenons qui seront rejoints l\'un à l\'autre; tu en feras à toutes les planches de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Tu feras donc les planches pour la Demeure: vingt planches pour la face au midi, à droite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Et sous ces vingt planches tu placeras quarante socles d\'argent, deux socles sous chaque planche pour ses deux tenons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Et pour le second côté de la Demeure, pour la face septentrionale, vingt planches');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'avec leurs quarante socles d\'argent, deux socles sous chaque planche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Et pour le fond de la Demeure, tourné à l\'occident, tu feras six planches.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Et tu feras deux planches pour les coins de la Demeure, dans le fond:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'elles seront pareilles depuis le bas, et toutes deux seront complètes jusqu\'à leur sommet vers le premier anneau; il en sera ainsi pour les deux; elles seront placées aux deux coins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Il y aura donc huit planches avec leurs socles d\'argent, seize socles, deux sous chaque planche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Et tu feras cinq traverses de bois d\'acacia pour les planches de l\'un des côtés de la Demeure');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'et cinq traverses pour les planches de l\'autre côté et cinq traverses pour les planches du côté du fond, à l\'occident.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Et la traverse du milieu traversera les planches par le milieu, d\'un bout à l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Et tu revêtiras d\'or les planches, et tu en feras en or les anneaux qui recevront les traverses, et tu revêtiras d\'or les traverses.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Tu érigeras la Demeure d\'après le plan qui t\'a été montré sur la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Tu feras un voile de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors. On le fera damassé de chérubins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Et tu le suspendras à quatre piliers d\'acacia revêtus d\'or et à clous d\'or, et posés sur quatre socles d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Et tu placeras le voile sous les agrafes et tu feras entrer là, derrière le voile, l\'arche du témoignage, et le voile fera pour vous une séparation entre le Lieu saint et le Lieu très saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Et tu placeras le propitiatoire sur l\'arche du témoignage dans le Lieu très saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Et tu placeras la table devant le voile, et le candélabre vis-à-vis de la table, du côté du midi, et tu poseras la table du côté du nord.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Et tu feras un rideau à l\'entrée de la Tente, en pourpre violette, pourpre écarlate, cramoisi et lin retors, en ouvrage broché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Et tu feras pour le rideau cinq piliers d\'acacia, et tu les revêtiras d\'or, et les clous en seront d\'or, et tu fondras pour ces piliers cinq socles d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Et tu feras l\'autel en bois d\'acacia, de cinq coudées de longueur et de cinq coudées de largeur. L\'autel sera carré et de la hauteur de trois coudées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Et tu feras ses cornes à ses quatre coins; les cornes feront corps avec lui; et tu le revêtiras d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Et tu feras les chaudrons pour recueillir les cendres, les pelles, les bassins, les fourches et les brasiers: pour tous ces objets tu emploieras l\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Et tu feras à l\'autel une grille; ce sera un treillis, d\'airain; et tu feras à ce treillis quatre anneaux d\'airain aux quatre bouts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Et tu le placeras sous la corniche de l\'autel, dans la partie inférieure, et ce treillis ira jusqu\'à mi-hauteur de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Et tu feras des barres pour l\'autel, des barres de bois d\'acacia et tu les revêtiras d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Et on fera passer ces barres dans les anneaux, et les barres seront aux deux côtés de l\'autel, quand on le transportera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tu le feras creux, en planches. On le fera comme on te l\'a fait voir sur la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Et tu feras le parvis de la Demeure. Pour le côté, du midi, à droite, les toiles du parvis, en lin retors, auront cent coudées de longueur sur un côté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Ce côté aura vingt piliers, et leurs socles, au nombre de vingt, seront d\'airain, et les clous des piliers et leurs tringles seront d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'De même, pour le côté du nord, en longueur, des toiles de cent coudées de long et vingt piliers avec leurs vingt socles d\'airain; les clous des piliers et les tringles seront d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Et pour la largeur du parvis, sur le côté de l\'occident, des toiles de cinquante coudées, et leurs dix piliers avec leurs dix socles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Et la largeur du parvis sur le devant, à l\'orient, sera de cinquante coudées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Et quinze coudées de toiles, d\'une part, et leurs trois piliers avec leurs trois socles,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'et d\'autre part aussi quinze [coudées] de toiles, et leurs trois piliers avec leurs trois socles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Et pour la porte du parvis, un rideau de vingt coudées, en pourpre violette, pourpre écarlate, cramoisi, lin retors, broché, et ses quatre piliers avec leurs quatre socles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Tous les piliers entourant le parvis auront des tringles d\'argent et leurs clous d\'argent, et leurs socles seront d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'La longueur du parvis sera de cent coudées, la largeur de cinquante de chaque côté, et la hauteur de cinq coudées, en lin retors, et les socles seront d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Tous les ustensiles de la Demeure, pour tout son service, toutes ses chevilles et toutes les chevilles du parvis seront d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Et toi, tu ordonneras aux fils d\'Israël de t\'apporter pour le luminaire de l\'huile pure d\'olives pilées, pour entretenir constamment des lampes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Dans la Tente d\'assignation, en dehors du voile qui est devant le témoignage, Aaron et ses fils la prépareront pour brûler du soir au matin devant l\'Eternel: redevance perpétuelle de la part des fils d\'Israël, de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Et toi, fais approcher de toi, du milieu des fils d\'Israël, Aaron ton frère et ses fils avec lui, pour qu\'il me serve comme sacrificateur: Aaron, Nadab et Abihu, Eléazar et Ithamar, fils d\'Aaron.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Et tu feras à Aaron ton frère des vêtements sacrés pour insignes et pour parure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Tu t\'adresseras à tous les hommes habiles que j\'ai remplis d\'un esprit de sagesse, et ils feront les vêtements d\'Aaron, afin de le consacrer, pour qu\'il me serve comme sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Voici les vêtements qu\'ils feront: un pectoral, un éphod, un surplis, une tunique à mailles, une tiare et une ceinture: ils feront ces vêtements sacrés pour Aaron ton frère et pour ses fils, afin qu\'il me serve comme sacrificateur:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'ils y emploieront de l\'or, de la pourpre violette, de la pourpre écarlate, du cramoisi et du lin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Ils feront l\'éphod d\'or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors, en brocart.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Il aura à ses deux extrémités deux épaulettes qui se joindront, et ainsi il sera joint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Et la bande qui y sera pour l\'attacher, sera de la même étoffe et fera corps avec lui: elle sera d\'or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Et tu prendras deux pierres d\'onyx sur lesquelles tu graveras les noms des fils d\'Israël:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'six de leurs noms sur la première pierre et les six autres noms sur la seconde pierre, selon leur naissance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Tu graveras sur ces deux pierres les noms des fils d\'Israël, comme on grave en creux les pierres servant de cachets; tu les enchâsseras dans des chatons d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Et tu placeras les deux pierres sur les épaulettes de l\'éphod comme pierres de mémorial des fils d\'Israël, et Aaron portera leurs noms devant l\'Eternel, sur les deux épaules, en mémorial.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Et tu feras des chatons d\'or');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'et deux chaînes d\'or pur, que tu feras en torsades à la façon de cordons, et tu placeras ces chaînes tressées en cordons sur les chatons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Tu feras un pectoral de jugement, en brocart; tu le feras du même travail que l\'éphod: tu le feras d\'or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Il sera carré et double, d\'un empan de long et d\'un empan de large.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Tu le garniras d\'une garniture de pierreries: quatre rangées de pierreries. Sur une rangée: une sardoine, une topaze, une émeraude, voilà la première rangée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'La seconde rangée: un rubis, un saphir et une calcédoine.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'La troisième rangée: une opale, une agate et une améthyste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'La quatrième rangée: une chrysolithe, un onyx et un jaspe. Elles seront enchâssées dans des garnitures d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Ces pierres correspondront aux noms des fils d\'Israël: il y en aura douze selon le nombre de leurs noms: elles seront gravées comme des cachets, chacune avec le nom d\'une des douze tribus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Tu feras pour le pectoral des chaînes en torsades, en façon de cordons, d\'or pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Et tu feras pour le pectoral deux anneaux d\'or, et tu mettras ces deux anneaux aux deux extrémités du pectoral.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Et tu fixeras les deux cordons d\'or aux deux anneaux placés aux extrémités du pectoral,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'et tu attacheras les deux bouts des deux cordons sur les deux chatons, et tu les mettras sur les deux épaulettes de l\'éphod par devant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Et tu feras deux anneaux d\'or que tu mettras aux deux extrémités du pectoral, sur le bord qui est tourné, vers l\'éphod en dedans;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'et tu feras deux anneaux d\'or que tu mettras aux deux épaulettes de l\'éphod, en bas, en dehors, près de sa jonction, au-dessus de la bande de l\'éphod.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'On fixera le pectoral en joignant ses anneaux aux anneaux de l\'éphod par un cordonnet de pourpre violette, pour qu\'il soit au-dessus de la bande de l\'éphod, et que le pectoral ne branle pas de dessus l\'éphod.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Et par ce pectoral de jugement, Aaron, lorsqu\'il entrera dans le sanctuaire, portera sur son cœur les noms des fils d\'Israël, en commémoration constante devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Et tu mettras dans le pectoral de jugement les Urim et les Thummim, et ils seront sur le cœur d\'Aaron lorsqu\'il entrera devant l\'Eternel, et Aaron portera constamment sur son cœur, devant l\'Eternel, le jugement des fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Tu feras le surplis de l\'éphod tout entier en pourpre violette:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'il aura au milieu une ouverture pour la tête, autour de laquelle il y aura un ourlet tissé comme à l\'ouverture d\'une cotte d\'armes, afin qu\'il ne se déchire pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Et tu mettras au bord inférieur des grenades de pourpre violette, de pourpre écarlate et de cramoisi tout autour du bord, et des clochettes d\'or entremêlées, tout autour:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'une clochette d\'or et une grenade, une clochette d\'or et une grenade au bas du surplis, tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Aaron le mettra pour officier, et le son s\'en fera entendre lorsqu\'il entrera dans le Sanctuaire devant l\'Eternel, et lorsqu\'il en sortira, et il ne mourra point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Et tu feras une lame d\'or pur et la graveras comme on grave sur les cachets: CONSÉCRATION A L\'ETERNEL.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Et tu y mettras un cordonnet de pourpre violette, et elle sera sur la tiare: elle doit être sur le devant de la tiare.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Et elle sera sur le front d\'Aaron, et Aaron portera les fautes commises dans les choses saintes que consacreront les fils d\'Israël en toute espèce d\'oblations saintes; et elle sera sur son front constamment devant l\'Eternel, pour qu\'ils soient agréés devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Tu feras à mailles la tunique, en lin; tu feras une tiare de lin et tu feras une ceinture en broderie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Et quant aux fils d\'Aaron, tu leur feras des tuniques, et tu leur feras des ceintures et des mitres, pour insignes et pour parure:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'tu en revêtiras Aaron ton frère et ses fils avec lui; tu les oindras, tu les installeras et tu les consacreras, et ils me serviront comme sacrificateurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Fais-leur aussi des caleçons de toile pour couvrir leur nudité: ils devront aller des reins jusqu\'aux cuisses,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'et Aaron et ses fils les porteront quand ils entreront dans la Tente d\'assignation ou quand ils s\'approcheront de l\'autel pour officier dans le Lieu saint, de peur qu\'ils ne se rendent coupables et ne meurent: ordonnance perpétuelle pour Aaron et pour sa postérité après lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Et voici ce que tu leur feras pour les consacrer à mon service comme sacrificateurs. Prends un jeune taureau et deux béliers sans défaut;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'du pain sans levain, des galettes sans levain pétries à l\'huile et des oublies sans levain ointes d\'huile, que tu feras de fleur de farine de froment;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'tu les mettras dans une seule corbeille et tu les présenteras dans la corbeille, en même temps que le taureau et les deux béliers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Et tu feras avancer Aaron et ses fils à l\'entrée de la Tente d\'assignation et tu les laveras d\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Et tu prendras les vêtements et tu revêtiras Aaron de la tunique, du surplis de l\'éphod, de l\'éphod et du pectoral, et tu le ceindras de la bande de l\'éphod.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Et tu placeras la tiare sur sa tête et tu mettras sur la tiare le saint diadème.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Tu prendras l\'huile d\'onction et tu la verseras sur sa tête et l\'oindras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Et tu feras avancer ses fils et les revêtiras de tuniques.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Et tu mettras une ceinture à Aaron et à ses fils et tu leur attacheras des mitres; et la sacrificature leur appartiendra par ordonnance perpétuelle, et tu installeras Aaron et ses fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Et tu feras avancer le taureau devant la Tente d\'assignation, et Aaron et ses fils appuieront leurs mains sur la tête du taureau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Et tu égorgeras le taureau devant l\'Eternel à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Et tu prendras du sang du taureau et tu en mettras avec le doigt sur les cornes de l\'autel et tu répandras tout le sang au pied de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Et tu prendras toute la graisse qui couvre les entrailles, le grand lobe du foie, les deux rognons et la graisse qui est dessus, et tu feras fumer cela sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Et la chair du taureau, sa peau et sa fiente, tu les brûleras hors du camp: c\'est un sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Puis tu prendras l\'un des béliers, et Aaron et ses fils appuieront leurs mains sur la tête du bélier,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'et tu égorgeras le bélier, et tu prendras son sang et en arroseras l\'autel tout autour;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'et le bélier, tu le découperas en ses pièces; et tu laveras ses entrailles et ses jambes et les mettras sur ses pièces et sur sa tête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Et tu feras fumer sur l\'autel tout le bélier: c\'est un holocauste à l\'Eternel, d\'agréable odeur, un sacrifice fait par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Puis tu prendras le second bélier, et Aaron et ses fils appuieront leurs mains sur la tête du bélier,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'et tu égorgeras le bélier et tu prendras de son sang et en mettras sur le bout de l\'oreille droite d\'Aaron, sur le bout de l\'oreille droite de ses fils, sur le pouce de leur main droite et sur l\'orteil de leur pied droit, et tu arroseras de sang l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Et tu prendras du sang qui sera sur l\'autel et de l\'huile d\'onction, et tu en feras aspersion sur Aaron et sur ses vêtements, et aussi sur ses fils et sur les vêtements de ses fils, et ainsi il sera consacré, lui et ses vêtements, ainsi que ses fils et les vêtements de ses fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Et tu prendras du bélier la graisse, la queue, la graisse qui couvre les entrailles, le grand lobe du foie, les deux rognons et la graisse qui y est, l\'épaule droite (car c\'est un bélier d\'installation),');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'avec une miche de pain, une galette à l\'huile et une oublie de la corbeille des pains sans levain placée devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Tu poseras toutes ces choses sur les paumes des mains d\'Aaron et sur les paumes des mains de ses fils et tu les balanceras comme offrande balancée devant, l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Et tu les prendras de leurs mains et les feras brûler sur l\'autel par-dessus l\'holocauste, en agréable odeur devant l\'Eternel: c\'est un sacrifice fait par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Et tu prendras la poitrine du bélier de l\'installation d\'Aaron, et tu la balanceras comme offrande balancée devant l\'Eternel et ce sera ta part.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Et tu consacreras de ce qui revient à Aaron et à ses fils la poitrine balancée et l\'épaule élevée, [à savoir] ce qui du bélier d\'installation aura été balancé et élevé:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'ce sera pour Aaron et pour ses fils une redevance à perpétuité de la part des fils d\'Israël, car c\'est une offrande élevée; et les fils d\'Israël auront à prélever une offrande de leurs sacrifices d\'actions de grâces; ce sera leur offrande prélevée pour l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Et les vêtements sacrés d\'Aaron seront après lui pour ses fils, afin qu\'ils en soient revêtus quand on les oindra et les installera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Celui de ses fils qui lui succédera comme sacrificateur, et qui entrera dans la Tente d\'assignation pour officier dans le Lieu saint, les portera pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Et tu prendras le bélier d\'installation et en feras cuire la chair en lieu saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Et Aaron et ses fils mangeront à l\'entrée de la Tente d\'assignation la chair du bélier et le pain qui est dans la corbeille:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'ils mangeront ce qui a servi à faire la propitiation pour les installer en les consacrant. Un étranger n\'en mangera pas, car ce sont choses sacrées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Et s\'il reste jusqu\'au lendemain de la chair de l\'installation et du pain, tu brûleras ce reste: on ne le mangera pas, car c\'est chose sacrée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tu feras pour Aaron et pour ses fils selon tout ce que je t\'ai ordonné: tu les installeras durant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Tu offriras chaque jour un taureau comme victime pour le péché, pour faire propitiation: tu enlèveras de l\'autel le péché par la propitiation que tu feras pour lui, et tu l\'oindras pour le consacrer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Pendant sept jours tu feras propitiation pour l\'autel et tu le consacreras, et l\'autel sera très saint: tout ce qui touchera l\'autel sera sacré.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Et voici ce que tu offriras sur l\'autel: deux agneaux d\'un an, chaque jour, à perpétuité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Tu offriras l\'un de ces agneaux le matin et tu offriras l\'autre agneau dans la soirée;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'tu y joindras un dixième de fleur de farine pétrie avec un quart de hin d\'huile vierge, et une libation d\'un quart de hin de vin: voilà pour le premier agneau;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'le second, tu l\'offriras dans la soirée; tu l\'accompagneras de la même oblation et de la même libation que le matin: c\'est un sacrifice d\'agréable odeur fait par le feu à l\'Eternel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'un holocauste perpétuel offert par vous de génération en génération, à l\'entrée de la Tente d\'assignation devant l\'Eternel, là où je me rencontrerai avec vous pour t\'y parler.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Je me rencontrerai là avec les fils d\'Israël, et ce lieu sera consacré par ma gloire,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'et je consacrerai la Tente d\'assignation et l\'autel, et je consacrerai Aaron et ses fils pour qu\'ils me servent comme sacrificateurs;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'j\'habiterai au milieu des fils d\'Israël et je serai leur Dieu,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'et ils sauront que moi, l\'Eternel, je suis le Dieu qui les ai fait sortir du pays d\'Egypte pour habiter au milieu d\'eux, moi l\'Eternel, leur Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Et tu feras un autel pour faire fumer l\'encens: tu le feras de bois d\'acacia,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'd\'une coudée de long et d\'une coudée de large; il doit être carré et de deux coudées de hauteur; ses cornes feront corps avec lui,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'et tu le revêtiras d\'or pur, le dessus, les parois tout autour et les cornes, et tu le garniras d\'une guirlande d\'or tout autour,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'et tu y adapteras deux anneaux d\'or, au-dessous de la guirlande, sur les deux arêtes: tu les mettras aux deux côtés, et ils serviront à recevoir les barres pour le porter;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'et tu feras les barres de bois d\'acacia et les revêtiras d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Tu placeras l\'autel devant le voile qui cache l\'arche du témoignage et le propitiatoire qui est sur le témoignage, là où je me rencontrerai avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Et Aaron y fera fumer l\'encens: chaque matin, quand il arrangera les lampes, il fera cet encensement;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'et dans la soirée, quand Aaron mettra les lampes en place, il le fera encore. C\'est un encensement perpétuel que vous ferez devant l\'Eternel de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Vous n\'y offrirez pas de parfum profane, ni d\'holocauste et d\'oblation, et vous n\'y ferez pas de libation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Aaron fera une fois l\'an propitiation sur les cornes de l\'autel avec le sang de la victime pour le péché offerte en propitiation. Une fois l\'an il fera propitiation pour l\'autel de génération en génération. Cet autel sera très saint à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Et l\'Eternel parla à Moïse en ces termes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Lorsque tu feras le compte des fils d\'Israël, en les dénombrant, chacun d\'eux donnera à l\'Eternel la rançon de sa personne, quand on les dénombrera, afin qu\'il n\'y ait point sur eux de fléau quand on les dénombrera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Voici ce que donnera quiconque sera compris dans le dénombrement: un demi-sicle, selon le sicle sacré qui est de vingt guéras; un demi-sicle sera la contribution pour l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Quiconque sera compris dans le dénombrement, depuis l\'âge de vingt ans et au-dessus, donnera la contribution de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Le riche ne donnera pas plus et le pauvre ne donnera pas moins qu\'un demi-sicle, en acquit de la contribution de l\'Eternel comme rançon de vos personnes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Tu recevras des fils d\'Israël l\'argent de cette rançon et tu l\'emploieras au service de la Tente d\'assignation, et ce sera pour les fils d\'Israël le titre de la rançon de leurs personnes, devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Et l\'Eternel parla à Moïse en ces termes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Tu feras aussi une cuve d\'airain et son piédestal d\'airain pour les ablutions; tu la placeras entre la Tente d\'assignation et l\'autel et tu y mettras de l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Et Aaron et ses fils en prendront pour laver leurs mains et leurs pieds.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Lorsqu\'ils entreront dans la Tente d\'assignation, ils se laveront d\'eau et ils ne mourront pas; et aussi lorsqu\'ils approcheront de l\'autel pour officier en faisant fumer un sacrifice fait par le feu à l\'Eternel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'ils laveront leurs mains et leurs pieds, et ils ne mourront pas: ordonnance perpétuelle pour eux, pour Aaron et sa postérité, de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Et l\'Eternel parla à Moïse en ces termes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Et toi, prends des aromates exquis: de myrrhe vierge, cinq cents sicles; de cinnamome, la moitié, soit deux cent cinquante; de roseau odorant, deux cent cinquante;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'de casse, cinq cents, pesé en sicles sacrés, et d\'huile d\'olives, un hin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Tu en feras une huile d\'onction sainte, un parfum composé selon l\'art du parfumeur; ce sera une huile d\'onction sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Tu en oindras la Tente d\'assignation et l\'arche du témoignage,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'la table avec tous ses ustensiles, le candélabre avec ses ustensiles, l\'autel des parfums,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'l\'autel des holocaustes avec tous ses ustensiles et le bassin avec son piédestal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Tu les consacreras, et ils seront très saints. Tout ce qui les touchera sera saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Tu oindras aussi Aaron et ses fils et tu les consacreras pour me servir comme sacrificateurs,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'et tu parleras ainsi aux fils d\'Israël: Ce sera l\'huile d\'onction sainte, elle m\'appartiendra de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Elle ne doit pas couler sur le corps d\'un homme, et vous n\'en ferez pas une pareille, de même composition. C\'est chose sacrée: ce doit être pour vous chose sacrée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Celui qui en composera une pareille et celui qui en mettra sur un profane sera retranché du milieu des siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Et l\'Eternel dit à Moïse: Prends des aromates, résine, coquille odorante, galbanum. Arômes et encens pur seront par doses égales.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Et tu en feras un parfum pour l\'encensement, composé selon l\'art du parfumeur, un parfum salé, pur, saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Tu le réduiras en poudre et tu en mettras devant le témoignage dans la Tente d\'assignation où je me rencontrerai avec toi. Ce sera pour vous une chose très sainte;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'et le parfum que tu feras, vous n\'en ferez pas pour vous de même composition: il sera pour toi chose sacrée appartenant à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Celui qui en fera un pareil pour en respirer l\'odeur sera retranché du milieu des siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Et l\'Eternel parla à Moïse en ces termes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Vois, j\'ai appelé par son nom Betsaléel, fils d\'Uri, fils de Hur, de la tribu de Juda,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'et je l\'ai rempli d\'esprit divin, d\'habileté, d\'intelligence, de savoir pour toutes sortes d\'ouvrages,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'pour faire des combinaisons, pour travailler l\'or, l\'argent et l\'airain,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'pour graver des pierres à enchâsser, pour sculpter le bois, de manière à exécuter toute espèce de travaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Et voici, je lui ai adjoint Oholiab, fils d\'Achisamac, de la tribu de Dan, et dans l\'esprit de tout homme habile j\'ai mis de l\'habileté pour qu\'ils exécutent tout ce que je t\'ai ordonné:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'la Tente d\'assignation, l\'arche du témoignage, le propitiatoire qui est dessus et tous les meubles de la Tente,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'la table et ses ustensiles, le candélabre [d\'or] pur et tous ses ustensiles, l\'autel des parfums,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'l\'autel des holocaustes et tous ses ustensiles, le bassin et son piédestal,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'les vêtements de cérémonie et les vêtements sacrés pour Aaron le sacrificateur, et les vêtements de ses fils pour les fonctions du sacerdoce,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'et l\'huile d\'onction et le parfum pour l\'encensement pour le Lieu saint. Ils exécuteront tout, comme je te l\'ai ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Et l\'Eternel parla à Moïse en ces termes:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Pour toi, parle ainsi aux fils d\'Israël: Seulement, observez mes sabbats; car c\'est là un signe entre moi et vous de génération en génération pour que vous sachiez que c\'est moi, l\'Eternel, qui vous sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Vous observerez le sabbat, car c\'est une chose sainte pour vous. Celui qui le violera doit être mis à mort; car quiconque fera un travail dans ce jour-là, cette personne-là sera retranchée du milieu des siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'On doit travailler six jours, et le septième jour sera un jour de complet repos, consacré à l\'Eternel. Quiconque fera un travail le jour du repos sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Les fils d\'Israël observeront le sabbat en le célébrant de génération en génération comme une alliance perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Entre moi et les fils d\'Israël, c\'est un signe à perpétuité; car en six jours l\'Eternel a fait les cieux et la terre, et le septième jour il a cessé et s\'est reposé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Après avoir achevé de s\'entretenir avec Moïse sur le mont Sinaï, l\'Eternel lui donna les deux tables du témoignage, tables de pierre écrites du doigt de Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Et le peuple, voyant que Moïse tardait à descendre de la montagne, s\'assembla autour d\'Aaron, et ils lui dirent: Allons! Fais-nous un dieu qui marche devant nous; car celui-là, Moïse, l\'homme, qui nous a fait sortir du pays d\'Egypte, nous ne savons ce qu\'il est devenu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Et Aaron leur dit: Arrachez les boucles d\'or qui sont aux oreilles de vos femmes, de vos fils et de vos filles, et apportez-les moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Et tout le monde arracha les boucles d\'or qu\'ils avaient aux oreilles et ils les apportèrent à Aaron.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Celui-ci reçut d\'eux cet or, le travailla au burin et en fit un veau de métal. Et ils dirent: C\'est ici ton Dieu, Israël, qui t\'a fait sortir du pays d\'Egypte!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Aaron, voyant cela, construisit un autel devant le veau; puis Aaron s\'écria et dit: Demain il y aura fête à l\'honneur de l\'Eternel!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Et le lendemain ils s\'empressèrent d\'offrir des holocaustes et de faire des sacrifices d\'actions de grâces. Et le peuple s\'assit pour manger et boire, puis on se leva pour se divertir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Et l\'Eternel dit à Moïse: Va, descends, car ton peuple, que tu as fait sortir d\'Egypte, se conduit mal!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Ils ont bien vite quitté la voie que je leur avais prescrite. Ils se sont fait un veau de métal, se sont prosternés devant lui et lui ont sacrifié, et ils ont dit: C\'est ici ton Dieu, Israël, qui t\'a fait sortir du pays d\'Egypte!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'L\'Eternel dit encore à Moïse: J\'ai vu ce peuple, et voici c\'est un peuple au cou roide.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Et maintenant, laisse ma colère s\'embraser contre eux et que je les consume! Et je ferai de toi une grande nation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Et Moïse chercha à apaiser l\'Eternel, son Dieu, en disant: Pourquoi, Eternel, ta colère s\'embraserait-elle contre ton peuple que tu as tiré du pays d\'Egypte par une grande puissance et d\'une main forte?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Pourquoi les Egyptiens diraient-ils: C\'est pour leur faire du mal qu\'il les en a tirés, pour les tuer dans les montagnes et les anéantir de dessus la face de la terre? Reviens de l\'ardeur de ta colère et repens-toi du mal que tu veux faire à ton peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Souviens-toi d\'Abraham, d\'Isaac et d\'Israël, tes serviteurs, auxquels tu as juré par toi-même et auxquels tu as dit: Je rendrai votre postérité aussi nombreuse que les étoiles du ciel, et tout ce pays dont j\'ai parlé, je le donnerai à votre postérité, et elle le possédera pour toujours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Et l\'Eternel se repentit du mal qu\'il avait parlé de faire à son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Et Moïse revint et descendit de la montagne, les deux tables du témoignage en sa main, tables écrites des deux côtés. Sur l\'une et sur l\'autre face elles étaient écrites,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'et ces tables étaient l\'ouvrage de Dieu, et l\'écriture, l\'écriture de Dieu, gravée sur les tables.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Et Josué entendit le bruit que faisait le peuple en poussant des cris et il dit à Moïse: Il y a un bruit de bataille dans le camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Et Moïse dit: Ce n\'est pas un bruit de cris de victoire ni un bruit de cris de défaite. J\'entends un bruit de gens qui chantent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Et quand il fut près du, camp, il vit le veau et les danses. Et Moïse fut enflammé de courroux et il jeta les tables et les brisa au pied de la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Puis il prit le veau qu\'ils avaient fait, le brûla et le broya de manière à le réduire en poudre, la répandit sur l\'eau et fit boire les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Et Moïse dit à Aaron: Que t\'a fait ce peuple, pour que tu aies amené sur lui un si grand péché?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron dit: Que mon seigneur ne se courrouce pas! Tu sais toi-même comme ces gens sont mauvais.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Ils m\'ont dit: Fais-nous un dieu qui marche devant nous; car celui-là, Moïse, l\'homme qui nous a fait sortir du pays d\'Egypte, nous ne savons ce qu\'il est devenu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Et je leur ai dit: Que ceux qui ont de l\'or s\'en dépouillent! Et ils m\'en ont donné, je l\'ai mis au feu et il en est sorti ce veau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Et Moïse vit que le peuple n\'avait plus de frein, et qu\'Aaron en lui ôtant tout frein l\'exposait à la risée de ses ennemis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Et Moïse se plaça à la porte du camp et il dit: A moi, ceux qui sont pour l\'Eternel! Alors tous les fils de Lévi se réunirent à lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Et il leur dit: Ainsi a dit l\'Eternel, Dieu d\'Israël: Que chacun de vous ceigne son épée! Passez et repassez dans le camp, d\'une porte à l\'autre, et que chacun tue son frère, son ami, son parent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Les fils de Lévi firent ce que disait Moïse et il périt du peuple en ce jour là environ trois mille hommes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Et Moïse dit: Consacrez-vous aujourd\'hui à l\'Eternel, puisque [vous avez combattu] chacun contre son fils et son frère, et vous recevrez aujourd\'hui une bénédiction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Et le lendemain Moïse dit au peuple: Pour vous, vous avez commis un grand péché. Maintenant je monterai vers l\'Eternel peut-être obtiendrai-je le pardon de votre péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Et Moïse retourna vers l\'Eternel et dit: Ah! ce peuple a commis un grand péché, il s\'est fait un dieu d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Et maintenant pardonne ce péché ou, sinon, efface-moi de ton livre, que tu as écrit!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Et l\'Eternel dit à Moïse: Celui qui a péché contre moi, c\'est lui que j\'effacerai de mon livre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Maintenant va, conduis ce peuple où je t\'ai dit. Voici, mon ange ira devant toi, et au jour où je jugerai, je jugerai sur eux leur péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Et l\'Eternel frappa le peuple, parce qu\'il était l\'auteur du veau qu\'Aaron avait fait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Et l\'Eternel dit à Moïse: Va, monte d\'ici, toi et le peuple que tu as tiré du pays d\'Egypte, [et va] au pays que j\'ai promis avec serment à Abraham, à Isaac et à Jacob, en disant: Je le donnerai à ta postérité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'J\'enverrai devant toi un ange et je chasserai le Cananéen, l\'Amorrhéen, le Héthien, le Phérézien, le Hévien et le Jébusien,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '[il vous conduira] dans un pays découlant de lait et de miel: car je ne veux point marcher au milieu de vous, qui êtes un peuple au cou roide, pour ne pas t\'anéantir en chemin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Et le peuple entendit cette parole funeste; et l\'on prit le deuil, et personne ne mit sur soi sa parure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Et l\'Eternel avait dit à Moïse: Dis aux fils d\'Israël: Vous êtes des gens au cou roide; si un seul instant je marchais au milieu de vous, je vous anéantirais. Dépose donc tes parures, que je sache ce que j\'ai à faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Et les fils d\'Israël se dépouillèrent de leurs parures dès le mont Horeb.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Et Moïse prit la tente et se la dressa hors du camp, loin du camp, et il l\'appela Tente d\'assignation; et quiconque voulait consulter l\'Eternel, se rendait à la Tente d\'assignation, qui était hors du camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Et quand Moïse sortait pour aller à cette Tente, tout le monde se levait et se tenait chacun à l\'entrée de sa tente et on suivait Moïse du regard jusqu\'à ce qu\'il entrât dans la Tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Et quand Moïse entrait dans la Tente, la colonne de nuée descendait et s\'arrêtait à l\'entrée de la Tente, et l\'Eternel parlait avec Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Et tout le monde voyait la colonne de nuée arrêtée à la porte de la Tente et tout le monde se levait et se prosternait chacun à l\'entrée de sa tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Et l\'Eternel parlait à Moïse face à face, comme un homme parle à un autre. Puis Moïse retournait au camp; mais son serviteur Josué, fils de Nun, jeune homme, ne bougeait pas de l\'intérieur de la Tente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Et Moïse dit à l\'Eternel: Voilà que tu me dis: Fais monter ce peuple... et tu ne me fais pas connaître celui que tu enverras, avec moi! Tu m\'avais dit pourtant: Je te connais par ton nom et tu as trouvé grâce à mes yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Eh bien! si j\'ai trouvé grâce à tes yeux, daigne me faire connaître tes voies! Oui, que je te connaisse, pour que je trouve grâce à tes yeux! Et considère que cette nation-là est ton peuple!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Et il répondit: Ma face ira et je te mettrai en repos.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Et Moïse dit: Si ta face ne vient, ne nous fais pas partir d\'ici.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'A quoi donc reconnaîtra-t-on que j\'ai trouvé grâce à tes yeux, moi et ton peuple? N\'est-ce pas à ce que tu marches avec nous? C\'est ce qui nous distinguera, moi et ton peuple, de tous les peuples qui sont sur la face de la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Et l\'Eternel dit à Moïse: Même cette chose que tu as dite, je la ferai, parce que tu as trouvé grâce à mes yeux et que je te connais par ton nom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Et Moïse dit: Je te prie, fais-moi voir ta gloire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Et il répondit: Je ferai passer devant toi toute ma bonté, et je prononcerai le nom de l\'Eternel devant toi, et j\'accorderai ma grâce à qui j\'accorderai ma grâce, et je ferai miséricorde à qui je ferai miséricorde.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Il dit encore: Tu ne pourras pas voir ma face, car l\'homme ne peut me voir et vivre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'L\'Eternel dit encore: Il y a là une place près de moi; tu te tiendras sur le rocher,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'et quand passera ma gloire, je te mettrai dans le creux du rocher et te couvrirai de ma main, jusqu\'à ce que j\'aie passé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Alors je retirerai ma main et tu me verras par derrière, mais ma face ne se verra pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Et l\'Eternel dit à Moïse: Taille-toi deux tables de pierre comme les premières, et j\'écrirai sur ces tables les paroles qui étaient sur les premières tables que tu as brisées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Sois prêt pour demain matin; monte le matin au mont Sinaï et présente-toi là devant moi au sommet de la montagne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Personne ne montera avec toi. Que personne même ne se montre nulle part sur la montagne. Que même ni menu ni gros bétail ne paisse du côté de cette montagne!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Et Moïse tailla deux tables de pierre comme les premières, et le lendemain de bonne heure il monta sur le mont Sinaï, comme l\'Eternel le lui avait ordonné, et il prit en sa main les deux tables de pierre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Et l\'Eternel descendit dans la nuée, et se tint là avec lui et prononça le nom de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Et l\'Eternel passa devant lui et prononça [ces paroles]: L\'Eternel, l\'Eternel, Dieu compatissant et miséricordieux, lent à la colère et abondant en grâce et en vérité;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'qui conserve sa grâce à mille générations; qui pardonne le crime, la défection et le péché; mais il ne les laisse pas impunis, poursuivant l\'iniquité des pères sur les fils et sur les fils des fils, sur la troisième et la quatrième génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Aussitôt Moïse s\'inclina contre terre et se prosterna,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'et il dit: Ah! si j\'ai trouvé grâce à tes yeux, Seigneur, que le Seigneur daigne marcher au milieu de nous, car c\'est un peuple au cou roide que celui-ci, et pardonne nos crimes et nos péchés et fais de nous ton héritage!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Il répondit: Voici je fais une alliance: En présence de tout ton peuple je ferai des miracles qui n\'ont encore eu lieu dans aucun pays et chez aucune nation, et tout le peuple qui t\'entoure verra l\'œuvre de l\'Eternel; car c\'est une chose redoutable que celle que je fais avec toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Prends garde à ce que je t\'ordonne aujourd\'hui. Je vais chasser de devant toi l\'Amorrhéen, le Cananéen, le Héthien, le Phérézien, le Hévien et le Jébusien.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Garde-toi de traiter avec les habitants du pays contre lequel tu marches, de peur qu\'ils ne deviennent un piège au milieu de vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Au contraire, leurs autels, vous les renverserez; leurs colonnes, vous les briserez; leurs idoles, vous les abattrez;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'car tu ne te prosterneras point devant un autre dieu, parce que l\'Eternel se nomme le Jaloux; il est un Dieu jaloux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ne traite donc point avec les habitants du pays; quand ils se prostituent à leurs dieux et qu\'ils font des sacrifices à leurs dieux, ils t\'inviteraient et tu mangerais de ce qu\'ils ont sacrifié;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'et tu prendrais de leurs filles pour tes fils, et leurs filles, se prostituant à leurs dieux, entraîneraient tes fils à se prostituer aussi à eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Tu ne te feras pas de dieu de métal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Tu observeras la fête des pains sans levain comme je l\'ai prescrit. Tu mangeras pendant sept jours des pains sans levain au temps fixé du mois d\'Abib, car c\'est au mois d\'Abib que tu es sorti d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Tout premier produit du sein maternel m\'appartient, et aussi tout premier produit mâle de ton bétail, bœuf ou menu bétail');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'et le premier produit de l\'âne, tu le rachèteras par une pièce de menu bétail, et si tu ne le rachètes pas, tu lui casseras le col. Tout premier-né de tes fils, tu le rachèteras, et l\'on ne paraîtra pas devant moi les mains vides.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Tu travailleras six jours, mais le septième jour tu chômeras; pendant le labour et la moisson tu chômeras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Tu célébreras aussi la fête des Semaines, la fête des premiers produits de la moisson de froment, et la fête de la récolte à la fin de l\'année.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trois fois par an tous les mâles d\'entre vous paraîtront devant le Souverain, l\'Eternel, Dieu d\'Israël;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'car je déposséderai des nations devant toi et je te donnerai un large territoire, et nul ne convoitera ton pays quand tu monteras pour paraître devant l\'Eternel ton Dieu trois fois par an.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Tu ne mêleras pas le sang de mon sacrifice à du pain levé et le sacrifice de la fête de Pâques ne sera pas gardé jusqu\'au matin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tu apporteras les prémices des premiers produits de ton sol à la maison de l\'Eternel ton Dieu. Tu ne feras pas bouillir un chevreau dans le lait de sa mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Et l\'Eternel dit à Moïse: Ecris, toi, ces paroles-là; car c\'est d\'après ces paroles-là que j\'ai fait alliance avec toi et avec Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Et il fût là avec l\'Eternel quarante jours et quarante nuits, sans manger ni boire, et l\'Eternel écrivit sur les tables les paroles de l\'alliance, les dix paroles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Et comme Moïse descendait du mont Sinaï, les deux tables du témoignage étaient dans la main de Moïse quand il descendait de la montagne, Moïse ne savait pas que la peau de son visage était devenue rayonnante pendant qu\'il parlait avec Dieu;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'et Aaron et tous les fils d\'Israël virent Moïse, et voici la peau de son visage rayonnait et ils craignirent de s\'approcher de lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Alors Moïse les appela, et Aaron et tous les princes de l\'assemblée retournèrent vers lui, et Moïse leur parla.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Après cela tous les fils d\'Israël s\'approchèrent, et Moïse leur prescrivit tout ce que l\'Eternel lui avait dit sur le mont Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Et Moïse acheva de parler avec eux et se couvrit le visage d\'un voile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Et quand Moïse entrait devant l\'Eternel pour parler avec lui, il ôtait le voile jusqu\'à ce qu\'il sortît. Puis il sortait et disait aux fils d\'Israël ce qui avait été ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Et les fils d\'Israël voyaient le visage de Moïse dont la peau rayonnait, et Moïse remettait le voile sur son visage jusqu\'à ce qu\'il entrât pour parler avec l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Moïse convoqua toute l\'assemblée des fils d\'Israël et leur dit: Voici les choses que l\'Eternel a commandé de faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'On travaillera six jours, mais le septième jour sera pour vous jour de repos, sabbat consacré à l\'Eternel. Quiconque fera un travail dans ce jour-là sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Vous n\'allumerez point de feu dans aucune de vos demeures le jour du sabbat.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Et Moïse parla ainsi à toute l\'assemblée des fils d\'Israël: Voici ce que l\'Eternel a commandé:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Apportez, de ce qui est à vous, des dons, pour l\'Eternel: tout homme qui y sera disposé apportera un don à l\'Eternel: de l\'or, de l\'argent et de l\'airain;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'de la pourpre violette, de la pourpre écarlate, du cramoisi, du lin et du poil de chèvre;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'des peaux de bélier teintes en rouge, des peaux de dauphin et du bois d\'acacia;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'de l\'huile pour le candélabre et des aromates pour l\'huile d\'onction et pour l\'encensement;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'des pierres d\'onyx et des pierres à enchâsser pour l\'éphod et pour le pectoral.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Et tous les hommes dans l\'esprit desquels il y a de l\'habileté viendront et exécuteront tout ce que l\'Eternel a ordonné:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'la Demeure, sa tente et sa couverture, ses agrafes, ses poutres, ses traverses, ses piliers et ses socles;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'l\'arche et ses barres, le propitiatoire et le voile de séparation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'la table, ses barres et tous ses ustensiles, et le pain de proposition;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'le candélabre, ses ustensiles et ses lampes, et l\'huile pour le luminaire;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'l\'autel des parfums et ses barres, et l\'huile d\'onction et le parfum pour l\'encensement, et le rideau de l\'entrée pour l\'entrée de la Demeure;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'l\'autel des holocaustes, sa grille d\'airain, ses barres et tous ses ustensiles, la cuve et son piédestal;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'les toiles du parvis, ses piliers, ses socles et le rideau pour la porte du parvis,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'les chevilles de la Demeure, les chevilles du parvis et leurs cordages;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'les vêtements de cérémonie pour faire le service dans le sanctuaire, les vêtements sacrés pour Aaron le sacrificateur et les vêtements de ses fils pour les fonctions du sacerdoce.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Toute l\'assemblée des fils d\'Israël sortit de devant Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Tous ceux que leur cœur y portait et tous ceux dont l\'esprit fut bien disposé vinrent et apportèrent des dons à l\'Eternel pour l\'œuvre de la Tente d\'assignation, pour tout son service et pour les vêtements sacrés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Et ils vinrent, hommes et femmes; tous ceux dont le cœur était bien disposé apportèrent des broches, des anneaux, des bagues, des bracelets, toutes sortes d\'objets d\'or, et chacun présenta l\'offrande d\'or qu\'il avait consacrée à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Tous ceux qui avaient chez eux de la pourpre violette, de la pourpre écarlate, du cramoisi, du lin et du poil de chèvre, des peaux de bélier teintes en rouge et des peaux de dauphin, les apportèrent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Tous ceux qui prélevèrent une offrande d\'argent et d\'airain apportèrent l\'offrande à l\'Eternel. Tous ceux qui avaient chez eux du bois d\'acacia l\'apportèrent pour tout l\'ouvrage à faire pour le service.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Et toutes les femmes habiles filèrent de leurs mains et apportèrent ce qu\'elles avaient filé: la pourpre violette, la pourpre écarlate, le cramoisi et le lin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Et toutes les femmes que leur cœur y portait et qui avaient de l\'habileté filèrent le poil de chèvre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Et les principaux du peuple apportèrent les pierres d\'onyx et les pierres à enchâsser pour l\'éphod et pour le pectoral,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'les aromates et l\'huile pour le luminaire, pour l\'huile d\'onction et pour le parfum aromatique.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Tous les fils d\'Israël, hommes et femmes, que leur cœur disposa à contribuer à tout l\'ouvrage que l\'Eternel avait commandé par Moïse, apportèrent à l\'Eternel des dons volontaires.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Et Moïse dit aux fils d\'Israël: Voyez, l\'Eternel a appelé par son nom Betsaléel, fils d\'Uri, fils de Hur, de la tribu de Juda,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'et il l\'a rempli d\'esprit divin, d\'habileté, d\'intelligence, de savoir pour toutes sortes d\'ouvrages,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'pour faire des combinaisons, pour travailler l\'or, l\'argent et l\'airain,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'pour graver des pierres à enchâsser, pour sculpter le bois de manière à exécuter toute espèce de travaux d\'art.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Il lui a accordé aussi le don d\'enseigner, de même qu\'à Oholiab, fils d\'Achisamac, de la tribu de Dan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Il les a remplis d\'intelligence, pour exécuter toutes sortes de travaux de sculpture et d\'art, pour broder et tisser la pourpre violette, la pourpre écarlate, le cramoisi et le lin, pour exécuter toutes sortes de travaux et pour faire des combinaisons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Et Betsaléel et Oholiab et tous les hommes intelligents en qui l\'Eternel a mis de l\'habileté et de l\'intelligence pour savoir faire tous les ouvrages pour le service du sanctuaire, exécuteront tout selon ce que l\'Eternel a ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Et Moïse appela Betsaléel et Oholiab et tous les hommes intelligents, en qui l\'Eternel avait mis de l\'intelligence, tous ceux que leur cœur portait à se mettre à l\'œuvre pour l\'exécuter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Et ils prirent de devant Moïse tous les dons que les fils d\'Israël avaient apportés pour exécuter les ouvrages pour le service du sanctuaire; et on continuait à apporter chaque matin à Moïse des dons volontaires.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Et tous les hommes habiles, qui exécutaient tous les ouvrages du sanctuaire, quittèrent chacun l\'ouvrage qu\'ils faisaient');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'et vinrent dire à Moïse: Le peuple apporte trop, plus qu\'il n\'en faut pour le service de l\'œuvre que l\'Eternel a commandé de faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Et Moïse fit proclamer dans le camp cet ordre: Que ni homme, ni femme ne fasse plus rien en fait d\'offrandes pour le sanctuaire. Et on empêcha le peuple de plus rien apporter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Les objets préparés suffisaient et au-delà pour tous les ouvrages à exécuter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Et les hommes habiles parmi ceux qui faisaient l\'ouvrage firent la Demeure de dix tentures, de lin retors, de pourpre violette, de pourpre écarlate et de cramoisi, damassé de chérubins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'La longueur d\'une tenture était de vingt-huit coudées et la largeur de quatre coudées par tenture: la même dimension pour chaque tenture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Il joignit cinq des tentures, les unes aux autres et il joignit aussi les cinq autres les unes aux autres;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'et il mit des ganses de pourpre violette sur le bord de la dernière tenture de l\'un de ces assemblages; il en mit de même au bord de la dernière tenture du second assemblage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Il en fit cinquante à une tenture et cinquante au bout de la dernière tenture du second assemblage. Ces ganses se correspondaient les unes aux autres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Et il fit cinquante agrafes d\'or, et il joignit les tentures l\'une à l\'autre au moyen de ces agrafes, et la Demeure forma un tout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Il fit aussi des tentures de poil de chèvre pour servir de tente sur la Demeure: il les fit au nombre de onze.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longueur d\'une tenture était de trente coudées et la largeur de quatre coudées par tenture: la même dimension pour chaque tenture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Et il joignit cinq de ces tentures d\'une part et les six autres d\'autre part.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Et il mit cinquante ganses sur le bord de la dernière tenture d\'un assemblage et cinquante sur le bord de la [dernière] tenture du second assemblage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Et il fit cinquante agrafes d\'airain pour joindre ainsi la Tente, afin qu\'elle formât un tout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Il fit pour la Tente une couverture en peaux de bélier teintes en rouge et une couverture en peaux de dauphin par-dessus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Et il fit aussi les planches de la Demeure, des planches d\'acacia posées debout.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Chaque planche avait dix coudées de longueur et une coudée et demie de largeur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Chaque planche avait deux tenons s\'emboîtant l\'un dans l\'autre; il en fit à toutes les planches de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Il fit donc les planches pour la Demeure; vingt pour la face au midi, à droite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Et sous ces vingt planches, il plaça quarante socles d\'argent, deux socles sous chaque planche pour ses deux tenons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Et pour le second côté de la Demeure, pour la face septentrionale, il fit vingt planches');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'avec leurs quarante socles d\'argent, deux socles sous chaque planche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Et pour le fond de la Demeure, tourné à l\'occident, il fit six planches,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'et il fit deux planches pour les coins de la Demeure, dans le fond.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Elles étaient pareilles depuis le bas et toutes deux complètes jusqu\'à leur sommet vers le premier anneau; c\'est ainsi qu\'il les fit toutes deux pour les deux coins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Il y avait donc huit planches, avec leurs socles d\'argent: seize socles, deux sous chaque planche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Et il fit cinq traverses de bois d\'acacia pour les planches d\'un côté de la Demeure,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'et cinq traverses pour celles de l\'autre côté, et cinq traverses pour celles du côté du fond, à l\'occident.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Et il fit la traverse du milieu pour traverser, les planches par le milieu, d\'un bout à l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Et il revêtit d\'or les planches et il fit en or les anneaux qui recevaient les traverses et il revêtit d\'or les traverses.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Il fit le voile de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors; il le fit damassé de chérubins.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Il fit pour lui quatre piliers d\'acacia et il les revêtit d\'or; ils avaient des clous d\'or, et il fondit pour eux quatre socles d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Et il fit un rideau à l\'entrée de la Tente, en pourpre violette, pourpre écarlate, cramoisi et lin retors, en ouvrage broché;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'il fit ses cinq piliers et leurs clous et il revêtit d\'or leurs chapiteaux et leurs tringles, et leurs cinq socles étaient d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Betsaléel fit l\'arche de bois d\'acacia, de deux coudées et demie de longueur, d\'une coudée et demie de largeur et d\'une coudée et demie de hauteur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'il la revêtit d\'or pur en dedans et en dehors et il la garnit d\'une guirlande d\'or tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Et il fondit quatre boucles d\'or [pour mettre] à ses quatre pieds, deux boucles d\'un côté et deux de l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Il fit des barres de bois d\'acacia et il les revêtit d\'or;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'et il passa ces barres dans les boucles le long des côtés de l\'arche pour la porter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Et il fit un propitiatoire d\'or pur de deux coudées et demie de longueur et d\'une coudée et demie de largeur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'et il fit deux chérubins d\'or battu faisant corps avec les deux bouts du propitiatoire:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'un chérubin à un bout et un à l\'autre; c\'est du propitiatoire même qu\'il fit sortir les chérubins à ses deux bouts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Et les chérubins avaient leurs ailes déployées vers le haut, couvrant de leurs ailes le propitiatoire et en face l\'un de l\'autre; les faces des chérubins étaient tournées vers le propitiatoire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Il fit la table de bois d\'acacia, de deux coudées de longueur, d\'une coudée de largeur et d\'une coudée et demie de hauteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Il la revêtit d\'or pur et il l\'entoura d\'une guirlande d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Et il lui fit un châssis d\'or d\'une palme et il fit autour du châssis une bordure d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Et il fondit quatre boucles d\'or et il mit ces boucles aux quatre coins, aux quatre pieds de la table;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'les boucles étaient tout près du châssis et recevaient les barres à porter la table.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Il fit les barres de bois d\'acacia et il les revêtit d\'or; elles servaient à porter la table.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Et il fit d\'or pur les ustensiles qu\'on devait mettre sur la table, les plats, les godets, les patères et les burettes avec lesquelles on devait faire les libations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Il fit le candélabre d\'or pur; le candélabre, son pied et sa tige, était d\'or battu; ses calices, ses boutons et ses fleurs faisaient corps avec lui;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'et six branches partaient de ses côtés, trois branches de candélabre d\'un côté et trois branches de candélabre de l\'autre côté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Il y avait sur la première branche trois coupes en fleur d\'amandier figurant un bouton qui s\'ouvre, et sur la seconde branche trois coupes, en fleur d\'amandier figurant un bouton qui s\'ouvre, et ainsi pour les six branches partant du candélabre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Et au candélabre même il y avait quatre coupes en fleurs d\'amandier figurant des boutons qui s\'ouvrent:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'un bouton sous les deux premières branches, un bouton sous les deux suivantes et un bouton sous les deux dernières des six branches sortant du candélabre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ces boutons et ces tiges faisaient corps avec lui; le tout était une seule masse d\'or pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Et il y fit les lampes au nombre de sept, avec les mouchettes et les cendriers, en or pur:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'on employa un talent d\'or pur pour faire le candélabre avec tous ses ustensiles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Il fit l\'autel des parfums de bois d\'acacia, d\'une coudée de longueur et d\'une coudée de largeur, carré, et de deux coudées de hauteur; ses cornes faisaient corps avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Et il le revêtit d\'or pur, le dessus, les parois tout autour et les cornes, et il le garnit d\'une guirlande d\'or tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Et il y adapta deux anneaux d\'or au-dessous de la guirlande, sur les deux arêtes; il les mit aux deux côtés pour recevoir les barres qui servaient à le porter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Et il fit les barres de bois d\'acacia et les revêtit d\'or.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Il fit l\'huile d\'onction sainte et l\'encens pur, composé selon l\'art du parfumeur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Et il fit l\'autel des holocaustes en bois d\'acacia, de cinq coudées de longueur et de cinq coudées de largeur, carré, et de trois coudées de hauteur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Et il fit ses cornes à ses quatre coins; les cornes faisaient corps avec lui, et il le revêtit d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Et il fit tous les ustensiles de l\'autel, les chaudrons, les pelles, les bassins, les fourches et les brasiers; il fit d\'airain tous ces ustensiles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Et il fit à l\'autel une grille; c\'était un treillis d\'airain; il le plaça sous la corniche de l\'autel dans la partie inférieure jusqu\'à mi-hauteur de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Et il fondit quatre anneaux qu\'il mit aux quatre coins de la grille d\'airain pour recevoir les barres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Et il fit les barres de bois d\'acacia et il les revêtit d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Et il fit passer dans les anneaux aux côtés de l\'autel les barres qui servaient à le transporter; il le fit creux, en planches.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Il fit aussi la cuve d\'airain à piédestal d\'airain en employant les miroirs des femmes qui s\'assemblaient à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Et il fit le parvis. Pour le côté du midi, à droite, les toiles du parvis, en lin retors, avaient cent coudées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Il avait vingt piliers, et leurs socles au nombre de vingt étaient d\'airain, et les clous et les tringles des piliers étaient d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Et pour le côté du nord il y avait cent coudées de toile et vingt piliers avec leurs vingt socles d\'airain; les clous et les tringles des piliers étaient d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Et pour le côté de l\'occident il y avait cinquante coudées de toile, et dix piliers avec leurs dix socles; les clous et les tringles des piliers étaient d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Et pour le devant, à l\'orient, il y avait cinquante coudées:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'quinze coudées de toile d\'une part et trois piliers avec leurs trois socles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Et d\'autre part (d\'un côté de la porte du parvis comme de l\'autre) quinze [coudées] de toile et trois piliers avec leurs trois socles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Toutes les toiles formant l\'enceinte du parvis étaient de lin retors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Les socles pour les piliers étaient d\'airain, les clous des piliers et leurs tringles étaient d\'argent et la couverture et leurs chapiteaux étaient d\'argent. Tous les piliers du parvis étaient joints par des tringles d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Le voile de la porte du parvis était broché, en pourpre violette, pourpre écarlate, cramoisi et lin retors; il avait une longueur de vingt coudées, et sa hauteur était de cinq coudées, comme la largeur des toiles du parvis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Les quatre piliers et leurs quatre socles étaient d\'airain, leurs clous étaient d\'argent et leurs sommets et leurs chapiteaux étaient revêtus d\'argent.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Toutes les chevilles pour la Demeure et pour l\'enceinte du parvis étaient d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Voici les comptes de la Demeure, de la Demeure du témoignage, faits sur l\'ordre de Moïse, par les soins des Lévites, sous la direction d\'Ithamar, fils d\'Aaron le sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Betsaléel, fils d\'Uri, fils de Hur, de la tribu de Juda, fit tout ce que l\'Eternel avait commandé à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Et avec lui Oholiab, fils d\'Achisamac, de la tribu de Dan, sculpteur, inventeur et brodeur en pourpre violette, en pourpre écarlate, en cramoisi et en lin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Total de l\'or employé à l\'ouvrage, à tout l\'ouvrage du Sanctuaire, or qui fut le produit des offrandes: Vingt-neuf talents et sept cent trente sicles, selon le sicle sacré.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'L\'argent de ceux de l\'assemblée dont on fit le dénombrement montait à cent talents et mille sept cent soixante-quinze sicles, selon le sicle sacré;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'un béka par tête, la moitié d\'un sicle selon le sicle sacré pour tous ceux qui passèrent par le dénombrement depuis l\'âge de vingt ans et au-dessus, soit pour six cent trois mille cinq cent cinquante hommes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Les cent talents d\'argent servirent à fondre les socles du sanctuaire et les socles du voile, cent socles pour les cent talents, un talent par socle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Et des mille sept cent soixante-quinze sicles on fit les clous pour les piliers, on revêtit leurs chapiteaux et on les joignit par des tringles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'L\'airain des offrandes montait à soixante-dix talents et deux mille quatre cents sicles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'On en fit les socles de l\'entrée de la Tente d\'assignation et l\'autel d\'airain avec sa grille d\'airain et tous les ustensiles de l\'autel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'et les socles du parvis tout autour et les socles de l\'entrée du parvis et toutes les chevilles de la Demeure et toutes les chevilles du parvis tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Et avec la pourpre violette, la pourpre écarlate et le cramoisi on fit les vêtements de cérémonie pour faire le service dans le sanctuaire, et on fit les vêtements sacrés qui étaient pour Aaron, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'On fit l\'éphod d\'or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'On étendit l\'or en lames et on coupa ces lames en fils que l\'on entrelaça dans la pourpre violette, la pourpre écarlate, le cramoisi et le lin; c\'était un ouvrage en brocart.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'On y attacha des épaulettes et ainsi il était joint aux deux bouts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Et la bande qui y était pour l\'attacher faisait corps avec lui et était de la même étoffe; elle était d\'or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Et l\'on enchâssa dans des chatons d\'or les pierres d\'onyx sur lesquelles on grava les noms des fils d\'Israël, comme on grave les cachets.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Et il les plaça sur les épaulettes de l\'éphod comme pierres de mémorial des fils d\'Israël, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Il fit le pectoral en brocart, du même travail que l\'éphod, d\'or, de pourpre violette, de pourpre écarlate, de cramoisi et de lin retors;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'il était carré. On fit le pectoral double; sa longueur était d\'un empan et sa largeur d\'un empan; il était double.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'On le garnit de quatre rangées de pierreries. Sur une rangée: une sardoine, une topaze, une émeraude, voilà la première rangée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'La seconde rangée: un rubis, un saphir et une calcédoine.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'La troisième rangée une opale, une agate et une améthyste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'La quatrième rangée une chrysolithe, un onyx et un jaspe. Ces pierres étaient entourées de chatons d\'or dans leurs garnitures.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Ces pierres correspondaient aux noms des fils d\'Israël: il y en avait douze selon le nombre de leurs noms; elles étaient gravées comme des cachets, chacune avec le nom d\'une des douze tribus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'On fit pour le pectoral des chaînes en torsade, en façon de cordons d\'or pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'On fit deux chatons d\'or et deux anneaux d\'or et on mit ces deux anneaux aux deux extrémités du pectoral.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Et on attacha les deux cordons d\'or aux deux anneaux placés aux extrémités du pectoral.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Et on fixa les deux bouts des deux cordons sur les deux chatons et on les mit sur les épaulettes de l\'éphod par devant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'On fit [encore] deux anneaux d\'or qu\'on mit aux deux bouts du pectoral, sur le bord tourné vers l\'éphod en dedans;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'et on fit [aussi] deux anneaux d\'or qu\'on mit aux deux épaulettes de l\'éphod en bas, en dehors, près de la jonction au-dessus de la bande de l\'éphod.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'On fixa le pectoral en joignant ses anneaux aux anneaux de l\'éphod par un cordonnet de pourpre violette, pour qu\'il se tînt sur la bande de l\'éphod, de sorte que le pectoral ne branlât pas de dessus l\'éphod, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Il fit le surplis de l\'éphod, tissé, tout en pourpre violette.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Il y avait au milieu du surplis une ouverture, comme celle d\'une cotte d\'armes; il y avait un ourlet tout autour de l\'ouverture, afin que le surplis ne se déchirât pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Et on mit au bord inférieur du surplis des grenades de pourpre violette, de pourpre écarlate, de cramoisi, en lin retors.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'On fit des clochettes d\'or pur et on mit les clochettes entre les grenades au bord inférieur du surplis tout autour entre les grenades,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'une clochette et une grenade, une clochette et une grenade au bas du surplis tout autour pour le service, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'On fit les tuniques de lin, tissées pour Aaron et pour ses fils,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'la tiare de lin et les mitres de lin servant de parure, les caleçons de toile, de lin retors,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'la ceinture de lin retors, en pourpre violette, en pourpre écarlate et en cramoisi, brodée, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'On fit d\'or pur la lame, diadème sacré, et on y grava comme on grave sur les cachets: Consécration à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'On y mit un cordonnet de pourpre violette, pour la mettre sur la tiare en haut, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Ainsi fut achevé tout l\'ouvrage de la Demeure, de la Tente d\'assignation; et les fils d\'Israël exécutèrent tout selon les ordres que l\'Eternel avait donnés à Moïse; ils firent ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Ils apportèrent la Demeure à Moïse, la Tente et tout ce qui en dépend, ses agrafes, ses planches, ses traverses, ses piliers et ses socles;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'la couverture de peaux de bélier teintes en rouge, la couverture de peaux de dauphin et le voile de séparation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'l\'arche du témoignage, ses barres et le propitiatoire;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'la table, tous ses ustensiles et le pain de proposition;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'le candélabre [d\'or] pur, ses lampes, les lampes à y ranger, tous ses ustensiles et l\'huile pour le luminaire;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'l\'autel d\'or, l\'huile d\'onction, le parfum pour l\'encens et le rideau pour l\'entrée de la Tente;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'l\'autel d\'airain et sa grille d\'airain, ses barres et tous ses ustensiles, la cuve et son piédestal;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'les toiles du parvis, ses piliers, ses socles, le rideau pour la porte du parvis, ses cordages, ses chevilles et tous les ustensiles pour le service de la Demeure, pour la Tente d\'assignation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'les vêtements de cérémonie pour faire le service dans le sanctuaire, les vêtements sacrés pour Aaron le sacrificateur et les vêtements de ses fils pour officier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'En toutes choses les fils d\'Israël firent tous ces ouvrages selon les ordres que l\'Eternel avait donnés à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Et Moïse vit tout l\'ouvrage, et voici ils l\'avaient fait; ils l\'avaient fait comme l\'Eternel l\'avait ordonné. Et Moïse les bénit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Et l\'Eternel parla à Moïse et dit:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Au premier jour du premier mois tu dresseras la Demeure, la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'tu y placeras l\'arche du témoignage et tu cacheras l\'arche avec le voile;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'tu apporteras la table et tu arrangeras ce qui doit la garnir et tu apporteras le candélabre et tu poseras dessus ses lampes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Tu mettras l\'autel d\'or pour le parfum devant l\'arche du témoignage et tu placeras le voile à l\'entrée de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Tu mettras l\'autel des holocaustes devant l\'entrée de la Demeure, de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Et tu mettras la cuve entre la Tente d\'assignation et l\'autel et tu y mettras de l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Tu placeras le parvis à l\'entour et tu mettras le voile à la porte du parvis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Et tu prendras l\'huile d\'onction et tu oindras la Demeure et tout ce qui y est. Tu la consacreras avec tous ses ustensiles et elle sera sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Tu oindras l\'autel des holocaustes et tous ses ustensiles. Tu consacreras l\'autel et l\'autel sera très saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Tu oindras la cuve et son piédestal et tu la consacreras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Tu feras avancer Aaron et ses fils à l\'entrée de la Tente d\'assignation et tu le laveras d\'eau;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'et tu revêtiras Aaron des vêtements sacrés, tu l\'oindras et tu le consacreras, et il me servira comme sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Tu feras avancer ses fils et tu les revêtiras de tuniques;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'tu les oindras comme tu as oint leur père et ils me serviront comme sacrificateurs, et leur onction leur conférera le sacerdoce à perpétuité, de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Moïse fit tout selon les ordres que l\'Eternel lui avait donnés; il fit ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Le premier jour du premier mois de la seconde année, la Demeure fut dressée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Moïse dressa la Demeure et il en posa les socles, il en plaça les planches et en mit les traverses et en dressa les piliers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Il étendit la Tente sur la Demeure et mit la couverture de la Tente par-dessus, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Et il prit le témoignage et le mit dans l\'arche; il mit les barres à l\'arche et il posa le propitiatoire au-dessus de l\'arche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Et il porta l\'arche dans la Demeure et plaça le voile de séparation, et il en voila l\'arche du témoignage, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Il plaça la table dans la Tente d\'assignation, au côté septentrional de la Demeure, en dehors du voile;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'et il y arrangea le pain devant l\'Eternel, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Il plaça le candélabre dans la Tente d\'assignation en face de la table, au côté méridional de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Et il y posa les lampes devant l\'Eternel, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Il plaça l\'autel d\'or dans la Tente d\'assignation devant le voile,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'et il y fit brûler l\'encens, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Il plaça le rideau à l\'entrée de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Il plaça l\'autel des holocaustes, à l\'entrée de la Demeure, de la Tente d\'assignation, et il y offrit l\'holocauste et l\'oblation, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Il plaça la cuve entre la Tente d\'assignation et l\'autel, et il y mit de l\'eau pour les ablutions.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Et Moïse, Aaron et ses fils s\'y lavèrent les mains et les pieds.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Lorsqu\'ils entraient dans la Tente d\'assignation et qu\'ils s\'approchaient de l\'autel, ils se lavaient, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Et il dressa le parvis autour de la Demeure et de l\'autel et il mit le rideau à la porte du parvis; ainsi Moïse acheva cette œuvre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Et la nuée couvrit la Tente d\'assignation et la gloire de l\'Eternel remplit la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Et Moïse ne put pas entrer dans la Tente d\'assignation, parce que la nuée se tenait dessus et que la gloire de l\'Eternel remplissait la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Or pendant toutes leurs marches, quand la nuée s\'élevait de dessus la Demeure, les fils d\'Israël partaient.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Mais si la nuée ne s\'élevait pas, ils ne partaient pas jusqu\'au jour où elle s\'élevait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Car la nuée de l\'Eternel était sur la Demeure pendant le jour; et de nuit, il y avait du feu dans la nuée, aux yeux de toute la maison d\'Israël, pendant toutes leurs marches.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Et l\'Eternel appela Moïse et lui parla de la Tente d\'assignation, en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Parle aux fils d\'Israël et dis-leur: Quand quelqu\'un d\'entre vous fera une offrande à l\'Eternel, ce sera du bétail que vous offrirez, soit du gros ou du menu bétail.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si son offrande est un holocauste et de gros bétail, il offrira un mâle sans défaut; il l\'offrira à l\'entrée de la Tente d\'assignation, pour être agréé devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Il appuiera sa main sur la tête de la victime et elle sera acceptée en sa faveur pour faire propitiation pour lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Et il égorgera le jeune taureau devant l\'Eternel; et les fils d\'Aaron, les sacrificateurs, offriront le sang et en arroseront tout autour l\'autel qui est à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Et on écorchera la victime et la découpera en ses pièces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Et les fils d\'Aaron le sacrificateur mettront du feu sur l\'autel et arrangeront des bûches sur le feu;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'et les fils d\'Aaron, les sacrificateurs, arrangeront les pièces, la tête et la fressure sur les bûches placées sur le feu qui est sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'On lavera dans l\'eau les entrailles et les jambes, et le sacrificateur fera fumer le tout sur l\'autel. C\'est un holocauste, un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Si son offrande est de menu bétail, un holocauste d\'agneaux ou de chevreaux, il offrira un mâle sans défaut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Et il l\'égorgera à côté de l\'autel, au nord, devant l\'Eternel et les fils d\'Aaron, les sacrificateurs, en répandront le sang sur l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'On le découpera en ses pièces et on les prendra avec sa tête et sa fressure, et le sacrificateur les arrangera sur les bûches placées sur le feu qui est sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Il lavera dans l\'eau les entrailles et les jambes; et le sacrificateur offrira le tout et le fera fumer sur l\'autel. C\'est un holocauste, un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Si son offrande à l\'Eternel est un holocauste d\'oiseaux, il offrira des tourterelles ou des pigeonneaux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Le sacrificateur apportera la victime à l\'autel; il lui détachera la tête et la fera fumer sur l\'autel, et son sang sera exprimé contre la paroi de l\'autel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'il ôtera le gésier avec ce qui s\'y trouve et le jettera près de l\'autel, vers l\'orient, au lieu où l\'on met les cendres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Puis il la fendra aux ailes, sans les détacher, et le sacrificateur la fera fumer sur l\'autel, sur les bûches placées sur le feu. C\'est un holocauste, un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Lorsque quelqu\'un présentera à l\'Eternel comme offrande une oblation, son offrande sera de fleur de farine, sur laquelle il versera de l\'huile, et il y ajoutera de l\'encens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Il l\'apportera aux fils d\'Aaron, les sacrificateurs; et le sacrificateur prendra une poignée de la fleur de farine arrosée d\'huile avec tout l\'encens et il fera fumer cela en mémorial sur l\'autel. C\'est un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Ce qui restera de l\'oblation sera pour Aaron et ses fils; c\'est une chose très sainte entre les sacrifices faits par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Lorsque tu offriras une oblation de ce qui est cuit au four, ce sera de la fleur de farine en gâteaux sans levain, pétris à l\'huile, et des galettes sans levain, ointes d\'huile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Et si ton offrande est une oblation cuite à la poêle, elle sera de fleur de farine pétrie à l\'huile, sans levain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Tu la briseras en morceaux et tu verseras de l\'huile dessus; c\'est une oblation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Et si ton offrande est une oblation cuite dans une casserole, elle sera faite de fleur de farine avec de l\'huile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Et tu apporteras l\'oblation faite de ces choses à l\'Eternel; elle sera présentée au sacrificateur, qui l\'apportera à l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Et le sacrificateur prélèvera de cette oblation le mémorial et le fera fumer sur l\'autel. C\'est un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Ce qui restera de l\'oblation sera pour Aaron et ses fils; c\'est une chose très sainte entre les sacrifices faits par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Quelque oblation que vous présentiez à l\'Eternel, elle ne sera pas fermentée; car vous ne ferez fumer ni levain ni miel en sacrifice fait par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Vous les présenterez à l\'Eternel en offrandes de prémices; mais ces offrandes-là ne seront pas placées sur l\'autel comme offrandes d\'agréable odeur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Tu saleras toute oblation que tu présenteras et tu ne laisseras point ton oblation manquer du sel de l\'alliance de ton Dieu; sur toutes tes offrandes tu offriras du sel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Si tu apportes une oblation de prémices à l\'Eternel, tu offriras en oblation de prémices des épis rôtis au feu, du grain nouveau broyé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Tu y mettras de l\'huile et tu répandras dessus de l\'encens; c\'est une oblation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Et le sacrificateur fera fumer comme mémorial une partie du grain broyé et de l\'huile, avec tout l\'encens. C\'est un sacrifice fait par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Lorsque quelqu\'un offrira un sacrifice d\'actions de grâces, s\'il offre du gros bétail, mâle ou femelle, il offrira une victime sans défaut, devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Il appuiera la main sur la tête de son offrande et l\'égorgera à l\'entrée de la Tente d\'assignation, et les fils d\'Aaron, les sacrificateurs, en répandront le sang sur l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'De ce sacrifice d\'actions de grâces, il offrira, en sacrifice par le feu à l\'Eternel, la graisse qui recouvre les entrailles et toute celle qui y est attachée,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'et les deux rognons et la graisse qui les enveloppe et qui tient aux lombes, et la taie du foie; il la détachera près des rognons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Et les fils d\'Aaron feront fumer cela sur l\'autel, avec l\'holocauste placé sur les bûches qui sont sur le feu. C\'est un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Si son offrande en sacrifice d\'actions de grâces à l\'Eternel est de menu bétail, il l\'offrira mâle ou femelle, sans défaut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'S\'il offre en sacrifice un agneau, il le présentera devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Il appuiera la main sur la tête de son offrande et il l\'égorgera devant la Tente d\'assignation, et les fils d\'Aaron en répandront le sang sur l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'De ce sacrifice d\'actions de grâces, il offrira, en sacrifice par le feu à l\'Eternel, sa graisse, la queue entière qu\'il séparera près de l\'échine, la graisse qui recouvre les entrailles et toute celle qui y est attachée,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'et les deux rognons et la graisse qui les enveloppe et qui tient aux lombes, et la taie du foie; il la détachera près des rognons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Le sacrificateur fera fumer cela sur l\'autel: c\'est un mets offert par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Si son offrande est une chèvre, il la présentera devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Il appuiera sa main sur la tête de l\'animal et il l\'égorgera devant la Tente d\'assignation, et les fils d\'Aaron en répandront le sang sur l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Et il en offrira, en sacrifice par le feu à l\'Eternel, la graisse qui recouvre les entrailles et toute celle qui y est attachée,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'et les deux rognons et la graisse qui les enveloppe et qui tient aux lombes, et la taie du foie; il la détachera près des rognons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Le sacrificateur fera fumer cela sur l\'autel: c\'est un mets offert par le feu, d\'agréable odeur. Toute graisse est pour l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'C\'est une ordonnance perpétuelle de génération en génération, dans tous les lieux où vous habiterez: vous ne mangerez ni graisse ni sang.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'L\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Parle aux fils d\'Israël et dis-leur: Lorsque quelqu\'un aura péché par erreur contre l\'un de tous les commandements de l\'Eternel, faisant l\'une de ces choses qui ne doivent pas se faire, et qu\'il aura fait l\'une de ces choses,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'si c\'est le sacrificateur ayant reçu l\'onction, qui a péché, de manière à rendre le peuple coupable, il offrira à l\'Eternel pour le péché qu\'il aura commis un jeune taureau sans défaut, en sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Il amènera le taureau à l\'entrée de la Tente d\'assignation, devant l\'Eternel; il appuiera sa main sur la tête du taureau et il égorgera le taureau devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Et le sacrificateur oint prendra du sang du taureau et l\'apportera dans la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'puis le sacrificateur trempera son doigt dans le sang et il fera sept fois aspersion du sang en présence de l\'Eternel, devant le voile du sanctuaire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Puis le sacrificateur mettra du sang sur les cornes de l\'autel des parfums aromatiques qui est devant l\'Eternel dans la Tente d\'assignation; et il répandra tout le sang du taureau sur le pied de l\'autel des holocaustes qui est à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Puis il enlèvera toute la graisse du taureau sacrifié pour le péché, la graisse qui recouvre les entrailles et toute celle qui y est attachée,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'et les deux rognons et la graisse qui les enveloppe et qui tient aux lombes, et la taie du foie il la détachera près des rognons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Le sacrificateur enlèvera ces parties, comme on les enlève du taureau dans le sacrifice d\'actions de grâces, et il les fera fumer sur l\'autel des holocaustes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Mais la peau du taureau, toute sa chair, avec sa tête, ses jambes, ses entrailles et ses excréments,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'le taureau entier, il l\'emportera hors du camp, en lieu pur, où l\'on jette la cendre, et il le brûlera sur du bois; il sera brûlé sur le tas de cendres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Si toute l\'assemblée d\'Israël a péché par erreur et que le peuple ne s\'en soit pas aperçu et qu\'ils aient fait quelqu\'une des choses que l\'Eternel a défendu de faire et qu\'ils se soient rendus coupables');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'et que le péché qu\'ils ont commis vienne à être découvert, l\'assemblée offrira un jeune taureau pour le péché et on l\'amènera devant la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'et les Anciens de l\'assemblée appuieront leurs mains sur la tête du taureau devant l\'Eternel et on égorgera le taureau devant l\'Eternel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'et le sacrificateur oint portera du sang du taureau dans la Tente d\'assignation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'puis le sacrificateur trempera son doigt dans le sang et en fera sept fois aspersion en présence de l\'Eternel devant le voile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Il mettra du sang sur les cornes de l\'autel qui est devant l\'Eternel dans la Tente d\'assignation; et il répandra tout le sang sur le pied de l\'autel des holocaustes qui est à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Puis il enlèvera toute la graisse et la fera fumer sur l\'autel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'et il fera de ce taureau comme il a fait du taureau sacrifié pour le péché; il fera de même. Ainsi le sacrificateur fera propitiation pour eux et ils seront pardonnés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Il emportera le taureau hors du camp et le brûlera comme il a brûlé le premier taureau. Tel est le sacrifice pour le péché de l\'assemblée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Si un chef a péché en faisant par erreur une des choses que l\'Eternel son Dieu a défendu de faire et qu\'il se soit rendu coupable,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'lorsque le péché qu\'il aura commis sera venu à sa connaissance, il présentera en offrande un bouc mâle sans défaut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Il appuiera sa main sur la tête du bouc et il l\'égorgera au lieu où l\'on égorge l\'holocauste devant l\'Eternel; c\'est un sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Le sacrificateur prendra avec son doigt du sang du sacrifice pour le péché et le mettra sur les cornes de l\'autel des holocaustes et il répandra le sang sur le pied de l\'autel des holocaustes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Il en brûlera toute la graisse sur l\'autel, comme la graisse du sacrifice d\'actions de grâces. Ainsi le sacrificateur fera pour lui la propitiation de son péché et il lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Si quelqu\'un de la masse du peuple a péché en faisant par erreur une des choses que l\'Eternel a défendu de faire et qu\'il se soit rendu coupable,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'lorsque le péché qu\'il aura commis sera venu à sa connaissance, il amènera pour son offrande une chèvre, une femelle sans défaut, pour le péché qu\'il aura commis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Il appuiera sa main sur la tête de la victime pour le péché et il l\'égorgera dans le lieu où l\'on offre l\'holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Puis le sacrificateur prendra avec son doigt du sang de la victime et le mettra sur les cornes de l\'autel des holocaustes, et il répandra tout le sang sur le pied de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Il ôtera toute la graisse, comme on l\'ôte du sacrifice d\'actions de grâces; et le sacrificateur la fera fumer sur l\'autel en agréable odeur pour l\'Eternel. Ainsi le sacrificateur fera propitiation pour cet homme et il lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'S\'il amène un agneau en sacrifice pour le péché, il amènera une femelle sans défaut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Il appuiera sa main sur la tête de la victime pour le péché et l\'égorgera pour le péché au lieu où l\'on égorge l\'holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Puis le sacrificateur prendra avec son doigt du sang de la victime pour le péché et le mettra sur les cornes de l\'autel des holocaustes et il répandra tout le sang au pied de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Il ôtera toute la graisse comme on ôte la graisse de l\'agneau du sacrifice d\'actions de grâces; et le sacrificateur la fera fumer sur l\'autel, sur les sacrifices faits par le feu à l\'Eternel. Et le sacrificateur fera propitiation pour cet homme, pour le péché qu\'il a commis, et il lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Lorsque quelqu\'un péchera en ce qu\'après avoir entendu l\'exécration du serment, il n\'aura pas déclaré en sa qualité de témoin ce qu\'il avait vu ou ce qu\'il savait, et qu\'il se sera ainsi chargé d\'une faute,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'ou lorsque quelqu\'un aura touché quelque chose de souillé, soit le cadavre d\'une bête sauvage impure, soit le cadavre d\'une bête domestique impure, soit le cadavre d\'un reptile impur, et cela sans s\'en être aperçu, et qu\'il se trouvera ainsi souillé et coupable,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'ou lorsqu\'il aura touché une souillure humaine, une chose quelconque par laquelle on devient souillé, et qu\'il n\'y aura pas pris garde, et qu\'il s\'apercevra qu\'il est coupable;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'ou lorsque quelqu\'un aura juré, parlant à la légère de faire du mal ou du bien, de quelque manière que l\'on puisse parler, et qu\'il n\'y aura pas pris garde, et qu\'il s\'apercevra qu\'il est coupable en l\'une de ces choses;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'quand donc quelqu\'un se trouvera en faute dans l\'une de ces choses, il confessera ce en quoi il a péché,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'et il amènera à l\'Eternel, pour le tort qu\'il lui a fait par le péché, une femelle de menu bétail, brebis ou chèvre, comme sacrifice pour le péché; et le sacrificateur fera pour lui la propitiation de son péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'S\'il n\'a pas le moyen de se procurer une brebis ou une chèvre, il apportera à l\'Eternel, pour lui avoir fait tort par son péché, deux tourterelles ou deux pigeonneaux, l\'un comme sacrifice pour le péché, l\'autre comme holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Il les apportera au sacrificateur, qui offrira en premier, lieu celui qui est pour le péché; il lui séparera la tête près de la nuque sans la détacher,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'et il fera aspersion du sang de la victime pour le péché sur la paroi de l\'autel, et le reste du sang sera exprimé au pied de l\'autel; c\'est un sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Du second oiseau il fera un holocauste, selon la règle. Et ainsi le sacrificateur fera pour cet homme la propitiation du péché qu\'il a commis, et il lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'S\'il n\'a pas le moyen de se procurer deux tourterelles ou deux pigeonneaux, il apportera en offrande pour son péché le dixième d\'un épha de fleur de farine, comme sacrifice pour le péché. Il ne mettra pas d\'huile dessus; il n\'y ajoutera point d\'encens, car c\'est un sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Il l\'apportera au sacrificateur, et le sacrificateur en prendra une poignée en mémorial et la fera fumer sur l\'autel, sur les sacrifices faits par le feu à l\'Eternel; c\'est un sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Ainsi le sacrificateur fera propitiation pour cet homme, pour le péché qu\'il aura commis à l\'égard d\'une de ces choses, et il lui sera pardonné, et le reste appartiendra au sacrificateur, comme dans l\'oblation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Lorsque quelqu\'un commettra une infidélité et péchera par erreur en retenant quelque chose de ce qui doit être consacré à l\'Eternel, il amènera son sacrifice de réparation à l\'Eternel, à savoir un bélier sans défaut, choisi du troupeau, évalué par toi deux sicles d\'argent au moins, selon le sicle du sanctuaire, comme sacrifice de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Et ce dont il aura fait tort au sanctuaire, il le restituera en ajoutant un cinquième en sus, et il le donnera au sacrificateur, et le sacrificateur fera propitiation pour lui par le bélier offert en sacrifice de réparation, et il lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Et lorsque quelqu\'un péchera en faisant quelqu\'une des choses que l\'Eternel a défendu de faire, et que, sans savoir en quoi il est coupable, il portera le poids d\'une faute,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'il amènera au sacrificateur, en sacrifice de réparation, un bélier sans défaut, choisi du troupeau, évalué, par toi, et le sacrificateur fera pour lui propitiation à l\'égard du péché qu\'il a commis par erreur et qu\'il n\'a pas connu, et il lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'C\'est un sacrifice de réparation; car il était réellement coupable envers l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Lorsque quelqu\'un péchera et commettra une infidélité envers l\'Eternel, en mentant à son prochain au sujet d\'un dépôt ou d\'un prêt ou d\'un larcin, ou qu\'il aura extorqué quelque chose à son prochain,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'ou qu\'il aura trouvé un objet perdu et mentira à ce sujet, et qu\'il aura fait un faux serment au sujet de l\'une des choses dans lesquelles l\'homme peut pécher;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'quand il aura ainsi péché et se reconnaîtra coupable, il rendra l\'objet qu\'il a ravi ou extorqué ou le dépôt qui lui avait été confié, ou l\'objet perdu qu\'il a trouvé,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'ou tout objet au sujet duquel il a juré faussement; il le restituera en son entier et il ajoutera un cinquième en sus et le remettra à celui à qui il appartient, le jour même où il offrira le sacrifice de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Il amènera au sacrificateur son sacrifice de réparation à l\'Eternel, savoir le bélier sans défaut, choisi du troupeau, évalué par toi, comme sacrifice de réparation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'et le sacrificateur fera propitiation pour lui en présence de l\'Eternel, et il lui sera pardonné, quelle que soit la faute dont il se sera rendu coupable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Donne cet ordre à Aaron et à ses fils et dis-leur: C\'est ici la loi de l\'holocauste: L\'holocauste [restera] sur le foyer de l\'autel toute la nuit jusqu\'au matin, et le feu y sera tenu allumé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Le sacrificateur revêtira sa tunique de lin et mettra des caleçons de lin sur sa chair, et il enlèvera la cendre produite par le feu qui aura consumé l\'holocauste sur l\'autel, et la déposera à côté de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Puis il quittera ses vêtements et en mettra d\'autres et transportera la cendre hors du camp dans un lieu pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'On fera brûler le feu sur l\'autel sans qu\'il s\'éteigne. Le sacrificateur y allumera du bois tous les matins et arrangera dessus l\'holocauste et y fera fumer les graisses des sacrifices d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Un feu continuel doit brûler sur l\'autel sans s\'éteindre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'C\'est ici la loi de l\'oblation: Les fils d\'Aaron la présenteront devant l\'Eternel, devant l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Puis on prélèvera une poignée de fleur de farine avec son huile et tout l\'encens qui est sur l\'oblation, et on fera fumer cela sur l\'autel, en agréable odeur, comme mémorial pour l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Et ce qui restera de l\'oblation, Aaron et ses fils le mangeront; on le mangera sans levain en lieu saint; c\'est dans le parvis de la Tente d\'assignation qu\'ils le mangeront.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'On ne le cuira pas avec du levain. C\'est la part que je leur ai donnée de mes sacrifices, faits par le feu. C\'est une chose très sainte, comme le sacrifice pour le péché et comme le sacrifice de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Tout mâle, fils d\'Aaron, en mangera. C\'est une part perpétuelle assignée à vos descendants sur les offrandes faites par le feu à l\'Eternel. Quiconque y touchera sera saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'C\'est ici l\'offrande d\'Aaron et de ses fils, qu\'ils offriront à l\'Eternel le jour où on l\'oindra: un dixième d\'épha de fleur de farine, comme oblation perpétuelle, moitié, le matin et moitié le soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Elle sera apprêtée à l\'huile dans la poêle; tu l\'apporteras à l\'état de friture; tu l\'offriras en morceaux comme offrande divisée, en agréable odeur à l\'Eternel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'et le sacrificateur oint qui lui succédera d\'entre ses fils fera [aussi] cette offrande: c\'est la part assignée perpétuellement à l\'Eternel; elle sera consumée tout entière.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Toute oblation de sacrificateur sera consumée entièrement; on ne la mangera pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Parle à Aaron et à ses fils, et dis-leur: C\'est ici la loi du sacrifice pour le péché: Dans le lieu où l\'on égorge l\'holocauste, c\'est là que sera égorgée la victime pour le péché devant l\'Eternel. C\'est une chose très sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Le sacrificateur qui l\'offrira la mangera; elle doit être mangée en lieu saint dans le parvis de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Quiconque en touchera la chair sera saint, et s\'il en rejaillit du sang sur un vêtement, ce sur quoi le sang aura rejailli tu le laveras en lieu saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Le vase de terre qui aura servi à la cuire sera brisé; si c\'est dans un vase d\'airain qu\'elle a cuit, il sera écuré et rincé dans l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Tout mâle sacrificateur en mangera; c\'est une chose très sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Mais nulle victime pour le péché dont on doit porter du sang dans la Tente d\'assignation, pour faire propitiation dans le sanctuaire, ne sera mangée. Elle sera brûlée au feu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'C\'est ici la loi du sacrifice de réparation; c\'est une chose très sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Dans le lieu où l\'on égorge l\'holocauste, c\'est là qu\'on égorgera la victime de réparation; l\'on arrosera de son sang l\'autel tout autour,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'et l\'on en offrira toute la graisse, la queue, la graisse qui recouvre les entrailles');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'et les deux rognons et la graisse qui les enveloppe et qui tient aux lombes, et la taie du foie; il la détachera près des rognons.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Et le sacrificateur les fera fumer sur l\'autel en sacrifice fait par le feu à l\'Eternel. C\'est un sacrifice de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Tout mâle sacrificateur en mangera; on le mangera en lieu saint; c\'est une chose très sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Il en est du sacrifice de réparation comme du sacrifice pour le péché; ils ont une même loi: la victime sera pour le sacrificateur qui fera la propitiation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Le sacrificateur qui offrira l\'holocauste de quelqu\'un, aura pour lui la peau de l\'holocauste qu\'il a offert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Toute oblation cuite au four et toute offrande préparée dans la casserole ou à la poêle sera pour le sacrificateur qui l\'a offerte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Et toute oblation pétrie à l\'huile ou sèche sera pour tous les fils d\'Aaron, pour l\'un comme pour l\'autre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'C\'est ici la loi du sacrifice d\'actions de grâces que l\'on offrira à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si on offre en hommage de reconnaissance, on offrira avec la victime de l\'hommage des gâteaux sans levain, pétris à l\'huile, et des galettes sans levain, ointes d\'huile, et de la fleur de farine frite, en gâteaux pétris à l\'huile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'On présentera l\'offrande sur les gâteaux de pain levé, avec la victime d\'hommage du sacrifice d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'On présentera de chacune de ces offrandes une pièce en oblation élevée à l\'Eternel; elle appartiendra au sacrificateur qui aura fait l\'aspersion du sang du sacrifice d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Et la chair de la victime d\'hommage du sacrifice d\'actions de grâces sera mangée le jour où on l\'aura offerte. On n\'en laissera rien jusqu\'au matin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Si la victime offerte est votive ou volontaire, la victime sera mangée le jour où on l\'aura offerte et le lendemain on en mangera le reste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Et ce qui restera de la chair de la victime au troisième jour, sera brûlé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Que si l\'on mange de la chair de la victime du sacrifice d\'actions de grâces le troisième jour, celui qui l\'aura offert ne sera point agréé; il ne lui en sera point tenu compte; ce sera une chose fétide, et la personne qui en aura mangé portera son iniquité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'La chair qui touchera quoi que ce soit de souillé ne se mangera pas: elle sera brûlée. Et la chair, quiconque est pur en mangera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Mais toute personne qui, étant souillée, aura mangé de la chair de la victime d\'actions de grâces appartenant à l\'Eternel, cette personne sera retranchée d\'entre les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Si quelqu\'un touche quoi que ce soit de souillé, souillure d\'homme, ou animal souillé, ou quelque abomination immonde, et qu\'il mange de la chair de la victime d\'actions de grâces appartenant à l\'Eternel, cette personne sera retranchée d\'entre les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Parle ainsi aux fils d\'Israël: Vous ne mangerez point de graisse de bœuf, ni d\'agneau, ni de chevreau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'La graisse d\'une bête morte et celle d\'une bête déchirée pourra servir à un usage quelconque; mais vous n\'en mangerez absolument pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Car quiconque mangera de la graisse des animaux dont on offre à l\'Eternel des sacrifices faits par le feu, la personne qui en aura mangé sera retranchée d\'entre les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Vous ne mangerez point de sang soit d\'oiseau, soit de quadrupède, dans tous les lieux où vous habiterez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Toute personne qui mangera d\'un sang quelconque, cette personne-là sera retranchée d\'entre les siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Parle aux fils d\'Israël et dis-leur: Celui qui offrira à l\'Eternel sa victime d\'actions de grâces, prélèvera sur ce sacrifice son offrande à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Il apportera de ses propres mains ce qui doit être offert à l\'Eternel par le feu. Il apportera la graisse avec la poitrine, la poitrine pour la balancer en offrande devant l\'Eternel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'et le sacrificateur fera fumer, la graisse sur l\'autel, et la poitrine sera pour Aaron et ses fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Vous donnerez aussi au sacrificateur en offrande élevée la cuisse droite de vos victimes, d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Celui des fils d\'Aaron qui offrira le sang et la graisse des sacrifices d\'actions de grâces, la cuisse droite lui reviendra pour sa part.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Car j\'ai pris, sur les sacrifices d\'actions de grâces des enfants d\'Israël, la poitrine qu\'on balance et la cuisse offerte par élévation, et je les donne à Aaron le sacrificateur et à ses fils par une ordonnance perpétuelle qu\'observeront les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'C\'est là le droit que l\'onction donnera à Aaron et à ses fils sur les sacrifices faits par le feu à l\'Eternel, au jour où on les présentera pour qu\'ils servent l\'Eternel comme sacrificateurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'C\'est là ce que l\'Eternel a commandé aux fils d\'Israël de leur donner depuis le jour de leur onction. C\'est une part perpétuelle qui leur est due d\'âge en âge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Telle est la loi pour l\'holocauste, pour l\'oblation, pour le sacrifice pour le péché, pour le sacrifice de réparation, pour l\'installation et pour le sacrifice d\'actions de grâces,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'loi que l\'Eternel donna à Moïse en la montagne de Sinaï, au jour où il ordonna aux enfants d\'Israël de présenter leurs offrandes à l\'Eternel dans le désert de Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'L\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Prends Aaron et ses fils avec lui, les vêtements, l\'huile d\'onction, le taureau pour le sacrifice pour le péché, les deux béliers et la corbeille de pains sans levain,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'et convoque toute l\'assemblée à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Moïse fit comme l\'Eternel lui avait commandé, et l\'assemblée se réunit à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Et Moïse dit à l\'assemblée: Voici ce que l\'Eternel a commandé de faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Moïse fit approcher Aaron et ses fils, et les lava avec de l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Et il mit à Aaron la tunique, le ceignit de la ceinture et le revêtit du surplis, et il plaça sur lui l\'éphod, qu\'il fixa avec la boucle de l\'éphod, et il le lui attacha.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Il lui mit le pectoral et mit au pectoral l\'Urim et le Thummim.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Il posa la tiare sur sa tête et, sur le devant de la tiare, la lame d\'or, saint diadème, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Et Moïse prit l\'huile d\'onction et il oignit le sanctuaire et toutes les choses qui y étaient, et il les consacra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Et il en fit sept fois aspersion sur l\'autel et il oignit l\'autel et tous ses ustensiles et la cuve et sa base, pour les consacrer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Et il versa de l\'huile d\'onction sur la tête d\'Aaron et l\'oignit pour le consacrer.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Et Moïse fit approcher les fils d\'Aaron; il les revêtit de tuniques, les ceignit de ceintures et leur attacha des mitres, comme l\'Eternel l\'avait commandé à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Et il fit avancer le taureau du sacrifice pour le péché, et Aaron et ses fils appuyèrent leurs mains sur la tête du taureau du sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Moïse l\'égorgea, prit le sang et en mit avec son doigt sur les cornes de l\'autel tout autour et purifia l\'autel; et il répandit le sang au pied de l\'autel et le consacra en faisant propitiation sur lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Et Moïse prit toute la graisse qui était sur les entrailles, la taie du foie et les deux rognons avec leur graisse, et Moïse les fit fumer sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Et le taureau, avec sa peau, sa chair et sa fiente, il le brûla hors du camp, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Et il fit approcher le bélier de l\'holocauste; et Aaron et ses fils appuyèrent leurs mains sur la tête du bélier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Et on l\'égorgea, et Moïse arrosa du sang l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Et on coupa le bélier, en ses pièces, et Moïse fit fumer la tête, les pièces et la fressure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Et on lava dans l\'eau les entrailles et les jambes, et Moïse fit fumer tout le bélier sur l\'autel; c\'était un holocauste d\'agréable odeur, un sacrifice fait par le feu à l\'Eternel, comme l\'Eternel l\'avait ordonné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Et il fit approcher le second bélier, le bélier d\'installation, et Aaron et ses fils appuyèrent leurs mains sur la tête du bélier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Il l\'égorgea, et Moïse prit de son sang et en mit sur le lobe de l\'oreille droite d\'Aaron, sur le pouce de sa main droite et sur le gros orteil de son pied droit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Et il fit approcher les fils d\'Aaron; et Moïse mit du sang sur le lobe de leur oreille droite, sur le pouce de leur main droite et sur le gros orteil de leur pied droit; et Moïse arrosa du sang l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Et il prit la graisse, la queue, toute la graisse qui était sur les entrailles, la taie du foie, les deux rognons avec leur graisse et la cuisse droite,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'puis, de la corbeille des pains sans levain qui était devant l\'Eternel, un gâteau de pain sans levain, un gâteau de pain à l\'huile et une galette; il les mit sur les graisses et sur la cuisse droite,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'et il plaça toutes ces choses sur les paumes des mains d\'Aaron et des mains de ses fils, et les balança en offrande devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Et Moïse les prit de dessus leurs mains et les fit fumer sur l\'autel, sur l\'holocauste. C\'était un sacrifice d\'installation, d\'agréable odeur; un sacrifice fait par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Et Moïse prit la poitrine du bélier d\'installation et la balança en offrande balancée devant l\'Eternel; ce fut la portion de Moïse, comme l\'Eternel l\'avait commandé à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Et Moïse prit de l\'huile d\'onction et du sang qui était sur l\'autel et il en fit l\'aspersion sur Aaron, sur ses vêtements, sur ses fils et les vêtements de ses fils avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Et Moïse dit à Aaron et à ses fils: Faites cuire la chair à l\'entrée de la Tente d\'assignation et vous la mangerez là avec le pain qui est dans la corbeille d\'installation, comme je l\'ai ordonné en disant: Aaron et ses fils mangeront cela.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Ce qui restera de la chair et du pain, vous le brûlerez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Et pendant sept jours vous ne sortirez pas de l\'entrée de la Tente d\'assignation, jusqu\'à ce que les jours de votre installation soient accomplis; car votre installation durera sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Ce qui s\'est fait en ce jour, l\'Eternel l\'a ordonné, afin de faire propitiation pour vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Vous resterez sept jours à l\'entrée de la Tente d\'assignation, jour et nuit, et vous observerez l\'ordonnance de l\'Eternel, et vous ne mourrez pas; car il a été ainsi ordonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Et Aaron et ses fils firent toutes les choses que l\'Eternel avait commandées à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Le huitième jour, Moïse, ayant appelé Aaron et ses fils et les Anciens d\'Israël,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'dit à Aaron: Prends un jeune veau pour le sacrifice pour le péché, et un bélier pour l\'holocauste, tous deux sans défaut, et offre-les à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Et tu parleras ainsi aux fils d\'Israël: Prenez un bouc pour le sacrifice pour le péché; un veau et un agneau âgés d\'un an, sans défaut, pour l\'holocauste;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'un taureau et un bélier pour le sacrifice d\'actions de grâces, pour les sacrifier devant l\'Eternel, et une oblation pétrie à l\'huile; car aujourd\'hui l\'Eternel vous apparaîtra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Et ils amenèrent devant la Tente d\'assignation ce que Moïse avait commandé; et toute l\'assemblée s\'approcha et se tint devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Et Moïse dit: Voici ce que l\'Eternel vous ordonne; faites-le, et la gloire de l\'Eternel vous apparaîtra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Et Moïse dit à Aaron: Approche-toi de l\'autel; offre ton sacrifice pour le péché et ton holocauste; et fais propitiation pour toi et pour le peuple; présente aussi l\'offrande du peuple et fais propitiation pour eux, comme l\'Eternel l\'a commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Aaron s\'approcha de l\'autel, et il égorgea le veau du sacrifice pour le péché offert pour lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Et les fils d\'Aaron lui présentèrent le sang; il trempa son doigt dans le sang, en mit sur les cornes de l\'autel, et répandit le sang sur le pied de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Et il fit fumer sur l\'autel la graisse, les rognons et la taie du foie de la victime pour le péché, comme l\'Eternel l\'avait commandé à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Et la chair et la peau, il les brûla hors du camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Et il égorgea l\'holocauste. Les fils d\'Aaron lui présentèrent le sang, et il en arrosa l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Et ils lui présentèrent l\'holocauste par pièces, et la tête, et il les fit fumer sur l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Il lava les entrailles et les jambes, et il les fit fumer sur l\'holocauste, à l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Et il présenta l\'offrande du peuple. Il prit le bouc du sacrifice pour le péché offert pour le peuple; il l\'égorgea et l\'offrit pour le péché, comme la première victime.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Et il offrit l\'holocauste et le fit selon l\'ordonnance.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Et il présenta l\'oblation; il en prit une poignée et la fit fumer sur l\'autel, en sus de l\'holocauste du matin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Et il égorgea le taureau et le bélier en sacrifice d\'actions de grâces pour le peuple. Les fils d\'Aaron lui présentèrent le sang, et il en arrosa l\'autel tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Et ils lui présentèrent les graisses du taureau et du bélier, la queue, ce qui recouvre les entrailles, les rognons et la taie du foie;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'et ils mirent les graisses sur les poitrines, et il fit fumer les graisses à l\'autel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'et les poitrines et la cuisse droite, Aaron les balança devant l\'Eternel, en offrande balancée, comme Moïse l\'avait commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Et Aaron éleva les mains vers le peuple et le bénit; et il descendit, après avoir offert le sacrifice pour le péché, l\'holocauste et le sacrifice d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Et Moïse et Aaron entrèrent dans la Tente d\'assignation; ils sortirent et bénirent le peuple; et la gloire de l\'Eternel apparut à tout le peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Un feu sortit de devant l\'Eternel et dévora sur l\'autel l\'holocauste et les graisses; et tout le peuple le vit, et ils poussèrent des cris de joie et tombèrent sur leurs faces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Et les fils d\'Aaron, Nadab et Abihu, prirent chacun son encensoir, y mirent du feu, posèrent du parfum dessus, et offrirent devant l\'Eternel un feu étranger; ce qu\'il ne leur avait point commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Et un feu sortit de devant l\'Eternel et les dévora, et ils moururent devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Et Moïse dit à Aaron: C\'est ce dont l\'Eternel a parlé en disant: Je serai sanctifié en ceux qui s\'approchent de moi, et je serai glorifié en présence de tout le peuple. Et Aaron se tut.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Et Moïse appela Misaël et Eltsaphan, fils d\'Uzziel, oncle d\'Aaron, et leur dit: Approchez-vous, emportez vos frères de devant le sanctuaire, hors du camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Et ils s\'approchèrent et les emportèrent dans leurs tuniques hors du camp, comme Moïse l\'avait dit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Et Moïse dit à Aaron et à Eléazar et à Ithamar, ses fils: Ne décoiffez pas vos têtes et ne déchirez point vos vêtements, de peur que vous ne mouriez et qu\'Il ne s\'irrite contre toute l\'assemblée. Vos frères, toute la maison d\'Israël, pleureront sur l\'embrasement que l\'Eternel a fait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Et ne sortez pas de l\'entrée de la Tente d\'assignation, de peur que vous ne mouriez; car l\'huile de l\'onction de l\'Eternel est sur vous. Et ils firent selon la parole de Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Puis l\'Eternel parla à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Ne bois ni vin ni cervoise, toi non plus que tes fils, quand vous entrerez dans la Tente d\'assignation, afin que vous ne mouriez pas, c\'est une loi perpétuelle de génération en génération,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'et [aussi] afin que vous puissiez discerner entre ce qui est saint et ce qui est profane, entre ce qui est souillé et ce qui est pur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'et enseigner aux fils d\'Israël toutes les ordonnances que l\'Eternel leur a données par Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Et Moïse dit à Aaron et à Eléazar et à Ithamar, ses fils, qui lui restaient: Prenez l\'oblation restant des sacrifices faits par le feu à l\'Eternel et mangez-la en pains sans levain à côté de l\'autel, car c\'est une chose très sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Vous la mangerez dans un lieu saint, car c\'est ta part et celle de tes fils sur les sacrifices faits par le feu à l\'Eternel; car tel est l\'ordre que j\'ai reçu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Quant à la poitrine qui aura été balancée et à la cuisse qui aura été prélevée, vous les mangerez en lieu pur, toi, tes fils et tes filles avec toi; car elles vous sont données comme ta part et la part de tes fils sur les sacrifices d\'actions de grâces des fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'On joindra avec les graisses destinées à être consumées par le feu la cuisse prélevée et la poitrine que l\'on offre en la balançant, afin qu\'elles soient balancées devant l\'Eternel; et cela t\'appartiendra ainsi qu\'à tes fils par une ordonnance perpétuelle, comme l\'Eternel l\'a commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Et Moïse s\'enquit de ce qu\'était devenu le bouc du sacrifice pour le péché; et il se trouva qu\'on l\'avait brûlé. Alors il s\'irrita contre Eléazar et Ithamar, les fils survivants d\'Aaron, et leur dit:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Pourquoi n\'avez-vous pas mangé le sacrifice pour le péché dans le saint lieu? car c\'est une chose très sainte, et cela vous a été donné, afin que vous portiez l\'iniquité de l\'assemblée, pour que vous fassiez propitiation pour eux devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Voici, quand le sang de la victime n\'a pas été porté dans l\'intérieur du sanctuaire, vous ne devez pas manquer de la manger dans le saint lieu, comme je l\'ai commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Et Aaron dit à Moïse: Voici, aujourd\'hui ils ont offert leur sacrifice pour le péché et leur holocauste devant l\'Eternel; et voilà ce qui m\'est arrivé, et j\'aurais mangé aujourd\'hui le sacrifice pour le péché! Est-ce que l\'Eternel l\'aurait approuvé?');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Et Moïse entendit cela et l\'approuva.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Et l\'Eternel parla à Moïse et à Aaron en leur disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Parlez aux fils d\'Israël, disant: Voici les bêtes que vous mangerez d\'entre tous les animaux qui sont sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Tout animal qui a l\'ongle divisé et le pied fourchu et qui rumine, vous le mangerez;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'mais voici ce que vous ne mangerez pas: ceux qui ruminent [seulement] ou qui ont [seulement] l\'ongle divisé: [ainsi] le chameau, qui rumine, mais qui n\'a pas l\'ongle divisé; il vous sera souillé;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'et la gerboise, qui rumine, mais qui n\'a pas l\'ongle divisé; elle vous sera souillée;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'et le lièvre, qui rumine, mais qui n\'a pas l\'ongle divisé; il vous sera souillé;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'et le porc, qui a l\'ongle divisé et le pied fourchu, mais qui ne rumine pas; il vous sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vous ne mangerez pas de leur chair, vous ne toucherez point leurs cadavres; ils vous seront souillés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Voici les animaux que vous mangerez, de tout ce qui est dans les eaux. Vous mangerez tout ce qui a nageoires et écailles, dans les eaux, mers et rivières;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'mais tout ce qui n\'a pas nageoires et écailles dans les mers et dans les rivières, d\'entre tout ce qui pullule dans les eaux et d\'entre tous les êtres vivants qui s\'y trouvent, est pour vous une abomination.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ils vous seront une abomination; vous ne mangerez pas de leur chair et vous tiendrez pour abominable leur cadavre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Tout ce qui dans les eaux n\'a pas nageoires et écailles vous sera en abomination.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Et voici ceux d\'entre les oiseaux que vous aurez en abomination; on ne les mangera pas, c\'est une abomination: l\'aigle, l\'orfraie et le vautour,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'le milan et toute espèce de faucons;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'toute espèce de corbeaux;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'l\'autruche, le chat-huant, la mouette, toute espèce d\'éperviers;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'le hibou, le plongeon, l\'ibis;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'la chouette, le pélican, le gypaète,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'la cigogne, toute espèce de hérons; la huppe et la chauve-souris.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Vous aurez en abomination toute bête ailée marchant sur quatre [pattes].');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Mais voici ce que vous mangerez d\'entre les bêtes ailées marchant sur quatre pattes: celles qui ont des jambes au-dessus de leurs pattes pour sauter sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'D\'entre elles voici celles que vous mangerez: toute espèce de sauterelles, toute espèce de solam, toute espèce de hargol, toute espèce de hagab.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Toute [autre] bête ailée marchant sur quatre pattes vous sera en abomination.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Ceux-ci aussi vous rendront souillés; quiconque touchera leur cadavre sera souillé jusqu\'au soir,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'et quiconque transportera quelque partie de leur corps mort lavera ses vêtements et sera souillé, jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Toute bête qui a l\'ongle divisé et qui n\'a pas le pied fourchu et qui ne rumine pas, vous sera souillée; quiconque les touchera sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Et tout ce qui marche sur la plante des pieds, entre tous les animaux marchant à quatre pieds, vous sera souillé; quiconque touchera leur corps mort sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Et quiconque portera leur corps mort, lavera ses vêtements et sera souillé jusqu\'au soir, ces animaux vous seront souillés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Et voici ce qui sera souillé pour vous parmi les petites bêtes qui bougent sur la terre: la belette, la souris et toute espèce de lézards;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'la musaraigne, la taupe, la salamandre, le colimaçon et le caméléon.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ceux-ci sont souillés pour vous entre tout ce qui bouge; quiconque les touchera morts sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Tout objet sur lequel il en tombera quand ils seront morts, sera souillé, ustensile de bois, vêtement, peau, sac, tout objet dont on fait usage; il sera mis dans l\'eau et sera souillé jusqu\'au soir; puis il sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Et s\'il en tombe quelque chose dans un vase de terre, tout ce qui se trouvera dedans, sera souillé, et vous briserez le vase.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Tout aliment dans lequel entre de l\'eau sera souillé; et tout breuvage qu\'on boit, quel que soit le vase qui le contienne, sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Tout objet sur lequel tombe quelque chose de leur corps mort sera souillé; le four et le foyer seront détruits; ils sont souillés et ils vous seront souillés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Toutefois une source ou une citerne où l\'eau s\'amasse restera pure; mais celui qui touchera leur corps mort sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Et s\'il tombe quelque chose de leur cadavre sur quelque semence que l\'on sème, elle restera pure;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'mais si l\'on a mis de l\'eau sur la semence et qu\'il y tombe quelque chose de leur cadavre, elle vous sera souillée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'S\'il meurt une des bêtes qui vous servent de nourriture, celui qui touchera le cadavre sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Celui qui mangera de son corps mort lavera ses vêtements et sera souillé jusqu\'au soir, et celui qui portera son corps mort lavera ses vêtements et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Tout ce qui bouge et rampe sur la terre est une abomination; on n\'en mangera point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Tout animal qui rampe sur la terre, vous n\'en mangerez pas, soit ceux qui se traînent sur le ventre, soit ceux qui marchent sur quatre pieds ou sur un grand nombre de pieds.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ne rendez pas vos personnes abominables par tous ces animaux qui rampent; ne vous rendez point impurs par eux; vous seriez impurs par eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Car je suis l\'Eternel votre Dieu; vous vous sanctifierez et vous serez saints, car je suis saint; et vous ne souillerez point vos personnes par aucun de ces animaux qui rampent sur la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Car je suis l\'Eternel qui vous ai fait monter du pays d\'Egypte pour être votre Dieu; vous serez saints, car je suis saint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Telle est la loi touchant les quadrupèdes, les oiseaux, tout être vivant qui se meut dans les eaux, et tout être qui rampe sur la terre,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'afin de distinguer entre ce qui est souillé et ce qui est pur, entre l\'animal qui se mange et celui qui ne se mange pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Parle aux fils d\'Israël et dis: Quand une femme enfantera et donnera le jour à un garçon, elle sera souillée sept jours; elle sera souillée comme aux jours où l\'isole son indisposition.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Le huitième jour on circoncira la chair du prépuce de l\'enfant;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'puis, pendant trente-trois jours, elle demeurera chez elle, à cause du sang de purification; elle ne touchera aucune chose sainte; elle n\'ira point au sanctuaire jusqu\'à ce que les jours de sa purification soient accomplis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Et si elle enfante une fille, elle sera souillée deux semaines comme aux jours où l\'isole son indisposition, et elle demeurera chez elle soixante-six jours à cause du sang de sa purification.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Et quand les jours de sa purification seront accomplis pour un fils ou pour une fille, elle présentera au sacrificateur, à l\'entrée de la Tente d\'assignation, un agneau d\'un an en holocauste, et un pigeonneau ou une tourterelle en sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Le sacrificateur les offrira devant l\'Eternel et fera propitiation pour elle, et elle sera pure du flux de son sang. Telle est la loi de l\'accouchée, tant pour un garçon que pour une fille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Mais si elle n\'a pas le moyen d\'offrir un agneau, elle prendra deux tourterelles ou deux pigeonneaux, l\'un pour l\'holocauste et l\'autre pour le sacrifice pour le péché; et le sacrificateur fera propitiation pour elle et elle sera pure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Et l\'Eternel parla à Moïse et à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Quand un homme aura sur, la peau de sa chair une tumeur ou une dartre ou une tache qui semble devenir sur la peau de son corps un mal de lèpre, on l\'amènera à Aaron, le sacrificateur, ou à un de ses fils, les sacrificateurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Et quand le sacrificateur aura vu le mal qui est sur la peau de sa chair, si le poil de la partie malade est devenu blanc et que le mal paraisse plus profond que la peau de la chair, c\'est la lèpre, et le sacrificateur, l\'ayant vu, le déclarera impur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mais s\'il y a sur la peau de la chair une tache blanche qui ne paraisse pas plus profonde que la peau, et que le poil ne soit pas devenu blanc, le sacrificateur séquestrera pendant sept jours celui qui est atteint du mal.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Au septième jour, le sacrificateur le verra, et dans le cas où le mal lui paraît s\'être arrêté, ne s\'étant pas étendu sur la peau, le sacrificateur le séquestrera une seconde fois pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Et le sacrificateur l\'examinera une seconde fois au septième jour; si la place malade a cessé d\'être luisante et ne s\'est pas étendue sur la peau, le sacrificateur déclarera cet homme pur; c\'est une dartre. Il lavera ses vêtements et sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Si la dartre s\'est étendue sur la peau après qu\'il se sera montré au sacrificateur pour être déclaré pur, il se montrera une seconde fois au sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Et si le sacrificateur s\'aperçoit que la dartre s\'est étendue sur la peau le sacrificateur le déclarera souillé; c\'est la lèpre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Lorsqu\'un homme sera atteint de lèpre, on l\'amènera au sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Et si le sacrificateur voit qu\'il y a une tumeur blanche sur la peau et qu\'elle a rendu le poil blanc et qu\'il y a de la chair vive dans la tumeur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'c\'est une lèpre invétérée dans la peau de sa chair, et le sacrificateur le déclarera souillé; il ne l\'enfermera pas, car il est souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Mais si la lèpre a complètement poussé sur la peau et que la lèpre couvre toute la peau de celui qui en est atteint, depuis la tête jusqu\'aux pieds, d\'après tout ce que voit le sacrificateur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'et si le sacrificateur constate que la lèpre a couvert toute la chair du malade, il le déclarera pur; il est devenu tout entier blanc, il est pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mais du moment où il y paraîtra de la chair vive, il sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Et le sacrificateur ayant vu la chair vive, le déclarera souillé; la chair vive est souillée, c\'est la lèpre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mais si la chair vive redevient blanche, il ira auprès du sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Le sacrificateur ayant constaté que la partie malade est devenue blanche, déclarera pur le malade; il est pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Lorsque la peau de quelqu\'un aura un abcès qui aura été guéri,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'et que, à la place où était l\'abcès, il y aura une tumeur blanche, ou une tache d\'un blanc rougeâtre, cet homme se montrera au sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Et si le sacrificateur constate que la tache paraît plus enfoncée que la peau, et que le poil y est devenu blanc, il le déclarera souillé; c\'est de la lèpre; elle a poussé dans l\'abcès.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mais si le sacrificateur voit qu\'il n\'y a point de poil blanc dans la tache, qu\'elle n\'est pas plus enfoncée que la peau et qu\'elle est devenue pâle, le sacrificateur séquestrera cet homme pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Si elle s\'étend sur la peau, le sacrificateur le déclarera souillé; il est atteint.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mais si la tache est restée au même point, sans s\'étendre, c\'est la cicatrice de l\'abcès; le sacrificateur le déclarera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Ou bien lorsque la peau de quelqu\'un aura une brûlure faite parle feu et qu\'il se produira sur cette brûlure une tache d\'un blanc rougeâtre ou blanche,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'si le sacrificateur, l\'ayant examinée, constate que le poil est devenu blanc dans la tache, et qu\'elle est plus profonde que la peau, c\'est la lèpre; elle a poussé dans la brûlure. Le sacrificateur déclarera cet homme souillé; il est atteint de lèpre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mais si le sacrificateur voit qu\'il n\'y a point de poil blanc dans la tache, qu\'elle n\'est pas plus enfoncée que la peau et qu\'elle est devenue pâle, le sacrificateur séquestrera cet homme pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Et quand le sacrificateur l\'aura examiné le septième jour, si la tache s\'est étendue sur la peau, le sacrificateur le déclarera souillé; il est atteint de lèpre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mais si la tache est restée au même point, sans s\'étendre sur la peau, et qu\'elle soit devenue pâle, c\'est la tumeur de la brûlure. Le sacrificateur le déclarera pur, car c\'est la cicatrice de la brûlure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Si quelqu\'un, homme ou femme, a une place malade à la tête ou sous la barbe,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'le sacrificateur examinera le mal. S\'il paraît plus profond que la peau, et qu\'il s\'y trouve du poil roux et grêle, le sacrificateur le déclarera souillé; c\'est la teigne, la lèpre de la tête ou de la barbe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mais si le sacrificateur, regardant la place, constate que la place de la plaie ne paraît pas plus profonde que la peau, sans pourtant qu\'il y ait de poil noir, il séquestrera pendant sept jours celui qui est atteint de la teigne,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'et au septième jour, quand le sacrificateur aura constaté que la teigne ne s\'est point étendue et qu\'elle n\'a point de poil jaune et que la plaie de la teigne n\'apparaît pas plus profonde que la peau,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'l\'homme se rasera, mais il ne rasera pas la place où est la teigne; et le sacrificateur séquestrera une seconde fois, pendant sept jours, celui qui est atteint de la teigne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Puis, au septième jour, le sacrificateur examinera la teigne; si elle ne s\'est pas étendue sur la peau et qu\'elle n\'apparaisse pas plus profonde que la peau, le sacrificateur le déclarera pur; il lavera ses vêtements et sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mais si la teigne s\'est étendue sur la peau après qu\'il aura été déclaré pur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'le sacrificateur l\'examinera. Et si la teigne s\'est étendue sur la peau, le sacrificateur n\'aura pas à rechercher si le poil est jaune; il est souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mais si la teigne lui montre encore le même aspect et qu\'il y ait crû des poils noirs, la teigne est guérie; il est guéri, et le sacrificateur le déclarera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Lorsque quelqu\'un, homme ou femme, a sur la peau des taches, des taches blanches,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'le sacrificateur l\'examinera; si les taches sur la peau sont d\'un blanc pâle, c\'est un exanthème qui a poussé sur la peau; il est pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Lorsqu\'un homme perd ses cheveux sur la tête, c\'est une calvitie du crâne; il est pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Si la tête se dégarnit du côté de la face, c\'est une calvitie du front; il est pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mais s\'il y a dans la partie chauve de devant ou de derrière une place d\'un blanc rougeâtre, c\'est la lèpre qui a fait éruption dans la partie chauve de derrière ou de devant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Si le sacrificateur, en l\'examinant, constate que la tumeur est d\'un blanc rougeâtre dans la partie chauve de derrière ou de devant, et qu\'elle a l\'aspect d\'une lèpre de la peau,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'il est lépreux, il est souillé; le sacrificateur doit le déclarer souillé; c\'est à la tête que le mal a éclaté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Le lépreux atteint du mal aura ses vêtements déchirés et la tête nue; il se couvrira la barbe et criera: Souillé, souillé!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Tout le temps que dure son mal il sera souillé. Il est souillé; il habitera seul; sa demeure sera hors du camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Quant aux vêtements, quand il s\'y montrera de la lèpre, que ce soit vêtement de laine ou vêtement de lin,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'tissu ou tricot de lin ou de laine, ou du cuir, ou un ouvrage quelconque fait de cuir,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'si la tache est verdâtre ou rougeâtre sur le vêtement ou sur le cuir, ou sur le tissu, ou sur le tricot, ou sur un objet de cuir quelconque, c\'est la lèpre; on la fera voir au sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Le sacrificateur examinera la tache et il enfermera l\'objet attaqué pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Le septième jour, il examinera la tache. Si la tache s\'est étendue sur le vêtement, ou sur le tissu, ou sur le tricot, ou sur le cuir, ou sur l\'ouvrage quelconque fait de cuir, c\'est une tache de lèpre maligne; l\'objet est souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Il brûlera le vêtement, ou le tissu, ou le tricot de laine ou de lin, ou tout objet fait de cuir sur lequel sera la tache, car c\'est une lèpre maligne; il doit être brûlé au feu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Mais si le sacrificateur voit que la tache ne s\'est pas étendue sur le vêtement, sur le tissu, ou sur le tricot, ou sur l\'objet quelconque fait de cuir,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'le sacrificateur fera laver l\'objet attaqué et l\'enfermera pendant sept jours une seconde fois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Et le sacrificateur examinera la tache après qu\'elle aura été lavée; si la tache n\'a pas changé d\'aspect et ne s\'est pas étendue, l\'objet est souillé; tu le brûleras; il y a corrosion à l\'endroit ou à l\'envers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mais si le sacrificateur voit que la plaie a pâli après avoir été lavée, il l\'arrachera du vêtement, ou du cuir, ou du tissu, ou du tricot.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Si elle paraît encore sur le vêtement, ou sur le tissu, ou sur le tricot, ou sur tout objet de cuir, c\'est la lèpre qui est apparue; tu brûleras l\'objet où est la tache.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mais le vêtement, ou le tissu, ou le tricot, ou un objet fait de cuir que tu auras lavé et d\'où la tache sera partie, sera lavé une seconde fois, et il sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Telle est la règle concernant la tache de lèpre sur un vêtement de laine ou de lin, ou sur un tissu ou un tricot, ou sur tout objet fait de cuir, pour le déclarer pur ou souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Voici quelle sera la loi concernant le lépreux pour le jour de sa purification: On l\'amènera au sacrificateur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'et le sacrificateur se rendra hors du camp, et le sacrificateur constatera que le lépreux est guéri de sa lèpre,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'et le sacrificateur ordonnera que l\'on prenne pour celui qui doit être purifié deux petits oiseaux vivants et purs, du bois de cèdre, du cramoisi et de l\'hysope.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Et le sacrificateur fera égorger l\'un des oiseaux dans un vase de terre, sur de l\'eau vive.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Et il prendra l\'oiseau vivant, ainsi que le bois de cèdre, le cramoisi et l\'hysope, et il les trempera, ainsi que l\'oiseau vivant, dans le sang de l\'oiseau égorgé sur l\'eau vive.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Il en fera sept fois aspersion sur celui qui doit être purifié de la lèpre, et il le déclarera pur et lâchera dans la campagne l\'oiseau vivant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Et celui qui se purifie lavera ses vêtements, rasera tout son poil, se baignera et sera pur; et après cela il entrera dans le camp et il demeurera hors de sa tente pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Au septième jour, il rasera tout son poil, ses cheveux, sa barbe, ses sourcils; il rasera tout son poil, il lavera ses vêtements et baignera son corps dans l\'eau, et il sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Le huitième jour, il prendra deux agneaux sans défaut et une brebis d\'un an sans défaut et trois dixièmes [d\'épha] de fleur de farine, comme oblation pétrie à l\'huile, et un log d\'huile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Et le sacrificateur qui fait la purification présentera l\'homme qui se purifie, ainsi que ces choses, devant l\'Eternel, à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Et le sacrificateur prendra l\'un des agneaux et l\'offrira en sacrifice de réparation, avec le log d\'huile, et il les balancera en offrande balancée devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Et il égorgera l\'agneau au lieu où l\'on égorge le sacrifice pour le péché et l\'holocauste, à la place consacrée; car le sacrifice de réparation appartient au sacrificateur comme le sacrifice pour le péché; c\'est une chose très sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Et le sacrificateur prendra du sang du sacrifice de réparation, et le sacrificateur en mettra sur le lobe de l\'oreille droite de celui qui se purifie et sur le pouce de sa main droite, et sur l\'orteil de son pied droit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Et le sacrificateur prendra le log d\'huile et en versera dans sa main gauche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Et le sacrificateur trempera le doigt de sa main droite dans l\'huile qui sera dans sa main gauche, et fera aspersion de l\'huile, avec son doigt, sept fois devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Et du reste de l\'huile qui est dans sa main, le sacrificateur en mettra sur le lobe de l\'oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur l\'orteil de son pied droit, par-dessus le sang de la victime de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Ce qui restera de l\'huile qui est dans sa main, il le mettra sur la tête de celui qui se purifie, et le sacrificateur fera propitiation pour lui devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Puis le sacrificateur offrira le sacrifice pour le péché et fera propitiation pour celui qui se purifie de sa souillure; et ensuite il immolera l\'holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Et le sacrificateur offrira l\'holocauste et l\'oblation sur l\'autel, et le sacrificateur fera propitiation pour cet homme, et il sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Si l\'homme est pauvre et que ses moyens n\'y suffisent pas, il prendra un seul agneau qui sera offert en sacrifice de réparation en offrande balancée pour faire propitiation pour lui, puis un dixième [d\'épha] de fleur de farine pétrie à l\'huile en oblation et un log d\'huile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Il prendra aussi deux tourterelles ou deux pigeonneaux, selon ses moyens; l\'un sera la victime pour le péché, l\'autre l\'holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Et il les apportera au sacrificateur le huitième jour pour sa purification, à l\'entrée de la Tente d\'assignation, devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Le sacrificateur prendra l\'agneau pour le sacrifice de réparation et le log d\'huile, et le sacrificateur les balancera en offrande balancée devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Et il égorgera l\'agneau du sacrifice de réparation, et le sacrificateur prendra du sang de la victime de réparation et en mettra sur le lobe de l\'oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur l\'orteil de son pied droit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Et le sacrificateur versera de l\'huile dans sa main gauche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Et le sacrificateur, avec le doigt de sa main droite, fera aspersion de l\'huile qui est dans sa main gauche, sept fois devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Et le sacrificateur mettra de l\'huile qui est dans sa main sur le lobe de l\'oreille droite de celui qui se purifie, sur le pouce de sa main droite et sur l\'orteil de son pied droit, à l\'endroit où il a mis du sang de la victime de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ce qui restera de l\'huile qui est dans la main du sacrificateur, il le mettra sur la tête de celui qui se purifie pour faire propitiation pour lui devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Et il sacrifiera l\'une des tourterelles ou l\'un des pigeonneaux, selon ce qu\'il a pu se procurer;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'des victimes qu\'il aura pu se procurer, il offrira l\'une en sacrifice pour le péché et l\'autre en holocauste, avec l\'oblation; ainsi le sacrificateur fera propitiation devant l\'Eternel pour celui qui se purifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'C\'est là la loi pour la purification de celui qui est atteint de la lèpre et dont les moyens ne suffisent pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Et l\'Eternel parla à Moïse et à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Lorsque vous serez entrés au pays de Canaan dont je vous donne la possession, si je frappe de lèpre une maison du pays que vous posséderez,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'celui à qui la maison appartient ira le déclarer au sacrificateur en disant: J\'ai vu comme une tache de lèpre à ma maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Alors le sacrificateur fera vider la maison avant d\'y entrer pour voir la tache, afin que tout ce qui est dans la maison ne soit pas souillé; après quoi le sacrificateur entrera pour examiner la maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Et il examinera la tache, et si la tache qui est aux murs de la maison consiste en places verdâtres ou rougeâtres, dont on voit qu\'elles font creux dans le mur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'le sacrificateur sortira de la maison et [se placera] à l\'entrée de la maison, et il fera fermer la maison pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Et le sacrificateur y retournera le septième jour, et s\'il constate que la tache s\'est étendue sur les murs de la maison,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'le sacrificateur fera enlever les pierres atteintes de la tache et les fera jeter hors de la ville, dans un lieu souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Et quant à la maison, on la raclera à l\'intérieur, tout autour, et on versera la poussière qu\'on aura raclée hors de la ville, dans un lieu souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'On prendra d\'autres pierres que l\'on mettra à la place des premières, et l\'on prendra d\'autre mortier pour recrépir la maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Mais si la tache fait de nouveau éruption dans la maison après qu\'on aura enlevé les pierres et qu\'on aura raclé la maison et qu\'on l\'aura recrépie,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'le sacrificateur ira, et s\'il constate que la tache s\'est étendue dans la maison, c\'est une lèpre maligne dans la maison; la maison est souillée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'On abattra la maison, les pierres, le bois et tout le mortier de la maison, et on transportera tout cela hors de la ville, dans un lieu souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Tout le temps que la maison est déclarée close, celui qui y entrera sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Celui qui y couchera lavera ses vêtements, celui qui y mangera lavera ses vêtements.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Et si le sacrificateur vient à constater que la tache ne s\'est pas étendue dans la maison après que la maison a été recrépie, il déclarera la maison pure, car le mal est guéri.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Et il prendra pour purifier la maison deux petits oiseaux, du bois de cèdre, du cramoisi et de l\'hysope;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'et il égorgera l\'un des oiseaux dans un vase de terre, sur de l\'eau vive;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'et il prendra le bois de cèdre, l\'hysope, le cramoisi et l\'oiseau vivant, et il les trempera dans le sang de l\'oiseau égorgé et dans l\'eau vive, et il en aspergera la maison sept fois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Et il purifiera la maison avec le sang de l\'oiseau, avec l\'eau vive, avec l\'oiseau vivant, le bois de cèdre, l\'hysope et le cramoisi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Et il lâchera l\'oiseau vivant hors de la ville, dans la campagne, et il fera ainsi propitiation pour la maison, et elle sera pure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Telle est la loi concernant tout mal de lèpre et la teigne,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'ainsi que la lèpre du vêtement et de la maison,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'et les tumeurs, les dartres et les taches,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'afin de montrer quand il y a souillure et quand il y a pureté. Telle est la loi concernant la lèpre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Et l\'Eternel parla à Moïse et à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Parlez aux enfants d\'Israël et dites-leur: Tout homme dont la chair coule est souillé par là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Voici [la règle quant à] la souillure provenant de son écoulement, soit que sa chair donne cours à l\'écoulement ou le retienne, la souillure existe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Tout lit sur lequel couchera celui qui a un écoulement sera souillé, et tout meuble sur lequel il s\'assiéra sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Celui qui touchera son lit lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Celui qui s\'assiéra sur le meuble où se sera assis l\'homme qui a un écoulement, lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Celui qui touchera le corps du malade lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Et si le malade crache sur quelqu\'un qui est pur, ce dernier lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Et toute selle sur laquelle sera monté l\'homme qui a un écoulement sera souillée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Quiconque touchera une chose quelconque qui aura été sous lui sera souillé jusqu\'au soir, et quiconque la portera lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Celui que le malade aura touché sans avoir versé de l\'eau sur ses mains, lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Un vase de terre que le malade aura touché sera brisé, et un vase de bois sera lavé dans l\'eau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Quand le malade sera guéri de son écoulement, il comptera sept jours pour sa purification; puis il lavera ses vêtements, il baignera son corps dans de l\'eau vive, et il sera pur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Et au huitième jour il se procurera deux tourterelles ou deux pigeonneaux, et il se présentera devant l\'Eternel, à l\'entrée de la Tente d\'assignation, et il les donnera au sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Et le sacrificateur les offrira, l\'un en sacrifice pour le péché, l\'autre en holocauste, et le sacrificateur fera propitiation pour lui devant l\'Eternel à cause de son écoulement.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'S\'il arrive à un homme d\'avoir un épanchement séminal, il baignera tout son corps dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Tout vêtement ou tout cuir qui en auront été atteints seront lavés dans l\'eau et seront souillés jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Et une femme dont un homme aura eu compagnie conjugalement se baignera dans l\'eau ainsi que lui, et ils seront souillés jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Quand une femme aura son flux, le sang, qui s\'écoule de sa chair, elle sera dans son impureté pendant sept jours; quiconque la touchera sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Tout meuble sur lequel elle se couchera pendant son impureté sera souillé; et tout meuble sur lequel elle s\'assiéra sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Quiconque touchera son lit lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Et quiconque touchera un meuble quelconque sur lequel elle se sera assise lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Et si l\'homme se trouvait sur le lit ou sur le meuble où elle était couchée et qu\'il ait touché son sang, il sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Si un homme couche avec elle et que son impureté le touche, il sera souillé sept jours, et tout lit sur lequel il couchera sera souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Quand une femme aura un écoulement de sang pendant plusieurs jours en dehors du temps de son impureté, ou quand elle aura des pertes au-delà du temps de son impureté, elle sera souillée tout le temps de cet écoulement, comme au temps de son impureté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Tout lit sur lequel elle couchera pendant tout le temps de son flux sera pour elle comme le lit de son impureté; et tout meuble sur lequel elle s\'assiéra sera souillé comme lors de son impureté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Et quiconque les touchera sera souillé; il lavera ses vêtements, se baignera dans l\'eau et sera souillé jusqu\'au soir.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Lorsqu\'elle sera nettoyée de son flux, elle comptera sept jours et après elle sera pure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Et au huitième jour elle prendra deux tourterelles ou deux pigeonneaux et les apportera au sacrificateur, à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Le sacrificateur offrira l\'un en sacrifice pour le péché et l\'autre en holocauste, et le sacrificateur fera propitiation devant l\'Eternel à cause du flux qui la souillait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Ainsi vous séparerez les enfants d\'Israël de leur souillure, et ils ne mourront pas à cause de leur souillure en souillant ma demeure qui est au milieu d\'eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Telle est la loi concernant celui qui a un écoulement oui qui est souillé par un épanchement séminal,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'et concernant celle qui est indisposée de son impureté périodique et toute personne atteinte d\'un écoulement, soit homme, soit femme, et pour l\'homme qui couche avec une femme souillée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'L\'Eternel parla à Moïse après la mort des deux fils d\'Aaron qui moururent lorsqu\'ils s\'étaient approchés de la face de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'L\'Eternel dit à Moïse: Parle à Aaron ton frère, et qu\'il n\'entre pas en tout temps dans le sanctuaire au-dedans du voile, devant le propitiatoire qui est sur l\'arche, de peur qu\'il ne meure; car j\'apparais dans la nuée sur le propitiatoire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Voici comment Aaron entrera dans le sanctuaire: il prendra un jeune taureau pour sacrifice pour le péché et un bélier pour holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Il se revêtira d\'une tunique de lin sacrée, il portera sur sa chair un caleçon de lin, il se ceindra d\'une ceinture de lin, il se couvrira la tête d\'une tiare de lin. Ce sont des vêtements sacrés; il baignera son corps dans l\'eau et s\'en revêtira.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Et de la part de l\'assemblée des fils d\'Israël, il doit prendre deux boucs pour sacrifice pour le péché, et un bélier pour holocauste.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Puis Aaron offrira le taureau du sacrifice pour le péché qui est pour lui, et il fera propitiation pour lui et pour sa maison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Et il prendra les deux boucs et les placera devant l\'Eternel, à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Puis Aaron jettera le sort sur les deux boucs, un sort pour l\'Eternel et un sort pour Azazel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Et Aaron fera approcher le bouc sur lequel sera tombé le sort pour l\'Eternel, et il en fera la victime pour le péché;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'et le bouc sur lequel sera tombé le sort pour Azazel, on le placera vivant devant l\'Eternel, afin de faire propitiation sur lui pour l\'envoyer à Azazel dans le désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Et Aaron offrira le taureau du sacrifice pour le péché qui est pour lui, et il fera propitiation pour lui et pour sa maison; et il égorgera le taureau qui est pour lui en sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Et il prendra l\'encensoir plein de charbons ardents de dessus l\'autel, de devant l\'Eternel, et deux poignées de poudre d\'aromates; et il portera ces choses au-delà du voile;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'et il mettra l\'encens sur le feu devant l\'Eternel, et le nuage d\'encens couvrira le propitiatoire qui est sur le témoignage, et il ne mourra pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Et il prendra du sang du taureau et en fera aspersion avec un doigt, sur la face du propitiatoire, du côté de devant, et il fera aspersion du sang sept fois avec son doigt devant le propitiatoire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Et il égorgera le bouc du sacrifice pour le péché qui est pour le peuple, et il en portera le sang au-delà du voile; il fera de ce sang comme il a fait du sang du taureau: il en fera l\'aspersion sur le propitiatoire et devant le propitiatoire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Et ainsi il fera propitiation pour le sanctuaire, [le purifiant] des souillures des fils d\'Israël et de leurs péchés, en quelques fautes qu\'ils consistent. Il fera de même pour la Tente d\'assignation qui demeure avec eux au milieu de leurs souillures;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'et personne ne sera dans la Tente d\'assignation quand il entrera pour faire propitiation dans le sanctuaire, jusqu\'à ce qu\'il en sorte; et il fera propitiation à cause de lui, de sa maison et de toute l\'assemblée d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Et il sortira vers l\'autel qui est devant l\'Eternel et fera propitiation pour l\'autel; et il prendra du sang du taureau et du sang du bouc, et il en mettra sur les cornes de l\'autel, tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Et il fera aspersion du sang avec son doigt sept fois sur l\'autel; il le purifiera et le sanctifiera des souillures des fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Et quand il aura achevé de faire propitiation pour le sanctuaire, pour la Tente d\'assignation et pour l\'autel, il fera approcher le bouc vivant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Et Aaron appuiera ses deux mains sur la tête du bouc vivant et confessera sur lui toutes les iniquités des fils d\'Israël et tous leurs péchés, en quelques fautes qu\'ils consistent; il les mettra sur la tête du bouc, puis il l\'enverra au désert par un homme tout prêt.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Et le bouc emportera sur lui toutes leurs iniquités dans une contrée écartée; et l\'homme lâchera le bouc dans le désert.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Et Aaron entrera dans la Tente d\'assignation et il quittera les vêtements de lin dont il s\'était revêtu pour entrer dans le sanctuaire, et il les déposera là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Et il baignera son corps avec de l\'eau dans un lieu saint et reprendra son costume; et il sortira et il offrira son holocauste et l\'holocauste du peuple, et fera propitiation pour lui et pour le peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Et il fera fumer sur l\'autel la graisse du sacrifice pour le péché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Et celui qui aura lâché le bouc pour Azazel lavera ses vêtements et baignera son corps dans l\'eau, et après il rentrera au camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'On emportera hors du camp le taureau du sacrifice pour le péché et le bouc du sacrifice pour le péché dont le sang aura été porté dans le sanctuaire pour faire propitiation, et l\'on brûlera leur peau, leur chair et leurs excréments.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Et celui qui les aura brûlés lavera ses vêtements, baignera son corps dans l\'eau, et après cela il rentrera au camp.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Et ceci sera pour vous une ordonnance perpétuelle: au septième mois, le dixième jour du mois, vous mortifierez vos âmes et vous ne ferez aucune œuvre, ni celui qui est du peuple, ni l\'étranger qui habite au milieu de vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Car en ce jour on fera propitiation pour vous afin de vous purifier; vous serez purs de tous vos péchés devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ce sera pour vous un jour de complet repos, et vous mortifierez vos âmes; c\'est une ordonnance perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Et la propitiation sera faite par le sacrificateur qu\'on aura oint et installé dans le sacerdoce en la place de son père; il se revêtira des vêtements de lin, des vêtements sacrés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Il fera la propitiation du sanctuaire sacré; il fera la propitiation de la Tente d\'assignation et de l\'autel; il fera la propitiation pour les sacrificateurs et pour tout le peuple de l\'assemblée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Ceci sera pour vous une ordonnance perpétuelle: qu\'une fois l\'an il soit fait propitiation pour les fils d\'Israël, pour les décharger de tous leurs péchés. Et l\'on fit comme l\'Eternel l\'avait commandé à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Parle à Aaron, à ses fils et à tous les fils d\'Israël et dis-leur: Voici ce que l\'Eternel a commandé:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Tout homme de la maison d\'Israël qui égorge un bœuf, un agneau ou une chèvre dans le camp ou hors du camp,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'et qui ne l\'amène pas à l\'entrée de la Tente d\'assignation pour le présenter en offrande à l\'Eternel, devant le sanctuaire de l\'Eternel, ce sang lui sera imputé: il a répandu du sang; cet homme-là sera retranché du milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'C\'est afin que les fils d\'Israël amènent leurs sacrifices qu\'ils immolent dans la campagne, qu\'ils les amènent au sacrificateur devant l\'Eternel, à l\'entrée de la Tente d\'assignation, et qu\'ils les offrent en sacrifice d\'actions de grâces à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Le sacrificateur répandra le sang sur l\'autel de l\'Eternel, à l\'entrée de la Tente d\'assignation, et il fera fumer la graisse en agréable odeur pour l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Ils n\'offriront plus leurs sacrifices aux satyres avec lesquels ils se prostituent; ceci sera pour eux une ordonnance perpétuelle de génération en génération.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Tu leur diras: Tout homme de la maison d\'Israël ou des étrangers séjournant au milieu d\'eux, qui offrira un holocauste ou un sacrifice');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'et ne l\'amènera pas à l\'entrée de la Tente d\'assignation pour le sacrifier à l\'Eternel, cet homme-là sera retranché du milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Tout homme de la maison d\'Israël ou des étrangers séjournant au milieu d\'eux qui mangera de quelque sang que ce soit, je tournerai ma face contre la personne qui mange le sang, et je la retrancherai du milieu de son peuple;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'car l\'âme de la chair est dans le sang. Et moi je vous l\'ai donné en vue de l\'autel pour faire propitiation pour vos âmes; car le sang, c\'est lui qui fait propitiation par l\'âme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'C\'est pourquoi j\'ai dit aux fils d\'Israël: Personne d\'entre vous ne mangera du sang, et l\'étranger qui séjourne au milieu de vous ne mangera pas de sang.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Tout homme des fils d\'Israël ou des étrangers séjournant au milieu d\'eux qui prend à la chasse un animal ou un oiseau qui se mange, il en versera le sang et le couvrira de terre;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'car l\'âme de toute chair, c\'est son sang, par l\'âme qui est en lui; et j\'ai dit aux fils d\'Israël: Vous ne mangerez le sang d\'aucune chair, car l\'âme de toute chair c\'est son sang; quiconque en mangera sera retranché.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Et toute personne née au pays ou étrangère, qui mangera d\'une bête morte ou déchirée lavera ses vêtements, se baignera dans l\'eau, et sera souillée jusqu\'au soir; puis elle sera pure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Et si elle ne lave pas ses vêtements et ne baigne pas son corps, elle portera son iniquité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Parle aux fils d\'Israël et dis-leur: Je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Vous ne ferez pas comme on fait au pays d\'Egypte où vous avez habité, et vous ne ferez pas comme on fait au pays de Canaan où je vous conduis; vous ne marcherez pas selon leurs statuts;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'vous écouterez mes ordonnances et vous observerez mes statuts pour y marcher. Je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Vous observerez mes statuts et mes ordonnances l\'homme qui les pratiquera vivra par elles: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nul de vous ne s\'approchera de sa proche parente pour découvrir sa nudité: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Tu ne découvriras point la nudité de ton père et la nudité de ta mère; c\'est ta mère, tu ne découvriras pas sa nudité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Tu ne découvriras point la nudité de la femme de ton père; c\'est la nudité de ton père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Tu ne découvriras point la nudité de ta sœur, fille de ton père ou fille de ta mère; qu\'elle soit née dans la maison ou qu\'elle soit née au dehors, tu ne découvriras point leur nudité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Tu ne découvriras point la nudité de la fille de ton fils ou de la fille de ta fille, car c\'est ta nudité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Tu ne découvriras pas la nudité de la fille de la femme de ton père, née de ton père; c\'est ta sœur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Tu ne découvriras pas la nudité de la sœur de ton père; elle est du sang de ton père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Tu ne découvriras pas la nudité de la sœur de ta mère; elle est du sang de ta mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Tu ne découvriras pas la nudité du frère de ton père, tu ne t\'approcheras point de sa femme; c\'est ta tante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Tu ne découvriras pas la nudité de ta belle-fille; c\'est la femme de ton fils, tu ne découvriras point sa nudité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Tu ne découvriras pas la nudité de la femme de ton frère; c\'est la nudité de ton frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Tu ne découvriras pas la nudité d\'une femme et de sa fille; tu ne prendras pas la fille de son fils, ni la fille de sa fille pour découvrir leur nudité; elles sont proches parentes, c\'est un crime.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Tu ne prendras pas la sœur de ta femme de manière, à créer une rivalité, en découvrant la nudité de l\'une avec celle de l\'autre de son vivant.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Tu ne t\'approcheras point d\'une femme pendant son impureté périodique pour découvrir sa nudité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Tu n\'auras point commerce avec la femme de ton prochain pour te souiller avec elle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Tu ne donneras point de tes enfants pour les sacrifier à Moloch et tu ne profaneras pas le nom de ton Dieu. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Tu ne coucheras point avec un homme comme on couche avec une femme; c\'est une abomination.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Tu ne coucheras point avec aucune bête pour te souiller avec elle. La femme ne s\'approchera point d\'une bête pour se prostituer à elle; c\'est une chose monstrueuse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne vous souillez par aucune de ces choses; car c\'est par toutes ces choses que se sont souillées les nations que je chasse devant vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Le pays en a été souillé, j\'ai puni son iniquité et la terre a vomi ses habitants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Mais vous, vous garderez mes statuts et mes ordonnances, et vous ne commettrez aucune de ces abominations, ni l\'indigène, ni l\'étranger qui séjourne au milieu de vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Car toutes ces abominations, les hommes du pays, qui y ont été avant vous, les ont commises, et la terre en a été souillée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Et la terre ne vous vomira pas pour l\'avoir souillée, comme elle a vomi la nation qui y a été avant vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Car tous ceux qui auront commis quelqu\'une de ces abominations, ceux qui auront fait cela seront retranchés du milieu de leur peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Vous garderez mes observances afin de ne pratiquer aucune des coutumes abominables qui ont été pratiquées avant vous; vous ne vous souillerez point par elles. Je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Parle à toute l\'assemblée des fils d\'Israël et dis-leur: Soyez saints, car je suis saint, moi l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Que chacun craigne sa mère et son père, observant mes sabbats. Je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne vous tournez point vers les faux dieux et ne vous faites point de dieux de fonte. Je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Et lorsque vous offrirez un sacrifice d\'actions de grâces à l\'Eternel, vous l\'offrirez de manière à être agréés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'On le mangera au jour où vous le sacrifierez, et le lendemain; ce qui restera jusqu\'au troisième jour sera brûlé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Si on en mange le troisième jour, c\'est une abomination, il ne sera point agréé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Celui qui en mangera portera son iniquité, car il a profané ce qui est consacré à l\'Eternel. Cette personne-là sera retranchée du milieu des siens.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Quand vous ferez les moissons de votre pays, tu n\'iras pas jusqu\'au bout de ton champ en moissonnant et tu ne glaneras pas ce qu\'il y a à glaner de ta moisson.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Tu ne grapilleras pas dans ta vigne et tu ne ramasseras pas dans ton verger les fruits tombés. Tu laisseras cela au pauvre et à l\'étranger. Je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Vous ne déroberez point, vous ne nierez point [un dépôt] et vous ne mentirez point à votre prochain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Vous ne jurerez point par mon nom en mentant, tu profanerais le nom de ton Dieu. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Tu ne fouleras point ton prochain et tu ne le dépouilleras pas. Tu ne retiendras point jusqu\'au lendemain le salaire du journalier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Tu ne maudiras point un sourd et tu ne mettras pas devant un aveugle quelque chose qui puisse le faire tomber, tu auras crainte de ton Dieu: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Vous ne commettrez point d\'injustice en jugeant; tu n\'auras pas de faveur pour le petit, ni de complaisance pour le grand tu jugeras ton prochain selon la justice.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Tu ne colporteras pas de diffamations au milieu de ton peuple; ne te présente pas comme témoin contre le sang de ton prochain: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Tu ne haïras pas ton frère dans ton cœur; tu ne manqueras pas de reprendre ton prochain, afin de ne pas te charger d\'un péché à cause de lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Tu ne te vengeras pas et tu ne garderas pas de rancune contre les enfants de ton peuple et tu aimeras ton prochain comme toi-même: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Vous observerez mes ordonnances. Tu n\'accoupleras pas des bestiaux d\'espèces différentes. Tu n\'ensemenceras pas ton champ de deux espèces de semences. Tu ne porteras pas un vêtement tissu de deux espèces de fils.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Si un homme a commerce avec une femme et que ce soit une esclave unie à un autre homme et qui n\'a pas été rachetée ou affranchie, ils seront châtiés, mais non punis de mort, car elle n\'était pas affranchie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'L\'homme amènera à l\'Eternel à l\'entrée de la Tente d\'assignation un bélier en sacrifice de réparation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Et avec le bélier du sacrifice de réparation le sacrificateur fera propitiation pour lui devant l\'Eternel, pour le péché qu\'il a commis, et le péché qu\'il a commis lui sera pardonné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Et quand vous entrerez dans le pays et que vous planterez toutes sortes d\'arbres fruitiers, vous considérerez pendant trois ans leurs fruits comme leurs prépuces; ils seront incirconcis pour vous, on n\'en mangera point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Et la quatrième année tous leurs fruits seront consacrés avec reconnaissance à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Et la cinquième année vous en mangerez le fruit, afin que l\'arbre vous continue son rapport: je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Vous ne mangerez rien avec le sang. Vous ne pratiquerez aucune sorte de divination ou de magie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Vous ne tondrez pas en rond votre tête et tu n\'enlèveras pas les côtés de ta barbe.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Vous ne vous ferez pas d\'incisions dans la chair pour un mort et vous n\'imprimerez point de figures sur vous: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne déshonore pas ta fille en la prostituant, et que le pays ne se livre pas à la prostitution et ne se remplisse pas de crimes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Vous observerez mes sabbats et vous révérerez mon sanctuaire je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne vous adressez pas aux évocateurs et aux devins; ne les consultez pas, vous souillant par eux: je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Lève-toi devant les cheveux blancs, honore le vieillard et aie crainte de ton Dieu: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Quand un étranger séjournera parmi vous, dans votre pays, vous ne le molesterez pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'L\'étranger qui séjourne parmi vous sera pour vous comme un des vôtres; tu l\'aimeras comme toi-même; car vous avez été étrangers dans le pays d\'Egypte: je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Vous ne commettrez point d\'injustice en affaires, ni dans les mesures de longueur, ni dans les poids, ni dans les mesures de capacité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Vous aurez une balance juste, des poids justes, un épha juste et un hin juste: je suis l\'Eternel, votre Dieu, qui vous ai fait sortir d\'Egypte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Vous observerez donc tous mes statuts et toutes mes ordonnances et vous les pratiquerez: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Parle aux fils d\'Israël: Quiconque d\'entre les fils d\'Israël ou d\'entre les étrangers qui séjournent en Israël donnera de ses enfants à Moloch, sera puni de mort: le peuple du pays le lapidera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Et moi je tournerai ma face contre cet homme et je le retrancherai du milieu de son peuple, parce qu\'il aura livré un de ses enfants à Moloch pour souiller mon sanctuaire et profaner mon saint nom.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Et si le peuple du pays ferme les yeux à l\'égard de cet homme lorsqu\'il livrera de ses enfants à Moloch, et ne le fait pas mourir,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'moi je tournerai ma face contre cet homme et contre sa famille et je le retrancherai du milieu de son peuple, avec tous ceux qui se prostituent comme lui en se prostituant à Moloch.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Et la personne qui s\'adressera aux esprits et aux devins, se prostituant après eux, je tournerai ma face contre cette personne et je la retrancherai du milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Vous vous sanctifierez et vous serez saints; car je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Vous observerez mes statuts et vous les pratiquerez; je suis l\'Eternel qui vous sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Quiconque aura maudit son père ou sa mère sera mis à mort: il a maudit son père ou sa mère; son sang est sur lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Si quelqu\'un commet adultère avec une femme mariée, adultère avec la femme de son prochain, l\'homme et la femme adultères seront mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Si un homme couche avec la femme de son père, il découvre la nudité de son père; ils seront tous deux mis à mort; leur sang est sur eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Si un homme couche avec sa belle-fille, ils seront tous deux mis à mort; ils ont commis une chose monstrueuse; leur sang est sur eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Si un homme couche avec un homme comme on couche avec une femme, ils ont fait tous deux une chose abominable; ils seront mis à mort; leur sang est sur eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Si un homme prend une femme et sa mère, c\'est un crime; on les brûlera au feu, lui et elles, afin que ce crime n\'existe pas parmi vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Si un homme a commerce avec une bête, il sera puni de mort et vous tuerez la bête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Si une femme s\'approche de quelque bête pour se prostituer à elle, tu tueras la femme et la bête: elles seront mises à mort; leur sang est sur elles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Si un homme prend sa sœur, fille de son père ou fille de sa mère, et qu\'il voie sa nudité et qu\'elle voie la sienne, c\'est un inceste infâme; ils seront retranchés en présence des enfants de leur peuple; il a découvert la nudité de sa sœur, il portera son iniquité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Si un homme couche avec une femme pendant son indisposition et découvre sa nudité, il a découvert son flux et elle a découvert le flux de son sang; ils seront tous deux retranchés du milieu de leur peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Tu ne découvriras point la nudité de la sœur de ta mère ni de la sœur de ton père, car c\'est découvrir sa proche parente; ils porteront leur iniquité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Si un homme couche avec sa tante, il découvre la nudité de son oncle, ils porteront leur péché, ils mourront sans enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Si un homme prend la femme de son frère, c\'est une impureté; il a découvert la nudité de son frère, ils seront sans enfants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Vous observerez tous mes statuts et toutes mes ordonnances et vous les pratiquerez, et le pays où je vous fais entrer pour y habiter ne vous vomira pas.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Vous n\'adopterez pas les mœurs de la nation que je chasse de devant vous, car ils ont fait toutes ces choses et je les ai pris en dégoût;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'et je vous ai dit: C\'est vous qui posséderez leur pays; je vous le donnerai pour le posséder; c\'est un pays où coulent le lait et le miel. Je suis l\'Eternel, votre Dieu, qui vous ai distingués des [autres] peuples.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Vous distinguerez les bêtes pures des impures et les oiseaux purs des impurs; et ne rendez pas vos personnes abominables par des bêtes, par des oiseaux et par tout ce qui rampe sur la terre, ce que j\'ai distingué pour vous, les déclarant impurs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Vous me serez saints; car je suis saint, moi, l\'Eternel, et je vous ai distingués des autres peuples pour que vous soyez à moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Tout homme ou femme qui évoque ou qui devine doit être mis à mort; on les lapidera; leur sang est sur eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'L\'Eternel dit à Moise: Parle aux sacrificateurs, fils d\'Aaron, et dis-leur: Nul ne doit se rendre impur au milieu de son peuple pour un mort,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'si ce n\'est pour son parent du même sang que lui, pour sa mère, pour son père, pour son fils, pour sa fille, pour son frère,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'et pour sa sœur vierge qui le touche de près et qui n\'appartient pas à un homme; pour elle, il se rendra impur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Comme mari, il ne se souillera pas parmi son peuple, de manière à se profaner.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Les sacrificateurs ne se raseront point la tête, ils n\'enlèveront pas les côtés de leur barbe, ils ne feront pas d\'incision dans leur chair.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Ils seront saints à leur Dieu, car ils offrent à l\'Eternel les sacrifices faits par le feu, le pain de leur Dieu. Ils seront saints.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ils ne prendront point une femme prostituée ou déshonorée et ils ne prendront point une femme répudiée par son mari, car le sacrificateur est saint à son Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Tu le tiendras pour saint, car il offre le pain de ton Dieu, et il te sera saint, car je suis saint, moi l\'Eternel, qui vous sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Si une fille de sacrificateur se déshonore en se prostituant, elle déshonore son père; elle sera brûlée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Le grand sacrificateur qui est au-dessus de ses frères, sur la tête duquel a été répandue l\'huile de l\'onction et qui a été installé en revêtant les vêtements sacrés, ne découvrira pas sa tête et ne déchirera pas ses vêtements.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Il n\'approchera d\'aucun corps mort; il ne se souillera ni pour son père, ni pour sa mère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Il ne sortira pas du sanctuaire et ne profanera pas le sanctuaire de son Dieu; car l\'huile de l\'onction de son Dieu est un diadème sur lui: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Il prendra pour femme une vierge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Il ne prendra ni une veuve, ni une femme répudiée, ni une femme déshonorée ou prostituée; mais il prendra pour femme une vierge du milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Il ne déshonorera point sa race au milieu de son peuple; car je suis l\'Eternel qui le sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Parle à Aaron et dis-lui: Nul homme de ta race, de génération en génération, qui aura une difformité, n\'approchera pour offrir le pain de son Dieu;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'car nul homme qui a une difformité n\'approchera. Nul homme aveugle ou boiteux, ou qui aura un défaut ou une excroissance,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ou un homme qui aura une fracture au pied ou à la main,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ou qui sera bossu ou nain, ou qui aura une tache à l\'œil, ou qui aura la gale, ou une dartre, ou les testicules écrasés,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'nul homme de la postérité d\'Aaron, le sacrificateur, qui aura une difformité, ne s\'approchera pour offrir les sacrifices faits par le feu à l\'Eternel; il a une difformité, il ne s\'approchera point pour offrir le pain de son Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Il mangera le pain de son Dieu, et des choses très saintes et des choses saintes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Mais il n\'ira point vers le voile et ne s\'approchera point de l\'autel, car il a une difformité. Il ne profanera point mon sanctuaire, car je suis l\'Eternel qui le sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Moïse parla ainsi à Aaron et à ses fils et à tous les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Parle à Aaron et à ses fils, afin qu\'ils soient sur leurs gardes à l\'égard des choses saintes des fils d\'Israël et qu\'ils ne profanent pas le nom de ma sainteté dans les choses qu\'ils me consacrent: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dis-leur: Tout homme de votre race qui, dans vos générations futures, s\'approchera des choses saintes que les fils d\'Israël ont consacrées à l\'Eternel et qui sera en état d\'impureté, cet homme sera retranché de devant moi: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Tout homme de la race d\'Aaron qui aura la lèpre ou un écoulement ne mangera pas des choses saintes jusqu\'à ce qu\'il soit pur. De même celui qui aura touché une personne souillée par le contact d\'un cadavre et celui qui aura eu un épanchement séminal,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ou celui qui aura touché quelque animal rampant qui l\'ait rendu souillé,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'ou touché quelqu\'un qui l\'ait souillé jusqu\'au soir: il ne mangera pas des choses saintes, mais il baignera son corps dans l\'eau,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'puis le soleil couché, il sera pur, et alors il mangera des choses saintes, car c\'est sa nourriture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Il ne mangera pas d\'une bête morte d\'elle-même ou déchirée, se souillant par là: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Ils observeront ce que je donne à observer, et ils ne se chargeront pas d\'un péché à ce sujet et ne mourront pas pour avoir commis en cela une profanation: je suis l\'Eternel qui les sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Aucun étranger ne mangera d\'une chose sainte; celui qui demeure chez un sacrificateur et le mercenaire ne mangeront pas d\'une chose sainte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mais un homme acquis par un sacrificateur à prix d\'argent en mangera, de même que celui qui sera né chez lui; ceux-là mangeront de sa nourriture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Une fille de sacrificateur qui sera mariée à quelqu\'un d\'étranger ne mangera pas de ce qui a été prélevé sur les choses saintes;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'mais une fille de sacrificateur veuve ou répudiée et sans enfants, et qui sera rentrée dans la maison de son père comme elle y était dans sa jeunesse, partagera la nourriture de son père; mais nul étranger n\'en mangera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Quelqu\'un qui mangera par erreur d\'une chose sainte en restituera la valeur au sacrificateur en y ajoutant un cinquième.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Ils ne profaneront point les choses saintes des fils d\'Israël, les choses que ceux-ci prélèvent pour l\'Eternel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'et ne leur feront pas porter le poids de la faute dont ils se rendraient coupables en mangeant leurs choses saintes; car je suis l\'Eternel qui les sanctifie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Parle à Aaron, à ses fils et à tous les fils d\'Israël, et dis-leur: Qui que ce soit, de la maison d\'Israël ou des étrangers d\'Israël, qui présente une offrande pour quelque vœu ou pour quelque don volontaire que ce soit, s\'il l\'offre à l\'Eternel en holocauste,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'pour que vous soyez agréés, que ce soit une victime irréprochable, mâle, tant en fait de gros bétail qu\'en fait de moutons ou de chèvres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Vous n\'offrirez rien qui ait un défaut, car le sacrifice ne serait pas agréé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Et quand un homme offrira à l\'Eternel un sacrifice d\'actions de grâces de gros ou de menu bétail pour s\'acquitter d\'un vœu ou en offrande volontaire, pour être agréée, la victime devra être sans défaut; il ne devra y avoir en elle aucune tare.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Une victime aveugle, estropiée, ou mutilée, ou affectée d\'ulcère, ou de la gale, ou d\'une dartre, vous ne l\'offrirez pas à l\'Eternel; vous n\'en ferez pas sur l\'autel un sacrifice par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Un bœuf ou un agneau ayant un membre trop gros ou trop court, tu pourras en faire une offrande volontaire, mais pour un vœu il ne sera pas agréé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Vous n\'offrirez point à l\'Eternel un animal qui ait les organes froissés, écrasés, arrachés ou coupés; vous ne ferez pas cela dans votre pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Même venant d\'un étranger, vous n\'offrirez aucun de ces animaux comme aliment de votre Dieu; puisqu\'elles sont mutilées, qu\'il y a un défaut en elles, elles ne seront point agréées de votre part.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Quand un veau, un agneau ou un chevreau naîtra, il sera sept jours avec sa mère, et à partir du huitième jour et les jours suivants il sera agréé comme offrande faite par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Grosse ou menue bête, vous n\'égorgerez pas l\'animal et son petit le même jour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Quand vous offrirez un sacrifice d\'actions de grâces à l\'Eternel, vous sacrifierez de manière à être agréés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Il sera mangé le jour même; vous n\'en laisserez rien jusqu\'au lendemain: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Vous garderez mes commandements et vous les accomplirez: je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Vous ne profanerez pas mon saint nom et je serai sanctifié au milieu des fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Je suis l\'Eternel qui vous sanctifie, celui qui vous a fait sortir du pays d\'Egypte pour être votre Dieu. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Parle aux fils d\'Israël et dis-leur: [Voici] les solennités de l\'Eternel que vous publierez comme convocations saintes. Ce sont ici mes solennités.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Durant six jours on vaquera à ses affaires; mais le septième jour il y aura repos, repos complet avec sainte convocation; vous ne ferez aucune œuvre; c\'est un repos consacré à l\'Eternel dans tous les lieux que vous habiterez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Voici les fêtes de l\'Eternel, les convocations saintes que vous publierez en leur saison.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Au premier mois, le quatorzième du mois, dans la soirée, c\'est la Pâque de l\'Eternel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'et le quinzième jour du mois, c\'est la fête des pains sans levain en l\'honneur de l\'Eternel; pendant sept jours vous mangerez des pains sans levain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Le premier jour vous aurez une sainte convocation; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Vous offrirez à l\'Eternel pendant sept jours des sacrifices faits par le feu. Au septième jour il y aura une sainte convocation; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Parle aux fils d\'Israël et dis-leur: Quand vous serez entrés au pays que je vous donne et que vous en ferez la moisson, vous apporterez au sacrificateur la première gerbe de votre moisson.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Il balancera cette gerbe devant l\'Eternel pour que vous lui soyez agréables; le sacrificateur la balancera le lendemain du sabbat.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Vous offrirez, le jour où vous balancerez la gerbe, un agneau sans défaut, d\'un an, en holocauste à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'L\'oblation qui l\'accompagne sera de deux dixièmes de fleur de farine pétrie à l\'huile, offerte en sacrifice par le feu, d\'agréable odeur, à l\'Eternel; la libation sera de vin, le quart d\'un hin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Vous ne mangerez ni pain, ni grains grillés ou broyés jusqu\'à ce jour même, jusqu\'à ce que vous ayez apporté l\'offrande de votre Dieu; c\'est une ordonnance perpétuelle pour vos descendants, dans tous les lieux que vous habiterez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Depuis le lendemain du sabbat, depuis le jour où vous apporterez la gerbe pour être balancée, vous compterez sept semaines complètes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Vous compterez cinquante jours jusqu\'au lendemain du septième sabbat, et vous offrirez à l\'Eternel une oblation nouvelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Vous apporterez, des lieux où vous habiterez, deux pains pour offrande balancée; ils seront de deux dixièmes de fleur de farine, cuits avec du levain; ce sont les prémices pour l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Avec le pain, vous offrirez aussi sept agneaux sans défaut, d\'un an, et un jeune taureau et deux béliers, qui seront un holocauste à l\'Eternel avec leur oblation et leurs libations; ce sera un sacrifice fait par le feu, d\'agréable odeur, à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Vous offrirez aussi un bouc en sacrifice pour le péché et deux agneaux d\'un an en sacrifice d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Et le sacrificateur les balancera avec le pain des prémices en offrande balancée devant l\'Eternel; avec les deux agneaux ils seront consacrés à l\'Eternel et appartiendront au sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'En ce même jour-là vous publierez la fête et vous aurez une sainte convocation. Vous ne ferez aucune œuvre servile; c\'est une ordonnance perpétuelle pour vos descendants dans tous les lieux où vous demeurerez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Quand vous ferez la moisson dans votre pays, tu n\'achèveras pas de moissonner le bout de ton champ, et tu ne glaneras pas ce qui pourra, rester de ta moisson; mais tu laisseras cela pour le pauvre et pour l\'étranger: je suis l\'Eternel ton Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Parle ainsi aux fils d\'Israël: Au septième mois, le premier du mois, vous aurez un repos solennel, un rappel à son de fanfare, une sainte convocation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Vous ne ferez aucune œuvre servile et vous offrirez à l\'Eternel des sacrifices faits par le feu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Or le dix de ce septième mois est le jour des Expiations; vous aurez une sainte convocation, vous vous mortifierez et vous offrirez à l\'Eternel des sacrifices faits par le feu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Vous ne ferez aucune œuvre ce jour-là, car c\'est un jour d\'expiation destiné à faire propitiation pour vous devant l\'Eternel votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Car toute personne qui ne se mortifiera pas ce jour-là sera retranchée du milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Et toute personne qui fera quelque œuvre servile en ce jour-là, je ferai périr cette personne au milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Vous ne ferez aucun travail. C\'est une ordonnance perpétuelle pour vos descendants, dans tous les lieux où vous demeurerez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ce sera pour vous un repos, un repos absolu, et vous vous mortifierez. Le neuf du mois, au soir, d\'un soir jusqu\'à l\'autre, vous observerez votre repos.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Parle aux fils d\'Israël et dis: Au quinzième jour de ce septième mois, c\'est la fête des Tabernacles pendant sept jours en l\'honneur de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Le premier jour il y aura une sainte convocation; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Pendant sept jours vous offrirez à l\'Eternel des sacrifices faits par le feu. Le huitième jour vous aurez une sainte convocation et vous offrirez à l\'Eternel des sacrifices faits par le feu: c\'est une fête de clôture; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Ce sont là les solennités de l\'Eternel que vous publierez comme convocation sainte en offrant à l\'Eternel des sacrifices faits par le feu, holocaustes et oblations, victimes et libations, chaque chose à son jour;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'indépendamment des sabbats de l\'Eternel et de vos dons et de tous vos vœux et de toutes vos offrandes volontaires que vous présenterez à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Or le quinzième jour, du septième mois, quand vous récolterez les produits de la terre, vous célébrerez la fête de l\'Eternel pendant sept jours. Au premier jour il y aura repos complet, et au huitième repos complet.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Et vous prendrez le premier jour de beaux fruits d\'arbres, des palmes et des branches d\'arbres touffus et de saules de rivières; et vous vous réjouirez devant l\'Eternel votre Dieu pendant sept jours.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Vous la célébrerez, cette fête à l\'Eternel, sept jours chaque année. C\'est une ordonnance perpétuelle pour vos descendants; vous la célébrerez le septième mois.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Vous demeurerez pendant sept jours dans des cabanes; tout ce qui est né en Israël demeurera dans des cabanes,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'pour que vos descendants sachent que j\'ai fait habiter les fils d\'Israël sous des tentes lorsque je les ai fait sortir du pays d\'Egypte: je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Et Moïse fit connaître aux fils d\'Israël les fêtes de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Ordonne aux fils d\'Israël de t\'apporter pour le candélabre de l\'huile pure d\'olives pilées, pour entretenir constamment les lampes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Aaron la préparera en dehors du voile du témoignage, dans la Tente d\'assignation, pour brûler du soir au matin devant l\'Eternel constamment; c\'est une ordonnance perpétuelle pour vos descendants.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Il arrangera les lampes sur le candélabre d\'or [pour qu\'elles brûlent] constamment devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Et tu prendras de la fleur de farine et tu en cuiras douze gâteaux; chaque gâteau sera de deux dixièmes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Et tu les placeras en deux piles, six par pile, sur la table d\'or devant l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Et tu mettras sur chaque pile de l\'encens pur qui servira pour le pain de mémorial offert par le feu à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Chaque jour de sabbat on disposera les pains devant l\'Eternel pour y être constamment de la part des fils d\'Israël: c\'est une alliance perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Ils appartiendront à Aaron et à ses fils qui les mangeront en lieu saint, car c\'est pour eux une chose très sainte prise sur les offrandes faites par le feu à l\'Eternel; c\'est une ordonnance perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Et le fils d\'une femme israélite, mais dont le père était égyptien, vint au milieu des fils d\'Israël, et il y eut une querelle dans le camp entre le fils de la femme israélite et un homme israélite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Et le fils de la femme israélite prononça le nom [sacré] et le blasphéma; et ils l\'amenèrent à Moïse. Et le nom de sa mère était Sélomith, fille de Dibri, de la tribu de Dan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Et ils le mirent sous garde pour que Moïse leur expliquât de la part de l\'Eternel ce qu\'il fallait faire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Et l\'Eternel parla à Moïse, disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Fais conduire en dehors du camp celui qui a blasphémé, et que tous ceux qui l\'ont entendu posent leurs mains sur sa tête et que toute l\'assemblée le lapide.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Et tu parleras; aux fils d\'Israël en disant: Qui que ce soit qui blasphème son Dieu, il portera son péché;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'et s\'il prononce le nom de l\'Eternel, il sera puni de mort; toute l\'assemblée le lapidera, étranger ou indigène; il mourra pour avoir blasphémé le nom [de l\'Eternel].');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Et un homme qui frappe mortellement quelque personne que ce soit, sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Et celui qui frappe mortellement une pièce de bétail, la remplacera: vie pour vie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Et un homme qui fera une blessure à son prochain, on lui fera comme il a fait.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Fracture pour fracture, œil pour œil, dent pour dent: on lui fera le même mal qu\'il a fait à son prochain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Celui qui aura tué une pièce de bétail la remplacera et celui qui aura tué un homme sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Vous n\'aurez qu\'une même loi; l\'étranger sera traité comme l\'indigène; car je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Et Moïse parla aux fils d\'Israël, et ils emmenèrent en dehors du camp celui qui avait blasphémé, et ils le lapidèrent. Ainsi les fils d\'Israël firent comme l\'Eternel l\'avait commandé à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Et l\'Eternel parla à Moïse au mont Sinaï, en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Parle aux fils d\'Israël et dis-leur: Quand vous serez entrés au pays que je vous donne, la terre se reposera; il y aura sabbat à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Pendant six ans, tu ensemenceras ton champ, et pendant six ans tu tailleras ta vigne, et tu en recueilleras le produit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Et la septième année il y aura repos, repos complet pour la terre, un sabbat à l\'Eternel; tu n\'ensemenceras point ton champ et tu ne tailleras point ta vigne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Tu ne moissonneras pas ce qui poussera [de soi-même] de ta moisson [précédente] et tu ne vendangeras pas les raisins de ta vigne non taillée; [ce sera] une année de repos pour la terre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Et le produit de ce repos de la terre vous servira de nourriture, à toi, à ton serviteur, à ta servante, à ton mercenaire et à ton étranger, qui demeurent avec toi;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'pour ton bétail aussi et pour les animaux qui sont dans ton pays; tout son produit leur servira de nourriture.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Et tu compteras sept semaines d\'années, sept fois sept ans, et ces sept semaines d\'années te feront une période de quarante-neuf ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Et au septième mois, le dix du mois, tu feras retentir le son de la trompette; au jour des Expiations vous ferez passer la trompette dans tout votre pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Et vous sanctifierez la cinquantième année et vous publierez la liberté dans le pays pour tous les habitants. Ce sera pour vous un jubilé; vous rentrerez chacun dans sa propriété et vous rentrerez chacun dans sa famille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'La cinquantième année sera pour vous le jubilé: vous ne sèmerez point et vous ne moissonnerez point le produit de cette année et vous n\'en vendangerez point le fruit venu de lui-même.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Car c\'est le jubilé; il vous sera sacré; vous en mangerez le produit en le prenant aux champs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En cette année de jubilé chacun de vous reviendra dans sa propriété.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Si vous faites une vente à votre prochain ou si vous achetez quelque chose de votre prochain, que nul de vous ne lèse son frère.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'C\'est d\'après le nombre des années écoulées depuis le jubilé que tu achèteras à ton prochain, et c\'est d\'après le nombre des années de récolte qu\'il te vendra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Selon qu\'il reste plus d\'années, tu augmenteras le prix d\'achat; selon qu\'il en reste moins, tu le réduiras; car c\'est le nombre des récoltes qu\'il te vend.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Nul de vous ne lésera son prochain; mais tu auras crainte de ton Dieu, car moi, l\'Eternel, je suis votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Vous pratiquerez mes ordonnances et vous observerez mes lois et les pratiquerez, et vous habiterez dans le pays en sécurité');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'et la terre donnera ses fruits; vous mangerez à satiété et vous y habiterez en sécurité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Que si vous dites: Que mangerons-nous la septième année? Voici, nous n\'aurons pas semé et nous ne ferons pas notre récolte!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'je vous enverrai ma bénédiction la sixième année et elle donnera une récolte pour trois ans.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Et vous sèmerez la huitième année et vous mangerez de l\'ancienne récolte jusqu\'à la neuvième année; jusqu\'à ce que sa récolte soit venue, vous mangerez de l\'ancienne.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Et la terre ne se vendra pas à perpétuité; car la terre est à moi; car vous êtes chez moi des étrangers et des gens en séjour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Et dans tout le pays que vous posséderez, vous accorderez le rachat du sol.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Lorsque ton frère devient pauvre et vendra une partie de sa propriété, son garant, son plus proche parent, viendra et rachètera ce que son frère aura vendu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Et s\'il ne se trouve pas de garant pour cet homme et qu\'il se procure lui-même la somme nécessaire pour le rachat,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'il comptera les années écoulées depuis la vente et restituera l\'excédant à l\'acquéreur et rentrera dans sa propriété.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'S\'il ne trouve pas de quoi faire cette restitution, la terre vendue restera entre les mains de l\'acquéreur jusqu\'à l\'année du jubilé; et au jubilé elle sera libérée et il rentrera dans sa propriété.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Lorsqu\'un homme vend une maison d\'habitation dans une ville entourée de murs, il aura droit de rachat jusqu\'à la fin de l\'année de la vente; son droit de rachat durera une année,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'mais si elle n\'est pas rachetée avant l\'expiration d\'une année complète, la maison qui est dans la ville entourée de murs demeurera à perpétuité à l\'acquéreur et à ses descendants; elle ne sera pas libérée au jubilé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mais les maisons des villages, qui ne sont pas entourés de murs, seront considérées comme allant avec le fonds de terre; on pourra les racheter et au jubilé elles seront libérées.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Et pour les villes des Lévites, pour les maisons qui leur appartiennent dans ces villes, il y aura droit de rachat perpétuel pour les Lévites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Si quelqu\'un d\'entre les Lévites a fait le rachat, cette vente perdra son effet au jubilé; car les maisons des villes des Lévites sont leur possession parmi les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Les champs des faubourgs et de leurs villes ne seront point vendus; car c\'est leur propriété perpétuelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Si ton frère qui est près de toi déchoit et s\'appauvrit, tu le soutiendras, fût-il étranger et habitant, afin qu\'il vive près de toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ne tire de lui ni intérêt, ni profit; et tu auras crainte de ton Dieu et ton frère vivra près de toi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Tu ne lui donneras pas ton argent à intérêt et tu ne [lui] donneras point de tes vivres pour en tirer un profit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Je suis l\'Eternel, votre Dieu, qui vous ai fait sortir du pays d\'Egypte pour vous donner le pays de Canaan, pour être votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Si ton frère qui est près de toi s\'appauvrit et se vend à toi, tu ne lui imposeras pas le travail d\'un esclave.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Il sera chez toi comme mercenaire, comme domestique; il travaillera chez toi jusqu\'à l\'année du jubilé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Et alors il sortira de chez toi, lui et ses fils avec lui; il retournera dans sa famille et rentrera dans la propriété de ses pères;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'car ils sont mes serviteurs, que j\'ai fait sortir pays d\'Egypte; ils ne seront point vendus comme on vend un esclave.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Tu ne domineras point sur lui avec rigueur; et tu auras crainte de ton Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Les esclaves, hommes ou femmes, qui vous appartiendront, seront pris des nations qui vous entourent; c\'est d\'elles que vous achèterez serviteurs et servantes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Et vous achèterez aussi des esclaves d\'entre les fils des étrangers établis chez vous et de leurs familles qui seront parmi vous, d\'entre les enfants qu\'ils auront engendrés dans votre pays, et ils seront votre propriété.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Vous les laisserez en héritage à vos fils après vous, pour les posséder comme propriété; vous les traiterez comme esclaves, à perpétuité; mais quant à vos frères, les fils d\'Israël, tu ne seras pas pour eux un maître dur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Lorsqu\'un étranger habitant chez toi se sera enrichi et que ton frère sera devenu pauvre près de lui et se vendra à l\'étranger domicilié chez toi ou à un rejeton d\'une famille étrangère,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'après qu\'il se sera vendu il y aura pour lui droit de rachat: un de ses frères, pourra le racheter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Son oncle ou le fils de son oncle pourra le racheter, ou quelqu\'un de ses parents du même sang pourra le racheter; ou, s\'il en a les moyens, il se rachètera lui-même.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Il comptera avec son acquéreur depuis l\'année où il s\'est vendu à lui jusqu\'à l\'année du jubilé; et le prix de vente se comptera d\'après le nombre des années; il sera chez lui sur le pied des journées d\'un mercenaire,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'S\'il y a encore beaucoup d\'années, il payera son rachat à raison de ces années et à proportion du prix pour lequel il avait été acquis;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'et s\'il reste peu d\'années jusqu\'à celle du jubilé, il comptera avec lui: il rendra pour le prix de son achat à proportion du nombre des années.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Il sera chez lui sur le pied des journées d\'un mercenaire à l\'année; celui-ci ne le traitera pas avec rigueur sous tes yeux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'S\'il n\'est racheté de l\'une de ces manières, il sortira l\'année du jubilé, lui et ses fils avec lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Car c\'est de moi que les fils d\'Israël sont serviteurs; ils sont mes serviteurs, que j\'ai fait sortir du pays d\'Egypte: je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Vous ne vous ferez point d\'idoles; vous ne vous dresserez pas d\'image taillée et de cippe, et vous ne mettrez pas dans votre pays de pierre ornée de figures, pour vous prosterner près d\'elles; car je suis l\'Eternel, votre Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Vous observerez mes sabbats et vous relèverez mon sanctuaire. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si vous marchez dans mes statuts, si vous gardez mes commandements et les pratiquez,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'je vous donnerai vos pluies dans leur saison; la terre donnera son produit, et les arbres des champs donneront leurs fruits.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Le foulage des grains atteindra chez vous la vendange, et la vendange atteindra les semailles; vous mangerez votre pain à satiété, et vous habiterez en sécurité dans votre pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Je ferai régner la paix dans le pays; vous dormirez sans que personne vous effraie; je ferai disparaître du pays les animaux malfaisants, et l\'épée ne passera point dans votre pays.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Vous poursuivrez vos ennemis, et ils tomberont devant vous par l\'épée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Cinq d\'entre vous en poursuivront cent, et cent d\'entre vous en poursuivront dix mille, et vos ennemis tomberont devant vous par l\'épée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Et je me tournerai vers vous, je vous ferai fructifier et multiplier, et j\'établirai mon alliance avec vous.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Vous mangerez des récoltes anciennes, très anciennes, et vous ferez sortir l\'ancienne pour faire place à la nouvelle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Et je mettrai ma demeure au milieu de vous, et mon âme ne vous prendra point en dégoût.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Et je marcherai au milieu de vous; je serai votre Dieu et vous serez mon peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Je suis l\'Eternel, votre Dieu, qui vous ai fait sortir du pays d\'Egypte pour n\'y plus être esclaves. J\'ai brisé les barres de votre joug et je vous ai fait marcher tête levée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mais si vous ne m\'écoutez pas et que vous ne pratiquiez pas tous ces commandements,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'si vous méprisez mes ordonnances et si votre âme a mes lois en aversion, pour ne pas pratiquer tous mes commandements et pour enfreindre mon alliance,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'à mon tour voici ce que je vous ferai: Je ferai venir sur vous des maux effrayants, la langueur et la fièvre, qui font défaillir le visage et dépérir la vie, vous sèmerez en vain votre semence: vos ennemis la mangeront.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Et je tournerai ma face contre vous; vous serez battus par vos ennemis; ceux qui vous haïssent domineront sur vous, et vous fuirez sans que personne vous poursuive.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Et si avec cela vous ne m\'écoutez pas, je vous châtierai encore sept fois autant à cause de vos péchés;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'et je briserai la force qui fait votre orgueil; je ferai que votre ciel soit comme de fer et votre terre d\'airain.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Vos efforts n\'aboutiront à rien; votre terre ne donnera pas son produit et l\'arbre de la terre ne donnera pas son fruit.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Et si vous marchez contre moi et ne voulez pas m\'écouter, je vous châtierai encore sept fois autant selon vos péchés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Je lâcherai contre vous les bêtes sauvages, qui vous raviront vos enfants, qui extermineront votre bétail et qui vous réduiront à un petit nombre, et vos chemins deviendront déserts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Et si avec ces châtiments vous ne revenez pas à moi et marchez toujours contre moi,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'à mon tour je marcherai contre vous et je vous frapperai moi aussi sept fois plus à cause de vos péchés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Et je ferai venir contre vous l\'épée vengeresse de l\'alliance; et vous vous presserez dans vos villes, et je déchaînerai la peste au milieu de vous, et vous serez livrés à l\'ennemi,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'lorsque je vous retirerai le pain, votre soutien, que dix femmes cuiront votre pain dans un même four et vous rendront votre pain au poids et que vous mangerez sans vous rassasier.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Et si avec cela vous ne m\'écoutez pas et marchez encore contre moi,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'je marcherai contre vous avec fureur et je vous châtierai moi aussi sept fois plus à cause de vos péchés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Vous mangerez la chair de vos fils et vous mangerez la chair de vos filles;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'je dévasterai vos hauts lieux, j\'abattrai vos colonnes solaires et je mettrai vos cadavres sur les cadavres de vos dieux infâmes et mon âme vous aura en dégoût.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Je mettrai vos villes en ruines; je désolerai vos sanctuaires, je ne respirerai plus le parfum de vos offrandes;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'et je désolerai, moi, le pays, et vos ennemis qui y habiteront en seront stupéfaits;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'et vous, je vous dispenserai parmi les nations et je tirerai l\'épée derrière vous, et votre pays restera désolé et vos villes resteront en ruines.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alors la terre se complaira en ses sabbats, durant tout le temps qu\'elle sera désolée et que vous serez dans le pays de vos ennemis; alors la terre se reposera et aura son plaisir en ses sabbats.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Tout le temps qu\'elle sera dévastée, elle jouira du repos qu\'elle n\'avait point eu dans vos sabbats pendant que vous l\'habitiez.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Quant à ceux d\'entre vous qui survivront, je rendrai leur cœur tremblant dans les pays de leurs ennemis; le bruit d\'une feuille agitée les poursuivra; ils fuiront comme ont fuit devant l\'épée et ils tomberont sans qu\'on les poursuive.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Ils trébucheront l\'un contre l\'autre comme devant l\'épée sans que personne les poursuive, et vous ne pourrez tenir bon devant vos ennemis.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Vous périrez parmi les nations, et le pays de vos ennemis vous dévorera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Et ceux d\'entre vous qui survivront seront consumés à cause de leurs iniquités dans les pays de vos ennemis, et ils seront aussi consumés à cause des iniquités de leurs pères, lesquelles sont avec eux.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Et ils confesseront leur iniquité et l\'iniquité de leurs pères dans leurs transgressions qu\'ils ont commises contre moi et dans la résistance qu\'ils m\'ont opposée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Et moi aussi je leur ai résisté et les ai fait venir dans le pays de leurs ennemis. Si alors leur cœur incirconcis s\'humilie et qu\'ils acquiescent à la punition de leurs fautes,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'je me souviendrai de mon alliance avec Jacob, et même je me souviendrai de mon alliance avec Isaac et de mon alliance avec Abraham, et je me souviendrai du pays;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'et le pays sera abandonné par eux et il se complaira en ses sabbats pendant qu\'il sera dévasté loin d\'eux, et ils acquiesceront à la punition de leurs fautes, parce qu\'ils ont méprisé mes ordonnances et que leur âme a eu mes statuts en aversion.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Mais même ainsi, lorsqu\'ils seront dans le pays de leurs ennemis, je ne les rejetterai point et je ne les aurai point en aversion jusqu\'à les exterminer et à rompre mon alliance avec eux; car je suis l\'Eternel leur Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Et je me souviendrai en leur faveur de l\'alliance faite avec leurs ancêtres, que j\'ai fait sortir du pays d\'Egypte, aux yeux des nations, pour être leur Dieu, moi l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Tels sont les statuts, les ordonnances et les lois que l\'Eternel établit entre lui et les fils d\'Israël au mont Sinaï, par le ministère de Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'L\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Parle aux fils d\'Israël et dis-leur: Si quelqu\'un fait un vœu à l\'Eternel, en promettant la valeur estimée en sicles d\'une personne,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'si c\'est un homme de vingt à soixante ans, l\'estimation sera de cinquante sicles d\'argent, selon le sicle sacré;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'si c\'est une femme, l\'estimation sera de trente sicles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Depuis l\'âge de cinq ans jusqu\'à l\'âge de vingt ans, l\'estimation sera de vingt sicles pour un garçon et de dix sicles pour une fille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Depuis l\'âge d\'un mois jusqu\'à l\'âge de cinq ans, l\'estimation sera de cinq sicles d\'argent pour un garçon et de trois sicles d\'argent pour une fille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Depuis l\'âge de soixante ans et au-dessus, si c\'est un homme, l\'estimation sera de quinze sicles, et de dix sicles si c\'est une femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Si la personne est trop pauvre pour payer la valeur de l\'estimation, on la présentera au sacrificateur, et le sacrificateur l\'estimera et le sacrificateur fixera le prix d\'après les ressources de celui qui a fait le vœu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'S\'il s\'agit d\'animaux dont ont fait offrande à l\'Eternel, tout ce qu\'on donne à l\'Eternel de ce genre d\'animaux sera chose sacrée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'On ne le changera point et on ne remplacera pas un bon par un mauvais, ni un mauvais par un bon, et si l\'on remplace un animal par un autre, tous les deux seront chose sacrée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'S\'il s\'agit de quelque animal impur dont on ne peut faire offrande à l\'Eternel, on présentera l\'animal au sacrificateur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'et le sacrificateur en fera l\'estimation selon qu\'il sera bon ou mauvais, et l\'on s\'en tiendra à l\'estimation du sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Mais si on veut le racheter, on ajoutera un cinquième à l\'estimation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Et quand quelqu\'un consacrera à l\'Eternel sa maison, le sacrificateur en fera l\'estimation selon qu\'elle sera bonne ou mauvaise; on s\'arrêtera à l\'estimation que le sacrificateur en aura faite.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Et si celui qui a consacré sa maison veut la racheter, il ajoutera un cinquième au prix de l\'estimation, et elle lui appartiendra.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Et si quelqu\'un consacre à l\'Eternel une partie de son domaine patrimonial, l\'estimation se fera d\'après la quantité qu\'on y sème, à raison de cinquante sicles d\'argent pour un homer d\'orge.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'S\'il consacre son champ dans l\'année du jubilé, on s\'en tiendra à ce prix d\'estimation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mais s\'il consacre son champ après le jubilé, le sacrificateur évaluera le prix à raison du nombre d\'années qui restent jusqu\'au jubilé, et il sera fait une réduction sur le prix d\'estimation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Et si celui qui a consacré son champ veut le racheter, il ajoutera un cinquième au prix de l\'estimation et le champ lui restera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'S\'il ne rachète pas le champ et qu\'il le vende à quelqu\'un d\'autre, il ne pourra plus être racheté.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Et quand l\'acquéreur en sortira au jubilé, son champ sera consacré à l\'Eternel comme un champ qui a été voué; il deviendra la propriété du sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Et, si quelqu\'un consacre à l\'Eternel un champ qu\'il ait acheté et qui ne soit pas de son patrimoine,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'le sacrificateur en évaluera le prix d\'après l\'estimation jusqu\'à l\'année du jubilé et cet homme payera le jour même le prix fixé, vu que le champ est consacré à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'L\'année du jubilé le champ retournera à celui de qui il l\'avait acheté, et du patrimoine duquel il faisait partie.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Toute estimation sera faite en sicles du sanctuaire; le sicle est de vingt guéras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Toutefois nul ne consacrera les premiers-nés de son bétail, lesquels appartiennent à l\'Eternel en leur qualité de premiers-nés: soit que ce soit du gros ou du menu bétail, ils appartiennent à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'S\'il s\'agit d\'une pièce de bétail impure, on la rachètera au prix de l\'estimation, en y ajoutant un cinquième; si elle n\'est pas rachetée, elle sera vendue d\'après l\'estimation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Mais tout ce que quelqu\'un aura voué par interdit à l\'Eternel dans ce qui lui appartient, soit homme, soit animal, soit champ patrimonial, ne pourra ni se vendre, ni se racheter: tout interdit est très saint et appartient à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Aucune personne vouée par interdit ne pourra être rachetée; elle sera mise à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Toute dîme de la terre, prélevée sur les semences de la terre et sur des fruits des arbres, appartient à l\'Eternel: elle est consacrée à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Si quelqu\'un veut racheter quelque chose de sa dîme, il y ajoutera un cinquième.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Toute dîme de gros et de menu bétail, de tout ce qui passe sous la houlette, le dixième sera consacré à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'On ne fera pas un choix entre ce qui est bon ou mauvais et on ne fera pas d\'échange; si toutefois on fait un échange, l\'animal remplacé et celui qui le remplace seront tous deux consacrés: ils ne pourront être rachetés.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Tels sont les commandements que l\'Eternel donna à Moïse pour les fils d\'Israël, au mont Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Et l\'Eternel parla à Moïse au désert de Sinaï, dans la Tente d\'assignation, le premier jour du second mois, la seconde année après leur sortie du pays d\'Egypte, en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Faites le compte de toute l\'assemblée des fils d\'Israël, selon leurs familles, selon leurs maisons patriarcales, en comptant les noms de tous les mâles par tête,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'depuis l\'âge de vingt ans et au-dessus, tout homme apte au service en Israël; vous en ferez le recensement selon leurs troupes, toi et Aaron.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Et avec vous il y aura un homme par tribu, un homme qui soit chef de sa maison patriarcale.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Voici les noms des hommes qui vous assisteront: Pour Ruben Elitsur, fils de Schédéur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'pour Siméon: Sélumiel, fils de Tsurischaddaï;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'pour Juda: Nahason, fils d\'Amminadab;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'pour Issacar: Néthanéel, fils de Tsuar;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'pour Zabulon: Eliab, fils de Hélon;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'pour les fils de Joseph: pour Ephraïm: Elisama, fils d\'Ammihud; pour Manassé: Gamliel, fils de Pédahtsur;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'pour Benjamin: Abidan, fils de Guidéoni;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'pour Dan: Ahiézer, fils d\'Ammischaddaï;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'pour Asser: Paguiel, fils d\'Ocran;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'pour Gad: Eliasaph, fils de Déuël;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'pour Nephthali: Abira, fils d\'Enan.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Tels sont ceux qui furent convoqués du sein de l\'assemblée; ils étaient princes de leurs tribus patriarcales; ce furent les chefs des milliers d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Moïse et Aaron prirent ces hommes, qui avaient été désignés par leurs noms,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'et convoquèrent toute l\'assemblée, le premier jour du second mois; et ils furent enregistrés, selon leurs familles, selon leurs maisons patriarcales, en comptant les noms par tête, depuis l\'âge de vingt ans et au-dessus,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'comme l\'Eternel l\'avait ordonné à Moïse, et il en fit le dénombrement au désert de Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Les fils de Ruben, premier-né d\'Israël, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms par tête, tous les mâles, depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'les recensés pour la tribu de Ruben furent quarante-six mille cinq cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Pour les fils de Siméon, leurs descendants selon leurs familles, selon leurs maisons patriarcales, recensés en comptant les noms de tous les mâles par tête, depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'les recensés de la tribu de Siméon furent cinquante-neuf mille trois cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Pour les fils de Gad, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'les recensés de la tribu de Gad furent quarante-cinq mille six cent cinquante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Pour les fils de Juda, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'les recensés de la tribu de Juda furent soixante-quatorze mille six cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Pour les fils d\'Issacar, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'les recensés de la tribu d\'Issacar furent cinquante-quatre mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Pour les fils de Zabulon, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'les recensés de la tribu de Zabulon furent cinquante-sept mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Pour les fils de Joseph: Pour les fils d\'Ephraïm, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'les recensés de la tribu d\'Ephraïm furent quarante mille cinq cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Pour les fils de Manassé, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'les recensés de la tribu de Manassé furent trente-deux mille deux cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Pour les fils de Benjamin, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'les recensés de la tribu de Benjamin furent trente-cinq mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Pour les fils de Dan, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'les recensés de la tribu de Dan furent soixante-deux mille sept cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Pour les fils d\'Asser, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'les recensés de la tribu d\'Asser furent quarante-un mille cinq cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Pour les fils de Nephthali, leurs descendants selon leurs familles, selon leurs maisons patriarcales, en comptant les noms depuis l\'âge de vingt ans et au-dessus, tout homme apte au service:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'les recensés de la tribu de Nephthali furent cinquante-trois mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Tels sont ceux dont Moïse et Aaron firent le recensement avec les douze hommes, princes d\'Israël, un homme par maison patriarcale.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Tous les fils d\'Israël dont on fit le recensement selon leurs maisons patriarcales, depuis l\'âge de vingt ans et au-dessus, tout homme apte au service,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'tous ceux dont on fit le recensement furent six cent trois mille cinq cent cinquante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Et les Lévites, selon leur tribu patriarcale, ne furent point compris dans le recensement avec les autres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'De la seule tribu de Lévi tu ne feras pas le recensement, et tu n\'en feras pas figurer le compte avec celui des fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Et toi, tu chargeras les Lévites du soin de la Demeure du témoignage, de tous ses ustensiles et de tout ce qui y tient; ce sont eux qui porteront la Demeure et tous ses ustensiles, qui en feront le service; et ils camperont autour de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Et quand la Demeure partira, les Lévites la démonteront; et quand la Demeure campera, les Lévites la dresseront; et l\'étranger qui en approchera sera mis à mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Les fils d\'Israël camperont chacun dans son camp, chacun près de sa bannière, selon leurs troupes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Et les Lévites camperont autour de la Demeure du témoignage, en sorte qu\'il n\'éclate pas de colère sur l\'assemblée des fils d\'Israël; et les Lévites auront la garde de la Demeure du témoignage.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Et les fils d\'Israël agirent en tout comme l\'Eternel l\'avait ordonné à Moïse; ils firent ainsi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'L\'Eternel parla à Moïse et à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Les fils d\'Israël camperont chacun près de sa bannière, sous les enseignes de leurs maisons patriarcales; ils camperont vis-à-vis de la Tente d\'assignation, tout autour.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'A l\'avant, vers l\'orient, campera la bannière du camp de Juda selon ses troupes; et le prince des fils de Juda est Nahason, fils d\'Amminadab,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'et son corps, et les hommes de son recensement sont soixante-quatorze mille six cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'A côté de lui campera la tribu d\'Issacar; et le prince des fils d\'Issacar est Néthanéel, fils de Tsuar,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'et son corps et les hommes de son recensement sont cinquante-quatre mille quatre cents;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'puis la tribu de Zabulon; et le prince des fils de Zabulon est Eliab, fils de Hélon,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'et son corps et les hommes de son recensement sont cinquante-sept mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Total des hommes du recensement pour le camp de Juda: cent quatre-vingt-six mille quatre cents hommes, selon leurs troupes. Ils se mettront en marche les premiers.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'La bannière du camp de Ruben sera au midi avec ses troupes. Le prince des fils de Ruben est Elitsur, fils de Schédéur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'et son corps et les hommes de son recensement sont quarante-six mille cinq cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'A côté de lui campera la tribu de Siméon; et le prince des fils de Siméon est Sélumiel, fils de Tsurischaddaï,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'et son corps et les hommes de son recensement sont cinquante-neuf mille trois cents;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'puis la tribu de Gad; et le prince des fils de Gad est Eliasaph, fils de Réuël,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'et son corps et les hommes de son recensement sont quarante-cinq mille six cent cinquante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Total des hommes du recensement pour le camp de Ruben: cent cinquante un mille quatre cent cinquante, selon leurs troupes. Ils se mettront en marche les seconds.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Ensuite se mettra en marche la Tente d\'assignation, le camp des Lévites, au milieu des autres camps. Ils marcheront dans l\'ordre dans lequel ils auront campé, chacun à son rang, selon sa bannière.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'La bannière du camp d\'Ephraïm sera à l\'occident, avec ses troupes; et le prince des fils d\'Ephraïm est Elisama, fils d\'Ammihud,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'et son corps et les hommes de son recensement sont quarante mille cinq cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'A côté de lui campera la tribu de Manassé; et le prince des fils de Manassé est Gamliel, fils de Pédahtsur,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'et son corps et les hommes de son recensement sont trente-deux mille deux cents;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'puis la tribu de Benjamin; et le prince des fils de Benjamin est Abidan, fils de Guidéoni,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'et son corps et les hommes de son recensement sont trente-cinq mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Total des hommes du recensement pour le camp d\'Ephraïm: cent huit mille et cent, selon leurs troupes. Ils se mettront en marche les troisièmes.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'La bannière du camp de Dan sera au nord avec ses troupes; et le prince des fils de Dan est Ahiézer, fils d\'Ammischaddaï,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'et son corps et les hommes de son recensement sont soixante-deux mille sept cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'A côté de lui campera la tribu d\'Asser; et le prince des fils d\'Asser est Paguiel, fils d\'Ocran,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'et son corps et les hommes de son recensement sont quarante et un mille cinq cents;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'puis la tribu de Nephthali; et le prince des fils de Nephthali est Ahira, fils d\'Enan,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'et son corps et les hommes de son recensement sont cinquante-trois mille quatre cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Total des hommes du recensement pour le camp de Dan: cent cinquante-sept mille six cents. Ils se mettront en marche les derniers d\'entre les bannières.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ce furent là les fils d\'Israël inscrits au recensement, selon leurs maisons patriarcales. Tous les hommes du recensement des camps, selon leurs troupes, furent six cent trois mille cinq cent cinquante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Les Lévites ne furent point compris dans le recensement avec les fils d\'Israël, suivant l\'ordre que l\'Eternel avait donné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Et les fils d\'Israël agirent en tout comme l\'Eternel l\'avait ordonné à Moïse: ainsi ils campaient, selon leurs bannières, et ainsi ils se mettaient en marche, chacun selon sa famille, selon sa maison patriarcale.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Voici la postérité d\'Aaron et de Moïse, à l\'époque où l\'Eternel parla avec Moïse, sur la montagne de Sinaï.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Ce sont ici les noms des fils d\'Aaron: l\'aîné, Nadab, puis Abihu, Eléazar et Ithamar.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ce sont là les noms des fils d\'Aaron, les sacrificateurs oints qui furent installés pour exercer le sacerdoce.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadab et Abihu moururent devant l\'Eternel, lorsqu\'ils apportèrent devant l\'Eternel du feu étranger, dans le désert de Sinaï; et ils n\'avaient point de fils; et Eléazar et Ithamar exercèrent le sacerdoce en présence d\'Aaron leur père.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Fais approcher la tribu de Lévi, et tu la placeras devant Aaron le sacrificateur, et ils l\'assisteront.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Ils auront la charge de tout ce qui est nécessaire pour lui et pour toute l\'assemblée, devant la Tente d\'assignation, et feront ainsi le service du Tabernacle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Ils auront la charge de tous les ustensiles du culte, de la Tente d\'assignation, et de ce que doivent conserver les fils d\'Israël, et ils feront ainsi le service du Tabernacle.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Et tu donneras les Lévites à Aaron et à ses fils; ils lui seront entièrement donnés, d\'entre les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Tu établiras Aaron et ses fils pour qu\'ils s\'acquittent des fonctions du sacerdoce; et l\'étranger qui approchera sera puni de mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Voici, j\'ai pris les Lévites du milieu des fils d\'Israël, à la place de tout premier-né, premier-né de sa mère parmi les fils d\'Israël, et les Lévites sont à moi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Car tout premier-né est à moi; le jour où j\'ai frappé tous les premiers-nés dans le pays d\'Egypte, je me suis consacré tout premier-né en Israël, depuis les hommes jusqu\'au bétail. Ils sont à moi. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Et l\'Eternel parla à Moïse, au désert de Sinaï, en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Fais le recensement des fils de Lévi, selon leurs maisons patriarcales, selon leurs familles; tu feras le recensement de tous les mâles, depuis l\'âge d\'un mois et au-dessus.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Moïse fit ce recensement sur l\'ordre de l\'Eternel, comme il lui avait été commandé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ce sont ici les fils de Lévi, d\'après leurs noms: Guerson, Kéhath et Mérari.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Voici les noms des fils de Guerson, selon leurs familles: Libni et Siméi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Et les fils de Kéhath, selon leurs familles: Amram et Jitséhar, Hébron et Uzziel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Et les fils de Mérari, selon leurs familles: Machli et Muschi. Ce sont là les familles de Lévi, selon leurs maisons patriarcales.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Pour Guerson: la famille de Libni et la famille de Siméi; ce sont là les familles des Guersonites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Ceux dont on fit le recensement, en comptant, tous les mâles depuis l\'âge d\'un mois et au-dessus, leurs recensés, furent sept mille cinq cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Les familles des Guersonites campaient derrière le Tabernacle, à l\'occident.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Prince de la maison patriarcale des Guersonites: Eliasaph, fils de Laël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Ce qui était remis à la garde des fils de Guerson dans la Tente d\'assignation, c\'étaient la Demeure et la Tente, sa couverture et le rideau de l\'entrée de la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'les toiles du parvis et le rideau de l\'entrée du parvis qui règne tout autour de la Demeure et de l\'autel, et ses cordages pour tout son service.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Pour Kéhath: la famille des Amramites, la famille des Jitséharites, la famille des Hébronites et la famille des Uzziélites; ce sont là les familles des Kéhathites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'En comptant tous les mâles depuis l\'âge d\'un mois et au-dessus, il y en eut huit mille six cents, chargés de la garde du sanctuaire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Les familles des fils de Kéhath campaient au côté méridional de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Prince de la maison patriarcale des familles des Kéhathites: Elitsaphan, fils d\'Uzziel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ce qui était remis à leur garde, c\'étaient l\'arche, la table, le chandelier, les autels, les ustensiles, du sanctuaire avec lesquels on fait le service, le rideau et tout son service.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Prince des princes des Lévites: Eléazar, fils d\'Aaron, le sacrificateur, ayant la surveillance de ceux qui étaient chargés de la garde du sanctuaire.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Pour Mérari: la famille de Machli et la famille de Muschi; ce sont là les familles des Mérarites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Ceux dont on fit le recensement en comptant tous les mâles depuis l\'âge d\'un mois et au-dessus, furent six mille deux cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Prince de la maison patriarcale des familles de Mérari: Tsuriel, fils d\'Abihaïl. Ils campaient du côté septentrional de la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'On remit à la garde et aux soins des fils de Mérari les planches de la Demeure, ses traverses, ses piliers et leurs socles, tous ses ustensiles et tout son service;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'les colonnes du parvis à l\'entour, leurs socles, leurs pieux et leurs cordages.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Ceux qui campaient en face de la Demeure, en avant, devant la Tente d\'assignation, au soleil levant, étaient Moïse et Aaron et ses fils, qui avaient la garde du sanctuaire, remis à la garde des fils d\'Israël; et l\'étranger qui s\'en approchait devait être puni de mort.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Tous les Lévites recensés dont Moïse et Aaron firent le recensement sur l\'ordre de l\'Eternel, selon leurs familles, tous les mâles depuis l\'âge d\'un mois et au-dessus furent vingt-deux mille.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Et l\'Eternel dit à Moïse: Fais le recensement de tous les premiers-nés mâles parmi les fils d\'Israël depuis l\'âge d\'un mois et au-dessus, et relève le nombre de leurs noms.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Et tu prendras, les Lévites pour moi, je suis l\'Eternel, à la place de tous les premiers-nés des fils d\'Israël, et le bétail des Lévites à la place de tous les premiers-nés du bétail des fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Et Moïse fit le recensement de tous les premiers-nés parmi les fils d\'Israël, selon l\'ordre que l\'Eternel lui avait donné.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Et tous les premiers-nés mâles, dont on fit le recensement, depuis l\'âge d\'un mois et au-dessus, firent d\'après le compte des noms vingt-deux mille deux cent soixante-treize.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'L\'Eternel parla à Moïse et dit:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Prends les Lévites à la place de tous les premiers-nés des fils d\'Israël, et le bétail des Lévites à la place de leur bétail, et les Lévites seront à moi. Je suis l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Pour le rachat des deux cent soixante-treize qui dépassent le nombre des Lévites, parmi les premiers-nés des fils d\'Israël,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'tu prendras cinq sicles par tête; tu les prendras selon le sicle sacré qui est de vingt guéras.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Tu donneras l\'argent à Aaron et à ses fils pour le rachat de ceux qui dépassent le nombre des Lévites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Moïse prit l\'argent du rachat de ceux qui dépassaient le nombre de ceux qui avaient été rachetés par les Lévites;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'il prit l\'argent des premiers-nés des fils d\'Israël: mille trois cent soixante-cinq sicles, selon le sicle sacré.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Et Moïse donna l\'argent du rachat à Aaron et à ses fils, sur l\'ordre de l\'Eternel, comme l\'Eternel l\'avait ordonné à Moise.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Et l\'Eternel parla à Moïse et à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Fais le compte des fils de Kéhath d\'entre les fils de Lévi, selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui ont à faire le service en remplissant une fonction dans la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Voici [sur quoi portera] le service des fils de Kéhath, quant à la Tente d\'assignation: les objets très saints.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Lorsqu\'on lèvera le camp, Aaron et ses fils viendront et descendront le voile de séparation, et ils en couvriront l\'arche du témoignage;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'ils mettront dessus une couverture de peaux de dauphin, et ils étendront par-dessus un drap, tout entier de pourpre violette, et ils mettront les barres à l\'arche.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Et sur la table de proposition, ils étendront un drap de pourpre violette, et ils mettront dessus les plats, les godets, les patères et les burettes pour la libation; et le pain perpétuel sera sur elle;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'ils étendront par-dessus un drap de cramoisi, et ils l\'envelopperont d\'une couverture de peaux de dauphin, et ils y mettront les barres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Et ils prendront un drap de pourpre violette, et ils couvriront le candélabre, ses lampes, ses mouchettes, ses cendriers et tous ses vases à huile nécessaires pour son service;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'et ils le mettront, avec tous ses ustensiles, dans une couverture de peaux de dauphin, et le placeront sur un brancard.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Et ils étendront un drap de pourpre violette sur l\'autel d\'or, et ils l\'envelopperont d\'une couverture de peaux de dauphin; et ils y mettront les barres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Et ils prendront tous les ustensiles dont on se sert pour le service dans le sanctuaire, ils les mettront dans un drap de pourpre violette, et ils les envelopperont d\'une couverture de peaux de dauphin, et les placeront sur un brancard.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Et ils nettoieront l\'autel de ses cendres, et étendront par-dessus un drap de pourpre écarlate;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'et ils mettront dessus tous les ustensiles nécessaires pour tout le service, les brasiers, les fourches, les pelles, les bassins, tous les ustensiles de l\'autel; et ils étendront par-dessus une couverture de peaux de dauphin, puis ils y mettront les barres.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Et Aaron et ses fils achèveront d\'envelopper le sanctuaire et tous les meubles du sanctuaire, lorsqu\'on lèvera le camp; après quoi, les fils de Kéhath viendront les emporter et ils ne toucheront point les choses saintes sous peine de mort. Voilà ce que les fils de Kéhath porteront de ce qui appartient à la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Et Eléazar, fils d\'Aaron, le sacrificateur, aura la surveillance de l\'huile du candélabre, du parfum odoriférant, de l\'offrande perpétuelle et de l\'huile d\'onction, la surveillance de toute la Demeure et de tout ce qui s\'y trouve, du sanctuaire et de ses meubles.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Et l\'Eternel parla à Moïse et à Aaron en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Prenez garde de faire retrancher la tribu des familles des Kéhathites du milieu des Lévites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Vous agirez ainsi à leur égard, afin qu\'ils vivent et ne meurent point, lorsqu\'ils s\'approcheront des objets très saints: Aaron et ses fils viendront, et leur assigneront à chacun leur service et ce qu\'ils ont à porter,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'afin qu\'en entrant ils ne voient pas même un instant les choses saintes, et qu\'ils ne meurent point.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Fais aussi le compte des fils de Guerson, selon leurs maisons patriarcales, selon leurs familles:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'tu feras leur recensement, depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui ont à faire le service en remplissant une fonction dans la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Voici le service des familles des Guersonites, pour ce qu\'ils auront à faire et à porter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Ils porteront les tentures de la Demeure et la Tente d\'assignation, sa couverture et la couverture de peaux de dauphin qui est par-dessus, le rideau de l\'entrée de la Tente d\'assignation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'les toiles du parvis et le rideau de l\'entrée de la porte du parvis qui est tout autour de la Demeure et de l\'autel, leurs cordages et tous les ustensiles de leur service. Et ils feront tout le service qui s\'y rapporte.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Tout le service des fils des Guersonites sera sous les ordres d\'Aaron et de ses fils, pour tout ce qu\'ils auront à porter et tout ce qu\'ils auront à faire; vous remettrez à leur aide tout ce qu\'ils ont à porter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tel est le service des familles des fils des Guersonites à l\'égard de la Tente d\'assignation, et ils seront sous la surveillance d\'Ithamar, fils d\'Aaron, le sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Tu feras le recensement des fils de Mérari, selon leurs familles, selon leurs maisons patriarcales;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'tu feras leur recensement, depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui ont à faire le service en remplissant une fonction dans la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Voici ce qu\'ils auront à soigner pour le transport selon tout leur service à l\'égard de la Tente d\'assignation: les planches du Tabernacle, ses traverses, ses piliers, ses socles les piliers du parvis qui est à l\'entour, leurs socles, leurs pieux,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'leurs cordages, tous leurs ustensiles et tout le service qui en dépend. Vous ferez l\'inventaire par leurs noms des objets confiés à leur garde qu\'ils ont à porter.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tel est le service des familles des fils de Mérari, tout leur service à l\'égard de la Tente d\'assignation, sous la direction d\'Ithamar, fils d\'Aaron, le sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Moïse, Aaron et les princes de l\'assemblée firent le recensement des fils des Kéhathites, selon leurs familles et selon leurs maisons patriarcales,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui avaient à faire le service en remplissant une fonction dans la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Ceux dont ils firent le recensement, selon leurs familles, furent deux mille sept cent cinquante.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ce furent là les recensés des familles des Kéhathites, tous remplissant une fonction dans la Tente d\'assignation; Moïse et Aaron en firent le recensement sur l\'ordre de l\'Eternel donné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Les recensés des fils de Guerson, selon leurs familles et selon leurs maisons patriarcales,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui avaient à faire le service en remplissant une fonction dans la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'les recensés, selon leurs familles, selon leurs maisons patriarcales, furent deux mille six cent trente.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ce furent là les recensés des fils de Guerson, tous remplissant une fonction dans la Tente d\'assignation; Moïse et Aaron en firent le recensement sur l\'ordre de l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Les recensés des familles des fils de Mérari, selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui avaient à faire le service en remplissant une fonction dans la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'les recensés, selon leurs familles, furent trois mille deux cents.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ce furent là les recensés des familles des fils de Mérari; Moïse et Aaron en firent le recensement sur l\'ordre de l\'Eternel donné à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Tous les recensés des Lévites dont Moïse, Aaron et les princes d\'Israël firent le recensement, selon leurs familles et selon leurs maisons patriarcales,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'depuis l\'âge de trente ans et au-dessus jusqu\'à l\'âge de cinquante ans, tous ceux qui avaient à faire le service en remplissant quelque fonction pour le service et pour le transport, à l\'égard de la Tente d\'assignation,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'ces recensés furent huit mille cinq cent quatre-vingts.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Sur l\'ordre de l\'Eternel, Moïse assigna à chacun le service qu\'il devait faire et la charge qu\'il devait porter; c\'est le recensement que l\'Eternel avait ordonné, à Moïse.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Ordonne aux fils d\'Israël de renvoyer du camp quiconque a la lèpre ou un écoulement, ou qui est souillé par le contact d\'un cadavre.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Hommes ou femmes, vous les renverrez; vous les renverrez hors du camp, et ils ne souilleront pas leurs camps au milieu desquels je demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Les fils d\'Israël firent ainsi, et ils les renvoyèrent hors du camp; comme l\'Eternel l\'avait dit à Moïse, ainsi firent les fils d\'Israël.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Dis aux fils d\'Israël: Si quelqu\'un, homme ou femme, a fait quelque tort à un homme, en commettant une infidélité à l\'égard de l\'Eternel, et que cette personne se soit rendue coupable,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'elle confessera le péché qu\'elle a commis, et elle restituera en son entier l\'objet du délit en ajoutant un cinquième en sus: elle le remettra à celui envers qui elle s\'est rendue coupable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Si celui-ci n\'a pas d\'héritier à qui l\'objet du délit puisse être rendu, cet objet revient à l\'Eternel, au sacrificateur, outre le bélier propitiatoire, avec lequel on fera propitiation pour le coupable.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Tout ce qui sera prélevé sur toutes les choses saintes que les fils d\'Israël présenteront au sacrificateur, appartiendra à celui-ci.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'C\'est à lui qu\'appartiendront les choses saintes; ce qu\'on donne au sacrificateur sera à lui.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Parle aux fils d\'Israël et dis-leur: Si une femme se détourne et devient infidèle à son mari;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'si un homme a eu commerce avec elle à l\'insu de son mari, ou si elle a été cachée en se souillant; s\'il n\'y a pas de témoin contre elle et qu\'elle n\'ait pas été surprise;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'et si l\'esprit de jalousie s\'empare de son mari et qu\'il soit jaloux de sa femme qui s\'est souillée; ou si l\'esprit de jalousie s\'empare de lui et qu\'il soit jaloux de sa femme sans qu\'elle se soit souillée;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'cet homme amènera sa femme devant le sacrificateur et apportera une offrande à cause d\'elle, un dixième d\'épha de farine d\'orge; il n\'y versera point d\'huile et n\'y mettra point d\'encens, car c\'est une oblation de jalousie, une oblation de ressouvenir qui rappelle l\'iniquité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Et le sacrificateur la fera approcher et se tenir debout devant l\'Eternel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'et le sacrificateur prendra de l\'eau sainte dans un vase de terre et le sacrificateur prendra de la poussière qui se trouve sur le sol de la Demeure et la mettra dans l\'eau;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'et le sacrificateur fera tenir la femme debout devant l\'Eternel, et il découvrira la tête de la femme et lui posera sur les mains l\'oblation de ressouvenir, qui est l\'oblation de jalousie; dans la main du sacrificateur seront les eaux amères de malédiction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Et le sacrificateur adjurera la femme et lui dira: Si aucun homme n\'a couché avec toi et que tu ne te sois point détournée pour te souiller, étant sous la puissance de ton mari, n\'éprouve aucun mal de ces eaux amères de malédiction.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mais si, étant sous la puissance de ton mari, tu t\'es détournée et que tu te sois souillée, et si un autre que ton mari a eu commerce avec toi...');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'le sacrificateur adjurera la femme par le serment d\'imprécation, et le sacrificateur dira à la femme: Que l\'Eternel fasse de toi une malédiction et une exécration au milieu de ton peuple, en faisant maigrir tes flancs et gonfler ton ventre,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'et que ces eaux de malédiction entrent dans tes entrailles pour faire gonfler ton ventre et maigrir tes flancs! Et la femme dira: Amen, amen!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Et le sacrificateur mettra par écrit ces imprécations et il les effacera dans les eaux amères;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'et il fera boire à la femme les eaux amères de malédiction, et les eaux de malédiction entreront en elle pour lui être amères;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'et le sacrificateur prendra des mains de la femme l\'oblation de jalousie, il balancera l\'oblation devant l\'Eternel et il l\'approchera de l\'autel;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'et le sacrificateur prendra une poignée de cette oblation en mémorial et il la fera fumer sur l\'autel et après cela il fera boire les eaux à la femme.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Et quand il les fera boire, il arrivera, si elle s\'est souillée et a été infidèle à son mari, que les eaux de malédiction entreront en elle pour lui être amères; son ventre gonflera, ses flancs maigriront et [le nom de] cette femme sera une malédiction au milieu de son peuple.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mais, si la femme ne s\'est point souillée et qu\'elle soit pure, elle n\'éprouvera aucun mal et demeurera féconde.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Telle est la loi sur la jalousie, quand une femme, étant sous la puissance de son mari, se détourne et se souille,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ou quand l\'esprit de jalousie s\'empare d\'un mari et qu\'il devient jaloux de sa femme: il fera tenir sa femme debout devant l\'Eternel et le sacrificateur lui appliquera toute cette loi.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Et le mari sera net de faute, mais cette femme portera son iniquité.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Parle aux fils d\'Israël et dis-leur: Lorsque quelqu\'un, homme ou femme, se consacre en faisant un vœu de naziréat, pour se séparer en l\'honneur de l\'Eternel,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'il s\'abstiendra de vin et de cervoise; il ne boira ni vinaigre de vin, ni vinaigre de cervoise; il ne boira d\'aucun suc de raisins et ne mangera point de raisins frais ni secs.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Tout le temps de son naziréat, il ne mangera d\'aucun produit de la vigne, depuis les pépins jusqu\'à la peau.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Pendant tout le temps du vœu de son naziréat le rasoir ne passera point sur sa tête, jusqu\'à l\'accomplissement des jours pendant lesquels il se sépare en l\'honneur de l\'Eternel, il sera saint, en laissant croître librement les cheveux de sa tête.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Tout le temps pendant lequel il se sépare en l\'honneur de l\'Eternel, il ne s\'approchera d\'aucun corps mort;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'que ce soit son père, sa mère, son frère ou sa sœur, il ne se souillera point pour eux à leur mort, car il porte sur sa tête la consécration à son Dieu.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Tout le temps de son Naziréat il est consacré à l\'Eternel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Si quelqu\'un meurt inopinément près de lui et souille sa tête consacrée, il rasera sa tête le jour de sa purification; le septième jour il la rasera.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Et le huitième jour il apportera deux tourterelles ou deux pigeonneaux au sacrificateur, à l\'entrée de la Tente d\'assignation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Et le sacrificateur offrira l\'un comme sacrifice pour le péché, et l\'autre comme holocauste, et il fera propitiation pour lui pour son péché à l\'occasion d\'un mort, et il consacrera sa tête ce jour-là.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Et il consacrera à l\'Eternel les jours de son naziréat, et il offrira un agneau d\'union en sacrifice de réparation; les jours antérieurs seront nuls, parce que son naziréat a été souillé.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Voici la loi du naziréen. Le jour où il aura accompli le temps de son naziréat, on le fera venir à l\'entrée de la Tente d\'assignation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'et il présentera son offrande à l\'Eternel: un agneau d\'un an, sans défaut, pour l\'holocauste, une brebis d\'un an, sans défaut, pour le sacrifice pour le péché, et un bélier sans défaut pour le sacrifice d\'actions de grâces;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'une corbeille de pains sans levain (de la fleur de farine en gâteaux pétris à l\'huile) et des galettes sans levain ointes d\'huile; et en outre l\'oblation et les libations.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Le sacrificateur les présentera devant l\'Eternel, et il offrira son sacrifice pour le péché, et son holocauste;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'il offrira le bélier comme sacrifice d\'actions de grâces à l\'Eternel, avec la corbeille de pains sans levain, et il fera l\'oblation et la libation.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Le naziréen rasera, à l\'entrée de la Tente d\'assignation, sa tête consacrée, il prendra les cheveux de sa tête consacrée, et il les jettera sur le feu qui est sous le sacrifice d\'actions de grâces.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Le sacrificateur prendra l\'épaule du bélier quand elle sera cuite, un gâteau sans levain de la corbeille, et une galette sans levain, et il les posera sur les mains du naziréen, après qu\'il aura rasé sa chevelure consacrée.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Le sacrificateur les balancera devant l\'Eternel: c\'est une chose sainte, qui appartient au sacrificateur, outre la poitrine balancée et la cuisse prélevée. Ensuite le naziréen pourra boire du vin.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Telle est la loi pour le naziréen qui a fait un vœu; [telle est] son offrande à l\'Eternel pour son naziréat, outre ce que ses moyens lui permettront de faire. Selon le vœu qu\'il aura fait, ainsi il agira, conformément à la loi de son naziréat.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'L\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Parle à Aaron et à ses fils en disant: Voici comment vous bénirez les fils d\'Israël; vous leur direz:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Que l\'Eternel te bénisse et te garde!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Que l\'Eternel fasse luire sa face sur toi et qu\'il te fasse grâce!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Que l\'Eternel tourne sa face vers toi et qu\'il te donne la paix!');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Et ils mettront mon nom sur les fils d\'Israël, et moi, je les bénirai.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Le jour où Moïse acheva de dresser la Demeure, de l\'oindre et de la sanctifier avec tous ses ustensiles, ainsi que l\'autel avec tous ses ustensiles; lorsqu\'il les eut oints et sanctifiés,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'les princes d\'Israël, chefs de leurs maisons patriarcales, qui sont princes des tribus et préposés au dénombrement,');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'présentèrent leur offrande et l\'amenèrent devant l\'Eternel: six chars-litières et douze bœufs, soit un char pour deux princes et un bœuf pour chaque prince, et ils les présentèrent devant la Demeure.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Et l\'Eternel parla à Moïse en disant:');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Reçois-les de leur part, et qu\'ils soient employés au service de la Tente d\'assignation; tu les donneras aux Lévites, à chacun selon ce que réclame son service.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Et Moïse prit les chars et les bœufs et il les donna aux Lévites.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Il donna deux chars et quatre bœufs aux fils de Guerson, selon ce que réclamait leur service;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'il donna quatre chars et huit bœufs, aux fils de Mérari, selon ce que réclamait leur service, sous la surveillance d\'Ithamar, fils d\'Aaron le sacrificateur.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Quant aux fils de Kéhath, il ne leur en donna point, car, ayant le service des objets sacrés, ils les portaient sur leurs épaules.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Et les princes présentèrent leur offrande pour la dédicace de l\'autel, le jour où on l\'oignit; les princes la présentèrent devant l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Et l\'Eternel dit à Moïse: Que les princes présentent leur offrande, un jour l\'un, l\'autre jour l\'autre, pour la dédicace de l\'autel.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Celui qui présenta le premier jour son offrande fut Nahason, fils d\'Amminadab, de la tribu de Juda.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Son offrande fut: un plat d\'argent du poids de cent trente sicles, un bassin d\'argent de soixante-dix sicles, selon le sicle sacré, tous deux pleins de fleur de farine pétrie à l\'huile, pour l\'oblation;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'un godet en or de dix sicles, plein de parfum;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'un jeune taureau, un bélier, un agneau d\'un an, pour l\'holocauste;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Un bouc, pour le sacrifice pour le péché;');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'et, pour le sacrifice d\'actions de grâces, deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'offrande de Nahason, fils d\'Amminadab.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Le second jour, Néthanéel, fils de Tsuar, prince d\'Issacar, présenta son offrande.');
INSERT INTO `FreBBB_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Son offrande fut: un plat d\'argent du poids de cent trente sicles, un bassin d\'argent de soixante-dix sicles, selon le sicle sacré, tous deux pleins de fleur de farine pétrie à l\'huile, pour l\'oblation;');
